INSERT INTO public.bible_verses (book_no, book_abbr, book_name, chapter, verse, content, language, translation)
VALUES
  ('24', 'yer', 'Yeremia', 49, 28, 'Mengenai Kedar dan mengenai kerajaan-kerajaan Hazor yang dipukul kalah oleh Nebukadnezar, raja Babel. Beginilah firman TUHAN: "Bersiaplah, majulah melawan Kedar, binasakanlah orang-orang di sebelah timur!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 29, 'Hendaklah kemah-kemah mereka dan kawanan domba mereka dirampas sampai bersih, tenda-tenda mereka dan segala perabot mereka; hendaklah unta-unta mereka habis dibawa serta, dan hendaklah berteriak-teriak kepada mereka: Kegentaran dari segala jurusan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 30, 'Larilah, mengungsilah cepat-cepat, bersembunyilah dalam liang-liang, hai penduduk Hazor! demikianlah firman TUHAN. Sebab Nebukadnezar, raja Babel, telah mengambil putusan terhadap kamu dan telah membuat rancangan terhadap kamu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 31, 'Bersiaplah, majulah melawan bangsa yang hidup sentosa, yang diam dengan aman tenteram, demikianlah firman TUHAN, dan yang tidak punya pintu gerbang atau palang, dan yang tinggal tersendiri!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 32, 'Unta-unta mereka akan menjadi jarahan, dan ternak mereka yang banyak itu menjadi rampasan! Aku akan menyerakkan ke segala mata angin mereka yang berpotong tepi rambutnya berkeliling, dan dari segala penjuru Aku akan mendatangkan bencana atas mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 33, 'Hazor akan menjadi tempat persembunyian bagi serigala, menjadi tempat tandus sampai selama-lamanya; seorangpun tidak akan diam lagi di sana dan seorang manusiapun tidak akan tinggal lagi di dalamnya."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 34, 'Firman TUHAN yang datang kepada nabi Yeremia mengenai Elam, pada permulaan pemerintahan Zedekia, raja Yehuda:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 35, 'Beginilah firman TUHAN semesta alam: "Sesungguhnya, Aku mematahkan busur Elam, yakni inti kekuatannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 36, 'Aku akan mendatangkan atas Elam keempat angin dari keempat penjuru langit dan akan menyerakkan mereka ke segala mata angin ini, sehingga tidak ada bangsa yang tidak kedatangan orang-orang yang berserakan dari Elam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 37, 'Aku akan membuat Elam terkejut di depan para musuhnya dan di depan orang-orang yang berusaha mencabut nyawanya. Aku akan mendatangkan atasnya malapetaka, yakni murka-Ku yang menyala-nyala, demikianlah firman TUHAN. Aku akan menyuruh pedang mengejar mereka sampai mereka Kuhabiskan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 38, 'Aku akan menaruh takhta-Ku di Elam, dan Aku akan membinasakan dari sana raja dan pemuka-pemuka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 49, 39, 'Tetapi di kemudian hari Aku akan memulihkan keadaan Elam, demikianlah firman TUHAN."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 1, 'Firman yang disampaikan TUHAN dengan perantaraan nabi Yeremia mengenai Babel, mengenai negeri orang-orang Kasdim:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 2, '"Beritahukanlah di antara bangsa-bangsa dan kabarkanlah, naikkanlah panji-panji dan kabarkanlah, janganlah sembunyikan, katakanlah: Babel telah direbut, dewa Bel menjadi malu, Merodakh telah terkejut! Berhala-berhalanya menjadi malu, dewa-dewanya yang keji telah terkejut!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 3, 'Maka suatu bangsa maju menyerangnya dari utara, membuat negerinya menjadi tempat tandus; tidak ada lagi yang diam di dalamnya, baik manusia maupun binatang, semuanya lari lenyap.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 4, 'Pada waktu itu dan pada masa itu, demikianlah firman TUHAN, orang Israel akan datang, bersama-sama dengan orang Yehuda; mereka akan berjalan sambil menangis dan mencari TUHAN, Allah mereka;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 5, 'mereka menanyakan jalan ke Sion, ke sanalah mereka terarah: Marilah kita menggabungkan diri kepada TUHAN, bergabung dalam suatu perjanjian kekal yang tidak dapat dilupakan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 6, 'Umat-Ku tadinya seperti domba-domba yang hilang; mereka dibiarkan sesat oleh gembala-gembalanya, dibiarkan mengembara di gunung-gunung, mereka berjalan dari gunung ke bukit sehingga lupa akan tempat pembaringannya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 7, 'Siapapun yang menjumpai mereka, memakan habis mereka, dan lawan-lawan mereka berkata: Kami tidak bersalah! Karena mereka telah berdosa kepada TUHAN, tempat kebenaran, TUHAN, pengharapan nenek moyang mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 8, 'Larilah dari tengah-tengah Babel, dari negeri orang-orang Kasdim! Keluarlah! Jadilah seperti kambing-kambing jantan yang mengepalai kawanannya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 9, 'Sebab sesungguhnya, Aku menggerakkan dan membangkitkan terhadap Babel sekumpulan bangsa-bangsa yang besar dari utara; mereka akan mengatur barisan untuk melawannya, dari sanalah kota itu akan direbut. Panah-panah mereka adalah seperti pahlawan yang mujur, yang tidak pernah kembali dengan tangan hampa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 10, 'Negeri orang-orang Kasdim akan menjadi rampasan, semua orang yang merampasnya akan puas hatinya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 11, 'Sekalipun kamu bersukacita dan beria-ria, hai orang-orang yang merampok milik-Ku, sekalipun kamu melompat-lompat seperti anak lembu di padang rumput, dan meringkik seperti kuda-kuda jantan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 12, 'namun, ibumu sangat menanggung malu, dan perempuan yang melahirkan kamu tersipu-sipu! Lihat, dialah yang menjadi terakhir dari bangsa-bangsa: padang gurun, padang belantara dan dataran rumput!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 13, 'Karena murka TUHAN negeri itu tidak akan didiami lagi, sama sekali akan menjadi tempat tandus. Setiap orang yang melewati Babel akan merasa ngeri dan akan bersuit karena pukulan-pukulan yang dideritanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 14, 'Aturlah barisanmu menyerang Babel dari segala pihak, hai semua orang pemanah! Panahlah kepadanya, janganlah merasa sayang akan anak panah, sebab kepada Tuhanlah ia berdosa!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 15, 'Bertempiksoraklah menyerangnya dari segala pihak! Dia sudah menyerah, tonggak-tonggaknya sudah rebah, pagar-pagarnya sudah runtuh! Sungguh, itulah pembalasan TUHAN! Laksanakanlah pembalasan terhadapnya, lakukanlah kepadanya seperti yang dilakukannya sendiri!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 16, 'Lenyapkanlah orang penabur dari Babel dan orang penyabit pada musim menuai! Untuk mengelakkan pedang yang dahsyat ini, setiap orang akan berpaling pulang kepada bangsanya, setiap orang akan lari ke negerinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 17, 'Israel adalah seperti domba yang diceraiberaikan, dihalaukan oleh singa-singa. Mula-mula raja Asyur memakan dia, dan sekarang pada akhirnya Nebukadnezar, raja Babel, mengerumit tulang-tulangnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 18, 'Sebab itu beginilah firman TUHAN semesta alam, Allah Israel: Sesungguhnya, Aku menghukum raja Babel dan negerinya, seperti Aku telah menghukum raja Asyur.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 19, 'Tetapi Aku akan mengembalikan Israel ke padang rumputnya, supaya ia makan rumput di atas Karmel dan di Basan, dan menjadi kenyang di atas pegunungan Efraim dan di Gilead.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 20, 'Pada waktu itu dan pada masa itu, demikianlah firman TUHAN, orang akan mencari kesalahan Israel, tetapi tidak didapatnya, dan dosa Yehuda, tetapi tidak ada ditemukannya, sebab Aku akan mengampuni orang-orang yang Kubiarkan tinggal hidup.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 21, 'Majulah ke negeri Merataim, majulah menyerangnya dan menyerang penduduk Pekod! Bunuhlah dan tumpaslah mereka, demikianlah firman TUHAN, lakukanlah tepat seperti yang Kuperintahkan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 22, 'Gemuruh perang di negeri dan terjadilah kehancuran besar!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 23, 'Betapa remuk redamnya dan hancur luluhnya martil seluruh bumi itu! Betapa Babel menjadi kengerian di antara bangsa-bangsa!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 24, 'Aku memasang jerat bagimu, dan memang engkau terjebak, hai Babel, dengan tidak mengetahuinya. Engkau terdapat dan memang engkau tertangkap, sebab engkau telah menantang TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 25, 'TUHAN telah membuka tempat perlengkapan-Nya dan mengeluarkan senjata-senjata geram-Nya, sebab ada pekerjaan bagi Tuhan ALLAH semesta alam di negeri orang-orang Kasdim:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 26, 'Marilah mendatanginya dari segala jurusan, bukalah lumbung-lumbungnya, onggokkanlah isinya bertimbun-timbun dan tumpaslah itu, janganlah ada tinggal sisanya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 27, 'Bunuhlah segala lembunya, biarlah rebah semuanya untuk dibantai! Celakalah mereka, sebab waktunya sudah tiba, saat penghukuman atas mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 28, 'Dengar! Pelarian-pelarian dan orang-orang yang terluput dari negeri Babel datang memberitahukan di Sion tentang pembalasan TUHAN, Allah kita, pembalasan karena bait suci-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 29, 'Kerahkanlah penembak-penembak melawan Babel, semua orang pemanah! Berkemahlah mengepungnya, supaya jangan ada yang lolos! Balaslah dia setimpal dengan perbuatannya, lakukanlah kepadanya tepat seperti yang dilakukannya sendiri! Sebab ia bertindak kurang ajar terhadap TUHAN, terhadap Yang Mahakudus, Allah Israel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 30, 'Sebab itu teruna-terunanya akan rebah di tanah-tanah lapangnya, dan semua prajuritnya akan menjadi bungkam pada waktu itu, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 31, 'Sesungguhnya, Aku menjadi lawanmu, hai engkau yang kurang ajar, demikianlah firman Tuhan ALLAH semesta alam, sebab waktumu sudah tiba, saat Aku menghukum engkau.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 32, 'Si kurang ajar itu akan tersandung jatuh dan tidak ada yang membangkitkan dia. Di kota-kotanya Aku akan menyalakan api yang akan menghanguskan segala apa yang di sekitarnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 33, 'Beginilah firman TUHAN semesta alam: Orang Israel tertindas bersama-sama dengan orang Yehuda. Semua orang yang menawan mereka tetap menahan mereka, tidak mau melepaskan mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 34, 'Tetapi Penebus mereka adalah kuat; TUHAN semesta alam nama-Nya. Tentulah Ia akan memperjuangkan perkara mereka, supaya Ia memberi ketenteraman kepada bumi, tetapi kegemparan kepada penduduk Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 35, 'Pedang akan menimpa orang-orang Kasdim, demikianlah firman TUHAN, menimpa penduduk Babel, menimpa pemuka-pemukanya dan orang-orangnya yang berhikmat!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 36, 'Pedang menimpa tukang-tukang ramal, sehingga ternyata mereka bodoh! Pedang menimpa pahlawan-pahlawannya, sehingga mereka menjadi terkejut!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 37, 'Pedang menimpa kudanya dan keretanya, menimpa segenap tentara campuran yang di tengah-tengahnya, sehingga mereka menjadi seperti perempuan! Pedang menimpa perbendaharaannya, sehingga dijarah orang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 38, 'Pedang menimpa segala airnya, sehingga menjadi kering! Sebab negeri itu penuh patung-patung, mereka menjadi gila oleh berhala-berhala mereka!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 39, 'Sebab itu binatang-binatang gurun serta anjing-anjing hutan akan diam di sana, juga burung-burung unta akan tinggal di dalamnya. Negeri itu tidak akan didiami lagi untuk seterusnya dan tidak akan ditinggali lagi turun-temurun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 40, 'Seperti dahulu pada waktu Allah menunggangbalikkan Sodom dan Gomora serta kota-kota tetangganya, demikianlah firman TUHAN, demikianlah tidak akan ada orang lagi yang diam di sana dan seorang anak manusiapun tidak akan tinggal lagi di dalamnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 41, 'Lihatlah, suatu bangsa akan datang dari utara, suatu suku bangsa yang besar, dan banyak raja, akan bergerak maju dari ujung bumi.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 42, 'Mereka memakai panah dan tombak; mereka bengis, tidak kenal belas kasihan. Suara mereka gemuruh seperti laut, mereka mengendarai kuda, berlengkap seperti orang maju berperang, menyerang engkau, hai puteri Babel!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 43, 'Raja Babel telah mendengar kabar tentang mereka, tangannya sudah menjadi lemah lesu, kesesakan telah menyergap dia, ia kesakitan seperti perempuan yang melahirkan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 44, 'Sesungguhnya, seperti singa yang bangkit keluar dari hutan belukar sungai Yordan mendatangi padang rumput tempat kawanan domba, demikianlah Aku akan membuat mereka lari dengan tiba-tiba dari negeri itu dan mengangkat di atasnya dia yang Kupilih. Sebab siapakah yang seperti Aku? Siapakah yang berani mendakwa Aku? Siapakah gerangan gembala yang tahan menghadapi Aku?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 45, 'Sebab itu dengarlah putusan yang telah diambil TUHAN terhadap Babel dan rancangan-rancangan yang telah dibuat-Nya terhadap negeri orang-orang Kasdim: Bahwa sesungguhnya, yang paling lemahpun di antara kawanan domba akan diseret. Bahwa sesungguhnya, padang rumput mereka sendiri akan merasa ngeri terhadap mereka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 50, 46, 'Bumi akan goncang karena kabar: Babel sudah direbut; ratap mereka akan terdengar di antara bangsa-bangsa!"', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 1, 'Beginilah firman TUHAN: "Sesungguhnya, Aku menggerakkan terhadap Babel, terhadap penduduk negeri orang-orang Kasdim, suatu semangat pemusnah.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 2, 'Aku akan mengirim ke Babel penampi-penampi yang akan menampinya dan yang akan menyapu bersih negerinya, sebab mereka mengepungnya dari segala pihak pada hari malapetaka.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 3, 'Hendaklah si pemanah membidikkan panahnya kepada orang yang membidik dan kepada orang yang berbaju zirah! Janganlah merasa sayang akan teruna-terunanya, tumpaslah segala tentaranya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 4, 'Orang-orang yang terbunuh akan rebah di negeri orang-orang Kasdim dan orang-orang yang luka parah di jalan-jalannya?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 5, 'sungguh, Israel dan Yehuda tidak ditinggalkan sebagai janda oleh Allahnya, oleh TUHAN semesta alam?sebab negeri orang Kasdim penuh dengan kesalahan terhadap Yang Mahakudus, Allah Israel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 6, 'Larilah dari tengah-tengah Babel, hendaklah setiap orang menyelamatkan nyawanya, supaya kamu jangan tertumpas karena kesalahannya! Sebab inilah waktu pembalasan bagi TUHAN; Ia membayar ganjaran kepadanya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 7, 'Babel tadinya seperti piala emas di tangan TUHAN yang memabukkan seluruh bumi. Bangsa-bangsa minum dari anggurnya, itulah sebabnya bangsa-bangsa menjadi gila.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 8, 'Tiba-tiba Babel jatuh dan pecah, ratapilah dia! Ambillah balsam untuk lukanya, mungkin ia menjadi sembuh!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 9, 'Kami tadinya mau menyembuhkan Babel, tetapi ia tidak dapat disembuhkan; tinggalkanlah dia, marilah kita pulang masing-masing ke negerinya! Sungguh, penghukumannya sudah sampai ke langit, sudah menjangkau awan-awan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 10, 'TUHAN telah membuat segala kebenaran kita menjadi nyata; marilah kita ceritakan di Sion perbuatan TUHAN, Allah kita!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 11, 'Lancipkanlah anak-anak panah, siapkanlah perisai-perisai! TUHAN telah membangkitkan semangat raja-raja Media, sebab rencana-Nya terhadap Babel ialah untuk memusnahkannya: itulah pembalasan TUHAN, pembalasan karena bait suci-Nya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 12, 'Angkatlah panji-panji terhadap tembok-tembok Babel, perkuatlah penjagaan! Tempatkanlah orang-orang jaga, persiapkanlah penghadangan! Sebab TUHAN telah merencanakan dan melaksanakan juga apa yang diancamkan-Nya terhadap penduduk Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 13, 'Hai engkau yang tinggal di tepi sungai besar, yang mempunyai kekayaan besar, akhir hidupmu sudah datang, batas hidupmu sudah sampai!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 14, 'TUHAN semesta alam telah bersumpah demi diri-Nya sendiri: Sungguhpun engkau penuh dengan manusia-manusia seperti belalang, tetapi orang akan mengangkat pekik pertempuran terhadapmu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 15, 'Tuhanlah yang menjadikan bumi dengan kekuatan-Nya, yang menegakkan dunia dengan kebijaksanaan-Nya, dan yang membentangkan langit dengan akal budi-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 16, 'Apabila Ia memperdengarkan suara-Nya, menderulah bunyi air di langit, Ia menaikkan kabut awan dari ujung bumi, Ia membuat kilat serta dengan hujan, dan mengeluarkan angin dari perbendaharaan-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 17, 'Setiap manusia ternyata bodoh, tidak berpengetahuan, dan setiap pandai emas akan menjadi malu karena patung buatannya. Sebab patung tuangannya itu adalah tipu, tidak ada nyawa di dalamnya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 18, 'semuanya adalah kesia-siaan, pekerjaan yang menjadi buah ejekan, dan yang akan binasa pada waktu dihukum.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 19, 'Tidaklah begitu Dia yang menjadi bagian Yakub, sebab Dialah yang membentuk segala-galanya, dan Israel adalah suku milik-Nya; nama-Nya ialah TUHAN semesta alam!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 20, 'Engkau tadinya adalah palu godam bagi-Ku, senjata perang: Dengan engkau Aku menghancurkan bangsa-bangsa, dengan engkau Aku memusnahkan kerajaan-kerajaan,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 21, 'dengan engkau Aku menghancurkan kuda dan pengendaranya, dengan engkau Aku menghancurkan kereta dan penunggangnya,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 22, 'dengan engkau Aku menghancurkan orang laki-laki dan perempuan, dengan engkau Aku menghancurkan orang tua dan muda, dengan engkau Aku menghancurkan teruna dan dara,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 23, 'dengan engkau Aku menghancurkan gembala dan kawanan dombanya, dengan engkau Aku menghancurkan petani dan lembu pembajaknya, dengan engkau Aku menghancurkan bupati-bupati dan pembesar-pembesar!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 24, 'Namun Aku akan membalaskan kepada Babel dan kepada segenap penduduk negeri orang Kasdim segala kejahatan yang telah mereka lakukan terhadap Sion, di depan matamu sendiri, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 25, 'Sesungguhnya, Aku menjadi lawanmu, hai gunung pemusnah, demikianlah firman TUHAN, yang memusnahkan seluruh bumi! Aku akan mengacungkan tangan-Ku kepadamu, menggulingkan engkau dari bukit batu, dan membuat engkau menjadi gunung api yang telah padam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 26, 'Orang tidak akan mengambil batu penjuru atau batu dasar dari padamu, tetapi engkau akan menjadi tempat tandus yang kekal, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 27, 'Angkatlah panji-panji di bumi, tiuplah sangkakala di antara bangsa-bangsa, persiapkanlah bangsa-bangsa berperang melawan Babel, kerahkanlah kerajaan-kerajaan melawannya?Ararat, Mini dan Askenas?angkatlah seorang panglima melawannya, tampilkanlah kuda seperti kawanan belalang!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 28, 'Persiapkanlah bangsa-bangsa berperang melawannya, raja-raja Media beserta bupati-bupati dan pembesar-pembesarnya, dan setiap negeri yang di bawah kuasanya!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 29, 'Bumi berguncang dan bergetar, sebab rancangan TUHAN terhadap Babel sedang terlaksana, yakni untuk membuat negeri Babel menjadi tempat tandus yang tidak berpenduduk.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 30, 'Pahlawan-pahlawan Babel telah berhenti berperang, mereka tinggal duduk di kubu-kubu pertahanan, kegagahberanian mereka sudah lenyap, mereka sudah menjadi seperti perempuan. Tempat-tempat tinggalnya sudah terbakar, palang-palang pintunya sudah patah!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 31, 'Pesuruh-pesuruh cepat berlari susul-menyusul, pembawa-pembawa kabar susul-menyusul, untuk mengabarkan kepada raja Babel, bahwa kotanya telah direbut dari segala penjuru,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 32, 'tempat-tempat penyeberangan telah diduduki, benteng-benteng pertahanan telah dihanguskan dengan api, prajurit-prajurit telah menjadi gempar.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 33, 'Sebab beginilah firman TUHAN semesta alam, Allah Israel: Puteri Babel adalah seperti tempat pengirikan pada waktu orang menginjak-injaknya! Sedikit waktu lagi akan datang waktu panen baginya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 34, 'Aku dimakan habis, dihamburkan oleh Nebukadnezar, raja Babel, diletakkan seperti mangkuk yang kosong. Ia menelan aku seperti ular naga, ia memenuhi perutnya dengan pengananku yang enak-enak, ia membuangkan aku.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 35, 'Biarlah penggagahan dan penghancuran atasku tertimpa kepada Babel, begitulah hendaknya berkata penduduk Sion, biarlah darahku tertimpa kepada penduduk negeri orang Kasdim, begitulah hendaknya berkata Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 36, 'Sebab itu beginilah firman TUHAN: Sesungguhnya, Aku akan memperjuangkan perkaramu, dan akan melakukan pembalasan untukmu: Aku akan mengeringkan lautnya dan akan menggersangkan sumber airnya;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 37, 'Babel akan menjadi timbunan puing, tempat persembunyian serigala-serigala tempat kengerian dan suitan, tanpa penduduk.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 38, 'Bersama-sama mereka mengaum seperti singa-singa muda, menggeram seperti anak-anak singa;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 39, 'jika mereka merasa panas, Aku akan menyediakan perjamuan bagi mereka, akan membuat mereka mabuk, supaya mereka menjadi pusing dan jatuh tertidur untuk selama-lamanya, tidak akan bangun-bangun lagi, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 40, 'Aku akan merebahkan mereka untuk dibantai seperti anak-anak kambing, seperti domba-domba jantan dan kambing-kambing jantan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 41, 'Betapa Sesakh direbut, dan negeri pujian seluruh bumi diduduki! Betapa Babel menjadi kengerian di antara bangsa-bangsa!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 42, 'Laut telah naik meliputi Babel, gelombang-gelombangnya yang menderu telah melingkupinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 43, 'Kota-kotanya sudah menjadi tempat tandus, menjadi negeri yang kering dan padang belantara, negeri yang tidak didiami oleh seorangpun dan yang tidak dilewati oleh seorang manusiapun.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 44, 'Aku akan menghukum dewa Bel di Babel, dan akan mengeluarkan dari mulutnya apa yang ditelannya. Bangsa-bangsa tidak akan datang lagi mengalir kepadanya, tembok Babelpun sudah runtuh.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 45, 'Keluarlah dari tengah-tengahnya, hai umat-Ku! Hendaklah setiap orang menyelamatkan nyawanya dari murka TUHAN yang menyala-nyala itu!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 46, 'Biarlah hatimu jangan kecut dan takut karena kabar yang terdengar di negeri: apabila tahun ini datang kabar ini, dan tahun kemudian kabar itu, apabila kekerasan merajalela di negeri dan penguasa lalim melawan penguasa lalim.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 47, 'Sebab itu sesungguhnya, waktunya akan datang, bahwa Aku akan menghukum patung-patung Babel; seluruh negerinya akan menjadi malu dan semua orangnya yang terbunuh akan rebah di tengah-tengahnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 48, 'Maka langit dan bumi serta segala apa yang ada di dalamnya akan bersorak-sorai tentang Babel, apabila dari utara datang kepadanya para perusak itu, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 49, 'Babel akan jatuh oleh karena orang-orang yang mati terbunuh di antara Israel sama seperti jatuhnya orang-orang yang mati terbunuh di seluruh bumi oleh karena Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 50, 'Kamu, orang-orang yang terluput dari pedang, pergilah, janganlah berhenti! Ingatlah dari jauh kepada TUHAN dan biarlah Yerusalem timbul lagi dalam hatimu:', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 51, 'Kami malu, sebab kami telah mendengar tentang aib, noda meliputi muka kami, sebab orang-orang asing telah memasuki tempat-tempat kudus di rumah TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 52, 'Sebab itu sesungguhnya, waktunya akan datang, demikianlah firman TUHAN, bahwa Aku akan menghukum patung-patungnya, dan di seluruh negerinya akan mengerang orang-orang yang luka tertikam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 53, 'Sekalipun Babel naik ke langit dan sekalipun dibuatnya kubu tak terhampiri di tempat tingginya, atas perintah-Ku akan datang para perusak kepadanya, demikianlah firman TUHAN.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 54, 'Dengar! Ratap dari Babel dan kehancuran besar dari negeri orang Kasdim!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 55, 'Sebab TUHAN merusakkan Babel dan menghentikan suaranya yang besar. Biarpun gelombang-gelombangnya menderu seperti air besar dan suaranya bertambah ribut,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 56, 'namun atas Babel akan datang perusak, para pahlawannya akan tertangkap dan busur-busurnya akan hancur, sebab TUHAN adalah Allah pembalas, tentulah Ia akan mengadakan pembalasan!', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 57, 'Aku akan membuat mabuk para pemukanya, orang-orang bijaksananya, para bupatinya, para pembesarnya dan para pahlawannya, sehingga mereka jatuh tertidur untuk selama-lamanya, tidak akan bangun-bangun lagi, demikianlah firman Sang Raja yang TUHAN semesta alam nama-Nya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 58, 'Beginilah firman TUHAN semesta alam: Tembok-tembok tebal Babel akan disamaratakan, dan pintu-pintu gerbangnya yang tinggi akan dibakar dengan api, sehingga bangsa-bangsa bersusah-susah untuk yang sia-sia dan suku-suku bangsa berlelah untuk api saja."', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 59, 'Pesan yang diberikan nabi Yeremia kepada Seraya bin Neria bin Mahseya, ketika Seraya pergi bersama-sama Zedekia, raja Yehuda, ke Babel pada tahun yang keempat dari pemerintahannya?Seraya waktu itu adalah kepala perlengkapan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 51, 60, 'Yeremia telah menuliskan dalam sebuah kitab segenap malapetaka yang akan menimpa Babel, yakni segala perkataan yang tertulis di sini mengenai Babel. ?', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 1, 'Zedekia berumur dua puluh satu tahun pada waktu ia menjadi raja dan sebelas tahun lamanya ia memerintah di Yerusalem. Nama ibunya ialah Hamutal binti Yeremia, dari Libna.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 2, 'Ia melakukan apa yang jahat di mata TUHAN tepat seperti yang telah dilakukan Yoyakim.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 3, 'Sebab oleh karena murka Tuhanlah hal itu terjadi terhadap Yerusalem dan Yehuda, yakni bahwa Ia sampai membuang mereka dari hadapan-Nya. Zedekia memberontak terhadap raja Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 4, 'Maka pada tahun kesembilan dari pemerintahannya, dalam bulan yang kesepuluh, pada tanggal sepuluh bulan itu, datanglah Nebukadnezar, raja Babel, dengan segala tentaranya menyerang Yerusalem. Berkemahlah mereka mengepungnya dan didirikan merekalah tembok pengepungan sekelilingnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 5, 'Demikianlah kota itu terkepung sampai tahun yang kesebelas pemerintahan raja Zedekia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 6, 'Pada tanggal sembilan bulan yang keempat, ketika kelaparan sudah merajalela di kota itu dan tidak ada lagi makanan pada rakyat negeri itu,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 7, 'maka dibelah oranglah tembok kota itu. Melihat hal itu maka melarikan dirilah raja dengan semua tentara, meninggalkan kota itu pada waktu malam melalui pintu gerbang antara kedua tembok yang ada di dekat taman raja, sekalipun orang Kasdim mengepung kota itu sekeliling. Mereka lari menuju ke Araba-Yordan.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 8, 'Tetapi tentara Kasdim itu mengejar raja dari belakang dan mencapai Zedekia di dataran Yerikho; segala tentaranya telah berserak-serak meninggalkan dia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 9, 'Mereka menangkap raja dan membawa dia ke Ribla di tanah Hamat, kepada raja Babel, yang menjatuhkan hukuman atas dia.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 10, 'Raja Babel menyuruh menyembelih anak-anak Zedekia di depan matanya; juga semua pemuka Yehuda disembelihnya di Ribla.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 11, 'Kemudian mata Zedekia dibutakannya, lalu ia dibelenggu dengan rantai tembaga. Kemudian raja Babel membawa dia ke Babel dan menaruhnya dalam rumah hukuman sampai kepada hari matinya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 12, 'Dalam bulan yang kelima, pada tanggal sepuluh bulan itu?itulah tahun kesembilan belas pemerintahan Nebukadnezar, raja Babel?datanglah Nebuzaradan, kepala pasukan pengawal, yang melayani raja Babel, ke Yerusalem.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 13, 'Ia membakar rumah TUHAN, rumah raja dan segala rumah di Yerusalem; segala rumah orang-orang besar dibakarnya dengan api.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 14, 'Segala tembok sekeliling kota Yerusalem dirobohkan oleh tentara Kasdim yang ada bersama-sama dengan kepala pasukan pengawal itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 15, 'Sebagian dari orang-orang yang paling lemah dan sisa-sisa rakyat yang masih tinggal di kota itu dan pembelot-pembelot yang menyeberang ke pihak raja Babel dan sisa-sisa para pekerja tangan diangkut ke dalam pembuangan oleh Nebuzaradan, kepala pasukan pengawal itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 16, 'Hanya beberapa orang miskin dari negeri itu ditinggalkan oleh Nebuzaradan, kepala pasukan pengawal itu, untuk menjadi tukang-tukang kebun anggur dan peladang-peladang.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 17, 'Juga tiang-tiang tembaga yang ada di rumah TUHAN dan kereta penopang dan laut tembaga yang ada di rumah TUHAN dipecahkan oleh orang Kasdim dan seluruh tembaganya diangkut mereka ke Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 18, 'Kuali-kuali, penyodok-penyodok, pisau-pisau, bokor-bokor penyiraman dan cawan-cawan dan segala perkakas tembaga yang dipakai untuk menyelenggarakan kebaktian diambil mereka,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 19, 'juga pasu-pasu, perbaraan-perbaraan, bokor-bokor penyiraman, kuali-kuali, kandil-kandil, cawan-cawan dan piala-piala, baik segala yang dari emas maupun segala yang dari perak, diambil oleh kepala pasukan pengawal itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 20, 'Adapun kedua tiang, laut yang satu itu dan kedua belas lembu tembaga yang ada di bawah kereta penopang, yang dibuat oleh raja Salomo untuk rumah TUHAN, tiada tertimbang tembaga segala perkakas ini.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 21, 'Adapun tiang-tiang itu, satu tiang delapan belas hasta tingginya dan dapat dililit oleh tali yang dua belas hasta panjangnya; tebalnya empat jari dan geronggang dari dalam.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 22, 'Di atasnya ada ganja dari tembaga; tinggi ganja yang satu itu lima hasta, dan jala-jala dan buah-buah delima ada di atas ganja itu sekeliling, semuanya dari tembaga. Dan tiang yang kedua seperti itu juga. Mengenai buah delima,', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 23, 'ada sembilan puluh enam buah delima yang merupakan gambar timbul; seluruhnya buah-buah delima itu ada seratus pada jala-jala itu berkeliling.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 24, 'Lalu kepala pasukan pengawal itu menangkap Seraya, imam kepala, dan Zefanya, imam tingkat dua, dan ketiga orang penjaga pintu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 25, 'Dari kota itu ditangkapnya seorang pegawai istana yang diangkat mengepalai prajurit-prajurit dan tujuh orang pelayan pribadi raja yang terdapat di kota itu, dan panitera panglima tentara yang mengerahkan rakyat negeri menjadi tentara, dan enam puluh orang dari rakyat negeri yang terdapat di tengah-tengah kota itu.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 26, 'Nebuzaradan, kepala pasukan pengawal, menangkap mereka dan membawa mereka kepada raja Babel, di Ribla.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 27, 'Lalu raja Babel menyuruh membunuh mereka di Ribla, di tanah Hamat. Demikianlah orang Yehuda diangkut ke dalam pembuangan dari tanahnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 28, 'Inilah jumlah rakyat yang diangkut ke dalam pembuangan oleh Nebuzaradan: dalam tahun ketujuh, tiga ribu dua puluh tiga orang Yehuda;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 29, 'dalam tahun kedelapan belas zaman Nebukadnezar, delapan ratus tiga puluh dua jiwa dari Yerusalem;', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 30, 'dalam tahun kedua puluh tiga zaman Nebukadnezar, diangkut ke dalam pembuangan oleh Nebuzaradan, kepala pasukan pengawal, tujuh ratus empat puluh lima jiwa orang Yehuda; seluruhnya berjumlah empat ribu enam ratus jiwa.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 31, 'Kemudian dalam tahun ketiga puluh tujuh sesudah Yoyakhin, raja Yehuda, dibuang, dalam bulan yang kedua belas, pada tanggal dua puluh lima bulan itu, maka Ewil-Merodakh, raja Babel, dalam tahun ia menjadi raja, menunjukkan belas kasihannya kepada Yoyakhin, raja Yehuda, dengan melepaskannya dari penjara.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 32, 'Ewil-Merodakh berbicara baik-baik dengan dia dan memberikan kedudukan kepadanya lebih tinggi dari pada kedudukan raja-raja yang bersama-sama dengan dia di Babel.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 33, 'Yoyakhin boleh mengganti pakaian penjaranya dan boleh selalu makan roti di hadapan raja selama hidupnya.', 'id', 'TB'),
  ('24', 'yer', 'Yeremia', 52, 34, 'Dan tentang belanjanya, raja Babel selalu memberikannya kepadanya, sekadar yang perlu tiap-tiap hari, selama hidupnya, sampai hari matinya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 1, 'Ah, betapa terpencilnya kota itu, yang dahulu ramai! Laksana seorang jandalah ia, yang dahulu agung di antara bangsa-bangsa. Yang dahulu ratu di antara kota-kota, sekarang menjadi jajahan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 2, 'Pada malam hari tersedu-sedu ia menangis, air matanya bercucuran di pipi; dari semua kekasihnya, tak ada seorangpun yang menghibur dia. Semua temannya mengkhianatinya, mereka menjadi seterunya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 3, 'Yehuda telah ditinggalkan penduduknya karena sengsara dan karena perbudakan yang berat; ia tinggal di tengah-tengah bangsa-bangsa, namun tidak mendapat ketenteraman; siapa saja yang menyerang dapat memasukinya pada saat ia terdesak.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 4, 'Jalan-jalan ke Sion diliputi dukacita, karena pengunjung-pengunjung perayaan tiada; sunyi senyaplah segala pintu gerbangnya, berkeluh kesahlah imam-imamnya; bersedih pedih dara-daranya; dan dia sendiri pilu hatinya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 5, 'Lawan-lawan menguasainya, seteru-seterunya berbahagia. Sungguh, TUHAN membuatnya merana, karena banyak pelanggarannya; kanak-kanaknya berjalan di depan lawan sebagai tawanan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 6, 'Lenyaplah dari puteri Sion segala kemuliaannya; pemimpin-pemimpinnya bagaikan rusa yang tidak menemukan padang rumput; mereka berjalan tanpa daya di depan yang mengejarnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 7, 'Terkenanglah Yerusalem, pada hari-hari sengsara dan penderitaannya, akan segala harta benda yang dimilikinya dahulu kala; tatkala penduduknya jatuh ke tangan lawan, dan tak ada penolong baginya, para lawan memandangnya, dan tertawa karena keruntuhannya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 8, 'Yerusalem sangat berdosa, sehingga najis adanya; semua yang dahulu menghormatinya, sekarang menghinanya, karena melihat telanjangnya; dan dia sendiri berkeluh kesah, dan memalingkan mukanya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 9, 'Kenajisannya melekat pada ujung kainnya; ia tak berpikir akan akhirnya, sangatlah dalam ia jatuh, tiada orang yang menghiburnya. "Ya, TUHAN, lihatlah sengsaraku, karena si seteru membesarkan dirinya!"', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 10, 'Si lawan mengulurkan tangannya kepada segala harta bendanya; bahkan harus dilihatnya bagaimana bangsa-bangsa masuk ke dalam tempat kudusnya, padahal Engkau, ya TUHAN, telah melarang mereka untuk masuk jemaah-Mu.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 11, 'Berkeluh kesah seluruh penduduknya, sedang mereka mencari roti; harta benda mereka berikan ganti makanan, untuk menyambung hidupnya. "Lihatlah, ya TUHAN, pandanglah, betapa hina aku ini!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 12, 'Acuh tak acuhkah kamu sekalian yang berlalu? Pandanglah dan lihatlah, apakah ada kesedihan seperti kesedihan yang ditimpakan TUHAN kepadaku, untuk membuat aku merana tatkala murka-Nya menyala-nyala!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 13, 'Dari atas dikirim-Nya api masuk ke dalam tulang-tulangku; dihamparkan-Nya jaring di muka kakiku, didesak-Nya aku mundur; aku dibuat-Nya terkejut, kesakitan sepanjang hari.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 14, 'Segala pelanggaranku adalah kuk yang berat, suatu jalinan yang dibuat tangan Tuhan, yang ditaruh di atas tengkukku, sehingga melumpuhkan kekuatanku; Tuhan telah menyerahkan aku ke tangan orang-orang, yang tidak dapat kutentangi.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 15, 'Tuhan membuang semua pahlawanku yang ada dalam lingkunganku; Ia menyelenggarakan pesta menentang aku untuk membinasakan teruna-terunaku; Tuhan telah menginjak-injak puteri Yehuda, dara itu, seperti orang mengirik memeras anggur.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 16, 'Karena inilah aku menangis, mataku mencucurkan air; karena jauh dari padaku penghibur yang dapat menyegarkan jiwaku; bingunglah anak-anakku, karena terlampau kuat si seteru."', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 17, 'Sion mengulurkan tangannya, tetapi tak ada orang yang menghiburnya; terhadap Yakub dikerahkan TUHAN tetangga-tetangganya sebagai lawan. Yerusalem telah menjadi najis di tengah-tengah mereka.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 18, '"Tuhanlah yang benar, karena aku telah memberontak terhadap firman-Nya; dengarlah hai segala bangsa, dan lihatlah kesedihanku; dara-daraku dan teruna-terunaku pergi sebagai tawanan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 19, 'Aku memanggil kekasih-kekasihku, tetapi mereka memperdayakan aku; imam-imamku dan para tua-tuaku telah mati semuanya di kota, tatkala mencari makan bagi dirinya untuk menyambung hidupnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 20, 'Ya, TUHAN, lihatlah, betapa besar ketakutanku, betapa gelisah jiwaku; hatiku terbolak-balik di dalam dadaku, karena sudah melampaui batas aku memberontak; di luar keturunanku dibinasakan oleh pedang, di dalam rumah oleh penyakit sampar.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 21, 'Dengarlah bagaimana keluh kesahku, sedang tiada penghibur bagiku; seteru-seteruku mendengar tentang kecelakaanku, mereka gembira karena Engkau yang mendatangkannya! Datanglah kiranya hari yang telah Engkau umumkan itu, dan biarlah mereka menjadi seperti aku!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 1, 22, 'Biarlah segala kejahatan mereka datang ke hadapan-Mu, dan perbuatlah kepada mereka, seperti Engkau telah perbuat kepadaku oleh karena segala pelanggaranku; karena banyaklah keluh kesahku, dan pedih hatiku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 1, 'Ah, betapa Tuhan menyelubungi puteri Sion dengan awan dalam murka-Nya! Keagungan Israel dilemparkan-Nya dari langit ke bumi. Tak diingat-Nya akan tumpuan kaki-Nya tatkala Ia murka.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 2, 'Tanpa belas kasihan Tuhan memusnahkan segala ladang Yakub. Ia menghancurkan dalam amarah-Nya benteng-benteng puteri Yehuda. Ia mencampakkan ke bumi dan mencemarkan kerajaan dan pemimpin-pemimpinnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 3, 'Dalam murka yang menyala-nyala Ia mematahkan segala tanduk Israel, menarik kembali tangan kanan-Nya pada waktu si seteru mendekat, membakar Yakub laksana api yang menyala-nyala, yang menjilat ke sekeliling.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 4, 'Ia membidikkan panah-Nya seperti seorang seteru dengan mengacungkan tangan kanan-Nya seperti seorang lawan; membunuh segala yang menyenangkan mata dalam kemah puteri Sion, memuntahkan geram-Nya seperti api.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 5, 'Tuhan menjadi seperti seorang seteru; Ia menghancurkan Israel, meremukkan segala purinya, mempuingkan benteng-bentengnya, memperbanyak susah dan kesah pada puteri Yehuda.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 6, 'Ia melanda kemah-Nya seperti kebun, menghancurkan tempat pertemuan-Nya. Di Sion TUHAN menjadikan orang lupa akan perayaan dan sabat, dan menolak dalam kegeraman murka-Nya raja dan imam.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 7, 'Tuhan membuang mezbah-Nya, meninggalkan tempat kudus-Nya, menyerahkan ke dalam tangan seteru tembok puri-purinya. Teriakan ramai mereka dalam Bait Allah seperti keramaian pada hari perayaan jemaah.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 8, 'TUHAN telah memutuskan untuk mempuingkan tembok puteri Sion. Ia mengukur semuanya dengan tali pengukur, Ia tak menahan tangan-Nya untuk menghancurkannya. Ia menjadikan berkabung tembok luar dan tembok dalam, mereka merana semua.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 9, 'Terbenam gapura-gapuranya di dalam tanah; TUHAN menghancurkan dan meluluhkan palang-palang pintunya. Rajanya dan pemimpin-pemimpinnya berada di antara bangsa-bangsa asing. Tak ada petunjuk dari TUHAN, bahkan nabi-nabi tidak menerima lagi wahyu dari pada-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 10, 'Duduklah tertegun di tanah para tua-tua puteri Sion; mereka menabur abu di atas kepala, dan mengenakan kain kabung. Dara-dara Yerusalem menundukkan kepalanya ke tanah.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 11, 'Mataku kusam dengan air mata, remuk redam hatiku; hancur habis hatiku karena keruntuhan puteri bangsaku, sebab jatuh pingsan kanak-kanak dan bayi di lapangan-lapangan kota.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 12, 'Kepada ibunya mereka bertanya: "Mana roti dan anggur?", sedang mereka jatuh pingsan seperti orang yang gugur di lapangan-lapangan kota, ketika menghembuskan nafas di pangkuan ibunya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 13, 'Apa yang dapat kunyatakan kepadamu, dengan apa aku dapat menyamakan engkau, ya puteri Yerusalem? Dengan apa aku dapat membandingkan engkau untuk dihibur, ya dara, puteri Sion? Karena luas bagaikan laut reruntuhanmu; siapa yang akan memulihkan engkau?', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 14, 'Nabi-nabimu melihat bagimu penglihatan yang dusta dan hampa. Mereka tidak menyatakan kesalahanmu, guna memulihkan engkau kembali. Mereka mengeluarkan bagimu ramalan-ramalan yang dusta dan menyesatkan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 15, 'Sekalian orang yang lewat bertepuk tangan karena engkau. Mereka bersuit-suit dan menggelengkan kepalanya mengenai puteri Yerusalem: "Inikah kota yang disebut orang kota yang paling indah, kesukaan dunia semesta?"', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 16, 'Terhadap engkau semua seterumu mengangakan mulutnya. Mereka bersuit-suit dan menggertakkan gigi: "Kami telah memusnahkannya!", kata mereka, "Nah, inilah harinya yang kami nanti-nantikan, kami mengalaminya, kami melihatnya!"', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 17, 'TUHAN telah menjalankan yang dirancangkan-Nya, Ia melaksanakan yang difirmankan-Nya, yang diperintahkan-Nya dahulu kala; Ia merusak tanpa belas kasihan, Ia menjadikan si seteru senang atas kamu, Ia meninggikan tanduk lawan-lawanmu.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 18, 'Berteriaklah kepada Tuhan dengan nyaring, hai, puteri Sion, cucurkanlah air mata bagaikan sungai siang dan malam; janganlah kauberikan dirimu istirahat, janganlah matamu tenang!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 19, 'Bangunlah, mengeranglah pada malam hari, pada permulaan giliran jaga malam; curahkanlah isi hatimu bagaikan air di hadapan Tuhan, angkatlah tanganmu kepada-Nya demi hidup anak-anakmu, yang jatuh pingsan karena lapar di ujung-ujung jalan!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 20, 'Lihatlah, TUHAN, dan tiliklah, kepada siapakah Engkau telah berbuat ini? Apakah perempuan harus makan anak kandungnya, anak-anak yang masih dibuai? Apakah dalam tempat kudus Tuhan harus dibunuh imam dan nabi?', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 21, 'Terbaring di debu jalan pemuda dan orang tua; dara-daraku dan teruna-terunaku gugur oleh pedang; Engkau membunuh mereka tatkala Engkau murka, tanpa belas kasihan Engkau menyembelih mereka!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 2, 22, 'Seolah-olah pada hari perayaan Engkau mengundang semua yang kutakuti dari sekeliling. Tatkala TUHAN murka tak ada seorang yang luput atau selamat. Mereka yang kubuai dan kubesarkan dibinasakan seteruku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 1, 'Akulah orang yang melihat sengsara disebabkan cambuk murka-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 2, 'Ia menghalau dan membawa aku ke dalam kegelapan yang tidak ada terangnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 3, 'Sesungguhnya, aku dipukul-Nya berulang-ulang dengan tangan-Nya sepanjang hari.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 4, 'Ia menyusutkan dagingku dan kulitku, tulang-tulangku dipatahkan-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 5, 'Ia mendirikan tembok sekelilingku, mengelilingi aku dengan kesedihan dan kesusahan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 6, 'Ia menempatkan aku di dalam gelap seperti orang yang sudah lama mati.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 7, 'Ia menutup segala jalan ke luar bagiku, Ia mengikat aku dengan rantai yang berat.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 8, 'Walaupun aku memanggil-manggil dan berteriak minta tolong, tak didengarkan-Nya doaku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 9, 'Ia merintangi jalan-jalanku dengan batu pahat, dan menjadikannya tidak terlalui.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 10, 'Laksana beruang Ia menghadang aku, laksana singa dalam tempat persembunyian.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 11, 'Ia membelokkan jalan-jalanku, merobek-robek aku dan membuat aku tertegun.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 12, 'Ia membidikkan panah-Nya, menjadikan aku sasaran anak panah.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 13, 'Ia menyusupkan ke dalam hatiku segala anak panah dari tabung-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 14, 'Aku menjadi tertawaan bagi segenap bangsaku, menjadi lagu ejekan mereka sepanjang hari.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 15, 'Ia mengenyangkan aku dengan kepahitan, memberi aku minum ipuh.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 16, 'Ia meremukkan gigi-gigiku dengan memberi aku makan kerikil; Ia menekan aku ke dalam debu.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 17, 'Engkau menceraikan nyawaku dari kesejahteraan, aku lupa akan kebahagiaan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 18, 'Sangkaku: hilang lenyaplah kemasyhuranku dan harapanku kepada TUHAN.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 19, '"Ingatlah akan sengsaraku dan pengembaraanku, akan ipuh dan racun itu."', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 20, 'Jiwaku selalu teringat akan hal itu dan tertekan dalam diriku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 21, 'Tetapi hal-hal inilah yang kuperhatikan, oleh sebab itu aku akan berharap:', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 22, 'Tak berkesudahan kasih setia TUHAN, tak habis-habisnya rahmat-Nya,', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 23, 'selalu baru tiap pagi; besar kesetiaan-Mu!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 24, '"TUHAN adalah bagianku," kata jiwaku, oleh sebab itu aku berharap kepada-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 25, 'TUHAN adalah baik bagi orang yang berharap kepada-Nya, bagi jiwa yang mencari Dia.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 26, 'Adalah baik menanti dengan diam pertolongan TUHAN.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 27, 'Adalah baik bagi seorang pria memikul kuk pada masa mudanya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 28, 'Biarlah ia duduk sendirian dan berdiam diri kalau TUHAN membebankannya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 29, 'Biarlah ia merebahkan diri dengan mukanya dalam debu, mungkin ada harapan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 30, 'Biarlah ia memberikan pipi kepada yang menamparnya, biarlah ia kenyang dengan cercaan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 31, 'Karena tidak untuk selama-lamanya Tuhan mengucilkan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 32, 'Karena walau Ia mendatangkan susah, Ia juga menyayangi menurut kebesaran kasih setia-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 33, 'Karena tidak dengan rela hati Ia menindas dan merisaukan anak-anak manusia.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 34, 'Kalau dipijak-pijak dengan kaki tawanan-tawanan di dunia,', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 35, 'kalau hak orang dibelokkan di hadapan Yang Mahatinggi,', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 36, 'atau orang diperlakukan tidak adil dalam perkaranya, masakan Tuhan tidak melihatnya?', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 37, 'Siapa berfirman, maka semuanya jadi? Bukankah Tuhan yang memerintahkannya?', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 38, 'Bukankah dari mulut Yang Mahatinggi keluar apa yang buruk dan apa yang baik?', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 39, 'Mengapa orang hidup mengeluh? Biarlah setiap orang mengeluh tentang dosanya!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 40, 'Marilah kita menyelidiki dan memeriksa hidup kita, dan berpaling kepada TUHAN.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 41, 'Marilah kita mengangkat hati dan tangan kita kepada Allah di sorga:', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 42, 'Kami telah mendurhaka dan memberontak, Engkau tidak mengampuni.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 43, 'Engkau menyelubungi diri-Mu dengan murka, mengejar kami dan membunuh kami tanpa belas kasihan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 44, 'Engkau menyelubungi diri-Mu dengan awan, sehingga doa tak dapat menembus.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 45, 'Kami Kaujadikan kotor dan keji di antara bangsa-bangsa.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 46, 'Terhadap kami semua seteru kami mengangakan mulutnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 47, 'Kejut dan jerat menimpa kami, kemusnahan dan kehancuran.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 48, 'Air mataku mengalir bagaikan batang air, karena keruntuhan puteri bangsaku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 49, 'Air mataku terus-menerus bercucuran, dengan tak henti-hentinya,', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 50, 'sampai TUHAN memandang dari atas dan melihat dari sorga.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 51, 'Mataku terasa pedih oleh sebab keadaan puteri-puteri kotaku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 52, 'Seperti burung aku diburu-buru oleh mereka yang menjadi seteruku tanpa sebab.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 53, 'Mereka melemparkan aku hidup-hidup dalam lobang, melontari aku dengan batu.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 54, 'Air membanjir di atas kepalaku, kusangka: "Binasa aku!"', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 55, '"Ya TUHAN, aku memanggil nama-Mu dari dasar lobang yang dalam.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 56, 'Engkau mendengar suaraku! Janganlah Kaututupi telinga-Mu terhadap kesahku dan teriak tolongku!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 57, 'Engkau dekat tatkala aku memanggil-Mu, Engkau berfirman: Jangan takut!"', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 58, '"Ya Tuhan, Engkau telah memperjuangkan perkaraku, Engkau telah menyelamatkan hidupku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 59, 'Engkau telah melihat ketidakadilan terhadap aku, ya TUHAN; berikanlah keadilan!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 3, 60, 'Engkau telah melihat segala dendam mereka, segala rancangan mereka terhadap aku."', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 1, 'Ah, sungguh pudar emas itu, emas murni itu berubah; batu-batu suci itu terbuang di pojok tiap jalan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 2, 'Anak-anak Sion yang berharga, yang setimbang dengan emas tua, sungguh mereka dianggap belanga-belanga tanah buatan tangan tukang periuk.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 3, 'Serigalapun memberikan teteknya dan menyusui anak-anaknya, tetapi puteri bangsaku telah menjadi kejam seperti burung unta di padang pasir.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 4, 'Lidah bayi melekat pada langit-langit karena haus; kanak-kanak meminta roti, tetapi tak seorangpun yang memberi.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 5, 'Yang biasa makan yang sedap-sedap mati bulur di jalan-jalan; yang biasa duduk di atas bantal kirmizi terbaring di timbunan sampah.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 6, 'Kedurjanaan puteri bangsaku melebihi dosa Sodom, yang sekejap mata dibongkar-bangkir tanpa ada tangan yang memukulnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 7, 'Pemimpin-pemimpin lebih bersih dari salju dan lebih putih dari susu, tubuh mereka lebih merah dari pada merjan, seperti batu nilam rupa mereka.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 8, 'Sekarang rupa mereka lebih hitam dari pada jelaga, mereka tidak dikenal di jalan-jalan, kulit mereka berkerut pada tulang-tulangnya, mengering seperti kayu.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 9, 'Lebih bahagia mereka yang gugur karena pedang dari pada mereka yang tewas karena lapar, yang merana dan mati sebab tak ada hasil ladang.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 10, 'Dengan tangan sendiri wanita yang lemah lembut memasak kanak-kanak mereka, untuk makanan mereka tatkala runtuh puteri bangsaku.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 11, 'TUHAN melepaskan segenap amarah-Nya, mencurahkan murka-Nya yang menyala-nyala, dan menyalakan api di Sion, yang memakan dasar-dasarnya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 12, 'Tidak percaya raja-raja di bumi, pun seluruh penduduk dunia, bahwa lawan dan seteru dapat masuk ke dalam gapura-gapura Yerusalem.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 13, 'Hal itu terjadi oleh sebab dosa nabi-nabinya dan kedurjanaan imam-imamnya yang di tengah-tengahnya mencurahkan darah orang yang tidak bersalah.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 14, 'Mereka terhuyung-huyung seperti orang buta di jalan-jalan, cemar oleh darah, sehingga orang tak dapat menyentuh pakaian mereka.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 15, '"Singkir! Najis!", kata orang kepada mereka, "Singkir! Singkir! Jangan sentuh!"; lalu mereka lari dan mengembara, maka berkatalah bangsa-bangsa: "Mereka tak boleh tinggal lebih lama di sini."', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 16, 'TUHAN sendiri mencerai-beraikan mereka, tak mau lagi Ia memandang mereka. Para imam tidak mereka hormati, dan orang-orang tua tidak mereka kasihani.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 17, 'Selalu mata kami merindukan pertolongan, tetapi sia-sia; dari menara penjagaan kami menanti-nantikan suatu bangsa yang tak dapat menolong.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 18, 'Mereka mengintai langkah-langkah kami, sehingga kami tak dapat berjalan di lapangan-lapangan kami; akhir hidup kami mendekat, hari-hari kami sudah genap, ya, akhir hidup kami sudah tiba.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 19, 'Pengejar-pengejar kami lebih cepat dari pada burung rajawali di angkasa mereka memburu kami di atas gunung-gunung, menghadang kami di padang gurun.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 20, 'Orang yang diurapi TUHAN, nafas hidup kami, tertangkap dalam pelubang mereka, dia yang kami sangka: "Dalam naungannya kami akan hidup di antara bangsa-bangsa."', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 21, 'Bergembira dan bersukacitalah, hai puteri Edom, engkau yang mendiami tanah Us, juga kepadamu piala akan sampai, engkau akan jadi mabuk lalu menelanjangi dirimu!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 4, 22, 'Telah hapus kesalahanmu, puteri Sion, tak akan lagi TUHAN membawa engkau ke dalam pembuangan, tetapi kesalahanmu, puteri Edom, akan dibalas-Nya, dan dosa-dosamu akan disingkapkan-Nya.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 1, 'Ingatlah, ya TUHAN, apa yang terjadi atas kami, pandanglah dan lihatlah akan kehinaan kami.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 2, 'Milik pusaka kami beralih kepada orang lain, rumah-rumah kami kepada orang asing.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 3, 'Kami menjadi anak yatim, tak punya bapa, dan ibu kami seperti janda.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 4, 'Air kami kami minum dengan membayar, kami mendapat kayu dengan bayaran.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 5, 'Kami dikejar dekat-dekat, kami lelah, bagi kami tak ada istirahat.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 6, 'Kami mengulurkan tangan kepada Mesir, dan kepada Asyur untuk menjadi kenyang dengan roti.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 7, 'Bapak-bapak kami berbuat dosa, mereka tak ada lagi, dan kami yang menanggung kedurjanaan mereka.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 8, 'Pelayan-pelayan memerintah atas kami; yang melepaskan kami dari tangan mereka tak ada.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 9, 'Dengan bahaya maut karena serangan pedang di padang gurun, kami harus mengambil makanan kami.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 10, 'Kulit kami membara laksana perapian, karena nyerinya kelaparan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 11, 'Mereka memperkosa wanita-wanita di Sion dan gadis-gadis di kota-kota Yehuda.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 12, 'Pemimpin-pemimpin digantung oleh tangan mereka, para tua-tua tidak dihormati.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 13, 'Pemuda-pemuda harus memikul batu kilangan, anak-anak terjatuh karena beratnya pikulan kayu.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 14, 'Para tua-tua tidak berkumpul lagi di pintu gerbang, para teruna berhenti main kecapi.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 15, 'Lenyaplah kegirangan hati kami, tari-tarian kami berubah menjadi perkabungan.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 16, 'Mahkota telah jatuh dari kepala kami. Wahai kami, karena kami telah berbuat dosa!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 17, 'Karena inilah hati kami sakit, karena inilah mata kami jadi kabur:', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 18, 'karena bukit Sion yang tandus, di mana anjing-anjing hutan berkeliaran.', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 19, 'Engkau, ya TUHAN, bertakhta selama-lamanya, takhta-Mu tetap dari masa ke masa!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 20, 'Mengapa Engkau melupakan kami selama-lamanya, meninggalkan kami demikian lama?', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 21, 'Bawalah kami kembali kepada-Mu, ya TUHAN, maka kami akan kembali, baharuilah hari-hari kami seperti dahulu kala!', 'id', 'TB'),
  ('25', 'rat', 'Ratapan', 5, 22, 'Atau, apa Engkau sudah membuang kami sama sekali? Sangat murkakah Engkau terhadap kami?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 1, 'Pada tahun ketiga puluh, dalam bulan yang keempat, pada tanggal lima bulan itu, ketika aku bersama-sama dengan para buangan berada di tepi sungai Kebar, terbukalah langit dan aku melihat penglihatan-penglihatan tentang Allah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 2, 'Pada tanggal lima bulan itu, yaitu tahun kelima sesudah raja Yoyakhin dibuang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 3, 'datanglah firman TUHAN kepada imam Yehezkiel, anak Busi, di negeri orang Kasdim di tepi sungai Kebar, dan di sana kekuasaan TUHAN meliputi dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 4, 'Lalu aku melihat, sungguh, angin badai bertiup dari utara, dan membawa segumpal awan yang besar dengan api yang berkilat-kilat dan awan itu dikelilingi oleh sinar; di dalam, di tengah-tengah api itu kelihatan seperti suasa mengkilat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 5, 'Dan di tengah-tengah itu juga ada yang menyerupai empat makhluk hidup dan beginilah kelihatannya mereka: mereka menyerupai manusia,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 6, 'tetapi masing-masing mempunyai empat muka dan pada masing-masing ada pula empat sayap.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 7, 'Kaki mereka adalah lurus dan telapak kaki mereka seperti kuku anak lembu; kaki-kaki ini mengkilap seperti tembaga yang baru digosok.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 8, 'Pada keempat sisi mereka di bawah sayap-sayapnya tampak tangan manusia. Mengenai muka dan sayap mereka berempat adalah begini:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 9, 'mereka saling menyentuh dengan sayapnya; mereka tidak berbalik kalau berjalan, masing-masing berjalan lurus ke depan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 10, 'Muka mereka kelihatan begini: Keempatnya mempunyai muka manusia di depan, muka singa di sebelah kanan, muka lembu di sebelah kiri, dan muka rajawali di belakang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 11, 'Sayap-sayap mereka dikembangkan ke atas; mereka saling menyentuh dengan sepasang sayapnya dan sepasang sayap yang lain menutupi badan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 12, 'Masing-masing berjalan lurus ke depan; ke arah mana roh itu hendak pergi, ke sanalah mereka pergi, mereka tidak berbalik kalau berjalan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 13, 'Di tengah makhluk-makhluk hidup itu kelihatan seperti bara api yang menyala, seperti suluh, yang bergerak kian ke mari di antara makhluk-makhluk hidup itu, dan api itu bersinar sedang dari api itu kilat sabung-menyabung.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 14, 'Makhluk-makhluk hidup itu terbang ke sana ke mari seperti kilat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 15, 'Aku melihat, sungguh, di atas tanah di samping masing-masing dari keempat makhluk-makhluk hidup itu ada sebuah roda.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 16, 'Rupa roda-roda itu seperti kilauan permata pirus dan keempatnya adalah serupa; buatannya seolah-olah roda yang satu di tengah-tengah yang lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 17, 'Kalau mereka berjalan mereka dapat menuju keempat jurusan; mereka tidak berbalik kalau berjalan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 18, 'Mereka mempunyai lingkar dan aku melihat, bahwa sekeliling lingkar yang empat itu penuh dengan mata.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 19, 'Kalau makhluk-makhluk hidup itu berjalan, roda-roda itu juga berjalan di samping mereka; dan kalau makhluk-makhluk hidup itu terangkat dari atas tanah, roda-roda itu turut terangkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 20, 'Ke arah mana roh itu hendak pergi, ke sanalah mereka pergi, dan roda-rodanya sama-sama terangkat dengan mereka, sebab roh makhluk-makhluk hidup itu berada di dalam roda-rodanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 21, 'Kalau makhluk-makhluk hidup itu berjalan, roda-roda itu berjalan; kalau mereka berhenti, roda-roda itu berhenti; dan kalau mereka terangkat dari tanah, roda-roda itu sama-sama terangkat dengan mereka; sebab roh makhluk-makhluk hidup itu berada di dalam roda-rodanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 22, 'Di atas kepala makhluk-makhluk hidup itu ada yang menyerupai cakrawala, yang kelihatan seperti hablur es yang mendahsyatkan, terbentang di atas kepala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 23, 'Dan di bawah cakrawala itu sayap mereka dikembangkan lurus, yang satu menyinggung yang lain; dan masing-masing mempunyai sepasang sayap yang menutupi badan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 24, 'Kalau mereka berjalan, aku mendengar suara sayapnya seperti suara air terjun yang menderu, seperti suara Yang Mahakuasa, seperti keributan laskar yang besar; kalau mereka berhenti, sayapnya dibiarkan terkulai.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 25, 'Maka kedengaranlah suara dari atas cakrawala yang ada di atas kepala mereka; kalau mereka berhenti, sayapnya dibiarkan terkulai.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 26, 'Di atas cakrawala yang ada di atas kepala mereka ada menyerupai takhta yang kelihatannya seperti permata lazurit; dan di atas yang menyerupai takhta itu ada yang kelihatan seperti rupa manusia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 27, 'Dari yang menyerupai pinggangnya sampai ke atas aku lihat seperti suasa mengkilat dan seperti api yang ditudungi sekelilingnya; dan dari yang menyerupai pinggangnya sampai ke bawah aku lihat seperti api yang dikelilingi sinar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 1, 28, 'Seperti busur pelangi, yang terlihat pada musim hujan di awan-awan, demikianlah kelihatan sinar yang mengelilinginya. Begitulah kelihatan gambar kemuliaan TUHAN. Tatkala aku melihatnya aku sembah sujud, lalu kudengar suara Dia yang berfirman.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 1, 'Firman-Nya kepadaku: "Hai anak manusia, bangunlah dan berdiri, karena Aku hendak berbicara dengan engkau."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 2, 'Sementara Ia berbicara dengan aku, kembalilah rohku ke dalam aku dan ditegakkannyalah aku. Kemudian aku mendengar Dia yang berbicara dengan aku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 3, 'Firman-Nya kepadaku: "Hai anak manusia, Aku mengutus engkau kepada orang Israel, kepada bangsa pemberontak yang telah memberontak melawan Aku. Mereka dan nenek moyang mereka telah mendurhaka terhadap Aku sampai hari ini juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 4, 'Kepada keturunan inilah, yang keras kepala dan tegar hati, Aku mengutus engkau dan harus kaukatakan kepada mereka: Beginilah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 5, 'Dan baik mereka mendengarkan atau tidak?sebab mereka adalah kaum pemberontak?mereka akan mengetahui bahwa seorang nabi ada di tengah-tengah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 6, 'Dan engkau, anak manusia, janganlah takut melihat mereka maupun mendengarkan kata-katanya, biarpun engkau di tengah-tengah onak dan duri dan engkau tinggal dekat kalajengking. Janganlah takut mendengarkan kata-kata mereka dan janganlah gentar melihat mukanya, sebab mereka adalah kaum pemberontak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 7, 'Sampaikanlah perkataan-perkataan-Ku kepada mereka, baik mereka mau mendengarkan atau tidak, sebab mereka adalah pemberontak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 8, 'Dan engkau, anak manusia, dengarlah apa yang Kufirmankan kepadamu; janganlah memberontak seperti kaum pemberontak ini. Ngangakanlah mulutmu dan makanlah apa yang Kuberikan kepadamu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 9, 'Aku melihat, sesungguhnya ada tangan yang terulur kepadaku, dan sungguh, dipegang-Nya sebuah gulungan kitab,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 2, 10, 'lalu dibentangkan-Nya di hadapanku. Gulungan kitab itu ditulisi timbal balik dan di sana tertulis nyanyian-nyanyian ratapan, keluh kesah dan rintihan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 1, 'Firman-Nya kepadaku: "Hai anak manusia, makanlah apa yang engkau lihat di sini; makanlah gulungan kitab ini dan pergilah, berbicaralah kepada kaum Israel."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 2, 'Maka kubukalah mulutku dan diberikan-Nya gulungan kitab itu kumakan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 3, 'Lalu firman-Nya kepadaku: "Hai anak manusia, makanlah gulungan kitab yang Kuberikan ini kepadamu dan isilah perutmu dengan itu." Lalu aku memakannya dan rasanya manis seperti madu dalam mulutku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 4, 'Firman-Nya kepadaku: "Hai anak manusia, mari, pergilah dan temuilah kaum Israel dan sampaikanlah perkataan-perkataan-Ku kepada mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 5, 'Sebab engkau tidak diutus kepada suatu bangsa yang berbahasa asing dan yang berat lidah, tetapi kepada kaum Israel;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 6, 'bukan kepada banyak bangsa-bangsa yang berbahasa asing dan yang berat lidah, yang engkau tidak mengerti bahasanya. Sekiranya aku mengutus engkau kepada bangsa yang demikian, mereka akan mendengarkan engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 7, 'Akan tetapi kaum Israel tidak mau mendengarkan engkau, sebab mereka tidak mau mendengarkan Aku, karena seluruh kaum Israel berkepala batu dan bertegar hati.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 8, 'Lihat, Aku meneguhkan hatimu melawan mereka yang berkepala batu dan membajakan semangatmu melawan ketegaran hati mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 9, 'Seperti batu intan, yang lebih keras dari pada batu Kuteguhkan hatimu; janganlah takut kepada mereka dan janganlah gentar melihat mukanya, sebab mereka adalah kaum pemberontak."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 10, 'Selanjutnya firman-Nya kepadaku: "Hai anak manusia, perhatikanlah segala perkataan-Ku yang akan Kufirmankan kepadamu dan berikanlah telingamu kepadanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 11, 'Mari, pergilah dan temuilah orang-orang buangan, teman sebangsamu, berbicaralah kepada mereka dan katakanlah: Beginilah firman Tuhan ALLAH; baik mereka mau mendengarkan atau tidak."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 12, 'Maka Roh itu mengangkat aku, dan aku mendengar di belakangku suatu suara gemuruh yang besar, tatkala kemuliaan Allah naik ke atas dari tempatnya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 13, 'yakni suara dari sayap-sayap makhluk-makhluk hidup yang menggesek satu sama lain, dan di samping itu suara gemertak dari roda-roda, suatu suara gemuruh yang besar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 14, 'Dan Roh itu mengangkat dan membawa aku, dan aku pergi dengan hati panas dan dengan perasaan pahit, karena kekuasaan TUHAN memaksa aku dengan sangat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 15, 'Demikianlah aku datang kepada orang-orang buangan yang tinggal di tepi sungai Kebar di Tel-Abib dan di sana aku duduk tertegun di tengah-tengah mereka selama tujuh hari.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 16, 'Sesudah tujuh hari datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 17, '"Hai anak manusia, Aku telah menetapkan engkau menjadi penjaga kaum Israel. Bilamana engkau mendengarkan sesuatu firman dari pada-Ku, peringatkanlah mereka atas nama-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 18, 'Kalau Aku berfirman kepada orang jahat: Engkau pasti dihukum mati! ?dan engkau tidak memperingatkan dia atau tidak berkata apa-apa untuk memperingatkan orang jahat itu dari hidupnya yang jahat, supaya ia tetap hidup, orang jahat itu akan mati dalam kesalahannya, tetapi Aku akan menuntut pertanggungan jawab atas nyawanya dari padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 19, 'Tetapi jikalau engkau memperingatkan orang jahat itu dan ia tidak berbalik dari kejahatannya dan dari hidupnya yang jahat, ia akan mati dalam kesalahannya, tetapi engkau telah menyelamatkan nyawamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 20, 'Jikalau seorang yang benar berbalik dari kebenarannya dan ia berbuat curang, dan Aku meletakkan batu sandungan di hadapannya, ia akan mati. Oleh karena engkau tidak memperingatkan dia, ia akan mati dalam dosanya dan perbuatan-perbuatan kebenaran yang dikerjakannya tidak akan diingat-ingat, tetapi Aku akan menuntut pertanggungan jawab atas nyawanya dari padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 21, 'Tetapi jikalau engkau memperingatkan orang yang benar itu supaya ia jangan berbuat dosa dan memang tidak berbuat dosa, ia akan tetap hidup, sebab ia mau menerima peringatan, dan engkau telah menyelamatkan nyawamu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 22, 'Maka di sana kekuasaan TUHAN meliputi aku dan Ia berfirman kepadaku: "Bangunlah dan pergilah ke lembah, di sana Aku akan berbicara dengan engkau."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 23, 'Aku bangun dan pergi ke lembah; sesungguhnya di sana kelihatan kemuliaan TUHAN seperti kemuliaan yang telah kulihat di tepi sungai Kebar, dan aku sujud.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 24, 'Tetapi masuklah Roh ke dalam aku dan ditegakkannya aku, lalu Ia berbicara dengan aku, kata-Nya: "Pergilah pulang, kurunglah dirimu di dalam rumahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 25, 'Dan engkau, anak manusia, sesungguhnya, engkau akan diikat dengan tali dan akan dibelenggu, sehingga engkau tidak bisa keluar masuk di tengah-tengah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 26, 'Dan Aku akan membuat lidahmu melekat pada langit-langitmu, sehingga engkau menjadi bisu dan tidak akan menempelak mereka, sebab mereka adalah kaum pemberontak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 3, 27, 'Tetapi kalau Aku berbicara dengan engkau, Aku akan membuka mulutmu dan engkau akan mengatakan kepada mereka: Beginilah firman Tuhan ALLAH. Orang yang mau mendengar, biarlah ia mendengar; dan orang yang mau membiarkan, baiklah membiarkan, sebab mereka adalah kaum pemberontak."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 1, '"Engkau, anak manusia, ambillah sebuah batu bata, letakkan di hadapanmu dan ukirlah di atasnya sebuah kota, yaitu Yerusalem.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 2, 'Ukirlah kota itu dalam keadaan terkepung: dirikan sebuah benteng pengepungan, timbun pula tanah menjadi tembok pengepungan, tempatkan perkemahan tentara dan susun alat-alat pendobrak sekeliling kota itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 3, 'Lalu ambillah sebidang besi dan dirikanlah itu di antaramu dengan kota itu menjadi dinding besi, kemudian tujukanlah wajahmu ke arah kota itu, sehingga kota itu dalam keadaan terkepung, dan engkaulah yang mengepung dia. Inilah menjadi lambang bagi kaum Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 4, 'Berbaringlah engkau pada sisi kirimu dan Aku akan menanggungkan hukuman kaum Israel atasmu. Berapa hari engkau berbaring demikian, selama itulah engkau menanggung hukuman mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 5, 'Beginilah Aku tentukan bagimu: Berapa tahun hukuman kaum Israel, sekian harilah engkau menanggung hukuman mereka, yaitu tiga ratus sembilan puluh hari.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 6, 'Kalau engkau sudah mengakhiri waktu ini, berbaringlah engkau untuk kedua kalinya, tetapi pada sisi kananmu dan tanggunglah hukuman kaum Yehuda empat puluh hari lamanya; Aku menentukan bagimu satu hari untuk satu tahun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 7, 'Tujukanlah wajahmu kepada pengepungan Yerusalem dan kepalkanlah tinjumu kepadanya dan bernubuatlah melawan kota itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 8, 'Lihat, Aku akan mengikat engkau dengan tali, sehingga engkau tidak dapat berbalik dari sisi yang satu ke sisi yang lain sampai engkau mengakhiri waktu pengepunganmu itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 9, 'Selanjutnya ambillah gandum, jelai, kacang merah besar, kacang merah kecil, jawan dan sekoi dan taruhlah dalam satu periuk dan masaklah itu menjadi roti bagimu. Itulah makananmu selama engkau berbaring pada sisimu, yaitu tiga ratus sembilan puluh hari.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 10, 'Dan makananmu yang harus kaumakan akan ditentukan timbangannya, yakni dua puluh syikal satu hari; makanlah itu pada waktu-waktu tertentu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 11, 'Air minumpun bagimu akan ditentukan, seperenam hin banyaknya; minumlah itu pada waktu-waktu tertentu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 12, 'Makanlah roti itu seperti roti jelai yang bundar dan engkau harus membakarnya di atas kotoran manusia yang sudah kering di hadapan mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 13, 'Selanjutnya TUHAN berfirman: "Aku akan membuang orang Israel ke tengah-tengah bangsa-bangsa dan demikianlah mereka akan memakan rotinya najis di sana."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 14, 'Maka kujawab: "Aduh, Tuhan ALLAH, sesungguhnya, aku tak pernah dinajiskan dan dari masa mudaku sampai sekarang tak pernah kumakan bangkai atau sisa mangsa binatang buas; lagipula tak pernah masuk ke mulutku ini daging yang sudah basi."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 15, 'Lalu firman-Nya kepadaku: "Lihat, kalau begitu Aku mengizinkan engkau memakai kotoran lembu ganti kotoran manusia dan bakarlah rotimu di atasnya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 16, 'Sesudah itu Ia berfirman kepadaku: "Hai, anak manusia, sesungguhnya, Aku akan memusnahkan persediaan makanan di Yerusalem?dan mereka akan memakan roti yang tertentu timbangannya dengan hati yang cemas; juga mereka akan meminum air dalam ukuran terbatas dengan hati yang gundah-gulana?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 4, 17, 'dengan maksud, supaya mereka kekurangan makanan dan minuman dan mereka semuanya menjadi gundah-gulana, sehingga mereka hancur di dalam hukumannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 1, 'Dan engkau, anak manusia, ambillah sebilah pedang yang tajam dan pakailah itu sebagai pisau cukur tukang pangkas; cukurlah rambutmu dan janggutmu dengan itu; lalu ambillah sebuah timbangan dan bagi-bagilah rambutmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 2, 'Sepertiga harus kaubakar dengan api di tengah-tengah kota itu sesudah berakhir waktu pengepungannya; sepertiga harus kauambil dan tetaklah dengan pedang itu sekelilingnya; dan sepertiga lagi hamburkanlah ke dalam angin, dan Aku akan menghunus pedang dari belakang mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 3, 'Engkau harus mengambil sedikit dari rambut itu dan bungkus di dalam punca kainmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 4, 'Dan sekali lagi engkau harus mengambil dari padanya, buangkan ke dalam api dan hanguskan dia di sana; dari sana akan keluar api untuk memakan seluruh kaum Israel. Dan berkatalah kepada mereka:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 5, 'Beginilah firman Tuhan ALLAH: Inilah Yerusalem! Di tengah-tengah bangsa-bangsa Kutempatkan dia dan sekelilingnya ada negeri-negeri mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 6, 'Ia sudah memberontak terhadap peraturan-peraturan-Ku lebih jahat dari pada bangsa-bangsa dan terhadap ketetapan-ketetapan-Ku lebih jahat dari negeri-negeri yang di sekitarnya; karena mereka menolak peraturan-peraturan-Ku dan kelakuan mereka tidak selaras dengan ketetapan-ketetapan-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 7, 'Sebab itu beginilah firman Tuhan ALLAH: Oleh karena engkau lebih jahat dari pada bangsa-bangsa yang di sekitarmu dan kelakuanmu tidak selaras dengan ketetapan-ketetapan-Ku dan engkau tidak melakukan peraturan-peraturan-Ku, bahkan engkau melakukan peraturan-peraturan bangsa-bangsa yang di sekitarmu,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 8, 'sebab itu beginilah firman Tuhan ALLAH: Lihat, Aku, ya Aku sendiri akan menjadi lawanmu dan Aku akan menjatuhkan hukuman kepadamu di hadapan bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 9, 'Oleh karena segala perbuatanmu yang keji akan Kuperbuat terhadapmu yang belum pernah Kuperbuat dan yang tidak pernah lagi akan Kuperbuat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 10, 'Sebab itu di tengah-tengahmu ayah-ayah akan memakan anak-anaknya dan anak-anak memakan ayahnya dan Aku akan menjatuhkan hukuman kepadamu, sedang semua yang masih tinggal lagi dari padamu akan Kuhamburkan ke semua penjuru angin.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 11, 'Sebab itu, demi Aku yang hidup, demikianlah firman Tuhan ALLAH, sesungguhnya, oleh karena engkau menajiskan tempat kudus-Ku dengan segala dewamu yang menjijikkan dan dengan segala perbuatanmu yang keji, Aku sendiri akan meruntuhkan engkau; Aku tidak akan merasa sayang dan tidak akan kenal belas kasihan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 12, 'Sepertiga dari padamu akan mati kena sampar dan mati kelaparan di tengah-tengahmu; sepertiga akan tewas dimakan pedang di sekitarmu; dan sepertiga lagi akan Kuhamburkan ke semua mata angin dan Aku akan menghunus pedang dari belakang mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 13, 'Aku akan melampiaskan murka-Ku kepada mereka, sehingga hati-Ku yang panas tenang kembali dan Aku merasa puas; dan mereka akan mengetahui, bahwa Akulah TUHAN yang mengatakannya di dalam cemburu-Ku, tatkala Aku melampiaskan amarah-Ku kepada mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 14, 'Aku akan membuat engkau menjadi reruntuhan dan buah celaan di antara bangsa-bangsa yang di sekitarmu di hadapan semua orang yang lintas dari padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 15, 'Engkau akan menjadi buah celaan dan cercaan, menjadi peringatan dan suatu kengerian bagi bangsa-bangsa yang di sekitarmu, tatkala Aku menjatuhkan hukuman kepadamu di dalam kemurkaan dan kemarahan dan di dalam penghajaran-penghajaran kemarahan?Aku, TUHAN, yang mengatakannya?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 16, 'tatkala Aku mendatangkan atasmu kelaparan yang dahsyat, yang membinasakan, dan Aku mendatangkannya untuk membinasakan kamu, tatkala Aku memperdahsyat bencana kelaparan atasmu dan memusnahkan persediaan makananmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 5, 17, 'Aku akan mendatangkan kelaparan atasmu dan binatang-binatang buas di tengah-tengahmu, yang akan memunahkan anak-anakmu; sampar akan berkecamuk dan darah akan mengalir di tengah-tengahmu dan Aku akan mendatangkan pedang atasmu, Aku, TUHAN, yang mengatakannya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 1, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 2, '"Hai anak manusia, tujukanlah mukamu ke gunung-gunung Israel dan bernubuatlah melawan mereka!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 3, 'Katakanlah: Hai gunung-gunung Israel, dengarkanlah firman Tuhan ALLAH! Beginilah firman Tuhan ALLAH kepada gunung-gunung dan bukit-bukit, kepada alur-alur sungai dan lembah-lembah: Sungguh, Aku akan mendatangkan perang atasmu dan Aku akan membinasakan bukit-bukit pengorbananmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 4, 'Mezbah-mezbahmu akan menjadi sunyi sepi dan pedupaan-pedupaanmu akan dirusak; dan Aku akan merebahkan orang-orangmu yang terbunuh di hadapan berhala-berhalamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 5, 'Aku akan mencampakkan mayat-mayat orang Israel di hadapan berhala-berhala mereka dan menghamburkan tulang-tulangmu keliling mezbah-mezbahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 6, 'Di mana saja kamu diam, kota-kotamu akan menjadi reruntuhan dan bukit-bukit pengorbananmu akan menjadi sunyi sepi, supaya mezbah-mezbahmu dihancurkan dan ditinggalkan sunyi sepi, berhala-berhalamu diremukkan dan ditiadakan, pedupaan-pedupaanmu diluluhkan dan buatan-buatan tanganmu dihapuskan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 7, 'Dan orang-orangmu yang terbunuh akan berebahan di tengah-tengahmu dan kamu akan mengetahui, bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 8, 'Tetapi sebagian, yaitu yang terluput dari pedang, akan Kutinggalkan hidup di antara bangsa-bangsa, bilamana kamu dihamburkan ke negeri-negeri itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 9, 'Di sana, di tengah-tengah bangsa-bangsa, ke mana mereka dibawa tertawan, orang-orang yang terluput dari antara kamu akan mengingat kepada-Ku, tatkala Aku mengembalikan hati mereka yang berzinah itu, yang sudah menjauh dari pada-Ku dan mengalihkan mata mereka, yang selalu berzinah dengan mengikuti berhala-berhala mereka; maka mereka sendiri akan merasa mual melihat kejahatan yang mereka lakukan dan melihat segala perbuatan mereka yang keji.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 10, 'Dan mereka akan mengetahui, bahwa Akulah TUHAN dan bukan cakap angin, kalau Aku berfirman hendak menjatuhkan malapetaka ini atas mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 11, 'Beginilah firman Tuhan ALLAH: "Bertepuklah dan entakkanlah kakimu ke tanah dan serukanlah: Awas! Oleh sebab segala perbuatan kaum Israel yang keji dan jahat, mereka akan rebah mati karena pedang, kelaparan dan penyakit sampar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 12, 'Yang jauh akan mati karena sampar, yang dekat akan rebah karena pedang dan yang terluput serta terpelihara akan mati karena kelaparan. Demikianlah Aku akan melampiaskan amarah-Ku kepada mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 13, 'Dan kamu akan mengetahui, bahwa Akulah TUHAN, tatkala orang-orang mereka yang terbunuh berebahan di tengah-tengah berhala-berhala mereka keliling mezbah-mezbahnya, di atas setiap bukit yang tinggi dan di atas semua puncak-puncak gunung, di bawah setiap pohon yang rimbun dan setiap pohon keramat yang penuh cabang-cabang, di tempat mana mereka membawa korban persembahan yang harum bagi semua berhala-berhala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 6, 14, 'Aku akan mengacungkan tangan-Ku melawan mereka dan tanahnya, di mana saja mereka diam, akan Kubuat menjadi musnah dan sunyi sepi mulai dari padang gurun sampai ke Ribla dan mereka akan mengetahui, bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 1, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 2, '"Engkau, anak manusia, katakanlah: Beginilah firman Tuhan ALLAH kepada tanah Israel: Berakhir! Berakhirlah keempat penjuru tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 3, 'Kini kesudahanmu tiba dan Aku akan mencurahkan murka-Ku atasmu dan Aku akan menghakimi engkau selaras dengan tingkah lakumu dan Aku akan membalaskan kepadamu segala perbuatanmu yang keji.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 4, 'Aku tidak akan merasa sayang kepadamu dan tidak akan kenal belas kasihan, tetapi Aku akan membalaskan kepadamu selaras dengan tingkah lakumu dan perbuatan-perbuatanmu yang keji akan tertimpa atasmu. Maka kamu akan mengetahui, bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 5, 'Beginilah firman Tuhan ALLAH: Lihat, bencana demi bencana akan datang!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 6, 'Kesudahan datang, kesudahanmu tiba, seakan-akan ia terbangun melawan engkau, lihat datangnya!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 7, 'Malapetaka datang atasmu, hai penduduk negeri! Waktunya datang, saatnya tiba! Hari huru-hara, bukan tempik sorak di atas gunung-gunung.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 8, 'Sekarang dengan segera Aku akan mencurahkan amarah-Ku atasmu dan melampiaskan murka-Ku kepadamu, Aku akan menghakimi engkau selaras dengan tingkah lakumu dan membalaskan kepadamu segala perbuatan-perbuat yang keji.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 9, 'Aku tidak akan merasa sayang dan tidak akan kenal belas kasihan; selaras dengan tingkah lakumu akan Kubalaskan kepadamu dan perbuatan-perbuatanm yang keji akan tertimpa atasmu. Maka kamu akan mengetahui, bahwa Aku, Tuhanlah, yang memusnahkan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 10, 'Lihat, harinya sungguh datang: malapetaka akan menimpa, kelaliman bertunas, keangkuhan bertaruk.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 11, 'Kekerasan bersimaharajalela, yang menjadi penopang segala kejahatan. Tidak ada dari mereka yang tertinggal, baik dari kelimpahan mereka maupun dari kemewahannya; kemolekannyapun akan terhapus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 12, 'Waktunya datang, harinya mendekat! Biarlah si pembeli jangan bergembira dan biarlah si penjual jangan berdukacita, karena kehangatan murka tertimpa atas segala kegemparan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 13, 'Sebab si penjual tidak akan kembali kepada jualannya, kalaupun mereka masih di tengah-tengah orang hidup, karena kehangatan murka tertimpa atas segala kegemparan mereka dan tidak dapat ditahan lagi, dan seorangpun tidak dapat mempertahankan hidupnya oleh karena kesalahannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 14, 'Tiuplah sangkakala dan sediakanlah segala sesuatu! Tetapi seorangpun tidak maju berperang, sebab kehangatan murka-Ku tertimpa atas segala kegemparan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 15, 'Pedang ada di luar kota, sampar dan kelaparan ada di dalam. Barangsiapa yang di luar kota akan mati karena pedang, dan barangsiapa yang di dalam kota akan binasa oleh kelaparan dan sampar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 16, 'Dan kalaupun ada yang terluput dari antara mereka, mereka akan tinggal di gunung-gunung seperti burung perkutut di lembah-lembah, semuanya mengerang, masing-masing karena kesalahannya sendiri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 17, 'Semua tangan terkulai dan semua orang terkencing ketakutan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 18, 'Mereka akan mengenakan kain kabung, kekejutan akan meliputi mereka, semuanya akan kehilangan muka dan semua kepala akan digundul sebagai tanda perkabungan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 19, 'Perak mereka akan dicampakkan ke luar dan emas mereka akan dianggap cemar. Emas dan peraknya tidak akan dapat menyelamatkan mereka pada hari kemurkaan TUHAN. Mereka tidak akan kenyang karenanya dan perut mereka tidak akan terisi dengannya. Sebab hal itu menjadi batu sandungan, yang menjatuhkan mereka ke dalam kesalahan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 20, 'Mereka menghiasi dirinya dengan emas dan peraknya dan kepermaian perhiasan ini membawa mereka dalam kecongkakan. Dari emas dan perak itu mereka membuat patung-patungnya yang keji dan dewa-dewanya yang menjijikkan; oleh sebab itu Aku akan menjadikan emas dan peraknya cemar bagi mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 21, 'Aku akan menyerahkannya menjadi rampasan di tangan orang-orang asing dan menjadi jarahan bagi orang-orang fasik di bumi ini, dan mereka ini akan menajiskannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 22, 'Aku akan memalingkan wajah-Ku dari pada mereka dan perampok-perampok akan menajiskan rumah-Ku yang berharga; mereka akan masuk ke dalamnya dan menajiskannya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 23, 'serta memusnahkannya. Sebab negeri itu penuh hutang darah dan kota itu penuh kekerasan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 24, 'Aku akan membiarkan datang bangsa-bangsa yang paling kejam dan bangsa-bangsa ini akan mengambil rumah-rumah mereka menjadi miliknya; Aku akan mengakhiri kecongkakan mereka, yang ditimbulkan kekuatan mereka itu, dan tempat-tempat kudus mereka akan dinajiskan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 25, 'Ketakutan datang, dan mereka mencari keselamatan, tetapi tidak ada.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 26, 'Bencana demi bencana akan datang, kabar demi kabar akan tersiar. Mereka akan menginginkan suatu penglihatan dari nabi, pengajaran hilang lenyap dari imam, dan nasihat dari tua-tua.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 7, 27, 'Raja akan berkabung dan pemimpin akan diliputi kekagetan dan tangan seluruh penduduk negeri itu menjadi lemas ketakutan. Aku akan perbuat terhadap mereka selaras dengan tingkah lakunya dan Aku akan menghakimi mereka selaras dengan cara mereka menghakimi. Dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 1, 'Pada tahun keenam, dalam bulan yang keenam, pada tanggal lima bulan itu, waktu aku duduk di rumahku berhadap-hadapan dengan para tua-tua Yehuda, kekuasaan Tuhan ALLAH meliputi aku di sana,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 2, 'dan aku menerima penglihatan: Sungguh, ada kelihatan yang menyerupai seorang laki-laki, dari yang menyerupai pinggangnya sampai ke bawah kelihatan seperti api dan dari pinggangnya ke atas kelihatan seperti cahaya, seperti suasa mengkilat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 3, 'Dia mengulurkan sesuatu yang berbentuk tangan dan dipegang-Nya jambul kepalaku. Lalu Roh itu mengangkat aku ke antara langit dan bumi dan membawa aku dalam penglihatan-penglihatan ilahi ke Yerusalem dekat pintu gerbang pelataran dalam yang menghadap ke utara, di mana terdapat berhala cemburuan, yang menimbulkan cemburu itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 4, 'Lihat, di sana tampak kemuliaan Allah Israel, seperti penglihatan yang kulihat di lembah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 5, 'Firman-Nya kepadaku: "Hai anak manusia, lihatlah ke utara!" Aku melihat ke utara, sungguh, di sebelah utara gerbang mezbah, dekat jalan masuk, terdapat berhala cemburuan tadi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 6, 'Firman-Nya kepadaku: "Hai anak manusia, kaulihatkah apa yang mereka perbuat, yaitu perbuatan-perbuatan kekejian yang besar-besar, yang dilakukan oleh kaum Israel di sini, sehingga Aku harus menjauhkan diri dari tempat kudus-Ku? Engkau masih akan melihat perbuatan-perbuatan kekejian yang lebih besar lagi."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 7, 'Dan dibawa-Nya aku ke pintu pelataran, aku melihat, sungguh, ada sebuah lobang di dalam temboknya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 8, 'Firman-Nya kepadaku: "Hai anak manusia, perbesarlah lobang yang di tembok itu!" Sesudah aku memperbesar lobang itu, lihat, ada sebuah pintu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 9, 'Firman-Nya kepadaku: "Masuklah dan lihatlah perbuatan-perbuatan kekejian yang jahat, yang mereka lakukan di sini."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 10, 'Lalu aku masuk dan melihat, sungguh, segala gambar-gambar binatang melata dan binatang-binatang lain yang menjijikkan dan segala berhala-berhala kaum Israel terukir pada tembok sekelilingnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 11, 'Dan di hadapannya berdiri tujuh puluh orang tua-tua kaum Israel, dengan Yaazanya bin Safan di tengah-tengah mereka dan masing-masing memegang bokor ukupannya di tangannya, dan keharuman dari asap ukupan itu naik ke atas.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 12, 'Firman-Nya kepadaku: "Kaulihatkah, hai anak manusia, apa yang dilakukan oleh tua-tua kaum Israel di dalam kegelapan, masing-masing di dalam kamar tempat ukiran-ukiran mereka? Sebab mereka berkata: TUHAN tidak melihat kita; TUHAN sudah meninggalkan tanah ini."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 13, 'Ditambahkan-Nya lagi: "Engkau masih akan melihat perbuatan-perbuatan kekejian yang lebih besar lagi yang mereka lakukan."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 14, 'Lalu dibawa-Nya aku dekat pintu gerbang rumah TUHAN yang di sebelah utara, sungguh, di sana ada perempuan-perempuan yang menangisi dewa Tamus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 15, 'Firman-Nya kepadaku: "Hai anak manusia, kaulihatkah apa yang mereka perbuat? Engkau masih akan melihat perbuatan-perbuatan kekejian yang lebih besar lagi dari pada ini."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 16, 'Kemudian dibawa-Nya aku ke pelataran dalam rumah TUHAN; sungguh, dekat jalan masuk ke bait TUHAN, di antara balai Bait Suci dan mezbah ada kira-kira dua puluh lima orang laki-laki, yang membelakangi bait TUHAN dan menghadap ke sebelah timur sambil sujud pada matahari di sebelah timur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 17, 'Lalu firman-Nya kepadaku: "Kaulihatkah itu, hai anak manusia? Perkara kecilkah itu bagi kaum Yehuda untuk melakukan perbuatan-perbuatan kekejian yang mereka lakukan di sini, bahwa mereka memenuhi tanah ini dengan kekerasan dan dengan itu terus menyakiti hati-Ku? Sungguh, mereka berkelakuan tak senonoh di hadapan-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 8, 18, 'Oleh karena itu Aku akan membalas di dalam kemurkaan-Ku. Aku tidak akan merasa sayang dan tidak akan kenal belas kasihan. Dan kalaupun mereka berseru-seru kepada-Ku dengan suara yang nyaring, Aku tidak akan mendengarkan mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 1, 'Lalu aku mendengar Dia berseru dengan suara yang nyaring: "Maju ke mari, hai, yang harus menjalankan hukuman atas kota ini! Masing-masing dengan alat pemusnah di tangannya!"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 2, 'Lihat, enam orang laki-laki datang dari jurusan pintu gerbang Atas, yang menghadap ke utara, masing-masing dengan alat pemukul di tangannya. Dan satu orang di antara mereka berpakaian lenan dan di sisinya terdapat suatu alat penulis. Mereka ini masuk dan berdiri di samping mezbah tembaga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 3, 'Pada saat itu kemuliaan Allah Israel sudah terangkat dari atas kerub, tempatnya semula, ke atas ambang pintu Bait Suci dan Dia memanggil orang yang berpakaian lenan dan yang mempunyai alat penulis di sisinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 4, 'Firman TUHAN kepadanya: "Berjalanlah dari tengah-tengah kota, yaitu Yerusalem dan tulislah huruf T pada dahi orang-orang yang berkeluh kesah karena segala perbuatan-perbuatan keji yang dilakukan di sana."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 5, 'Dan kepada yang lain-lain aku mendengar Dia berfirman: "Ikutilah dia dari belakang melalui kota itu dan pukullah sampai mati! Janganlah merasa sayang dan jangan kenal belas kasihan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 6, 'Orang-orang tua, teruna-teruna dan dara-dara, anak-anak kecil dan perempuan-perempuan, bunuh dan musnahkan! Tetapi semua orang yang ditandai dengan huruf T itu, jangan singgung! Dan mulailah dari tempat kudus-Ku!" Lalu mereka mulai dengan tua-tua yang berada di hadapan Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 7, 'Kemudian firman-Nya kepada mereka: "Najiskanlah Bait Suci itu dan penuhilah pelataran-pelatarannya dengan orang-orang yang terbunuh. Pergilah!" Mereka pergi ke luar dan memukuli orang-orang sampai mati di dalam kota.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 8, 'Sedang mereka memukuli orang-orang sampai mati?waktu itu aku tinggal di belakang?aku sujud dan berseru, kataku: "Aduh, Tuhan ALLAH, apakah Engkau memusnahkan seluruh sisa Israel di dalam mencurahkan amarah-Mu atas Yerusalem?"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 9, 'Jawab-Nya kepadaku: "Kesalahan kaum Israel dan Yehuda sangat banyak, sehingga tanah ini penuh hutang darah dan kota ini penuh ketidakadilan; sebab mereka berkata: TUHAN sudah meninggalkan tanah ini dan TUHAN tidak melihatnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 10, 'Karena itu Aku juga tidak akan merasa sayang dan tidak akan kenal belas kasihan; kelakuan mereka akan Kutimpakan atas kepala mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 9, 11, 'Lihat, orang yang berpakaian lenan itu dan yang mempunyai alat penulis di sisinya memberikan laporan, katanya: "Aku sudah kerjakan seperti Engkau perintahkan kepadaku."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 1, 'Lalu aku melihat, sungguh, di atas cakrawala yang di atas kepala kerub tampak di atas mereka sesuatu yang menyerupai takhta, yang seperti permata lazurit kelihatannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 2, 'Maka Ia berkata kepada orang yang berpakaian lenan itu: "Masuklah ke bawah kerub dari antara roda-rodanya dan penuhilah rangkup tanganmu dengan bara api dari tengah-tengah kerub itu dan hamburkan ke atas kota itu." Lalu aku melihat dia masuk.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 3, 'Kerub-kerub itu berdiri di sebelah selatan Bait Suci, waktu orang itu masuk ke tengah-tengah roda-rodanya; dan segumpal awan memenuhi pelataran dalam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 4, 'Dalam pada itu kemuliaan TUHAN naik dari atas kerub dan pergi ke atas ambang pintu Bait Suci, dan Bait Suci ini dipenuhi oleh awan itu dan pelatarannya penuh dengan sinar kemuliaan TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 5, 'Suara sayap kerub itu terdengar sampai pelataran luar seperti suara ALLAH Yang Mahakuasa, kalau Ia berfirman.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 6, 'Ia memerintahkan kepada orang yang berpakaian lenan itu: "Ambillah api dari tengah-tengah roda-rodanya, dari tengah-tengah kerub itu!" Maka yang berpakaian lenan ini pergi berdiri di samping salah satu dari roda-roda itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 7, 'Lalu seorang kerub itu mengulurkan tangannya dari tengah kerub-kerub ke api yang ada di tengah-tengah mereka, diambilnya sedikit dan ditaruhnya di dalam tangan orang yang berpakaian lenan. Orang ini menerimanya dan pergi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 8, 'Pada kerub-kerub itu tampak yang menyerupai tangan manusia di bawah sayap mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 9, 'Aku melihat, sungguh, di samping kerub-kerub itu terdapat empat roda, satu roda di samping seorang kerub, dan roda-roda ini kelihatannya seperti kilauan permata pirus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 10, 'Kelihatannya keempatnya adalah serupa, seolah-olah roda yang satu di tengah-tengah yang lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 11, 'Kalau mereka berjalan mereka dapat menuju keempat jurusan tanpa berbalik kalau berjalan; karena tempat mana yang dituju oleh yang di muka, ke situlah pergi yang lain-lain, tanpa berbalik kalau berjalan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 12, 'Seluruh badan mereka, punggungnya, tangannya, sayapnya, dan roda-rodanya penuh dengan mata sekelilingnya, ya, roda-roda mereka berempat juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 13, 'Aku dengar bahwa roda-rodanya disebut "puting beliung".', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 14, 'Masing-masing mempunyai empat muka: muka yang pertama ialah muka kerub, yang kedua ialah muka manusia, yang ketiga ialah muka singa dan yang keempat ialah muka rajawali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 15, 'Kerub-kerub itu naik ke atas. Itulah makhluk-makhluk hidup yang dahulu kulihat di tepi sungai Kebar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 16, 'Kalau kerub-kerub itu berjalan, roda-roda itu juga berjalan di samping mereka; kalau kerub-kerub itu mengangkat sayapnya untuk terbang dari tanah, roda-roda itu tidak bergerak dari samping mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 17, 'Kalau kerub-kerub itu berhenti, roda-roda itu berhenti, kalau kerub-kerub itu naik ke atas, roda-roda itu sama-sama naik dengan mereka; sebab roh makhluk-makhluk hidup itu ialah di dalam roda-roda itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 18, 'Lalu kemuliaan TUHAN pergi dari ambang pintu Bait Suci dan hinggap di atas kerub-kerub.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 19, 'Dan kerub-kerub itu mengangkat sayap mereka, dan waktu mereka pergi, aku lihat, mereka naik dari tanah dan roda-rodanya bersama-sama dengan mereka. Lalu mereka berhenti dekat pintu gerbang rumah TUHAN yang di sebelah timur, sedang kemuliaan Allah Israel berada di atas mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 20, 'Itulah makhluk-makhluk hidup yang dahulu kulihat di bawah Allah Israel di tepi sungai Kebar. Dan aku mengerti, bahwa mereka adalah kerub-kerub.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 21, 'Masing-masing mempunyai empat muka dan bagi masing-masing ada empat sayap dan di bawah sayap mereka ada yang berbentuk tangan manusia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 10, 22, 'Kelihatannya muka mereka adalah serupa dengan muka yang kulihat di tepi sungai Kebar. Masing-masing berjalan lurus ke mukanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 1, 'Lalu Roh itu mengangkat aku dan membawa aku ke pintu gerbang Timur dari rumah TUHAN, pintu yang menghadap ke sebelah timur. Lihat, di dalam pintu gerbang itu ada dua puluh lima orang dan di antara mereka kulihat Yaazanya bin Azur dan Pelaca bin Benaya, yaitu pemimpin-pemimpin bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 2, 'Firman-Nya kepadaku: "Hai anak manusia, inilah orang-orang yang merancang kedurjanaan dan menaburkan nasihat jahat di kota ini,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 3, 'yang mengatakan: Bukankah belum lama berselang rumah-rumah kita dibangun kembali? Kota inilah periuk dan kita dagingnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 4, 'Oleh sebab itu bernubuatlah melawan mereka, bernubuatlah, hai anak manusia!"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 5, 'Maka Roh TUHAN meliputi aku dan TUHAN berfirman kepadaku: "Katakanlah: Beginilah firman TUHAN: Kamu berkata-kata begini, hai kaum Israel, dan Aku tahu apa yang timbul dalam hatimu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 6, 'Orang-orang yang kamu bunuh di kota ini bertambah banyak dan kamu penuhi jalan-jalannya dengan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 7, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Orang-orang yang kamu bunuh di kota ini, merekalah dagingnya dan kota inilah periuk, tetapi kamu akan Kugiring keluar dari dalamnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 8, 'Kamu takut kepada pedang, tetapi Aku akan mendatangkan pedang atasmu, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 9, 'Aku akan menggiring kamu keluar dari dalamnya dan menyerahkan kamu di tangan orang-orang asing dan menjatuhkan hukuman-hukuman kepadamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 10, 'Kamu akan berebahan karena pedang dan di tanah Israel Aku akan menghukum kamu; dan kamu akan mengetahui, bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 11, 'Kota ini tidak akan menjadi periuk bagimu ataupun kamu seakan-akan daging di dalamnya; di tanah Israel Aku akan menghukum kamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 12, 'Dan kamu akan mengetahui, bahwa Akulah TUHAN, karena kelakuanmu tidak selaras dengan ketetapan-ketetapan-Ku dan peraturan-peraturan-Ku tidak kamu lakukan; bahkan engkau melakukan peraturan-peraturan bangsa-bangsa yang di sekitarmu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 13, 'Maka sedang aku bernubuat, matilah Pelaca bin Benaya. Lalu aku sujud dan berseru dengan suara nyaring, kataku: "Aduh, Tuhan ALLAH, apakah Engkau menghabiskan sisa Israel?"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 14, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 15, '"Hai anak manusia, penduduk-penduduk Yerusalem berkata tentang semua saudara-saudaramu, tentang kaum kerabatmu dan segenap kaum Israel dalam keseluruhannya: Mereka telah jauh dari TUHAN, kepada kami tanah ini diberikan menjadi milik.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 16, 'Oleh sebab itu katakanlah: Beginilah firman Tuhan ALLAH: Walaupun Aku membawa mereka jauh-jauh di antara bangsa-bangsa dan menyerakkan mereka di negeri-negeri itu dan Aku menjadi tempat kudus yang sedikit artinya bagi mereka di negeri-negeri di mana mereka datang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 17, 'oleh sebab itu katakanlah: Beginilah firman Tuhan ALLAH: Aku akan menghimpunkan kamu dari bangsa-bangsa dan mengumpulkan kamu dari negeri-negeri di mana kamu berserak, dan Aku akan memberikan kamu tanah Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 18, 'Maka sesudah mereka datang di sana, mereka akan menjauhkan segala dewa-dewanya yang menjijikkan dan segala perbuatan-perbuatan yang keji dari tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 19, 'Aku akan memberikan mereka hati yang lain dan roh yang baru di dalam batin mereka; juga Aku akan menjauhkan dari tubuh mereka hati yang keras dan memberikan mereka hati yang taat,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 20, 'supaya mereka hidup menurut segala ketetapan-Ku dan peraturan-peraturan-K dengan setia; maka mereka akan menjadi umat-Ku dan Aku akan menjadi Allah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 21, 'Mengenai mereka, yang hatinya berpaut pada dewa-dewanya yang menjijikkan dan pada perbuatan-perbuatannya yang keji, Aku akan menimpakan kelakuan mereka atas kepalanya sendiri, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 22, 'Maka kerub-kerub itu mengangkat sayap mereka, dan roda-rodanya bergerak bersama-sama dengan mereka, sedang kemuliaan Allah Israel berada di atas mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 23, 'Lalu kemuliaan TUHAN naik ke atas dari tengah-tengah kota dan hinggap di atas gunung yang di sebelah timur kota.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 24, 'Dan Roh itu mengangkat aku dan membawa aku kembali di dalam penglihatan yang dari Roh Allah ke negeri Kasdim kepada para buangan. Lalu menghilanglah penglihatan yang kulihat itu dari padaku', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 11, 25, 'dan aku sampaikan kepada para buangan itu segala sesuatu yang diperlihatkan TUHAN kepadaku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 1, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 2, '"Hai anak manusia, engkau tinggal di tengah-tengah kaum pemberontak, yang mempunyai mata untuk melihat, tetapi tidak melihat dan mempunyai telinga untuk mendengar, tetapi tidak mendengar, sebab mereka adalah kaum pemberontak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 3, 'Maka engkau, anak manusia, sediakanlah bagimu barang-barang seorang buangan dan berjalanlah seperti seorang buangan pada siang hari di hadapan mata mereka; pergilah dari tempatmu sekarang ke tempat yang lain seperti seorang buangan di hadapan mata mereka. Barangkali mereka akan insaf bahwa mereka adalah kaum pemberontak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 4, 'Bawalah barang-barangmu itu ke luar seperti barang-barang seorang buangan pada siang hari di hadapan mata mereka; dan engkau sendiri harus keluar pada malam hari di hadapan mata mereka, seperti seorang yang harus keluar dan pergi ke pembuangan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 5, 'Di hadapan mata mereka perbuatlah sebuah lobang di tembok dan keluarlah dari situ.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 6, 'Di hadapan mata mereka taruhlah barang-barangmu ke atas bahumu, dan bawalah itu ke luar pada malam gelap; engkau harus menutupi mukamu, sehingga engkau tidak melihat tanah; sebab Aku membuat engkau menjadi lambang bagi kaum Israel."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 7, 'Lalu kulakukan seperti diperintahkan kepadaku: aku membawa pada siang hari barang-barang seperti barang-barang seorang buangan dan pada malam hari aku membuat dengan tanganku sebuah lobang di tembok, pada malam gelap aku keluar dan di hadapan mata mereka aku menaruh barang-barangku ke atas bahuku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 8, 'Pada hari besoknya datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 9, '"Hai anak manusia, bukankah ditanya oleh kaum Israel, kaum pemberontak itu kepadamu: Apakah yang kaulakukan ini?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 10, 'Katakanlah kepada mereka: beginilah firman Tuhan ALLAH: Ucapan ilahi ini mengenai raja di Yerusalem dan seluruh kaum Israel yang tinggal di sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 11, 'Katakanlah: Aku menjadi lambang bagimu; seperti yang kulakukan ini begitulah akan berlaku kepada mereka: sebagai orang buangan mereka akan pergi ke pembuangan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 12, 'Dan raja yang di tengah-tengah mereka akan menaruh barang-barangnya ke atas bahunya pada malam gelap dan akan pergi ke luar; orang akan membuat sebuah lobang di tembok supaya ada baginya jalan keluar; ia akan menutupi mukanya supaya ia tidak akan melihat tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 13, 'Aku akan memasang jaring-Ku untuk menangkap dia dan di dalam perangkap-Ku dia akan terjebak dan Aku akan membawa dia ke Babel, tanah orang Kasdim, tetapi tanah itu sendiri tidak akan dilihatnya; ia akan mati di sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 14, 'Dan semua yang di sekitarnya, para pembantunya dan bala tentaranya, akan Kuhamburkan ke semua mata angin dan Aku akan menghunus pedang dari belakang mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 15, 'Maka mereka akan mengetahui bahwa Akulah TUHAN, apabila aku menyerakkan mereka di antara bangsa-bangsa dan menghamburkan mereka ke semua negeri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 16, 'Tetapi Aku akan meninggalkan sedikit dari mereka yang luput dari pedang, dari kelaparan dan dari sampar, supaya mereka menceriterakan segala perbuatan-perbuatan mereka yang keji di antara bangsa-bangsa, di mana mereka datang; dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 17, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 18, '"Hai anak manusia, makanlah makananmu dengan gemetar dan minumlah air dengan menggigil dan dengan hati yang cemas,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 19, 'dan katakanlah kepada penduduk negeri ini: Beginilah firman Tuhan ALLAH tentang penduduk Yerusalem yang di tanah Israel: Mereka akan makan makanannya dengan hati yang cemas dan minum air dengan hati yang gundah-gulana supaya tanah mereka menjadi sunyi sepi lantaran isinya sudah lenyap, oleh karena kekerasan yang dilakukan oleh semua yang tinggal di sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 20, 'Kota-kota yang masih didiami orang akan menjadi reruntuhan dan tanah itu akan menjadi sunyi sepi; dan kamu akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 21, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 22, '"Hai anak manusia, sindiran apakah itu yang hidup di antara kamu di tanah Israel, yang berbunyi: Sudah lama berselang, tetapi satu penglihatanpun tak jadi?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 23, 'Oleh karena itu katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Aku akan menghentikan sindiran ini dan orang tidak akan mengucapkannya lagi di tanah Israel. Sebaliknya, katakanlah kepada mereka: Waktunya sudah dekat dan tiap penglihatan akan jadi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 24, 'Sebab tidak akan ada lagi penglihatan yang menipu ataupun tenungan yang menyesatkan di tengah-tengah kaum Israel,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 25, 'sebab Aku, TUHAN, akan berfirman dan apa yang Kufirmankan akan terjadi, dan firman itu tidak akan ditunda-tunda lagi, sebab pada masa hidupmu, hai kaum pemberontak, Aku akan mengucapkan suatu firman dan Aku akan menggenapinya, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 26, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 27, '"Hai anak manusia, lihatlah, kaum Israel berkata: Penglihatan yang dilihatnya itu, harinya masih jauh, nubuatan yang diucapkannya, waktunya masih lama.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 12, 28, 'Oleh karena itu katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Tidak satupun dari firman-Ku akan ditunda-tunda. Apa yang Kufirmankan akan terjadi, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 1, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 2, '"Hai anak manusia, bernubuatlah melawan nabi-nabi Israel, bernubuatlah dan katakanlah kepada mereka yang bernubuat sesuka hatinya saja: Dengarlah firman TUHAN!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 3, 'Beginilah firman Tuhan ALLAH: Celakalah nabi-nabi yang bebal yang mengikuti bisikan hatinya sendiri dan yang tidak melihat sesuatu penglihatan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 4, 'Seperti anjing hutan di tengah-tengah reruntuhan, begitulah nabi-nabimu, hai Israel!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 5, 'Kamu tidak mempertahankan lobang-lobang pada tembokmu dan tidak mendirikan tembok sekeliling rumah Israel, supaya mereka dapat tetap berdiri di dalam peperangan pada hari TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 6, 'Penglihatan mereka menipu dan tenungan mereka adalah bohong; mereka berkata: Demikianlah firman TUHAN, padahal TUHAN tidak mengutus mereka, dan mereka menanti firman itu digenapi-Nya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 7, 'Bukankah penglihatan tipuan yang kamu lihat dan tenungan bohong yang kamu katakan, kalau kamu berkata: Demikianlah firman TUHAN, padahal Aku tidak berbicara?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 8, 'Sebab itu, beginilah firman Tuhan ALLAH, oleh karena kamu mengatakan kata-kata dusta dan melihat perkara-perkara bohong, maka Aku akan menjadi lawanmu, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 9, 'Aku akan mengacungkan tangan-Ku melawan nabi-nabi yang melihat perkara-perkara yang menipu dan yang mengucapkan tenungan-tenungan bohong; mereka tidak termasuk perkumpulan umat-Ku dan tidak akan tercatat dalam daftar kaum Israel, dan tidak akan masuk lagi di tanah Israel; dan kamu akan mengetahui bahwa Akulah Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 10, 'Oleh karena, ya sungguh karena mereka menyesatkan umat-Ku dengan mengatakan: Damai sejahtera!, padahal sama sekali tidak ada damai sejahtera?mereka itu mendirikan tembok dan lihat, mereka mengapurnya?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 11, 'katakanlah kepada mereka yang mengapur tembok itu: Hujan lebat akan membanjir, rambun akan jatuh dan angin tofan akan bertiup!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 12, 'Kalau tembok itu sudah runtuh, apakah orang tidak akan berkata kepadamu: Di mana sekarang kapur, yang kamu oleskan itu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 13, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Di dalam amarah-Ku Aku akan membuat angin tofan bertiup dan di dalam murka-Ku hujan lebat akan membanjir, dan di dalam amarah-Ku rambun yang membinasakan akan jatuh.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 14, 'Dan Aku akan meruntuhkan tembok yang kamu kapur itu dan merobohkannya ke tanah, supaya dasarnya menjadi kelihatan; tembok kota itu akan runtuh dan kamu akan tewas di dalamnya. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 15, 'Begitulah Aku akan melampiaskan amarah-Ku atas tembok itu dan kepada mereka yang mengapurnya dan Aku akan berkata kepadamu: Lenyap temboknya dan lenyap orang-orang yang mengapurnya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 16, 'yaitu nabi-nabi Israel yang bernubuat tentang Yerusalem dan melihat baginya suatu penglihatan mengenai damai sejahtera, padahal sama sekali tidak ada damai sejahtera, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 17, '"Engkau anak manusia, tujukanlah mukamu kepada kaum perempuan bangsamu yang bernubuat sesuka hatinya saja dan bernubuatlah melawan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 18, 'Katakanlah: Beginilah firman Tuhan ALLAH: Celakalah dukun-dukun perempuan, yang mengikatkan tali-tali azimat pada semua pergelangan dan mengenakan selubung pada kepala semua orang, tua atau muda, untuk menangkap jiwa orang. Apakah kamu hendak menangkap jiwa orang yang termasuk umat-Ku dan membiarkan orang-orang lain hidup untuk kepentinganmu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 19, 'Kamu melanggar kekudusan-Ku di tengah-tengah umat-Ku hanya demi beberapa genggam jelai dan beberapa potong roti, dengan membunuh orang-orang yang tidak patut mati, dan membiarkan hidup orang-orang yang tidak patut hidup, dalam hal kamu berbohong kepada umat-Ku yang sedia mendengar bohong.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 20, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Aku akan menentang tali-tali azimatmu, dengan mana kamu menangkap jiwa orang dan Aku akan mengoyakkannya dari tanganmu dan melepaskan seperti burung-burung, orang-orang yang kamu tangkap.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 21, 'Aku akan mengoyakkan selubungmu dan akan melepaskan umat-Ku dari tanganmu dan mereka tidak lagi menjadi mangsa di dalam tanganmu. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 22, 'Oleh karena kamu melemahkan hati orang benar dengan dusta, sedang Aku tidak mendukakan hatinya, dan sebaliknya kamu mengeraskan hati orang fasik, sehingga ia tidak bertobat dari kelakuannya yang fasik itu, dan kamu membiarkan dia hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 13, 23, 'Oleh sebab itu kamu tidak lagi melihat perkara-perkara yang menipu dan mengucapkan tenungan-tenungan bohong; Aku akan melepaskan umat-Ku dari tanganmu dan kamu akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 1, 'Sesudah itu datanglah kepadaku beberapa orang dari tua-tua Israel dan duduk di hadapanku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 2, 'Maka datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 3, '"Hai anak manusia, orang-orang ini menjunjung berhala-berhala mereka dalam hatinya dan menempatkan di hadapan mereka batu sandungan, yang menjatuhkan mereka ke dalam kesalahan. Apakah Aku mau mereka meminta petunjuk dari pada-Ku?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 4, 'Oleh sebab itu berbicaralah kepada mereka dan katakan: Beginilah firman Tuhan ALLAH: Setiap orang dari kaum Israel yang menjunjung berhala-berhalanya dalam hatinya dan menempatkan di hadapannya batu sandungan yang menjatuhkannya ke dalam kesalahan, lalu datang menemui nabi?Aku, TUHAN sendiri akan menjawab dia oleh karena berhala-berhalanya yang banyak itu,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 5, 'supaya Aku memikat hati kaum Israel, yang seluruhnya sudah menyimpang dari pada-Ku dengan mengikuti segala berhala-berhala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 6, 'Oleh karena itu katakanlah kepada kaum Israel: Beginilah firman Tuhan ALLAH: Bertobatlah dan berpalinglah dari berhala-berhalamu dan palingkanlah mukamu dari segala perbuatan-perbuatanmu yang keji.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 7, 'Karena setiap orang, baik dari kaum Israel maupun dari orang-orang asing yang tinggal di tengah-tengah Israel, yang menyimpang dari pada-Ku dan menjunjung berhala-berhalanya dalam hatinya dan menempatkan di hadapannya batu sandungan, yang menjatuhkannya ke dalam kesalahan, lalu datang menemui nabi untuk meminta petunjuk dari pada-Ku baginya?Aku, TUHAN sendiri akan menjawab dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 8, 'Aku sendiri akan menentang orang itu dan Aku akan membuat dia menjadi lambang dan kiasan dan melenyapkannya dari tengah-tengah umat-Ku. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 9, 'Jikalau nabi itu membiarkan dirinya tergoda dengan mengatakan suatu ucapan?Aku, TUHAN yang menggoda nabi itu?maka Aku akan mengacungkan tangan-Ku melawan dia dan memunahkannya dari tengah-tengah umat-Ku Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 10, 'Mereka akan menanggung kesalahannya sendiri, baik yang meminta petunjuk maupun nabi,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 11, 'supaya kaum Israel jangan lagi sesat dari pada-Ku dan jangan lagi menajiskan dirinya dengan segala pelanggaran mereka; dengan demikian mereka akan menjadi umat-Ku dan Aku akan menjadi Allah mereka, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 12, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 13, '"Hai anak manusia, kalau sesuatu negeri berdosa kepada-Ku dengan berobah setia dan Aku mengacungkan tangan-Ku melawannya dengan memusnahkan persediaan makanannya dan mendatangkan kelaparan atasnya dan melenyapkan dari negeri itu manusia dan binatang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 14, 'biarpun di tengah-tengahnya berada ketiga orang ini, yaitu Nuh, Daniel dan Ayub, mereka akan menyelamatkan hanya nyawanya sendiri karena kebenaran mereka, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 15, 'Atau jikalau Aku membuat binatang buas berkeliaran di negeri itu, yang memunahkan penduduknya, sehingga negeri itu menjadi sunyi sepi, dan tidak seorangpun berani melintasinya karena binatang buas itu,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 16, 'dan biarpun di tengah-tengahnya berada ketiga orang tadi, demi Aku yang hidup, demikianlah firman Tuhan ALLAH, mereka tidak akan menyelamatkan baik anak-anak lelaki maupun anak-anak perempuan; hanya mereka sendiri akan diselamatkan, tetapi negeri itu akan menjadi sunyi sepi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 17, 'Atau jikalau Aku membawa pedang atas negeri itu dan Aku berfirman: Hai pedang, jelajahilah negeri itu!, dan Aku melenyapkan dari negeri itu manusia dan binatang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 18, 'dan biarpun di tengah-tengahnya berada ketiga orang tadi, demi Aku yang hidup, demikianlah firman Tuhan ALLAH, mereka tidak akan menyelamatkan baik anak-anak lelaki maupun anak-anak perempuan, tetapi hanya mereka sendiri akan diselamatkan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 19, 'Atau jikalau Aku mendatangkan sampar atas negeri itu dan Aku mencurahkan amarah-Ku atasnya sehingga darah mengalir dengan melenyapkan dari negeri itu manusia dan binatang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 20, 'dan biarpun Nuh, Daniel dan Ayub berada di tengah-tengahnya, demi Aku yang hidup, demikianlah firman Tuhan ALLAH, mereka tidak akan menyelamatkan baik anak laki-laki maupun anak perempuan, melainkan mereka akan menyelamatkan hanya nyawanya sendiri karena kebenaran mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 21, 'Ya, beginilah firman Tuhan ALLAH: Jauh lebih dari itu, kalau Aku mendatangkan keempat hukuman-Ku yang berat-berat, yaitu pedang, kelaparan, binatang buas dan sampar, atas Yerusalem untuk melenyapkan dari padanya manusia dan binatang!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 22, 'Tetapi sungguh, akan tertinggal di sana orang yang terluput, yang mengiring ke luar anak-anak lelaki dan perempuan; lihat, mereka akan datang kepadamu dan kamu akan melihat tingkah laku mereka dan kamu akan merasa terhibur tentang malapetaka yang Kudatangkan atas Yerusalem, ya tentang segala-galanya yang Kudatangkan atasnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 14, 23, 'Mereka akan menghibur kamu, kalau kamu melihat tingkah lakunya, dan kamu akan mengetahui bahwa bukan tanpa alasan Kuperbuat segala sesuatu yang Kuperbuat atas Yerusalem, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 1, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 2, '"Hai anak manusia, apakah kelebihan kayu anggur dari semua kayu yang buahnya seperti anggur yang tumbuh di antara kayu-kayu di hutan?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 3, 'Apakah orang mengambil kayunya untuk membuat sesuatu dari padanya ataukah membuat gantungan dari padanya untuk menggantungkan segala macam perkakas padanya?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 4, 'Sungguh, kayu itu dilemparkan ke dalam api untuk dibakar; kedua ujungnya habis dimakan api dan tengah-tengahnya sedang menyala, bergunakah lagi itu untuk membuat sesuatu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 5, 'Lihat, sedangkan waktu ia masih utuh, tidak dipakai untuk sesuatu, apalagi sesudah dimakan api dan terbakar; apakah masih dapat lagi dipakai untuk sesuatu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 6, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Seperti kayu anggur di antara kayu-kayu di hutan, yang Kulemparkan ke dalam api untuk dibakar, begitulah Aku lakukan terhadap penduduk Yerusalem.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 7, 'Aku sendiri akan menentang mereka. Walaupun mereka luput dari api, tetapi api akan memakan mereka. Dan kamu akan mengetahui bahwa Akulah TUHAN, pada saat Aku menentang mereka', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 15, 8, 'dan Aku menjadikan negeri itu sunyi sepi, oleh karena mereka berobah setia, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 1, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 2, '"Hai anak manusia, beritahukanlah kepada Yerusalem perbuatan-perbuatannya yang keji', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 3, 'dan katakanlah: Beginilah firman Tuhan ALLAH kepada Yerusalem: Asalmu dan kelahiranmu ialah dari tanah Kanaan; ayahmu ialah orang Amori dan ibumu orang Heti.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 4, 'Kelahiranmu begini: Waktu engkau dilahirkan, pusatmu tidak dipotong dan engkau tidak dibasuh dengan air supaya bersih; juga dengan garampun engkau tidak digosok atau dibedungi dengan lampin.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 5, 'Tidak seorangpun merasa sayang kepadamu sehingga diperbuatnya hal-hal itu kepadamu dari rasa belas kasihan; malahan engkau dibuang ke ladang, oleh karena orang pandang enteng kepadamu pada hari lahirmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 6, 'Maka Aku lalu dari situ dan Kulihat engkau menendang-nendang dengan kakimu sambil berlumuran darah dan Aku berkata kepadamu dalam keadaan berlumuran darah itu: Engkau harus hidup', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 7, 'dan jadilah besar seperti tumbuh-tumbuhan di ladang! Engkau menjadi besar dan sudah cukup umur, bahkan sudah sampai pada masa mudamu. Maka buah dadamu sudah montok, rambutmu sudah tumbuh, tetapi engkau dalam keadaan telanjang bugil.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 8, 'Maka Aku lalu dari situ dan Aku melihat engkau, sungguh, engkau sudah sampai pada masa cinta berahi. Aku menghamparkan kain-Ku kepadamu dan menutupi auratmu. Dengan sumpah Aku mengadakan perjanjian dengan engkau, demikianlah firman Tuhan ALLAH, dan dengan itu engkau Aku punya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 9, 'Aku membasuh engkau dengan air untuk membersihkan darahmu dari padamu dan Aku mengurapi engkau dengan minyak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 10, 'Aku mengenakan pakaian berwarna-warna kepadamu dan memberikan engkau sandal-sandal dari kulit lumba-lumba dan tutup kepala dari lenan halus dan selendang dari sutera.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 11, 'Dan Aku menghiasi engkau dengan perhiasan-perhiasan dan mengenakan gelang pada tanganmu dan kalung pada lehermu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 12, 'Dan Aku mengenakan anting-anting pada hidungmu dan anting-anting pada telingamu dan mahkota kemuliaan di atas kepalamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 13, 'Dengan demikian engkau menghias dirimu dengan emas dan perak, pakaianmu lenan halus dan sutera dan kain berwarna-warna; makananmu ialah tepung yang terbaik, madu dan minyak dan engkau menjadi sangat cantik, sehingga layak menjadi ratu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 14, 'Dan namamu termasyhur di antara bangsa-bangsa karena kecantikanmu, sebab sangat sempurna adanya, oleh karena semarak perhiasan-Ku yang Kuberikan kepadamu, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 15, '"Tetapi engkau mengandalkan kecantikanmu dan engkau seumpama bersundal dalam menganggarkan ketermasyhuranmu dan engkau menghamburkan persundalanmu kepada setiap orang yang lewat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 16, 'Engkau mengambil dari pakaian-pakaianmu untuk membuat bukit-bukit pengorbananmu berwarna-warni dan engkau bersundal di situ; seperti itu belum pernah terjadi dan tidak akan ada lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 17, 'Engkau mengambil juga perhiasan-perhiasanmu yang dibuat dari emas-Ku dan perak-Ku, yang Kuberikan kepadamu, dan engkau membuat bagimu patung-patung lelaki dan engkau bersundal dengan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 18, 'Engkau mengambil dari pakaianmu yang berwarna-warni untuk menutupi mereka dan engkau mempersembahkan kepada mereka minyak-Ku dan ukupan-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 19, 'Juga makanan-Ku yang Kuberikan kepadamu?tepung yang terbaik, minyak dan madu Kuberikan makananmu?engkau persembahkan kepada mereka menjadi persembahan yang harum, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 20, 'Bahkan, engkau mengambil anak-anakmu lelaki dan perempuan yang engkau lahirkan bagi-Ku dan mempersembahkannya kepada mereka menjadi makanan mereka. Apakah persundalanmu ini masih perkara enteng', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 21, 'bahwa engkau menyembelih anak-anak-Ku dan menyerahkannya kepada mereka dengan mempersembahkannya sebagai korban dalam api?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 22, 'Dalam segala perbuatan-perbuatanmu yang keji dan persundalanmu itu engkau tidak teringat lagi kepada masa mudamu, waktu engkau telanjang bugil sambil menendang-nendang dengan kakimu dalam lumuran darahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 23, 'Dan sesudah segala kejahatanmu itu?celaka, celakalah engkau! Demikianlah firman Tuhan ALLAH?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 24, 'engkau membangun bagimu tempat yang tinggi dan membuat bagimu bukit pengorbanan di tiap-tiap tanah lapang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 25, 'Pada setiap persimpangan jalan engkau membangun bukit pengorbanan dan menjual kecantikanmu menjadi kekejian dengan merenggangkan kedua pahamu bagi setiap orang yang lewat, sehingga persundalanmu bertambah-tambah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 26, 'Engkau bersundal dengan orang Mesir, tetanggamu, si aurat besar itu, sehingga persundalanmu bertambah-tambah, yang menimbulkan sakit hati-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 27, 'Lihat, Aku telah melawan engkau dan telah mengurangi bagianmu dan menyerahkan engkau kepada kesewenang-wenangan orang-orang yang membenci engkau, yaitu perempuan-perempuan Filistin, yang merasa malu melihat tingkah lakumu yang mesum itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 28, 'Engkau bersundal juga dengan orang Asyur, oleh karena engkau belum merasa puas; ya, engkau bersundal dengan mereka, tetapi masih belum merasa puas.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 29, 'Engkau memperbanyak lagi persundalanmu dengan negeri perdagangan Kasdim, tetapi dengan itu juga engkau belum merasa puas.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 30, 'Betapa besar hawa nafsumu itu, demikianlah firman Tuhan ALLAH, engkau yang melakukan segala-galanya ini, yaitu perbuatan seorang perempuan sundal jahanam,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 31, 'yang membangun tempatmu yang tinggi pada setiap persimpangan jalan dan membuat bukit pengorbananmu di tiap-tiap tanah lapang. Tetapi engkau tidak seperti sundal biasa, oleh karena engkau menolak upah sundal.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 32, 'Hai isteri yang berzinah, yang memeluk orang-orang lain ganti suaminya sendiri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 33, 'Kepada semua perempuan sundal orang memberi upah, tetapi engkau sebaliknya, engkau yang memberi hadiah umpan kepada semua yang mencintai engkau sebagai bujukan, supaya mereka dari sekitarmu datang kepadamu untuk bersundal.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 34, 'Maka dalam persundalanmu engkau adalah kebalikan dari perempuan-perempuan yang lain; bukan orang yang mengejar engkau hendak bersundal; tetapi engkau yang memberi upah persundalan, sedang engkau tidak diberi apa-apa; itulah kebalikannya padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 35, 'Oleh karena itu, hai perempuan sundal, dengarkanlah firman TUHAN!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 36, 'Beginilah firman Tuhan ALLAH: Oleh karena engkau menghamburkan kemesumanmu dan auratmu disingkapkan dalam persundalanmu dengan orang yang mencintaimu dan dengan berhala-berhalamu yang keji dan oleh karena darah anak-anakmu yang engkau persembahkan kepada mereka,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 37, 'sungguh, oleh karena itu Aku akan mengumpulkan semua kekasihmu, yaitu yang merayu hatimu, baik yang engkau cintai maupun yang engkau benci; Aku akan mengumpulkan mereka dari sekitarmu untuk melawan engkau dan Aku akan menyingkapkan auratmu di hadapan mereka, sehingga mereka melihat seluruh kemaluanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 38, 'Aku akan menghakimi engkau seperti orang menghakimi perempuan-perempuan yang berzinah dan yang menumpahkan darah dan Aku akan melampiaskan atasmu murka dan cemburuan-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 39, 'Aku akan menyerahkan engkau di dalam tangan mereka dan mereka akan meruntuhkan tempatmu yang tinggi dan merusakkan bukit-bukitmu, mereka akan menelanjangi engkau, akan merampas perhiasan-perhiasanmu dan membiarkan engkau telanjang bugil.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 40, 'Mereka akan menyuruh bangkit sekumpulan orang melawan engkau, yang melempari engkau dengan batu dan memancung engkau dengan pedang-pedang mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 41, 'Mereka akan membakar rumah-rumahmu dan menjatuhkan hukuman kepadamu di hadapan banyak perempuan. Dengan demikian Aku membuat engkau berhenti bersundal dan upah sundal tidak akan kauberikan lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 42, 'Demikianlah Aku melampiaskan murka-Ku kepadamu sehingga cemburu-Ku kepadamu reda kembali; barulah Aku merasa tenang dan tidak sakit hati lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 43, 'Oleh karena engkau tidak teringat lagi kepada masa mudamu, tetapi dengan semuanya ini membuat Aku gemetar kemarahan, sungguh, Aku juga akan menimpakan kelakuanmu atas kepalamu, demikianlah firman Tuhan ALLAH. Bukankah engkau melakukan kemesuman ini lagi di samping segala perbuatan-perbuatanmu yang keji?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 44, 'Lihat, setiap penyair akan mengatakan sindiran ini mengenai engkau: Begitu ibu, begitu anak!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 45, 'Anak ibumu engkau, yang jijik melihat suaminya dan anak-anaknya lelaki, dan adik kakak-kakakmu perempuan engkau, yang jijik melihat suami-suami mereka dan anak-anak mereka lelaki. Ibumu adalah orang Heti dan ayahmu adalah orang Amori.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 46, 'Kakakmu yang tertua ialah Samaria, yang beserta anak-anaknya perempuan diam di sebelah utaramu, dan kakakmu yang termuda ialah Sodom, yang beserta anak-anaknya perempuan diam di sebelah selatanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 47, 'Bukankah engkau hidup menurut perbuatan mereka dan engkau lakukan seperti perbuatan-perbuatan mereka yang keji; sebentar lagi saja engkau berbuat lebih jahat dari mereka dalam seluruh hidupmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 48, 'Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, sesungguh-sungguhnya Sodom, kakakmu yang termuda beserta anak-anaknya perempuan tidak berbuat seperti engkau lakukan beserta anak-anakmu perempuan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 49, 'Lihat, inilah kesalahan Sodom, kakakmu yang termuda itu: kecongkakan, makanan yang berlimpah-limpah dan kesenangan hidup ada padanya dan pada anak-anaknya perempuan, tetapi ia tidak menolong orang-orang sengsara dan miskin.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 50, 'Mereka menjadi tinggi hati dan melakukan kekejian di hadapan-Ku; maka Aku menjauhkan mereka sesudah Aku melihat itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 51, 'Dan Samaria tidak membuat setengahpun dari dosa-dosamu, bahkan engkau melakukan lebih banyak kekejian dari mereka berdua, sehingga dengan segala kekejian-kekejianmu yang engkau lakukan, engkau membuat kakak-kakakmu perempuan kelihatan benar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 52, 'Tanggunglah nodamu, hai engkau, yang mengakibatkan hukuman lebih ringan kepada kakak-kakakmu perempuan; dengan dosa-dosamu yang lebih keji dari mereka, mereka lebih benar dari padamu. Biarlah engkau merasa malu dan tanggunglah nodamu, oleh karena engkau membuat kakak-kakakmu perempuan kelihatan benar."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 53, '"Tetapi Aku akan memulihkan keadaan mereka, baik keadaan Sodom bersama anak-anaknya perempuan maupun keadaan Samaria bersama anak-anaknya perempuan, dan juga Aku akan memulihkan keadaanmu di tengah-tengah mereka,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 54, 'supaya engkau menanggung nodamu dan supaya engkau merasa malu karena segala perbuatanmu, sehingga engkau menjadi penghiburan bagi mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 55, 'Mengenai kakak-kakakmu, Sodom bersama anak-anaknya perempuan akan dipulihkan ke dalam keadaannya semula; Samaria juga bersama anak-anaknya perempuan akan dipulihkan ke dalam keadaannya semula; dan engkaupun bersama anak-anakmu perempuan akan dipulihkan ke dalam keadaanmu semula.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 56, 'Bukankah Sodom, kakakmu yang termuda, menjadi buah bibirmu pada masa kecongkakanmu,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 57, 'sebelum kejahatanmu menjadi nyata, seperti pada saat ini engkau diaibkan oleh anak-anak perempuan Edom dengan semua yang di sekitarnya dan anak-anak perempuan Filistin, yang menghina engkau dari sekitarmu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 58, 'Kemesumanmu dan perbuatan-perbuatanmu yang keji harus engkau tanggung, demikianlah firman TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 59, 'Sebab beginilah firman Tuhan ALLAH: Aku akan melakukan kepadamu seperti engkau lakukan, yaitu engkau memandang ringan kepada sumpah dengan mengingkari perjanjian.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 16, 60, 'Tetapi Aku akan mengingat perjanjian-Ku dengan engkau pada masa mudamu dan Aku akan meneguhkan bagimu perjanjian yang kekal.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 1, 'Maka datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 2, '"Hai anak manusia, katakanlah suatu teka-teki dan ucapkanlah suatu perumpamaan kepada kaum Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 3, 'Katakanlah: Beginilah firman Tuhan ALLAH: Seekor burung rajawali yang besar dengan sayapnya yang besar dan panjang, penuh dengan bulu yang berwarna-warna datang ke gunung Libanon dan ia mengambil puncak pohon aras.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 4, 'Ia mematahkan pucuknya yang paling ujung dan dibawanya ke sebuah negeri perdagangan lalu diletakkannya dia di kota perniagaan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 5, 'Ia mengambil sebuah dari taruk-taruk tanah itu dan menanamnya di ladang yang sudah sedia ditaburi; ia menempatkannya dekat air yang berlimpah-limpah seperti pohon gandarusa', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 6, 'sehingga ia tumbuh dan menjadi pohon anggur yang rimbun, yang tumbuhnya rendah dan cabang-cabangnya melengkung menuju burung itu dan akar-akarnya tetap di bawahnya. Demikianlah ia menjadi pohon anggur dan mengeluarkan tunas-tunas dan memancarkan taruk-taruk.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 7, 'Dalam pada itu ada juga burung rajawali besar yang lain dengan sayapnya yang besar dan bulu yang lebat. Dan sungguh, pohon anggur ini mengarahkan akar-akarnya ke burung itu dan cabang-cabangnya dijulurkannya kepadanya, supaya burung itu mengairi dia lebih baik dari bedeng di mana ia ditanam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 8, 'Namun ia ditanam di ladang yang baik, dekat air yang berlimpah-limpah, supaya ia bercabang-cabang dan berbuah dan supaya menjadi pohon anggur yang bagus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 9, 'Katakanlah: Beginilah firman Tuhan ALLAH: Apakah itu akan berhasil? Apakah orang tidak akan mencabut akar-akarnya dan menyentakkan buahnya, sehingga semua ulamnya yang baru menjadi kering? Tidak usah tangan yang kuat dan banyak orang untuk mencabut dia dengan akar-akarnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 10, 'Lihat, ia memang ditanam, tetapi apakah ia akan memberi hasil? Apakah ia tidak akan layu kering kalau ditimpa angin timur? Ia akan layu kering di bedeng tempat tumbuhnya itu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 11, 'Maka datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 12, '"Katakanlah kepada kaum pemberontak: Tidakkah kamu mengetahui apa artinya ini? Katakan: Lihat, raja Babel datang ke Yerusalem dan ia mengambil rajanya dan pemuka-pemukanya dan membawa mereka ke Babel baginya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 13, 'Lalu ia mengambil seorang yang berasal dari keturunan raja dan mengadakan perjanjian dengan dia sambil menyuruh dia bersumpah. Ia mengambil juga orang-orang berkuasa negeri itu,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 14, 'supaya kerajaan itu menjadi lemah dan jangan memberontak lagi, juga supaya memegang teguh perjanjian itu dan dengan demikian tetap ada.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 15, 'Tetapi orang itu memberontak kepadanya dengan menyuruh utusannya ke Mesir, supaya ia diberi kuda dan tentara yang besar. Apakah ia akan berhasil? Apakah orang yang berbuat demikian dapat luput? Apakah orang yang mengingkari perjanjian dapat luput?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 16, 'Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, ia pasti mati di Babel, di tempat raja yang mengangkatnya menjadi raja. Karena ia memandang ringan kepada sumpah yang dimintakan raja itu dari padanya dan mengingkari perjanjian raja itu dengan dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 17, 'Dan Firaun tidak akan membantu dia dalam peperangan dengan tentara yang besar dan sekumpulan banyak orang, pada waktu tembok pengepungan ditimbun dan benteng pengepungan didirikan untuk melenyapkan banyak orang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 18, 'Ya, ia memandang ringan kepada sumpah dan mengingkari perjanjian. Sungguh, walaupun ia menyungguhkan hal itu dengan berjabat tangan, tetapi ia melanggar semuanya itu, maka ia tidak dapat luput.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 19, 'Oleh sebab itu, beginilah firman Tuhan ALLAH: Demi Aku yang hidup, Aku pasti menimpakan atas kepalanya sumpahnya kepada-Ku, yang dipandangnya ringan dan perjanjiannya di hadapan-Ku, yang diingkarinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 20, 'Aku akan memasang jaring-Ku untuk menangkap dia dan di dalam perangkap-Ku ia akan terjebak; Aku akan membawa dia ke Babel dan di sana Aku akan berperkara dengan dia, karena ia berobah setia terhadap Aku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 21, 'Dan semua tentara pilihannya akan tewas dimakan pedang dan yang terluput akan dihamburkan ke semua mata angin. Dan kamu akan mengetahui bahwa Akulah TUHAN, yang mengatakannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 22, 'Beginilah firman Tuhan ALLAH: Aku sendiri akan mengambil sebuah carang dari puncak pohon aras yang tinggi dan menanamnya; Aku mematahkannya dari pucuk yang paling ujung dan yang masih muda dan Aku sendiri akan menanamnya di atas sebuah gunung yang menjulang tinggi ke atas;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 23, 'di atas gunung Israel yang tinggi akan Kutanam dia, agar ia bercabang-cabang dan berbuah dan menjadi pohon aras yang hebat; segala macam burung dan yang berbulu bersayap tinggal di bawahnya, mereka bernaung di bawah cabang-cabangnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 17, 24, 'Maka segala pohon di ladang akan mengetahui, bahwa Aku, TUHAN, merendahkan pohon yang tinggi dan meninggikan pohon yang rendah, membuat pohon yang tumbuh menjadi layu kering dan membuat pohon yang layu kering bertaruk kembali. Aku, TUHAN, yang mengatakannya dan akan membuatnya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 1, 'Maka datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 2, '"Ada apa dengan kamu, sehingga kamu mengucapkan kata sindiran ini di tanah Israel: Ayah-ayah makan buah mentah dan gigi anak-anaknya menjadi ngilu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 3, 'Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, kamu tidak akan mengucapkan kata sindiran ini lagi di Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 4, 'Sungguh, semua jiwa Aku punya! Baik jiwa ayah maupun jiwa anak Aku punya! Dan orang yang berbuat dosa, itu yang harus mati.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 5, 'Kalau seseorang adalah orang benar dan ia melakukan keadilan dan kebenaran,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 6, 'dan ia tidak makan daging persembahan di atas gunung atau tidak melihat kepada berhala-berhala kaum Israel, tidak mencemari isteri sesamanya dan tidak menghampiri perempuan waktu bercemar kain,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 7, 'tidak menindas orang lain, ia mengembalikan gadaian orang, tidak merampas apa-apa, memberi makan orang lapar, memberi pakaian kepada orang telanjang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 8, 'tidak memungut bunga uang atau mengambil riba, menjauhkan diri dari kecurangan, melakukan hukum yang benar di antara manusia dengan manusia,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 9, 'hidup menurut ketetapan-Ku dan tetap mengikuti peraturan-Ku dengan berlaku setia?ialah orang benar, dan ia pasti hidup, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 10, 'Tetapi kalau ia melahirkan seorang anak yang menjadi perampok, dan yang suka menumpahkan darah atau melakukan salah satu dari hal-hal itu', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 11, '?walaupun ayah tidak melakukan satupun?juga makan daging persembahan di atas gunung dan mencemari isteri sesamanya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 12, 'menindas orang sengsara dan miskin, merampas, tidak mengembalikan gadaian orang, melihat kepada berhala-berhala dan melakukan kekejian,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 13, 'memungut bunga uang dan mengambil riba, orang yang demikian tidak akan hidup. Segala kekejian ini dilakukannya, ia harus mati; darahnya tertimpa kepadanya sendiri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 14, 'Sesungguhnya, kalau ia melahirkan seorang anak dan anak ini melihat segala dosa yang dilakukan ayahnya, tetapi menginsafi hal itu, sehingga tidak melakukan seperti itu:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 15, 'ia tidak makan daging persembahan di atas gunung dan tidak melihat kepada berhala-berhala kaum Israel, tidak mencemari isteri sesamanya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 16, 'tidak menindas orang lain, tidak mau meminta gadai, tidak merampas apa-apa, memberi makan orang lapar, memberi pakaian kepada orang telanjang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 17, 'menjauhkan diri dari kecurangan, tidak mengambil bunga uang atau riba, melakukan peraturan-Ku dan hidup menurut ketetapan-Ku?orang yang demikian tidak akan mati karena kesalahan ayahnya, ia pasti hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 18, 'Ayahnya, yang melakukan pemerasan, yang merampas sesuatu, dan yang melakukan hal-hal yang tidak baik di tengah-tengah bangsanya, sungguh, ia akan mati karena kesalahannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 19, 'Tetapi kamu berkata: Mengapa anak tidak turut menanggung kesalahan ayahnya? ?Karena anak itu melakukan keadilan dan kebenaran, melakukan semua ketetapan-Ku dengan setia, maka ia pasti hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 20, 'Orang yang berbuat dosa, itu yang harus mati. Anak tidak akan turut menanggung kesalahan ayahnya dan ayah tidak akan turut menanggung kesalahan anaknya. Orang benar akan menerima berkat kebenarannya, dan kefasikan orang fasik akan tertanggung atasnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 21, 'Tetapi jikalau orang fasik bertobat dari segala dosa yang dilakukannya dan berpegang pada segala ketetapan-Ku serta melakukan keadilan dan kebenaran, ia pasti hidup, ia tidak akan mati.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 22, 'Segala durhaka yang dibuatnya tidak akan diingat-ingat lagi terhadap dia; ia akan hidup karena kebenaran yang dilakukannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 23, 'Apakah Aku berkenan kepada kematian orang fasik? demikianlah firman Tuhan ALLAH. Bukankah kepada pertobatannya supaya ia hidup?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 24, 'Jikalau orang benar berbalik dari kebenarannya dan melakukan kecurangan seperti segala kekejian yang dilakukan oleh orang fasik?apakah ia akan hidup? Segala kebenaran yang dilakukannya tidak akan diingat-ingat lagi. Ia harus mati karena ia berobah setia dan karena dosa yang dilakukannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 25, 'Tetapi kamu berkata: Tindakan Tuhan tidak tepat! Dengarlah dulu, hai kaum Israel, apakah tindakan-Ku yang tidak tepat ataukah tindakanmu yang tidak tepat?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 26, 'Kalau orang benar berbalik dari kebenarannya dan melakukan kecurangan sehingga ia mati, ia harus mati karena kecurangan yang dilakukannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 27, 'Sebaliknya, kalau orang fasik bertobat dari kefasikan yang dilakukannya dan ia melakukan keadilan dan kebenaran, ia akan menyelamatkan nyawanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 28, 'Ia insaf dan bertobat dari segala durhaka yang dibuatnya, ia pasti hidup, ia tidak akan mati.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 29, 'Tetapi kaum Israel berkata: Tindakan Tuhan tidak tepat! Apakah tindakan-Ku yang tidak tepat, hai kaum Israel, ataukah tindakanmu yang tidak tepat?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 30, 'Oleh karena itu Aku akan menghukum kamu masing-masing menurut tindakannya, hai kaum Israel, demikianlah firman Tuhan ALLAH. Bertobatlah dan berpalinglah dari segala durhakamu, supaya itu jangan bagimu menjadi batu sandungan, yang menjatuhkan kamu ke dalam kesalahan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 31, 'Buangkanlah dari padamu segala durhaka yang kamu buat terhadap Aku dan perbaharuilah hatimu dan rohmu! Mengapakah kamu akan mati, hai kaum Israel?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 18, 32, 'Sebab Aku tidak berkenan kepada kematian seseorang yang harus ditanggungnya, demikianlah firman Tuhan ALLAH. Oleh sebab itu, bertobatlah, supaya kamu hidup!"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 1, 'Hai, ucapkanlah suatu ratapan mengenai raja Israel,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 2, 'dan katakanlah begini: "Betapa ibumu menjadi seekor singa betina di antara singa-singa! Ia berbaring di antara singa-singa muda, dan menyusui anak-anaknya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 3, 'Ia membesarkan seekor dari anak-anaknya, sehingga menjadi singa muda; ia belajar menerkam, malah manusia ditelannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 4, 'Bangsa-bangsa menyerukan: Singa mengamuk! akhirnya ia terjebak dalam pelubang mereka; mereka mengelikir dia dan menggiringnya ke Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 5, 'Sesudah induk singa menyadari bahwa usahanya gagal dan pengharapannya hilang lenyap, ia mengambil anaknya yang lain dan membesarkannya menjadi singa muda.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 6, 'Anaknya ini berjalan-jalan di antara kawanan singa, ia menjadi seekor singa muda; ia belajar menerkam, malah manusia ditelannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 7, 'Ia merusak puri-puri mereka dan menumpas kota-kotanya; bumi serta segala isinya diam ketakutan mendengar suara aumnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 8, 'Maka bangsa-bangsa bangkit melawan dia dari daerah-daerah sekelilingnya, mereka memasang jaring untuk menangkapnya dan menjebaknya dalam pelubang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 9, 'Ia dikurung dalam kandang, sambil dikelikir, dibawa ke hadapan raja Babel dan dimasukkan dalam penjara, supaya suaranya jangan kedengaran lagi di atas gunung-gunung Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 10, 'Ibumu seperti pohon anggur dalam kebun anggur, yang tertanam dekat air, berbuah dan bercabang karena air yang berlimpah-limpah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 11, 'Padanya tumbuh suatu cabang yang kuat yang menjadi tongkat kerajaan; ia menjulang tinggi di antara cabang-cabangnya yang rapat, dan menjadi kentara karena tingginya dan karena rantingnya yang banyak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 12, 'Tetapi ia tercabut di dalam kemarahan dan dilemparkan ke bumi; angin timur membuatnya layu kering, buahnya disentakkan, cabang yang kuat menjadi layu kering; dan api menghabiskannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 13, 'Dan sekarang ia tertanam di padang gurun, di tanah yang kering dan haus akan air.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 19, 14, 'Maka keluarlah api dari cabangnya yang memakan habis ranting dan buahnya, sehingga tiada lagi padanya cabang yang kuat dan tiada tongkat kerajaan." Ini adalah ratapan dan sudah menjadi ratapan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 1, 'Pada tahun ketujuh, dalam bulan yang kelima, pada tanggal sepuluh bulan itu, datanglah beberapa orang dari tua-tua Israel untuk meminta petunjuk dari pada TUHAN dan duduk di hadapanku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 2, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 3, '"Hai anak manusia, berbicaralah kepada tua-tua Israel dan katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Apakah kamu datang untuk meminta petunjuk dari pada-Ku? Demi Aku yang hidup, Aku tidak mau kamu meminta petunjuk dari pada-Ku, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 4, 'Maukah engkau menghakimi mereka, hai anak manusia, maukah engkau menghakimi mereka? Beritahukanlah kepada mereka perbuatan-perbuatan yang keji dari nenek moyang mereka,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 5, 'dan katakanlah kepadanya: Beginilah firman Tuhan ALLAH: Pada hari Aku memilih Israel, Aku bersumpah kepada keturunan kaum Yakub dan menyatakan diri kepada mereka di tanah Mesir; Aku bersumpah kepada mereka: Akulah TUHAN Allahmu!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 6, 'Pada hari itu Aku bersumpah kepada mereka untuk membawa mereka dari tanah Mesir ke tanah yang Kupilih baginya, negeri yang berlimpah-limpah susu dan madunya, tanah yang permai di antara semua negeri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 7, 'Dan Aku berkata kepada mereka: Biarlah setiap orang membuangkan dewa-dewanya yang menjijikkan, ke mana ia selalu melihat dan janganlah menajiskan dirimu dengan berhala-berhala Mesir; Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 8, 'Tetapi mereka memberontak terhadap Aku dan tidak mau mendengar kepada-Ku; setiap orang tidak membuangkan dewa-dewanya yang menjijikkan, ke mana ia selalu melihat, dan tidak meninggalkan berhala-berhala Mesir. Maka Aku bermaksud hendak mencurahkan amarah-Ku ke atas mereka untuk melampiaskan murka-Ku kepadanya di tengah-tengah tanah Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 9, 'Tetapi Aku bertindak oleh karena nama-Ku, supaya itu jangan dinajiskan di hadapan bangsa-bangsa, di mana mereka berada. Di hadapan bangsa-bangsa itu Aku menyatakan diri kepada mereka dalam hal Aku membawa mereka keluar dari tanah Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 10, 'Aku membawa mereka keluar dari tanah Mesir dan menuntun mereka ke padang gurun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 11, 'Di sana Aku memberikan kepada mereka ketetapan-ketetapan-Ku dan memberitahukan peraturan-peraturan-Ku, dan manusia yang melakukannya, akan hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 12, 'Hari-hari Sabat-Ku juga Kuberikan kepada mereka menjadi peringatan di antara Aku dan mereka, supaya mereka mengetahui bahwa Akulah TUHAN, yang menguduskan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 13, 'Tetapi kaum Israel memberontak terhadap Aku di padang gurun; mereka tidak hidup menurut ketetapan-ketetapan-Ku dan mereka menolak peraturan-peraturan-Ku, yang, kalau manusia melakukannya, ia akan hidup. Mereka juga melanggar kekudusan hari-hari Sabat-Ku dengan sangat. Maka Aku bermaksud hendak mencurahkan amarah-Ku ke atas mereka di padang gurun hendak membinasakan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 14, 'Tetapi Aku bertindak karena nama-Ku, supaya itu jangan dinajiskan di hadapan bangsa-bangsa, yang melihat sendiri waktu Aku membawa mereka ke luar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 15, 'Walaupun begitu Aku bersumpah kepadanya di padang gurun, bahwa Aku tidak akan membawa mereka masuk ke tanah yang telah Kuberikan kepada mereka, yang berlimpah-limpah susu dan madunya, tanah yang permai di antara semua negeri,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 16, 'oleh karena mereka menolak peraturan-peraturan-Ku dan tidak hidup menurut ketetapan-ketetapan-Ku dan melanggar kekudusan hari-hari Sabat-Ku; sebab hati mereka mengikuti berhala-berhala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 17, 'Tetapi Aku merasa sayang melihat mereka, sehingga Aku tidak membinasakannya dan tidak menghabisinya di padang gurun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 18, 'Maka Aku berkata kepada anak-anak mereka di padang gurun: Janganlah kamu hidup menurut ketetapan-ketetapan ayahmu dan janganlah berpegang pada peraturan-peraturan mereka dan janganlah menajiskan dirimu dengan berhala-berhala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 19, 'Akulah TUHAN, Allahmu: Hiduplah menurut ketetapan-ketetapan-Ku dan lakukanlah peraturan-peraturan-Ku dengan setia,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 20, 'kuduskanlah hari-hari Sabat-Ku, sehingga itu menjadi peringatan di antara Aku dan kamu, supaya orang mengetahui bahwa Akulah TUHAN, Allahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 21, 'Tetapi anak-anak mereka memberontak terhadap Aku, mereka tidak hidup menurut ketetapan-ketetapan-Ku dan tidak melakukan peraturan-peraturan-Ku dengan setia, sedang manusia yang melakukannya, akan hidup; mereka juga melanggar kekudusan hari-hari Sabat-Ku. Maka Aku bermaksud mencurahkan amarah-Ku ke atas mereka untuk melampiaskan murka-Ku kepadanya di padang gurun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 22, 'Tetapi Aku menarik tangan-Ku kembali dan bertindak karena nama-Ku, supaya itu jangan dinajiskan di hadapan bangsa-bangsa yang melihat sendiri waktu Aku membawa mereka ke luar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 23, 'Walaupun begitu Aku bersumpah kepadanya di padang gurun untuk menyerakkan mereka di antara bangsa-bangsa dan menghamburkan mereka ke semua negeri,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 24, 'oleh karena mereka tidak melakukan peraturan-peraturan-Ku dan menolak ketetapan-ketetapan-Ku dan melanggar kekudusan hari-hari Sabat-Ku dan matanya selalu tertuju kepada berhala-berhala ayah-ayah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 25, 'Begitulah Aku juga memberi kepada mereka ketetapan-ketetapan yang tidak baik dan peraturan-peraturan, yang karenanya mereka tidak dapat hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 26, 'Aku membiarkan mereka menjadi najis dengan persembahan-persembahan mereka, dalam hal mereka mempersembahkan sebagai korban dalam api semua yang terdahulu lahir dari kandungan, supaya Kubuat mereka tertegun, agar mereka mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 27, 'Oleh karena itu berbicaralah kepada kaum Israel, hai anak manusia, dan katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Dalam hal ini juga nenek moyangmu menghujat Aku, yaitu mereka berobah setia kepada-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 28, 'Sebab sesudah Aku membawa mereka ke negeri yang dengan sumpah telah Kujanjikan memberikannya kepada mereka, mereka melihat ke setiap bukit yang tinggi dan ke setiap pohon yang penuh cabang-cabang dan mereka mempersembahkan di sana korban sembelihannya dan membawa persembahannya yang menyakiti hati, juga menyerbakkan di sana persembahan-perse mereka yang harum dan mempersembahkan mereka di sana korban-korban curahan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 29, 'Maka Aku berkata kepada mereka: Tempat tinggi apa itu yang kamu naiki? Maka namanya disebut Tempat Tinggi sampai hari ini.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 30, 'Oleh sebab itu katakanlah kepada kaum Israel: Beginilah firman Tuhan ALLAH: Apakah kamu menajiskan dirimu juga dengan cara hidup nenek moyangmu dan berzinah dengan mengikuti dewa-dewanya yang menjijikkan?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 31, 'Dalam membawa persembahan-persembahanmu, yaitu mempersembahkan anak-anakmu sebagai korban dalam api, kamu menajiskan dirimu dengan segala berhala-berhalamu sampai hari ini, apakah Aku masih mau kamu minta petunjuk dari pada-Ku, hai kaum Israel? Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, Aku tidak mau lagi kamu minta petunjuk dari pada-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 32, 'Dan apa yang timbul dalam hatimu sama sekali tidak akan terjadi, yaitu yang kamu katakan: Kami ingin seperti bangsa-bangsa lain, seperti segala kaum di negeri-negeri untuk berbakti kepada pohon dan batu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 33, 'Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, Aku akan memerintah kamu dengan tangan yang kuat dan lengan yang teracung dan amarah yang tercurah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 34, 'Aku akan membawa kamu keluar dari tengah bangsa-bangsa dan mengumpulkan kamu dari negeri-negeri, di mana kamu berserak dengan tangan yang kuat dan lengan yang teracung dan amarah yang tercurah,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 35, 'dan Aku akan membawa kamu ke padang gurun bangsa-bangsa dan di sana Aku akan berperkara dengan kamu berhadapan muka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 36, 'Seperti Aku berperkara dengan nenek moyangmu di padang gurun tanah Mesir, begitulah Aku akan berperkara dengan kamu, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 37, 'Aku akan membiarkan kamu lewat dari bawah tongkat gembala-Ku dan memasukkan kamu ke kandang dengan menghitung kamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 38, 'Aku akan memisahkan dari tengah-tengahmu orang-orang yang memberontak dan mendurhaka terhadap Aku; Aku akan membawa mereka keluar dari negeri, tempat mereka tinggal sebagai orang asing, tetapi di tanah Israel mereka tidak akan masuk. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 39, 'Hai kamu, kaum Israel, beginilah firman Tuhan ALLAH, biarlah masing-masing pergi beribadah kepada berhala-berhalanya. Tetapi kemudian kamu akan mendengarkan Aku dan tidak lagi melanggar kekudusan nama-Ku yang kudus dengan persembahan-persembahanmu dan berhala-berhalamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 40, 'Sebab di atas gunung-Ku yang kudus, di atas gunung Israel yang tinggi, demikianlah firman Tuhan ALLAH, di sana di tanah itu segenap kaum Israel dalam keseluruhannya akan beribadah kepada-Ku. Di sana Aku akan berkenan kepadamu dan di sana Aku akan menuntut dari kamu persembahan-persembahan khususmu dan sajian-sajianmu yang terpilih, segala yang kamu kuduskan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 41, 'Seperti kepada persembahan yang harum Aku berkenan kepadamu pada waktu Aku mengeluarkan kamu dari tengah bangsa-bangsa dan mengumpulkan kamu dari negeri-negeri, di mana kamu berserak, dan Aku akan menunjukkan kekudusan-Ku kepadamu di hadapan bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 42, 'Dan kamu akan mengetahui bahwa Akulah TUHAN, pada waktu Aku membawa kamu masuk ke tanah Israel, ke negeri yang dengan sumpah telah Kujanjikan memberikannya kepada nenek moyangmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 43, 'Di sana kamu akan teringat-ingat kepada segala tingkah lakumu, dengan mana kamu menajiskan dirimu, dan kamu akan merasa mual melihat dirimu sendiri karena segala kejahatan-kejahatan yang kamu lakukan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 44, 'Dan kamu akan mengetahui bahwa Akulah TUHAN, pada masa Aku, oleh karena nama-Ku, tidak memperlakukan kamu selaras dengan tingkah lakumu yang jahat dan busuk, hai kaum Israel, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 45, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 46, '"Hai anak manusia, tujukanlah mukamu ke selatan dan ucapkanlah banyak tegoran terhadap tanah selatan dan bernubuatlah terhadap tanah kehutanan di sebelah selatan;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 47, 'dan katakanlah kepada hutan di sebelah selatan: Dengarlah firman TUHAN: Beginilah firman Tuhan ALLAH: Lihat, Aku akan menyalakan api di dalammu yang akan memakan habis setiap pohon yang hidup padamu dan setiap pohon yang layu kering. Apinya yang sedang bernyala-nyala tidak akan padam dan semua muka dari selatan sampai utara akan terbakar kepanasan olehnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 48, 'Dan setiap manusia akan melihat, bahwa Aku, Tuhanlah yang memasangnya; api itu tidak akan padam."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 20, 49, 'Lalu aku berkata: "Aduh, Tuhan ALLAH, mereka berkata tentang aku: Apakah ia tidak hanya mengucapkan kata-kata sindiran?"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 2, '"Hai anak manusia, tujukanlah mukamu ke Yerusalem dan ucapkanlah banyak tegoran terhadap tempat kudusnya dan bernubuatlah melawan tanah Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 3, 'Katakanlah kepada tanah Israel: Beginilah firman TUHAN: Lihat, Aku akan menjadi lawanmu dan akan mencabut pedang-Ku dari sarungnya dan melenyapkan dari tengah-tengahmu orang benar dan orang fasik.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 4, 'Oleh karena Aku hendak melenyapkan dari tengah-tengahmu orang benar dan orang fasik, maka pedang-Ku akan terhunus dari sarungnya terhadap semua manusia dari selatan sampai utara.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 5, 'Dan semua manusia akan mengetahui bahwa Aku, TUHAN, mencabut pedang-Ku dari sarungnya, sehingga tidak akan kembali lagi ke situ.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 6, 'Dan engkau anak manusia, mengeranglah! Mengeranglah di hadapan mereka seperti seorang yang tulang pinggangnya patah dan yang berada dalam kesengsaraan yang pahit.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 7, 'Dan kalau mereka bertanya kepadamu: Mengapa engkau mengeluh? jawablah: Karena suatu berita! Kalau berita itu sudah tersiar, setiap hati akan menjadi tawar dan semua tangan menjadi lemah lesu, segala semangat menghilang dan semua orang terkencing ketakutan. Sungguh, pasti datang dan terjadi! demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 8, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 9, '"Hai anak manusia, bernubuatlah dan katakan: Beginilah firman TUHAN: Pedang! Pedang! Yang sudah diasah dan juga digosok!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 10, 'Diasah untuk menumpahkan darah dan digosok supaya mengkilap seperti petir. Apakah kita akan bersukacita? ?Tongkat anakku menghina segala macam kayu. ?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 11, 'Pedang itu diberikan supaya digosok, supaya sedia dipergunakan; pedang itu diasah dan digosok, supaya diberikan ke tangan si pembunuh.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 12, 'Berserulah dan merataplah, hai anak manusia! Sebab pedang itu ditujukan melawan umat-Ku, ditujukan melawan semua pemimpin Israel; mereka dan umat-Ku sama-sama dibiarkan dimakan pedang. Oleh sebab itu tepuklah pinggangmu sebagai tanda perkabungan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 13, 'Sebab percobaan datang dan tidak suatupun yang dapat tahan, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 14, 'Dan engkau anak manusia, bernubuatlah dan tepuklah tanganmu, biarlah pedang itu menjadi dua kali lipat, tiga kali lipat. Itu pedang pembunuh, pedang untuk pembunuhan besar-besaran, yang berkeliling menghabiskan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 15, 'Supaya hati mereka hancur dan yang jatuh berebahan bertambah-tambah di tiap pintu gerbang mereka, Aku memerintahkan penumpahan darah dengan pedang itu. Aduh, pedang itu dibuat menyamai petir dan digosok untuk menumpahkan darah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 16, 'Pancung yang di kanan dan di kiri, ke mana saja matamu menetak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 17, 'Dan Aku juga akan bertepuk tangan dan hati-Ku yang panas menjadi tenang kembali. Aku, TUHAN, yang mengatakannya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 18, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 19, '"Hai engkau anak manusia, gambarlah dua jalan yang akan dilalui oleh pedang raja Babel; keduanya mulai dari satu negeri. Buatlah sebuah papan penunjuk jalan pada awal jalan yang menuju ke masing-masing kota.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 20, 'Gambarlah dari jalan mana pedang itu datang melawan Raba, ibukota bani Amon dan melawan Yehuda, yang bentengnya ada di Yerusalem.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 21, 'Sebab raja Babel berdiri pada persimpangan jalan itu, pada awal kedua jalan itu untuk melakukan tenungan; ia mengocok panah, meminta petunjuk dari terafim dan menilik hati binatang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 22, 'Ke dalam tangan kanannya terjatuh panah tenungan mengenai Yerusalem: supaya diperdengarkannya suara orang yang membunuh dan menyerukan pekik pertempuran, supaya menyusun alat-alat pendobrak pintu gerbang dan menimbun tanah menjadi tembok pengepungan dan mendirikan benteng pengepungan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 23, 'Tetapi bagi mereka, itu adalah tenungan yang menipu, walaupun mereka mengangkat sumpah yang muluk-muluk; tetapi ia mengingat kesalahan mereka, sehingga mereka ditangkap.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 24, 'Oleh sebab itu, beginilah firman Tuhan ALLAH: Oleh karena kamu membuat kesalahanmu itu teringat kembali dengan tersingkapnya pelanggaranmu, sehingga kentara dosa-dosamu dalam segala perbuatanmu, oleh karena kamu menjadi teringat kembali, kamu akan ditangkap dengan kekerasan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 25, 'Dan hai engkau, raja Israel, orang fasik yang durhaka, yang saatmu sudah tiba untuk penghakiman terakhir,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 26, 'beginilah firman Tuhan ALLAH: Jauhkanlah serbanmu dan buangkanlah mahkotamu! Tiada yang tetap seperti keadaannya sekarang. Yang rendah harus ditinggikan, yang tinggi harus direndahkan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 27, 'Puing, puing, puing akan Kujadikan dia! Inipun tidak akan tetap. Sampai ia datang yang berhak atasnya, dan kepadanya akan Kuberikan itu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 28, '"Dan engkau anak manusia, bernubuatlah dan katakan: Beginilah firman Tuhan ALLAH mengenai bani Amon dan cercaan mereka; katakanlah: Pedang, pedang sudah tercabut untuk menumpahkan darah, digosok untuk memusnahkan, dan supaya mengkilap seperti petir?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 29, 'sedang orang melihat penglihatan-penglihatan yang menipu bagimu dan memberi tenungan-tenungan bohong kepadamu?untuk ditetakkan ke leher orang-orang fasik yang durhaka, yang saatnya sudah tiba untuk penghakiman terakhir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 30, 'Kembalikanlah itu ke sarungnya! Di tempat penciptaanmu dan di negeri asalmu Aku akan menghukum engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 31, 'Aku akan mencurahkan geram-Ku atasmu dan menyemburkan api murka-Ku kepadamu dan menyerahkan engkau ke dalam tangan orang-orang dungu, yang menimbulkan kemusnahan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 21, 32, 'Engkau menjadi makanan api, darahmu akan tertumpah di tengah-tengah tanah itu, dan engkau tidak akan diingat-ingat lagi, sebab Aku, TUHAN, yang mengatakannya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 2, '"Hai engkau, anak manusia, maukah engkau menjatuhkan, ya, menjatuhkan hukuman atas kota yang penuh hutang darah? Beritahukanlah kepadanya segala perbuatannya yang keji,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 3, 'dan katakanlah: Beginilah firman Tuhan ALLAH: Hai kota, yang mencurahkan darah di tengah-tengahmu, sehingga waktu penghukumanmu datang dan membuat berhala-berhala bagimu yang menajiskan dirimu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 4, 'Dengan darah yang engkau curahkan engkau bersalah dan dengan berhala-berhalamu yang engkau perbuat engkau menjadi najis; dengan demikian engkau membuat saatmu mendekat dan membuat akhir tahun-tahunmu datang. Oleh karena itu Aku memberi engkau cercaan bagi bangsa-bangsa dan ejekan bagi semua negeri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 5, 'Yang dekat padamu dan yang jauh dari padamu akan mengejek engkau, yang kenajisannya terkenal dan yang penuh huru-hara.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 6, 'Lihat, masing-masing pemimpin Israel mengandalkan kekuatannya di tengah-tengahmu untuk menumpahkan darah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 7, 'Padamu ayah dan ibu dihina dan di tengah-tengahmu orang melakukan pemerasan terhadap orang asing, padamu anak yatim dan janda ditindas.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 8, 'Engkau memandang ringan terhadap hal-hal yang kudus bagi-Ku dan hari-hari Sabat-Ku kaunajiskan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 9, 'Padamu berkeliaran orang-orang pemfitnah dengan maksud mencurahkan darah dan orang makan daging persembahan di atas gunung-gunung; kemesuman dilakukan di tengah-tengahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 10, 'Padamu orang menyingkapkan aurat isteri ayahnya dan memperkosa perempuan pada waktu cemar kainnya yang menajiskannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 11, 'Yang satu melakukan kekejian dengan isteri sesamanya dan yang lain menajiskan menantunya perempuan dengan perbuatan mesum, orang lain lagi memperkosa saudaranya perempuan, anak kandung ayahnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 12, 'Padamu orang menerima suap untuk mencurahkan darah, engkau memungut bunga uang atau mengambil riba dan merugikan sesamamu dengan pemerasan, tetapi Aku kaulupakan, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 13, 'Sungguh, Aku bertepuk tangan mengenai keuntunganmu yang haram yang kaudapati dan mengenai darah yang dicurahkan di tengah-tengahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 14, 'Apakah hatimu akan tetap teguh dan tanganmu merasa kuat pada masa Aku bertindak terhadap engkau? Aku, TUHAN, yang mengatakannya dan yang akan membuatnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 15, 'Aku akan menyerakkan engkau di antara bangsa-bangsa dan menghamburkan engkau ke semua negeri dan Aku akan mengikis kenajisanmu dari padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 16, 'Maka engkau akan dinajiskan di hadapan bangsa-bangsa karena kesalahanmu sendiri, dan engkau akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 17, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 18, '"Hai anak manusia, bagi-Ku kaum Israel sudah menjadi sanga; mereka semuanya adalah ibarat tembaga, timah putih, besi dan timah hitam di dalam peleburan; mereka seperti sanga perak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 19, 'Sebab itu beginilah firman Tuhan ALLAH: Oleh karena kamu semuanya menjadi sanga, maka sungguh, Aku akan mengumpulkan kamu di tengah-tengah Yerusalem.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 20, 'Seperti orang mengumpulkan perak, tembaga, besi, timah hitam dan timah putih di dalam peleburan dan mengembus api di bawahnya untuk meleburnya, demikianlah Aku akan mengumpulkan kamu dalam murka-Ku dan amarah-Ku dan menaruh kamu di dalamnya dan melebur kamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 21, 'Aku akan mengumpulkan kamu dan menyemburkan api kemurkaan-Ku kepadamu, sehingga kamu dilebur di dalamnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 22, 'Seperti perak dilebur dalam peleburan, begitulah kamu dilebur di dalamnya. Dan kamu akan mengetahui, bahwa Aku, TUHAN, yang mencurahkan amarah-Ku atasmu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 23, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 24, '"Hai anak manusia, katakanlah kepadanya: Engkau adalah tanah yang tidak menerima hujan, tidak mendapat air pada masa kegeraman,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 25, 'yang pemimpin-pemimpinnya di tengah-tengahnya seperti singa yang mengaum, yang menerkam mangsanya: manusia ditelan, harta benda dan barang-barang yang berharga dirampas, janda-janda dibuat bertambah-tambah di tengah-tengahnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 26, 'Imam-imamnya memperkosa hukum Taurat-Ku dan menajiskan hal-hal yang kudus bagi-Ku, mereka tidak membedakan antara yang kudus dengan yang tidak kudus, tidak mengajarkan perbedaan yang najis dengan yang tahir, mereka menutup mata terhadap hari-hari Sabat-Ku. Demikianlah Aku dinajiskan di tengah-tengah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 27, 'Pemuka-pemukanya di tengah-tengahnya adalah seperti serigala-serigala yang menerkam mangsanya dalam kehausan akan darah, yang membinasakan orang-orang untuk menguntungkan diri sendiri secara haram.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 28, 'Dan nabi-nabinya mengoles mereka dengan kapur dengan melihat penglihatan yang menipu dan memberi tenungan bohong bagi mereka; nabi-nabi itu berkata: Beginilah firman Tuhan ALLAH! ?tetapi TUHAN tidak berfirman.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 29, 'Penduduk negeri melakukan pemerasan dan perampasan, menindas orang sengsara dan miskin dan mereka melakukan pemerasan terhadap orang asing bertentangan dengan hukum.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 30, 'Aku mencari di tengah-tengah mereka seorang yang hendak mendirikan tembok atau yang mempertahankan negeri itu di hadapan-Ku, supaya jangan Kumusnahkan, tetapi Aku tidak menemuinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 22, 31, 'Maka Aku mencurahkan geram-Ku atas mereka dan membinasakan mereka dengan api kemurkaan-Ku; kelakuan mereka Kutimpakan atas kepala mereka, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 2, '"Hai anak manusia, ada dua orang perempuan, anak dari satu ibu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 3, 'Mereka bersundal di Mesir, mereka bersundal pada masa mudanya; di sana susunya dijamah-jamah dan dada keperawanannya dipegang-pegang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 4, 'Nama yang tertua ialah Ohola dan nama adiknya ialah Oholiba. Mereka Aku punya dan mereka melahirkan anak-anak lelaki dan perempuan. Mengenai nama-nama mereka, Ohola ialah Samaria dan Oholiba ialah Yerusalem.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 5, 'Dan Ohola berzinah, sedang ia Aku punya. Ia sangat berahi kepada kekasih-kekasihnya, kepada orang Asyur, pahlawan-pahlawan perang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 6, 'berpakaian kain ungu tua, bupati-bupati dan penguasa-penguasa, semuanya pemuda yang ganteng, pasukan kuda.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 7, 'Ia melakukan persundalannya dengan mereka, semuanya orang Asyur pilihan; ia menajiskan dirinya dengan semua orang, kepada siapa ia berahi dan dengan berhala-berhalanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 8, 'Ia tidak meninggalkan persundalannya yang dilakukannya sejak dari Mesir, sebab pada masa mudanya orang sudah menidurinya, dan mereka memegang-megang dada keperawanannya dan mencurahkan persundalan mereka kepadanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 9, 'Oleh sebab itu Aku menyerahkan dia ke dalam tangan kekasih-kekasihnya, dalam tangan orang Asyur, kepada siapa ia berahi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 10, 'Mereka menyingkapkan auratnya, anak-anaknya lelaki dan perempuan ditangkap dan ia sendiri dibunuh dengan pedang. Dengan demikian namanya dipercakapkan di antara kaum perempuan sebab hukuman telah dijatuhkan atasnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 11, 'Walaupun hal itu dilihat oleh adiknya, Oholiba, ia lebih berahi lagi dan persundalannya melebihi lagi dari kakaknya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 12, 'Ia berahi kepada orang Asyur, kepada bupati-bupati dan penguasa-penguasan kepada pahlawan-pahlawan perang yang pakaiannya sangat sempurna, kepada pasukan kuda, semuanya pemuda yang ganteng.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 13, 'Aku melihat bahwa ia menajiskan diri; kelakuan mereka berdua adalah sama.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 14, 'Bahkan, ia menambah persundalannya lagi: ia melihat laki-laki yang terukir pada dinding, gambar orang-orang Kasdim, diukir dalam warna linggam,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 15, 'pinggangnya diikat dengan ikat pinggang, kepalanya memakai serban yang berjuntai, semuanya kelihatan seperti perwira, yang menyerupai orang Babel dari Kasdim, tanah kelahiran mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 16, 'Segera sesudah kelihatan oleh matanya ia berahi kepada mereka dan mengirim suruhan kepada mereka ke tanah Kasdim.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 17, 'Maka orang Babel datang kepadanya menikmati tempat tidur percintaan dan menajiskan dia dengan persundalan mereka; sesudah ia menjadi najis oleh mereka, ia meronta dari mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 18, 'Oleh karena ia melakukan persundalannya dengan terang-terangan dan memperlihatkan sendiri auratnya, maka Aku menjauhkan diri karena jijik dari padanya, seperti Aku menjauhkan diri dari adiknya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 19, 'Ia melakukan lebih banyak lagi persundalannya sambil teringat kepada masa mudanya, waktu ia bersundal di tanah Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 20, 'Ia berahi kepada kawan-kawannya bersundal, yang auratnya seperti aurat keledai dan zakarnya seperti zakar kuda.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 21, 'Engkau menginginkan kemesuman masa mudamu, waktu orang Mesir memegang-megang dadamu dan menjamah-jamah susu kegadisanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 22, 'Oleh sebab itu, hai Oholiba, beginilah firman Tuhan ALLAH, memang engkau sudah menjauhkan dirimu dari kekasih-kekasihmu, tetapi sungguh, Aku akan menyuruh mereka bergerak melawan engkau; Aku akan membawa mereka melawan engkau dari sekitarmu:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 23, 'orang Babel dan semua orang Kasdim, orang Pekod, orang Soa dan orang Koa, dan semua orang Asyur bersama mereka, pemuda yang ganteng, bupati-bupati dan para penguasa semuanya, perwira-perwira dan pahlawan-pahlawan perang, pasukan kuda semuanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 24, 'Mereka datang melawan engkau dengan banyak kereta dan roda-roda dan dengan sekumpulan bangsa-bangsa; mereka akan menyusun perisai besar dan kecil dan ketopong di sekitarmu melawan engkau, dan Aku akan menyerahkan perkara ini di hadapannya dan mereka akan menghakimi engkau menurut hukum mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 25, 'Aku akan membalaskan cemburuan-Ku kepadamu, sehingga mereka memperlakukan engkau dengan kemurkaan, hidung dan telingamu akan dikerat dan sisamu akan mati rebah oleh pedang. Mereka akan menangkap anak-anakmu lelaki dan perempuan dan sisamu akan dimakan api.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 26, 'Mereka akan menelanjangi engkau dan merampas perhiasan-perhiasanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 27, 'Aku akan membuat engkau menghentikan kemesumanmu dan persundalanmu sejak dari tanah Mesir, sehingga engkau tidak lagi melirik kepada mereka dan tidak lagi mengingat-ingat orang Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 28, 'Sebab beginilah firman Tuhan ALLAH: Lihat, Aku akan menyerahkan engkau ke dalam tangan orang yang kaubenci, walaupun engkau sudah menjauhkan diri dari mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 29, 'Mereka akan memperlakukan engkau dengan kebencian dan akan merampas segala hasil jerih payahmu dan meninggalkan engkau telanjang bugil, sehingga aurat persundalanmu kelihatan. Kemesumanmu dan persundalanmu', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 30, 'mendatangkan hal ini atasmu, karena engkau bersundal dengan mengandalkan bangsa-bangsa dan menajiskan dirimu dengan berhala-berhala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 31, 'Engkau hidup mengikuti kelakuan kakakmu, sebab itu Aku akan memberi engkau minum dari pialanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 32, 'Beginilah firman Tuhan ALLAH: Engkau harus minum dari piala kakakmu, piala yang dalam dan lebar mulutnya, yaitu piala yang banyak isinya; menjadi tertawaan dan olok-olok engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 33, 'Engkau akan penuh kemabukan dan dukacita. Piala kengerian disertai kesunyian ialah piala kakakmu Samaria.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 34, 'Engkau meminumnya beserta ampasnya, sampai mengunggis pecahan-pecahannya dan engkau merabitkan susumu. Sebab Aku yang mengatakannya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 35, 'Oleh sebab itu, beginilah firman Tuhan ALLAH: Oleh karena engkau melupakan Aku dan membelakangi Aku, sekarang tanggung sendirilah kemesumanmu dan persundalanmu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 36, 'Lalu TUHAN berfirman kepadaku: "Hai anak manusia, maukah engkau menghakimi Ohola dan Oholiba dan memberitahukan kepada mereka perbuatan-perbuatannya yang keji?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 37, 'Sebab mereka berzinah, tangan mereka berlumuran darah dan mereka berzinah dengan menyembah berhala-berhalanya, bahkan anak-anak lelaki mereka yang dilahirkan bagi-Ku dipersembahkannya sebagai korban dalam api kepada berhala-berhalanya menjadi makanan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 38, 'Selain itu hal ini juga mereka lakukan terhadap Aku, mereka menajiskan tempat kudus-Ku pada hari itu dan melanggar kekudusan hari-hari Sabat-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 39, 'Dan sedang mereka menyembelih anak-anak mereka untuk berhala-berhalanya, mereka datang pada hari itu ke tempat kudus-Ku dan melanggar kekudusannya. Sungguh, inilah yang dilakukan mereka di dalam rumah-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 40, 'Tambahan lagi mereka meminta orang-orang datang dari tempat yang jauh dengan menyuruh suruhan memanggil mereka, dan sungguh, mereka datang. Demi kedatangan mereka engkau mandi bersih-bersih, mencalak alismu dan menghias dirimu dengan perhiasan-perhiasan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 41, 'Engkau duduk di tempat tidur yang serba indah dan di hadapannya meja dengan hidangan yang disajikan; di atas tempat tidurmu itu kautaruh ukupan-Ku dan minyak-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 42, 'Lalu kedengaranlah suara keramaian hidup bersenang-senang padanya dan kepada orang-orang dari orang banyak ditambahkan lagi pemabuk-pemabuk dari padang gurun. Mereka mengenakan gelang pada tangannya dan mahkota kemuliaan di atas kepalanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 43, 'Aku berkata: Apakah bunga yang layu ini masih melakukan perzinahan? Orang bersundal dengan dia, bahkan dengan dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 44, 'Mereka datang kepadanya seperti orang mendatangi perempuan sundal. Demikianlah mereka datang kepada Ohola dan Oholiba untuk melakukan kemesuman.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 45, 'Tetapi orang-orang yang benar saleh akan menghakimi mereka seperti orang menghakimi perempuan-perempuan yang berzinah dan yang menumpahkan darah, sebab mereka adalah perempuan-perempuan berzinah dan tangan mereka berlumuran darah."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 46, 'Sebab beginilah firman Tuhan ALLAH: "Biarlah bangkit sekumpulan orang melawan mereka dan biarkanlah mereka menjadi kengerian dan rampasan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 47, 'Kumpulan orang ini akan melontari mereka dengan batu dan memancung mereka dengan pedangnya, membunuh anak-anak lelaki dan anak-anak perempuan mereka dan membakar habis rumah-rumah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 48, 'Aku akan menghentikan kemesuman di tanah itu dan semua kaum perempuan akan memperhatikan peringatan itu dan tidak akan melakukan kemesuman lagi seperti yang kamu lakukan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 23, 49, 'Orang akan membalaskan kemesumanmu atasmu dan kamu harus menanggung dosa-dosamu lantaran kamu menyembah berhala-berhala. Dan kamu akan mengetahui bahwa Akulah Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 1, 'Pada tahun kesembilan, dalam bulan yang kesepuluh, pada tanggal sepuluh bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 2, '"Hai anak manusia, tuliskanlah tanggal hari ini, ya, tanggal hari ini. Pada hari ini juga raja Babel mulai menyerang Yerusalem.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 3, 'Ucapkanlah suatu perumpamaan kepada kaum pemberontak dan katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Taruhlah kuali di atas api, taruhlah, dan tuanglah juga air ke dalamnya;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 4, 'taruhlah potongan daging di dalamnya, semua potongan yang baik, paha dan punggungnya; penuhilah itu dengan tulang-tulang pilihan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 5, 'Ambillah domba yang terpilih, dan susunlah juga kayu di bawahnya, biarlah masakan itu mendidih dan tulang-tulangnya turut empuk di dalamnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 6, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Celakalah kota yang penuh hutang darah, kuali yang berkarat di dalamnya dan karatnya tidak hilang dari padanya! Keluarkan potong demi potong dari dalamnya tanpa memilih-milih.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 7, 'Sebab darah yang dicurahkannya masih terdapat di tengah-tengahnya; ia mencurahkannya di atas bukit batu yang gundul. Ia tidak mencurahkannya di atas tanah, supaya ditutupinya dengan tanah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 8, 'Demi amarah yang timbul dan rasa pembalasan yang bangkit Aku akan mencurahkan darahnya sendiri ke atas bukit batu yang gundul supaya jangan ditutupi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 9, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Celakalah kota yang penuh hutang darah! Aku juga hendak memperbesar pancakanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 10, 'Susunlah banyak kayu, nyalakan api, biarlah dagingnya masak betul, buanglah kuahnya dan biarlah tulang-tulangnya hangus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 11, 'Letakkanlah periuk itu kosong di atas bara api, supaya itu dibakar dan tembaganya menjadi merah, sehingga kotorannya hancur di dalamnya dan karatnya hilang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 12, 'Aku bersusah payah dengan sia-sia, sebab karatnya yang tebal tidak mau hilang dari padanya, biar dalam api.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 13, 'Oleh karena engkau menajiskan dirimu dengan kemesumanmu, dan Aku ingin mentahirkan engkau, tetapi engkau tidak menjadi tahir dari kenajisanmu, maka engkau tidak akan ditahirkan lagi, sampai Aku melampiaskan amarah-Ku atasmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 14, 'Aku, TUHAN, yang mengatakannya. Hal itu akan datang, dan Aku yang akan membuatnya. Aku tidak melalaikannya dan tidak merasa sayang, juga tidak menyesal. Aku akan menghakimi engkau menurut perbuatanmu, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 15, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 16, '"Hai anak manusia, lihat, Aku hendak mengambil dari padamu dia yang sangat kaucintai seperti yang kena tulah, tetapi janganlah meratap ataupun menangis dan janganlah mengeluarkan air mata.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 17, 'Diam-diam saja mengeluh, jangan mengadakan ratapan kematian; lilitkanlah destarmu dan pakailah kasutmu, jangan tutupi mukamu dan jangan makan roti perkabungan."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 18, 'Pada paginya aku berbicara kepada bangsa itu dan pada malamnya isteriku mati. Pada pagi berikutnya aku melakukan seperti diperintahkan kepadaku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 19, 'Maka bangsa itu berkata kepadaku: "Tidakkah engkau bersedia memberitahukan kepada kami, apa artinya ini bagi kami, bahwa engkau melakukan demikian?"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 20, 'Lalu kujawab mereka: "Firman TUHAN sudah datang kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 21, 'Katakanlah kepada kaum Israel: Beginilah firman Tuhan ALLAH: Sesungguh-sungguhnya Aku akan menajiskan tempat kudus-Ku, kekuasaanmu yang kaubanggakan, kenikmatan bagi matamu dan bagi jiwamu; dan anak-anakmu lelaki dan perempuan yang kamu tinggalkan akan mati rebah oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 22, 'Kamu akan melakukan seperti yang kulakukan: Mukamu tidak akan kamu tutupi dan roti perkabungan tidak akan kamu makan,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 23, 'kepalamu pakai destar dan kakimu pakai kasut; dan kamu tidak akan meratap atau menangis. Tetapi kamu akan hancur lebur dalam hukumanmu, dan kamu akan mengeluh seorang kepada yang lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 24, 'Demikianlah Yehezkiel menjadi lambang bagimu; tepat seperti yang dilakukannya kamu akan lakukan. Kalau itu sudah terjadi maka kamu akan mengetahui, bahwa Akulah Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 25, 'Dan engkau, anak manusia, bukankah begini akan terjadi? Pada hari Aku mengambil dari mereka benteng mereka, perhiasannya yang menggirangkan hatinya, kenikmatan matanya dan yang dirindukan jiwanya, anak-anak mereka lelaki dan perempuan,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 26, 'pada hari itu juga akan datang seorang yang terluput membawa berita kepadamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 24, 27, 'Pada hari itu mulutmu akan terbuka dan engkau akan berbicara kepada orang yang terluput itu dan tidak lagi tetap bisu. Dengan demikian engkau menjadi lambang bagi mereka dan mereka akan mengetahui, bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 2, '"Hai anak manusia, tujukanlah mukamu kepada bani Amon dan bernubuatlah melawan mereka!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 3, 'Katakanlah kepada bani Amon: Dengarlah firman Tuhan ALLAH: Beginilah firman Tuhan ALLAH: Oleh karena engkau menyerukan: Syukur! mengenai tempat kudus-Ku, waktu kekudusannya dilanggar, dan mengenai tanah Israel, waktu itu dijadikan sunyi sepi, dan mengenai kaum Yehuda, waktu mereka harus pergi ke dalam pembuangan,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 4, 'oleh sebab itu, sungguh, Aku menyerahkan engkau kepada orang dari sebelah timur menjadi miliknya; mereka akan mendirikan perkemahannya padamu dan membangun tempat kediamannya; mereka akan memakan buah-buahanmu dan meminum susu ternakmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 5, 'Aku akan membuat Raba menjadi padang rumput untuk unta dan kota-kota bani Amon menjadi tempat kambing domba. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 6, 'Sebab beginilah firman Tuhan ALLAH: Oleh karena engkau bertepuk tangan dan mengentakkan kakimu ke tanah, dan bergembira dalam hatimu atas kecelakaan tanah Israel,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 7, 'oleh sebab itu, sungguh, Aku akan mengacungkan tangan-Ku melawan engkau dan menyerahkan engkau menjadi jarahan bagi suku-suku bangsa dan melenyapkan engkau dari tengah bangsa-bangsa dan membinasakan engkau dari negeri-negeri; Aku akan memusnahkan engkau. Dengan demikian engkau akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 8, 'Beginilah firman Tuhan ALLAH: "Oleh karena Moab berkata: Sungguh, kaum Yehuda adalah sama dengan semua bangsa lain,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 9, 'oleh sebab itu, sungguh, Aku akan membiarkan dataran tinggi Moab terbuka dengan runtuhnya kota-kotanya, ya, kota-kotanya tanpa terkecuali, yaitu kepermaian negeri itu: Bet-Yesimot, Baal-Meon dan Kiryataim.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 10, 'Aku akan menyerahkan dia bersama bani Amon kepada orang dari sebelah Timur menjadi miliknya, supaya bani Amon jangan diingat-ingat lagi di antara bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 11, 'Aku akan menjatuhkan hukuman kepada Moab dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 12, 'Beginilah firman Tuhan ALLAH: "Oleh karena Edom membalaskan dendam kesumat terhadap kaum Yehuda dan membuat kesalahan besar dengan melakukan pembalasan terhadap mereka,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 13, 'oleh sebab itu beginilah firman Tuhan ALLAH, Aku akan mengacungkan tangan-Ku melawan Edom dan melenyapkan dari padanya manusia dan binatang dan Aku membuatnya menjadi reruntuhan; dari Teman sampai Dedan mereka akan mati rebah oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 14, 'Aku akan melakukan pembalasan-Ku terhadap Edom dengan tangan umat-Ku Israel. Dan mereka akan memperlakukan Edom selaras dengan murka-Ku dan amarah-Ku, dan mereka akan mengetahui, bahwa Akulah yang membalas, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 15, 'Beginilah firman Tuhan ALLAH: "Oleh karena orang Filistin membalaskan dendam kesumat dan di dalam kegembiraannya atas kecelakaan Israel melakukan pembalasan dengan melakukan pembinasaan karena rasa permusuhan yang turun-temurun,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 16, 'oleh sebab itu, beginilah firman Tuhan ALLAH: Sungguh, Aku akan mengacungkan tangan-Ku melawan orang Filistin dan melenyapkan orang Kreta dan membinasakan yang lain-lain di tepi pantai laut.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 25, 17, 'Aku akan melakukan pembalasan yang kejam terhadap mereka disertai penghajaran-penghajaran kemarahan. Dan mereka akan mengetahui bahwa Akulah TUHAN, pada waktu Aku melakukan pembalasan-Ku terhadap mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 1, 'Pada tahun kesebelas, dalam bulan yang tertentu, pada tanggal satu bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 2, '"Hai anak manusia, oleh karena Tirus berkata mengenai Yerusalem: Syukur! Sudah rusak pintu gerbang bangsa-bangsa itu; ia akan beralih kepadaku, sehingga aku menjadi penuh, tetapi ia menjadi reruntuhan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 3, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Lihat, Aku menjadi lawanmu, hai Tirus. Aku akan menyuruh bangkit banyak bangsa melawan engkau, seperti lautan menimbulkan gelombang-gelombangnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 4, 'Mereka akan memusnahkan tembok-tembok Tirus dan meruntuhkan menara-menaranya, debu tanahnya akan Kubuang sampai bersih dari padanya dan akan Kujadikan dia gunung batu yang gundul.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 5, 'Ia akan menjadi penjemuran pukat di tengah lautan, sebab Aku yang mengatakannya, demikianlah firman Tuhan ALLAH; ia akan menjadi jarahan bagi bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 6, 'Dan anak-anaknya perempuan, yang tinggal di daratan akan ditewaskan dengan pedang. Dan mereka akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 7, 'Sebab beginilah firman Tuhan ALLAH: Sungguh, Aku membawa dari utara raja Nebukadnezar, raja Babel, raja segala raja untuk melawan Tirus dengan memakai kuda, kereta, pasukan berkuda, dan sekumpulan tentara yang banyak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 8, 'Anak-anakmu perempuan yang tinggal di daratan akan dibunuhnya dengan pedang; ia akan menimbun tembok pengepungan dan menyusun alat-alat pendobrak dan memasang perisai melawan engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 9, 'Tumbukan alat pendobraknya akan dilancarkan terhadap tembok-tembokmu dan menara-menaramu akan dirobohkan dengan beliung-beliungnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 10, 'Kudanya adalah begitu banyak, sehingga engkau akan ditutupi oleh abu; karena derap pasukan berkudanya dan kertak roda keretanya tembok-tembokmu akan gemetar, kalau ia memasuki pintu-pintu gerbangmu seperti orang memasuki kota yang sudah terbuka karena pendobrakan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 11, 'Dengan kaki kuda-kudanya ia hendak menginjak-injak semua jalan-jalanmu, rakyatmu akan dibunuh dengan pedang, dan tugu-tugu yang kauandalkan akan dirobohkan ke tanah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 12, 'Mereka akan merampas kekayaanmu dan menjarah barang-barang perniagaanmu; mereka akan meruntuhkan tembok-tembokmu dan merobohkan rumah-rumahmu yang indah; batumu, kayumu dan tanahmu akan dibuang ke dalam air.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 13, 'Aku akan mengakhiri keramaian nyanyianmu dan suara kecapimu tidak akan kedengaran lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 14, 'Aku akan menjadikan engkau gunung batu yang gundul dan dengan demikian engkau akan menjadi penjemuran pukat, sehingga engkau tidak akan dibangun kembali, sebab Aku, Tuhanlah yang mengatakannya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 15, 'Beginilah firman Tuhan ALLAH kepada Tirus: Apakah daerah pesisir tidak akan gemetar mendengar derum kejatuhanmu, kalau orang-orang yang berebahan mengerang karena pembunuhan bersimaharajalela di tengah-tengahmu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 16, 'Semua pemuka bangsa-bangsa yang di tepi lautan akan turun takhta dan menjauhkan jubah-jubah kerajaannya dan menanggalkan pakaiannya yang berwarna-warna. Mereka akan diliputi kegentaran dan akan duduk di tanah; mereka akan gentar senantiasa dan kaget melihat engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 17, 'Dan mereka akan mengucapkan suatu ratapan mengenai engkau dan akan mengatakan kepadamu: Bagaimana engkau, hai kota yang terpuja, hilang dari lautan, kota yang berkuasa di laut, engkau dengan pendudukmu, yang menimbulkan ketakutan pada penduduk di daratan?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 18, 'Sekarang, daerah pesisir jadi gentar pada hari jatuhmu, ya, daerah pesisir yang di tepi laut gempar mendengar kesudahanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 19, 'Sebab beginilah firman Tuhan ALLAH: Pada saat Aku menjadikan engkau kota reruntuhan, seperti kota-kota yang tidak berpenduduk lagi, kalau Aku menaikkan pasang samudera raya atasmu dan air banjir menutupi engkau,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 20, 'maka Aku akan menurunkan engkau, supaya engkau bersama-sama di sana dengan orang-orang yang turun ke liang kubur, kepada bangsa dahulu kala, dan Aku akan membuat engkau tinggal di bumi yang paling bawah seperti reruntuhan dahulu kala, bersama dengan orang-orang yang turun ke liang kubur, supaya engkau jangan lagi didiami orang, dan jangan tampil lagi di negeri orang-orang hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 26, 21, 'Aku menentukan bagimu akhir hidupmu yang mendahsyatkan dan engkau tidak terjumpa lagi. Engkau dicari orang, tetapi tidak ditemui lagi untuk selama-lamanya, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 2, '"Hai engkau anak manusia, ucapkanlah suatu ratapan mengenai Tirus,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 3, 'dan katakanlah kepada Tirus, yang terletak di pintu masuk lautan, dan yang berdagang dengan bangsa-bangsa di banyak daerah pesisir: Beginilah firman Tuhan ALLAH: Hai Tirus, engkau berkata: aku kapal yang maha indah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 4, 'Wilayahmu di tengah lautan; ahli bangunmu membuat keindahanmu sempurna.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 5, 'Seluruh badanmu mereka buat dari kayu sanobar Senir, mereka mengambil aras Libanon membuat bagimu tiang layar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 6, 'Pohon tarbantin dari Basan dipakai untuk dayungmu; geladakmu mereka buat dari tulang gading ditatahkan di cemara dari pantai Kitim.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 7, 'Layarmu diperbuat dari lenan halus yang berwarna-warni dari tanah Mesir; itulah tandamu. Dan tendamu diperbuat dari kain ungu tua dan kain ungu muda dari pantai Elisa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 8, 'Orang Sidon dan Arwad menjadi pendayungmu; tukang-tukangmu, hai Tirus, berada padamu, mereka menjadi pelaut-pelautmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 9, 'Tua-tua Gebal dengan ahli-ahlinya berada padamu hendak memperbaiki kerusakan-kerusakanmu. Segala kapal laut beserta anak kapalnya berlabuh padamu hendak menukarkan barang dagangannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 10, 'Orang Persia, Lud dan Put, yang menjadi prajuritmu ada dalam ketenteraanmu. Perisai dan ketopong digantungkan padamu; mereka menambah semarakmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 11, 'Orang Arwad dan tentaranya memanjat di atas tembok-tembokmu sekeliling dan orang Gamad di atas menara-menaramu; mereka menggantungkan perisai-perisainya pada tembok-tembokmu sekeliling, mereka membuat keindahanmu sempurna.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 12, 'Tarsis berdagang dengan engkau dalam segala macam harta yang banyak; mereka menukarkan perak, besi, timah putih dan timah hitam ganti barang-barangmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 13, 'Yawan, Tubal dan Mesekh berdagang dengan engkau; mereka menukarkan budak-budak, barang-barang tembaga ganti barang-barang daganganmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 14, 'Dari Bet-Togarma mereka menukarkan kuda kereta, kuda tunggang dan bagal ganti barang-barangmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 15, 'Orang Rodos berdagang dengan engkau, banyak daerah pesisir menjadi daerah pasaranmu; mereka membawa kepadamu tulang gading dan kayu arang sebagai upeti.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 16, 'Edom berdagang dengan engkau karena banyaknya hasil-hasilmu; mereka menukarkan permata batu darah, kain ungu muda, pakaian berwarna-warna, kain lenan halus, karang dan batu delima ganti barang-barangmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 17, 'Yuda dan tanah Israel berdagang dengan engkau; mereka menukarkan gandum dari Minit, mur, madu, minyak dan balsam ganti barang-barang daganganmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 18, 'Damsyik berdagang dengan engkau karena banyaknya hasil-hasilmu, karena segala macam barangmu yang banyak. Anggur dari Helbon, bulu domba dari Sakhar,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 19, 'dan anggur ditukarkan mereka ganti barang-barangmu; besi yang sudah dikerjakan dari Uzal, kayu teja dan tebu ada di antara barang-barang daganganmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 20, 'Dedan berdagang dengan engkau dalam kulit pelana untuk menunggang kuda.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 21, 'Arab dan semua pemuka Kedar berdagang dengan engkau dalam anak domba, domba jantan dan kambing jantan; dalam hal-hal itulah mereka berdagang dengan engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 22, 'Pedagang Syeba dan Raema berdagang dengan engkau; mereka menukarkan yang terbaik dari segala rempah-rempah dan segala batu permata yang mahal-mahal dan emas ganti barang-barangmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 23, 'Haran, Kane, Eden, Asyur dan Kilmad berdagang dengan engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 24, 'Mereka berdagang di pasar-pasarmu dalam jubah-jubah yang maha indah, kain ungu tua, pakaian yang berwarna-warni, permadani yang beraneka warna dan tali berpilin yang teguh.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 25, 'Kapal-kapal Tarsis membawa barang-barang dagangan ini bagimu. Penuh dengan muatan berat engkau di tengah lautan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 26, 'Ke lautan luas pendayungmu membawa engkau. Tetapi badai timur melandamu di tengah lautan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 27, 'Hartamu, barangmu, daganganmu, anak kapalmu dan pelaut-pelautmu, tukang-tukangmu dan pedagang-pedagangmu dengan semua prajurit-prajuritmu yang ada padamu, ya, bersama seluruh penumpang-penumpangmu, terbenam dalam lautan pada hari tenggelammu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 28, 'Mendengar teriakan pelautmu gemetarlah tanah daratan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 29, 'Mereka turun dari kapalnya, yang mengayun dayung semua. Anak kapal, pelaut semuanya ke daratan lari mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 30, 'Ratapan kuat, teriakan pahit diperdengarkan terhadapmu; taruh abu di atas kepala, berguling-guling dalam debu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 31, 'Mereka menggundul diri, demi engkau, dan melilitkan kain kabung; mereka menangis, jiwa merana, karena engkau; suatu ratapan yang pahit.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 32, 'Dalam meratap karena engkau mereka mengucapkan, menangiskan ratapan: Siapa seperti Tirus, yang sudah dimusnahkan di tengah lautan?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 33, 'Sesudah barangmu datang dari laut engkau mengenyangkan banyak bangsa-bangsa, dengan banyaknya hartamu, daganganmu engkau memperkaya raja-raja dunia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 34, 'Sekarang engkau dirusak dan dilenyapkan dari permukaan laut dan tenggelam di dasar lautan; daganganmu dan seluruh penumpangmu tenggelam dengan engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 35, 'Orang pesisir kaget semua melihatmu; raja-rajanya menggigil, mukanya berkerut.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 27, 36, 'Pedagang bangsa-bangsa bersuit-suit terhadapmu, akhir hidupmu mendahsyatkan, dan lenyap selamanya engkau."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 1, 'Maka datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 2, '"Hai anak manusia, katakanlah kepada raja Tirus: Beginilah firman Tuhan ALLAH: Karena engkau menjadi tinggi hati, dan berkata: Aku adalah Allah! Aku duduk di takhta Allah di tengah-tengah lautan. Padahal engkau adalah manusia, bukanlah Allah, walau hatimu menempatkan diri sama dengan Allah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 3, 'Memang hikmatmu melebihi hikmat Daniel; tiada rahasia yang terlindung bagimu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 4, 'Dengan hikmatmu dan pengertianmu engkau memperoleh kekayaan. Emas dan perak kaukumpulkan dalam perbendaharaanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 5, 'Karena engkau sangat pandai berdagang engkau memperbanyak kekayaanmu, dan karena itu engkau jadi sombong.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 6, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Karena hatimu menempatkan diri sama dengan Allah', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 7, 'maka, sungguh, Aku membawa orang asing melawan engkau, yaitu bangsa yang paling ganas, yang akan menghunus pedang mereka, melawan hikmatmu yang terpuja; dan semarakmu dinajiskan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 8, 'Engkau diturunkannya ke lobang kubur, engkau mati seperti orang yang mati terbunuh di tengah lautan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 9, 'Apakah engkau masih akan mengatakan di hadapan pembunuhmu: Aku adalah Allah!? Padahal terhadap kuasa penikammu engkau adalah manusia, bukanlah Allah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 10, 'Engkau akan mati seperti orang tak bersunat oleh tangan orang asing. Sebab Aku yang mengatakannya, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 11, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 12, '"Hai anak manusia, ucapkanlah suatu ratapan mengenai raja Tirus dan katakanlah kepadanya: Beginilah firman Tuhan ALLAH: Gambar dari kesempurnaan engkau, penuh hikmat dan maha indah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 13, 'Engkau di taman Eden, yaitu taman Allah penuh segala batu permata yang berharga: yaspis merah, krisolit dan yaspis hijau, permata pirus, krisopras dan nefrit, lazurit, batu darah dan malakit. Tempat tatahannya diperbuat dari emas dan disediakan pada hari penciptaanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 14, 'Kuberikan tempatmu dekat kerub yang berjaga, di gunung kudus Allah engkau berada dan berjalan-jalan di tengah batu-batu yang bercahaya-cahaya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 15, 'Engkau tak bercela di dalam tingkah lakumu sejak hari penciptaanmu sampai terdapat kecurangan padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 16, 'Dengan dagangmu yang besar engkau penuh dengan kekerasan dan engkau berbuat dosa. Maka Kubuangkan engkau dari gunung Allah dan kerub yang berjaga membinasakan engkau dari tengah batu-batu yang bercahaya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 17, 'Engkau sombong karena kecantikanmu, hikmatmu kaumusnahkan demi semarakmu. Ke bumi kau Kulempar, kepada raja-raja engkau Kuserahkan menjadi tontonan bagi matanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 18, 'Dengan banyaknya kesalahanmu dan kecurangan dalam dagangmu engkau melanggar kekudusan tempat kudusmu. Maka Aku menyalakan api dari tengahmu yang akan memakan habis engkau. Dan Kubiarkan engkau menjadi abu di atas bumi di hadapan semua yang melihatmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 19, 'Semua di antara bangsa-bangsa yang mengenal engkau kaget melihat keadaanmu. Akhir hidupmu mendahsyatkan dan lenyap selamanya engkau."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 20, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 21, '"Hai anak manusia, tujukanlah mukamu kepada Sidon dan bernubuatlah melawan dia', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 22, 'dan katakanlah: Beginilah firman Tuhan ALLAH: Lihat, Aku menjadi lawanmu, hai Sidon, dan Aku menyatakan kemuliaan-Ku di tengah-tengahmu. Dan mereka akan mengetahui bahwa Akulah TUHAN, pada saat Aku menjatuhkan hukuman atasnya dan menunjukkan kekudusan-Ku terhadap dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 23, 'Aku akan mendatangkan sampar atasnya dan darah akan mengalir di jalan-jalannya dan orang-orang akan mati rebah di tengah-tengahnya karena pedang yang datang dari sekitarnya melawan dia. Dan mereka akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 24, 'Dan tidak akan ada lagi bagi kaum Israel dari semua tetangganya yang menghina mereka, menjadi duri yang menusuk atau onak yang memedihkan. Dan mereka akan mengetahui bahwa Akulah Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 25, 'Beginilah firman Tuhan ALLAH: Pada saat Aku mengumpulkan kaum Israel dari tengah suku-suku bangsa, di mana mereka berserak dan Aku menunjukkan kekudusan-Ku kepada mereka di hadapan bangsa-bangsa, maka mereka akan diam di tanah mereka yang telah Kuberikan kepada hamba-Ku Yakub.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 28, 26, 'Mereka akan diam di sana dengan aman tenteram, mereka akan membangun rumah dan membuat kebun anggur. Ya, mereka akan diam dengan aman tenteram pada saat Aku menjatuhkan hukuman atas semua tetangganya yang menghina mereka. Dan mereka akan mengetahui bahwa Akulah TUHAN, Allah mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 1, 'Pada tahun kesepuluh, dalam bulan yang kesepuluh, pada tanggal dua belas bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 2, '"Hai anak manusia, tujukanlah mukamu kepada Firaun, raja Mesir dan bernubuatlah melawan dia dan melawan seluruh Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 3, 'Berbicaralah dan katakan: Beginilah firman Tuhan ALLAH: Lihat, Aku menjadi lawanmu, hai Firaun, raja Mesir, buaya yang besar, yang berbaring di tengah anak-anak sungaimu, yaitu Nil, dan yang berkata: Sungai Nil aku punya, aku yang membuatnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 4, 'Aku akan mengenakan kelikir pada rahangmu dan membuat ikan dari anak-anak sungaimu berlekatan pada sisikmu. Aku akan mengangkat engkau dari tengah anak-anak sungaimu dengan segala ikannya yang berlekatan pada sisikmu', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 5, 'dan Aku akan melemparkan engkau ke padang gurun, ya, engkau dengan segala ikan anak-anak sungaimu. Engkau akan jatuh di padang dan tidak akan dipungut atau dikubur. Aku memberikan engkau menjadi makanan binatang-binatang liar dan burung-burung di udara.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 6, 'Dan semua penduduk Mesir akan mengetahui bahwa Akulah TUHAN. Oleh karena engkau ibarat tongkat bambu bagi kaum Israel:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 7, 'pada saat mereka memegang engkau dengan tangan, engkau patah terkulai dan engkau melukai bahu mereka semua; dan waktu mereka bertopang padamu, engkau patah dan engkau membuat mereka semua terhuyung-huyung.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 8, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Sungguh, Aku mendatangkan pedang atasmu dan melenyapkan manusia dan binatang dari padamu,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 9, 'sehingga tanah Mesir akan menjadi sunyi sepi dan menjadi reruntuhan. Dan mereka akan mengetahui bahwa Akulah TUHAN. Oleh karena engkau berkata: Sungai Nil aku punya, aku yang membuatnya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 10, 'maka sungguh, Aku menjadi lawanmu dan lawan anak-anak sungaimu dan Aku akan membuat tanah Mesir menjadi reruntuhan dan menjadi sunyi sepi mulai dari Migdol sampai Siene, bahkan sampai perbatasan tanah Etiopia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 11, 'Tidak seorang manusiapun akan melintasinya, bahkan seekor binatangpun tidak dan tanah itu tidak akan didiami selama empat puluh tahun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 12, 'Aku akan membuat tanah Mesir menjadi sunyi sepi di tengah negeri-negeri yang sudah dimusnahkan dan kota-kotanya akan menjadi sunyi sepi di tengah kota-kota yang diruntuhkan selama empat puluh tahun. Aku akan menyerakkan orang Mesir di antara bangsa-bangsa dan menghamburkannya ke semua negeri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 13, 'Sebab beginilah firman Tuhan ALLAH: Pada akhir keempat puluh tahun itu Aku akan mengumpulkan orang-orang Mesir dari tengah bangsa-bangsa di mana mereka berserak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 14, 'Dan Aku akan memulihkan keadaan Mesir dan mengembalikan mereka ke tanah Patros, yaitu tanah asal mereka, dan di sana mereka menjadi kerajaan yang lemah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 15, 'Di antara kerajaan-kerajaan ia akan yang paling lemah dan tidak akan dapat meninggikan dirinya lagi di atas bangsa-bangsa lain. Aku akan membuat mereka begitu lemah, sehingga mereka tidak akan memerintah bangsa-bangsa lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 16, 'Dan bagi kaum Israel mereka tidak lagi menjadi kepercayaan, yang mengingatkan kesalahan Israel, kalau Israel berpaling kepada mereka untuk meminta pertolongan. Dan Mesir akan mengetahui bahwa Akulah Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 17, 'Lalu pada tahun kedua puluh tujuh, dalam bulan pertama, pada tanggal satu bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 18, '"Hai anak manusia, Nebukadnezar, raja Babel, menyuruh tentaranya bekerja keras melawan Tirus; semua kepala sudah gundul dan semua bahu sudah lecet, tetapi baik ia maupun tentaranya tidak mendapat untung dari Tirus atas usaha yang dilakukannya melawan dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 19, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Aku memberikan tanah Mesir kepada Nebukadnezar, raja Babel, dan ia akan mengangkut kekayaannya; ia akan melakukan perampasan dan penjarahan dan itulah upah bagi tentaranya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 20, 'Aku akan memberikan kepadanya tanah Mesir sebagai pahala atas pekerjaan yang dilakukannya, sebab mereka sudah bekerja bagi-Ku, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 29, 21, 'Pada hari itu Aku akan menumbuhkan tanduk bagi kaum Israel dan membuat engkau dapat berbicara lagi di tengah-tengah mereka. Dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 2, '"Hai anak manusia, bernubuatlah dan katakanlah: Beginilah firman Tuhan ALLAH: Merataplah: Aduh, hari itu!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 3, 'Hari itu sudah dekat, hari TUHAN sudah dekat, hari dengan awan gelap; itu adalah saat bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 4, 'Pedang datang atas Mesir dan Etiopia akan gemetar pada saat berebahan orang-orang yang mati terbunuh di Mesir dan kekayaannya dilarikan dan dasar-dasarnya terbongkar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 5, 'Orang Etiopia, Put, Lud, seluruh tanah Arab, Libia dan orang-orang dari negeri yang bersekutu dengan mereka akan mati rebah oleh pedang bersama mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 6, 'Beginilah firman TUHAN: Orang-orang yang mendukung Mesir akan mati rebah, dan kecongkakan Mesir yang ditimbulkan kekuatannya akan patah. Dari Migdol sampai Siene mereka mati rebah oleh pedang, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 7, 'Ia akan dimusnahkan di tengah negeri-negeri yang sudah sunyi sepi dan kota-kotanya termasuk kota-kota yang sudah runtuh.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 8, 'Maka mereka akan mengetahui bahwa Akulah TUHAN, pada saat Aku menimbulkan api di Mesir sehingga semua orang yang membantunya dimusnahkan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 9, 'Pada hari itu utusan-utusan-Ku akan berangkat dengan cepat-cepat untuk mengejutkan Etiopia yang bersenang-senang dan mereka akan gentar pada hari penghukuman Mesir; sebab, sungguh, hari itu akan datang!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 10, 'Beginilah firman Tuhan ALLAH: Aku akan meniadakan kekayaan Mesir dengan perantaraan Nebukadnezar, raja Babel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 11, 'Ia bersama bangsanya, yaitu yang paling ganas di antara bangsa-bangsa, akan dibawa untuk memusnahkan tanah itu dan mereka akan menghunus pedang terhadap Mesir dan memenuhi tanah itu dengan orang-orang yang terbunuh.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 12, 'Aku akan mengeringkan anak-anak sungai Nil dan akan menyerahkan tanah itu dalam tangan orang-orang jahat dan memusnahkan tanah itu serta segala isinya dengan perantaraan orang-orang asing. Aku, TUHAN, yang mengatakannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 13, 'Beginilah firman Tuhan ALLAH: Aku akan membinasakan berhala-berhala dan meniadakan dewa-dewa dari Memfis; dan tidak akan ada lagi pemimpin di tanah Mesir dan Aku akan menimbulkan ketakutan di sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 14, 'Aku akan memusnahkan Patros dan menimbulkan api di Soan dan menjatuhkan hukuman atas Tebe.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 15, 'Aku akan mencurahkan amarah-Ku atas Sin, benteng Mesir dan melenyapkan kekayaan Tebe.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 16, 'Aku akan menimbulkan api di Mesir, Sin akan gemetar dan Tebe akan direbut dan tembok-temboknya akan dibongkar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 17, 'Teruna-teruna On dan Pi-Beset akan mati rebah oleh pedang dan perempuan-perempuan akan diangkut tertawan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 18, 'Di Tahpanhes hari akan menjadi gelap pada saat Aku mematahkan kekuasaan Mesir di sana dan kecongkakannya, yang ditimbulkan kekuatannya, berakhir. Kota itu akan ditutupi oleh awan dan anak-anaknya perempuan akan diangkut tertawan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 19, 'Dan Aku akan menjatuhkan hukuman atas Mesir dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 20, 'Pada tahun kesebelas, dalam bulan pertama, pada tanggal tujuh bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 21, '"Hai anak manusia, Aku telah mematahkan tangan kekuatan Firaun, raja Mesir, dan lihat, tangannya itu tidak dibalut supaya sembuh kembali, tidak ada yang memasang pembalut supaya kuat kembali untuk mengacungkan pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 22, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Lihat, Aku menjadi lawan Firaun, raja Mesir, dan Aku akan mematahkan tangannya, baik yang masih kuat maupun yang sudah patah, dan Aku akan menjatuhkan pedang dari tangannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 23, 'Aku akan menyerakkan orang Mesir di antara bangsa-bangsa dan menghamburkan mereka ke semua negeri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 24, 'Aku akan menguatkan tangan raja Babel dan akan memberikan pedang-Ku dalam tangannya, tetapi Aku akan mematahkan tangan Firaun dan ia akan merintih di hadapannya seperti orang yang mendapat luka berat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 25, 'Ya, Aku akan menguatkan tangan raja Babel, tetapi tangan raja Firaun akan jatuh terkulai. Dan mereka akan mengetahui bahwa Akulah TUHAN, pada saat Aku memberikan pedang-Ku dalam tangan raja Babel dan ia mengacungkannya melawan tanah Mesir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 30, 26, 'Aku akan menyerakkan orang Mesir di antara bangsa-bangsa dan menghamburkan mereka ke semua negeri. Dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 1, 'Pada tahun kesebelas, dalam bulan yang ketiga, pada tanggal satu bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 2, '"Hai anak manusia, katakanlah kepada Firaun, raja Mesir dan kepada khalayak ramai yang mengikutinya: Di dalam kebesaranmu siapakah yang dapat menyamai engkau?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 3, 'Lihat, Aku menyamakan engkau dengan pohon aras di Libanon, penuh dengan cabang yang elok dan daun yang rumpun sekali; tumbuhnya sangat tinggi, puncaknya sampai ke langit.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 4, 'Sungai-sungai membuatnya besar samudera raya membuatnya meninggi; itu membuat sungainya mengalir mengelilingi bedengnya itu; dan menjulurkan saluran-saluran ke segala pohon yang ada di padang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 5, 'Maka dari itu tumbuhnya lebih tinggi dari segala pohon di padang; ranting-rantingnya menjadi banyak, cabang-cabangnya menjadi panjang lantaran air yang melimpah datang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 6, 'Pada rantingnya diam bersarang segala burung yang di udara, di bawah cabangnya segala binatang di hutan, melahirkan anaknya; dan semuanya bangsa besar duduk bernaung di bawahnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 7, 'Ia elok karena besarnya dan karena cabangnya yang panjang-panjang; karena akarnya julur-jalar sampai di air yang berlimpah-limpah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 8, 'Pohon-pohon aras di dalam taman Allah tidak akan dapat menyainginya, juga pohon sanobar tidak akan dapat menyamai ranting-rantingnya, dan pohon berangan tidak dapat dibandingkan dengan cabang-cabangnya. Segala pohon-pohon yang di taman Allah tiada yang dapat disamakan dengan dia mengenai keelokannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 9, 'Aku membuat dia sungguh-sungguh elok dengan cabang-cabangnya yang sangat rapat. Di taman Eden, di taman Allah segala pohon cemburu padanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 10, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Oleh karena ia tumbuh tinggi dan puncaknya menjulang sampai ke langit dan ia menjadi sombong karena ketinggiannya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 11, 'maka Aku telah menyerahkan dia ke dalam tangan seorang berkuasa di antara bangsa-bangsa, supaya ia memperlakukannya selaras dengan kejahatannya; Aku menghalau dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 12, 'Orang-orang asing, yaitu yang paling ganas di antara bangsa-bangsa, akan menebang dia dan membiarkannya; di atas gunung-gunung dan di semua lembah cabang-cabangnya berjatuhan dan di semua alur sungai negeri itu ranting-rantingnya berpatahan dan semua bangsa di bumi pergi lari dari naungannya dan membiarkan dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 13, 'Di atas batangnya yang roboh itu berhinggapan segala burung di udara dan di antara cabang-cabangnya diam segala binatang di hutan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 14, 'Semuanya ini terjadi supaya segala pohon yang di tepi air jangan meninggikan dirinya dan puncaknya jangan dijulurkan sampai ke langit dan supaya pohon-pohon besar, yaitu semua yang menghisap banyak air, jangan tetap berdiri di dalam kecongkakannya; sebab mereka semuanya telah diserahkan ke dalam maut, ke dalam bumi yang paling bawah, di tengah anak-anak manusia yang telah turun ke liang kubur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 15, 'Beginilah firman Tuhan ALLAH: Pada hari ia turun ke dunia orang mati, Aku membuat samudera raya berkabung karena dia. Aku mengempang sungai-sungainya, sehingga air banjirnya dibendung. Dan karena dia Aku membuat gunung Libanon berpakaian kabung dan membuat segala pohon di hutan layu lesu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 16, 'Mendengar derum kejatuhannya Aku membuat bangsa-bangsa gemetar, pada saat Aku menurunkan dia ke dunia orang mati, menjumpai mereka yang telah turun ke liang kubur. Dan segala pohon taman Eden akan merasa terhibur di bumi yang paling bawah, yaitu pohon yang terpilih dan yang terindah dari Libanon, yang menghisap banyak air.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 17, 'Mereka juga turun bersama dia ke dunia orang mati, yaitu ke orang-orang yang mati terbunuh oleh pedang, dan mereka yang bernaung di bawahnya di tengah bangsa-bangsa mati juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 31, 18, 'Maka dengan siapakah engkau dapat disamakan di antara pohon-pohon di taman Eden dalam hal kemuliaan dan kebesaran? Engkau akan diturunkan ke bumi yang paling bawah bersama pohon-pohon di taman Eden dan engkau telentang di tengah orang-orang yang tak bersunat bersama orang-orang yang mati terbunuh oleh pedang. Itulah Firaun dengan semua khalayak ramai yang mengikutinya, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 1, 'Pada tahun kedua belas, dalam bulan yang kedua belas, pada tanggal satu bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 2, '"Hai anak manusia, ucapkanlah suatu ratapan mengenai Firaun, raja Mesir dan katakanlah kepadanya: Engkau menyamakan dirimu dengan singa muda di antara bangsa-bangsa. Tetapi engkau seperti buaya di laut; sungai-sungaimu kaubuat berbuih, engkau mengeruhkan airnya dengan kaki dan menggelompar dalam lumpur sungainya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 3, 'Beginilah firman Tuhan ALLAH: Aku memasang jaringku menangkap engkau dengan sekumpulan bangsa-bangsa yang banyak, dan mengangkat engkau di dalam pukat-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 4, 'Kuhempaskan engkau ke tanah, Kulemparkan engkau ke padang. Dan ke atasmu Kusuruh hinggap segala burung di udara, dengan dagingmu Kukenyangkan binatang-binatang seluruh bumi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 5, 'Dagingmu Kubiarkan berhamburan di atas pegunungan, lembah-lembah Aku penuhi dengan bangkai-bangkaimu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 6, 'Bumi Kuberi minum darahmu yang mengalir, ya, juga gunung-gunung; dan alur-alur sungai akan penuh dengannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 7, 'Waktu Aku membinasakan engkau, langit akan Kututup dan bintangnya Kubuat berkabut. Matahari Kututup dengan awan dan bulan, cahayanya tak disinarkan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 8, 'Semua yang bersinar di langit akan Kugelapkan demi engkau. Kegelapan Kudatangkan atas tanahmu, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 9, 'Aku menggelisahkan hati banyak bangsa, kalau Aku membawa kamu sebagai tawanan di tengah bangsa-bangsa, ke negeri-negeri yang belum kamu kenal.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 10, 'Aku akan membuat banyak bangsa kaget melihat engkau, dan raja-rajanya akan menggigil melihatmu, kalau Aku menetak-netakkan pedang-Ku di hadapan mereka. Mereka akan gentar, terus-menerus, masing-masing demi hidupnya, pada hari kesudahanmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 11, 'Sebab beginilah firman Tuhan ALLAH: Pedang raja Babel akan datang atasmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 12, 'Aku akan membuat khalayak pengikutmu berebahan oleh pedang para pahlawan, semuanya yang terganas di antara bangsa-bangsa. Kecongkakan Mesir akan dipatahkan dan khalayak pengikutnya semua dipunahkan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 13, 'Semua binatangnya akan Kubinasakan dari tepi sungai-sungai besar; kaki manusia tidak lagi mengeruhkannya dan di dalamnya tiada hewan menggelompar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 14, 'Maka airnya akan Kujernihkan, sungai-sungainya akan Kubuat mengalir seperti minyak, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 15, 'Pada saat Mesir Kujadikan sunyi sepi, juga habis dilenyapkan segala isi negeri dan semua penduduknya habis Kumusnahkan, mereka akan tahu bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 16, 'Inilah ratapan yang seharusnya dinyanyikan; kaum perempuan bangsa-bangsa akan menyanyikannya; mereka akan menyanyikannya atas Mesir dan atas seluruh rakyatnya yang banyak, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 17, 'Pada tahun kedua belas, dalam bulan pertama, pada tanggal lima belas bulan itu, datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 18, '"Hai anak manusia, perdengarkanlah suatu ratapan?engkau bersama kaum perempuan bangsa-bangsa yang hebat?mengenai khalayak ramai di Mesir dan turunkanlah mereka ke bumi yang paling bawah menjumpai mereka yang telah turun ke liang kubur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 19, 'Dari siapakah engkau lebih cantik? Turunlah dan berbaringlah bersama orang-orang yang tidak bersunat!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 20, 'Mereka akan rebah di tengah orang-orang yang mati terbunuh oleh pedang dan seluruh rakyatnya yang banyak akan telentang bersama dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 21, 'Orang-orang berkuasa yang gagah perkasa beserta pembantu-pembantunya akan berbicara mengenai dia dari tengah dunia orang mati: Mereka telah turun dan telentang, orang-orang yang tidak bersunat itu, yang mati terbunuh oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 22, 'Di situ Asyur dengan semua sekutunya, sekelilingnya terdapat kuburnya; mereka semuanya mati terbunuh, rebah oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 23, 'Kuburnya ditentukan pada bagian yang terdalam dari liang dan kumpulan pengikutnya terdapat sekeliling kuburnya; mereka semuanya mati terbunuh, rebah oleh pedang, yaitu yang menimbulkan ketakutan di dunia orang-orang hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 24, 'Di situ Elam dan sekeliling kuburnya seluruh rakyatnya yang banyak; mereka semuanya mati terbunuh, rebah oleh pedang, yaitu yang tanpa disunat turun ke bumi yang paling bawah, yang dari pihaknya menimbulkan ketakutan di dunia orang-orang hidup. Mereka menanggung nodanya bersama orang-orang yang turun ke liang kubur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 25, 'Di tengah orang-orang yang mati terbunuh disediakan tempat tidur baginya dengan seluruh rakyatnya yang banyak sekeliling kuburnya; mereka semuanya orang-orang yang tidak disunat, mati terbunuh oleh pedang. Oleh sebab ketakutan terhadap mereka sudah ditimbulkan di dunia orang-orang hidup, dan mereka menanggung nodanya bersama orang-orang yang turun ke liang kubur; mereka ditempatkan di tengah orang-orang yang mati terbunuh.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 26, 'Di situ Mesekh dan Tubal dengan seluruh rakyatnya yang banyak sekeliling kuburnya; mereka semuanya orang-orang yang tidak disunat, mati terbunuh oleh pedang, sebab mereka menimbulkan ketakutan di dunia orang-orang hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 27, 'Mereka tidak dibaringkan bersama pahlawan-pahlawan yang mati rebah pada zaman dahulu, yang turun ke dunia orang mati bersama segala senjata perangnya dan yang pedang-pedangnya ditaruh orang di bawah kepalanya serta perisai-perisainya terletak di atas tulang-tulangnya; sebab ketakutan terhadap pahlawan-pahlawan itu meliputi dunia orang-orang hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 28, 'Engkau akan telentang di tengah orang-orang yang tidak bersunat bersama orang-orang yang mati terbunuh oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 29, 'Di situ Edom, raja-rajanya dan semua pemimpinnya, yang ditempatkan dekat orang-orang yang mati terbunuh oleh pedang, walaupun mereka kuat; mereka dibaringkan dekat orang-orang yang tidak disunat dan dekat orang-orang yang turun ke liang kubur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 30, 'Di situ pemimpin-pemimpin dari utara, semuanya mereka, dan semua orang Sidon, yang dengan malu turun dekat orang-orang yang mati terbunuh, walaupun dengan kekuatannya mereka sudah menimbulkan ketakutan terhadap mereka; mereka dibaringkan tanpa disunat dekat orang-orang yang mati terbunuh oleh pedang dan mereka menanggung nodanya bersama orang-orang yang turun ke liang kubur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 31, 'Firaun akan melihat mereka semuanya dan ia akan merasa terhibur dengan nasib khalayak ramai yang mengikutinya. Firaun mati terbunuh oleh pedang dengan seluruh tentaranya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 32, 32, 'Oleh karena ia menimbulkan ketakutan di dunia orang-orang hidup, maka ia dibaringkan di tengah orang-orang yang tidak disunat, dekat orang yang mati terbunuh oleh pedang. Firaun dengan seluruh khalayak ramai yang mengikutinya, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 1, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 2, '"Hai anak manusia, berbicaralah kepada teman-temanmu sebangsa dan katakanlah kepada mereka: Kalau Aku mendatangkan pedang atas sesuatu negeri dan bangsa negeri itu mengambil seorang dari antara mereka dan menetapkan dia menjadi penjaganya', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 3, 'dan penjaga ini melihat pedang itu datang atas negerinya, lalu meniup sangkakala untuk memperingatkan bangsanya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 4, 'kalau ada seorang yang memang mendengar suara sangkakala itu, tetapi ia tidak mau diperingatkan, sehingga sesudah pedang itu datang ia dihabiskan, darahnya tertimpa kepadanya sendiri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 5, 'Ia mendengar suara sangkakala, tetapi ia tidak mau diperingatkan, darahnya tertimpa kepadanya sendiri. Kalau ia mau diperingatkan, ia menyelamatkan nyawanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 6, 'Sebaliknya penjaga, yang melihat pedang itu datang, tetapi tidak meniup sangkakala dan bangsanya tidak mendapat peringatan, sehingga sesudah pedang itu datang, seorang dari antara mereka dihabiskan, orang itu dihabiskan dalam kesalahannya, tetapi Aku akan menuntut pertanggungan jawab atas nyawanya dari penjaga itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 7, 'Dan engkau anak manusia, Aku menetapkan engkau menjadi penjaga bagi kaum Israel. Bilamana engkau mendengar sesuatu firman dari pada-Ku, peringatkanlah mereka demi nama-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 8, 'Kalau Aku berfirman kepada orang jahat: Hai orang jahat, engkau pasti mati! ?dan engkau tidak berkata apa-apa untuk memperingatkan orang jahat itu supaya bertobat dari hidupnya, orang jahat itu akan mati dalam kesalahannya, tetapi Aku akan menuntut pertanggungan jawab atas nyawanya dari padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 9, 'Tetapi jikalau engkau memperingatkan orang jahat itu supaya ia bertobat dari hidupnya, tetapi ia tidak mau bertobat, ia akan mati dalam kesalahannya, tetapi engkau telah menyelamatkan nyawamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 10, 'Dan engkau anak manusia, katakanlah kepada kaum Israel: Kamu berkata begini: Pelanggaran kami dan dosa kami sudah tertanggung atas kami dan karena itu kami hancur; bagaimanakah kami dapat tetap hidup?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 11, 'Katakanlah kepada mereka: Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, Aku tidak berkenan kepada kematian orang fasik, melainkan Aku berkenan kepada pertobatan orang fasik itu dari kelakuannya supaya ia hidup. Bertobatlah, bertobatlah dari hidupmu yang jahat itu! Mengapakah kamu akan mati, hai kaum Israel?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 12, 'Dan engkau anak manusia, katakanlah kepada teman-temanmu sebangsa: Kebenaran orang benar tidak menyelamatkan dia, pada waktu ia jatuh dalam pelanggaran dan kejahatan orang jahat tidak menyebabkan dia tersandung, pada waktu ia bertobat dari kejahatannya; dan orang benar tidak dapat hidup karena kebenarannya, pada waktu ia berbuat dosa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 13, 'Kalau Aku berfirman kepada orang benar: Engkau pasti hidup! ?tetapi ia mengandalkan kebenarannya dan ia berbuat curang, segala perbuatan-perbuatan kebenarannya tidak akan diperhitungkan, dan ia harus mati dalam kecurangan yang diperbuatnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 14, 'Kalau Aku berfirman kepada orang jahat: Engkau pasti mati! ?tetapi ia bertobat dari dosanya serta melakukan keadilan dan kebenaran,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 15, 'orang jahat itu mengembalikan gadaian orang, ia membayar ganti rampasannya, menuruti peraturan-peraturan yang memberi hidup, sehingga tidak berbuat curang lagi, ia pasti hidup, ia tidak akan mati.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 16, 'Semua dosa yang diperbuatnya tidak akan diingat-ingat lagi; ia sudah melakukan keadilan dan kebenaran, maka ia pasti hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 17, 'Tetapi teman-temanmu sebangsa berkata: Tindakan Tuhan tidak tepat! Padahal tindakan mereka yang tidak tepat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 18, 'Jikalau orang benar berbalik dari kebenarannya dan melakukan kecurangan, ia harus mati karena itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 19, 'Sebaliknya, kalau orang fasik bertobat dari kefasikannya dan ia melakukan keadilan dan kebenaran, ia pasti hidup karena itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 20, 'Tetapi kamu berkata: Tindakan Tuhan tidak tepat! Aku akan menghakimi kamu, masing-masing menurut kelakuannya, hai kaum Israel."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 21, 'Pada tahun kesebelas sesudah pembuangan kami, dalam bulan yang kesepuluh, pada tanggal lima bulan itu, datanglah kepadaku seorang yang terluput dari Yerusalem dan berkata: "Kota itu sudah ditaklukkan!"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 22, 'Maka kekuasaan TUHAN meliputi aku pada malam sebelum kedatangan orang yang terluput itu dan TUHAN membuka mulutku pada saat menjelang kedatangan orang yang terluput itu pada pagi hari. Mulutku sudah terbuka dan aku tidak bisu lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 23, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 24, '"Hai anak manusia, orang-orang yang tinggal pada reruntuhan-reruntuhan ini, yaitu yang di tanah Israel, berkata begini: Abraham adalah seorang diri, tatkala ia mendapat tanah ini menjadi miliknya, tetapi kita banyak, tentu tanah ini diberikan kepada kita menjadi milik.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 25, 'Oleh karena itu katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Kamu makan daging dengan darahnya, kamu melihat juga kepada berhala-berhalamu dan kamu menumpahkan darah?apakah kamu akan tetap memiliki tanah ini?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 26, 'Kamu bersandar pada pedangmu, kamu melakukan kekejian dan masing-masing mencemari isteri sesamanya?apakah kamu akan tetap memiliki tanah ini?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 27, 'Katakanlah begini kepada mereka: Beginilah firman Tuhan ALLAH. Demi Aku yang hidup, orang-orang yang tinggal pada reruntuhan-reruntuhan akan mati rebah oleh pedang, dan orang-orang yang di padang akan Kuberikan kepada binatang liar menjadi makanannya dan orang-orang yang di dalam kubu dan gua akan mati kena sampar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 28, 'Tanah ini akan Kubuat musnah dan sunyi sepi, dan kecongkakannya, yang ditimbulkan kekuatannya, akan berakhir; gunung-gunung Israel akan menjadi sunyi sepi, sehingga tidak seorangpun berani melintasinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 29, 'Dan mereka akan mengetahui bahwa Akulah TUHAN, pada saat Aku membuat tanah ini musnah dan sunyi sepi, oleh karena semua perbuatan-perbuatan mereka yang keji, yang mereka lakukan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 30, 'Dan engkau anak manusia, teman-temanmu sebangsa bercakap-cakap mengenai engkau dekat tembok-tembok dan di pintu rumah-rumah dan berkata satu sama lain, masing-masing kepada temannya. Silakan datang dan dengar, apa yang difirmankan oleh TUHAN!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 31, 'Dan mereka datang kepadamu seperti rakyat berkerumun dan duduk di hadapanmu sebagai umat-Ku, mereka mendengar apa yang kauucapkan, tetapi mereka tidak melakukannya; mulutnya penuh dengan kata-kata cinta kasih, tetapi hati mereka mengejar keuntungan yang haram.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 32, 'Sungguh, engkau bagi mereka seperti seorang yang melagukan syair cinta kasih dengan suara yang merdu, dan yang pandai main kecapi; mereka mendengar apa yang kauucapkan, tetapi mereka sama sekali tidak melakukannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 33, 33, 'Kalau hal itu datang?dan sungguh akan datang! ?mereka akan mengetahui bahwa seorang nabi ada di tengah-tengah mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 1, 'Lalu datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 2, '"Hai anak manusia, bernubuatlah melawan gembala-gembala Israel, bernubuatlah dan katakanlah kepada mereka, kepada gembala-gembala itu: Beginilah firman Tuhan ALLAH: Celakalah gembala-gembala Israel, yang menggembalakan dirinya sendiri! Bukankah domba-domba yang seharusnya digembalakan oleh gembala-gembala itu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 3, 'Kamu menikmati susunya, dari bulunya kamu buat pakaian, yang gemuk kamu sembelih, tetapi domba-domba itu sendiri tidak kamu gembalakan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 4, 'Yang lemah tidak kamu kuatkan, yang sakit tidak kamu obati, yang luka tidak kamu balut, yang tersesat tidak kamu bawa pulang, yang hilang tidak kamu cari, melainkan kamu injak-injak mereka dengan kekerasan dan kekejaman.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 5, 'Dengan demikian mereka berserak, oleh karena gembala tidak ada, dan mereka menjadi makanan bagi segala binatang di hutan. Domba-domba-Ku berserak', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 6, 'dan tersesat di semua gunung dan di semua bukit yang tinggi; ya, di seluruh tanah itu domba-domba-Ku berserak, tanpa seorangpun yang memperhatikan atau yang mencarinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 7, 'Oleh sebab itu, hai gembala-gembala, dengarlah firman TUHAN:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 8, 'Demi Aku yang hidup, demikianlah firman Tuhan ALLAH, sesungguhnya oleh karena domba-domba-Ku menjadi mangsa dan menjadi makanan bagi segala binatang di hutan, lantaran yang menggembalakannya tidak ada, oleh sebab gembala-gembala-Ku tidak memperhatikan domba-domba-Ku, melainkan mereka itu menggembalakan dirinya sendiri, tetapi domba-domba-Ku tidak digembalakannya?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 9, 'oleh karena itu, hai gembala-gembala, dengarlah firman TUHAN:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 10, 'Beginilah firman Tuhan ALLAH: Aku sendiri akan menjadi lawan gembala-gembala itu dan Aku akan menuntut kembali domba-domba-Ku dari mereka dan akan memberhentikan mereka menggembalakan domba-domba-Ku. Gembala-gembala itu tidak akan terus lagi menggembalakan dirinya sendiri; Aku akan melepaskan domba-domba-Ku dari mulut mereka, sehingga tidak terus lagi menjadi makanannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 11, 'Sebab beginilah firman Tuhan ALLAH: Dengan sesungguhnya Aku sendiri akan memperhatikan domba-domba-Ku dan akan mencarinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 12, 'Seperti seorang gembala mencari dombanya pada waktu domba itu tercerai dari kawanan dombanya, begitulah Aku akan mencari domba-domba-Ku dan Aku akan menyelamatkan mereka dari segala tempat, ke mana mereka diserahkan pada hari berkabut dan hari kegelapan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 13, 'Aku akan membawa mereka keluar dari tengah bangsa-bangsa dan mengumpulkan mereka dari negeri-negeri dan membawa mereka ke tanahnya; Aku akan menggembalakan mereka di atas gunung-gunung Israel, di alur-alur sungainya dan di semua tempat kediaman orang di tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 14, 'Di padang rumput yang baik akan Kugembalakan mereka dan di atas gunung-gunung Israel yang tinggi di situlah tempat penggembalaannya; di sana di tempat penggembalaan yang baik mereka akan berbaring dan rumput yang subur menjadi makanannya di atas gunung-gunung Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 15, 'Aku sendiri akan menggembalakan domba-domba-Ku dan Aku akan membiarkan mereka berbaring, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 16, 'Yang hilang akan Kucari, yang tersesat akan Kubawa pulang, yang luka akan Kubalut, yang sakit akan Kukuatkan, serta yang gemuk dan yang kuat akan Kulindungi; Aku akan menggembalakan mereka sebagaimana seharusnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 17, 'Dan hai kamu domba-domba-Ku, beginilah firman Tuhan ALLAH: Sungguh, Aku akan menjadi hakim di antara domba dengan domba, dan di antara domba jantan dan kambing jantan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 18, 'Apakah belum cukup bagimu bahwa kamu menghabiskan padang rumput yang terbaik? Mesti pulakah kamu injak-injak padang rumput yang lain-lain dengan kakimu? Belum cukup bahwa kamu minum air yang jernih? Mesti pulakah yang tinggal itu kamu keruhkan dengan kakimu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 19, 'Apakah domba-domba-Ku seharusnya memakan rumput yang sudah diinjak-injak kakimu dan meminum air yang sudah dikeruhkan kakimu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 20, 'Oleh sebab itu, beginilah firman Tuhan ALLAH terhadap mereka. Dengan sesungguhnya Aku sendiri akan menjadi hakim di antara domba yang gemuk dengan domba yang kurus;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 21, 'oleh karena semua yang lemah kamu desak dengan lambungmu dan bahumu serta kamu tanduk dengan tandukmu, sehingga kamu menghalau mereka ke luar kandang,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 22, 'maka Aku akan menolong domba-domba-Ku, supaya mereka jangan lagi menjadi mangsa dan Aku akan menjadi hakim di antara domba dengan domba.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 23, 'Aku akan mengangkat satu orang gembala atas mereka, yang akan menggembalakannya, yaitu Daud, hamba-Ku; dia akan menggembalakan mereka, dan menjadi gembalanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 24, 'Dan Aku, TUHAN, akan menjadi Allah mereka serta hamba-Ku Daud menjadi raja di tengah-tengah mereka. Aku, TUHAN, yang mengatakannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 25, 'Aku akan mengadakan perjanjian damai dengan mereka dan Aku akan meniadakan binatang buas dari tanah itu, sehingga mereka dapat diam di padang gurun dengan aman tenteram dan dapat tidur di hutan-hutan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 26, 'Aku akan menjadikan mereka dan semua yang di sekitar gunung-Ku menjadi berkat; Aku akan menurunkan hujan pada waktunya; itu adalah hujan yang membawa berkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 27, 'Pohon-pohon di ladang akan memberi buahnya dan tanah itu akan memberi hasilnya. Mereka akan hidup aman tenteram di tanahnya. Mereka akan mengetahui, bahwa Akulah TUHAN, pada saat Aku mematahkan kayu kuk mereka dan melepaskan mereka dari tangan orang yang memperbudak mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 28, 'Mereka tidak lagi menjadi jarahan bagi bangsa-bangsa dan binatang liar tidak akan menerkam mereka, sehingga mereka akan diam dengan aman tenteram dengan tidak dikejutkan oleh apapun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 29, 'Aku akan mendirikan bagi mereka suatu taman kebahagiaan, sehingga di tanah itu tidak seorangpun akan mati kelaparan dan mereka tidak lagi menanggung noda yang ditimbulkan bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 30, 'Dan mereka akan mengetahui bahwa Aku, TUHAN, Allah mereka, menyertai mereka dan mereka, kaum Israel, adalah umat-Ku, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 34, 31, 'Kamu adalah domba-domba-Ku, domba gembalaan-Ku, dan Aku adalah Allahmu, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 2, '"Hai anak manusia, tujukanlah mukamu kepada pegunungan Seir, bernubuatlah melawan dia', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 3, 'dan katakanlah kepadanya: Beginilah firman Tuhan ALLAH: Aku akan menjadi lawanmu, hai pegunungan Seir dan Aku akan mengacungkan tangan-Ku melawanmu dan akan menjadikan engkau musnah dan sunyi sepi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 4, 'Aku akan menjadikan kota-kotamu reruntuhan dan engkau menjadi sunyi sepi, dan engkau akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 5, 'Oleh karena dalam hatimu terpendam rasa permusuhan yang turun-temurun dan engkau membiarkan orang Israel menjadi makanan pedang pada hari sial mereka, waktu saatnya tiba untuk penghakiman terakhir,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 6, 'oleh sebab itu, demi Aku yang hidup, demikianlah firman Tuhan ALLAH, Aku akan menjadikan engkau darah dan darah akan mengejar engkau; oleh sebab engkau bersalah karena mencurahkan darah, maka darah akan mengejar engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 7, 'Aku akan menjadikan pegunungan Seir musnah dan sunyi sepi dan melenyapkan dari padanya orang-orang yang lalu lalang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 8, 'Aku akan memenuhi juga pegunungannya dengan orang-orang yang mati terbunuh. Di bukit-bukitmu, di lembah-lembahmu dan alur-alur sungaimu akan berebahan orang-orang yang mati terbunuh oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 9, 'Aku akan menjadikan engkau sunyi sepi untuk selama-lamanya dan kota-kotamu tidak akan didiami lagi. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 10, 'Oleh sebab engkau mengatakan: Kedua bangsa itu dan kedua negeri itu akan menjadi milikku dan kita akan memilikinya?sebetulnya TUHAN ada di situ?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 11, 'oleh sebab itu, demi Aku yang hidup, demikianlah firman Tuhan ALLAH, Aku akan memperlakukan engkau seperti engkau memperlakukan mereka dalam murkamu dan cemburumu, yang timbul dari kebencianmu terhadap mereka; dan Aku akan menyatakan diri kepadamu pada saat Aku menghakimi engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 12, 'Dan engkau akan mengetahui bahwa Aku, TUHAN, mendengar segala penistaanmu yang kauucapkan melawan gunung-gunung Israel yang demikian: Gunung-gunung itu sudah menjadi sunyi sepi dan diserahkan kepada kita menjadi makanan kita.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 13, 'Dengan demikian kamu membesarkan dirimu terhadap Aku di dalam ucapanmu dan banyak sekali kata-katamu terhadap Aku. Aku mendengarnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 14, 'Beginilah firman Tuhan ALLAH: Seluruh bumi akan bersukacita pada saat Aku menjadikan engkau sunyi sepi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 35, 15, 'Seperti engkau bersukacita mengenai milik pusaka kaum Israel, yang sudah menjadi sunyi sepi, demikianlah akan Kulakukan terhadap engkau. Engkau akan menjadi sunyi sepi, hai pegunungan Seir dan engkau, segenap Edom dalam keseluruhanmu. Dan mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 1, '"Hai engkau, anak manusia, bernubuatlah mengenai gunung-gunung Israel dan katakanlah: Hai gunung-gunung Israel, dengarlah firman TUHAN!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 2, 'Beginilah firman Tuhan ALLAH: Oleh karena musuh itu berkata mengenai kamu: Syukur! Bukit-bukit dari dahulu kala sudah menjadi milik kita.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 3, 'Oleh karena itu bernubuatlah dan katakan: Beginilah firman Tuhan ALLAH: Oleh karena, ya sungguh karena musuh dari sekitarmu menjadikan kamu sunyi sepi dan mengingini kamu, supaya kamu menjadi milik sisa bangsa-bangsa, dan oleh karena kamu menjadi buah mulut orang dan banyak dipergunjingkan,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 4, 'oleh karena itu, hai gunung-gunung Israel, dengarlah firman Tuhan ALLAH kepada gunung-gunung dan bukit-bukit, kepada alur-alur sungai dan lembah-lembah, kepada reruntuhan-reruntuhan yang sunyi sepi dan kepada kota-kota yang sudah ditinggalkan, yang sudah menjadi jarahan dan olok-olokan bagi sisa bangsa-bangsa yang di sekitarnya;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 5, 'oleh karena itu beginilah firman Tuhan ALLAH: Aku pasti berfirman dalam api cemburuan-Ku melawan sisa bangsa-bangsa dan melawan seluruh Edom, yang menentukan tanah-Ku menjadi miliknya dengan segala rasa sukacita dan rasa penghinaan, sehingga tanah-Ku itu dimilikinya dan dapat habis dijarah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 6, 'Oleh karena itu bernubuatlah mengenai tanah Israel dan katakanlah kepada gunung-gunung dan bukit-bukit, kepada alur-alur sungai dan lembah-lembah: Beginilah firman Tuhan ALLAH: Sungguh, Aku berfirman dalam amarah cemburuan-Ku, oleh karena kamu sudah menanggung noda yang ditimbulkan bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 7, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Aku bersumpah bahwa bangsa-bangsa yang di sekitarmu sendiri pasti akan menanggung noda mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 8, 'Maka kamu, gunung-gunung Israel, akan bertunas kembali dan akan memberi buah untuk umat-Ku Israel, sebab mereka akan segera kembali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 9, 'Hati-Ku akan baik kembali dan Aku akan berpaling kepadamu dan kamu akan dikerjakan dan ditaburi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 10, 'Aku akan membuat manusia banyak di atasmu, yaitu segenap kaum Israel dalam keseluruhannya; kota-kota akan didiami lagi dan reruntuhan-reruntuhan akan dibangun kembali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 11, 'Aku akan membuat manusia dan binatang banyak di atasmu, dan mereka akan bertambah banyak dan beranak cucu dan Aku akan membuat kamu didiami kembali seperti keadaan semula dan akan berbuat baik kepadamu lebih dari pada keadaan dahulu. Dan kamu akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 12, 'Aku akan membuat manusia lalu-lalang di atasmu yaitu umat-Ku Israel; mereka akan menduduki engkau dan engkau akan menjadi milik pusaka mereka dan engkau tidak lagi terus memunahkan mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 13, 'Beginilah firman Tuhan ALLAH: Oleh karena orang berkata tentangmu: Engkau memakan orang dan engkau memunahkan bangsamu?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 14, 'oleh karena itu engkau tidak akan makan orang lagi dan tidak akan memunahkan bangsamu lagi, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 15, 'Aku tidak lagi membiarkan orang membicarakan noda yang ditimbulkan bangsa-bangsa terhadap engkau dan engkau tidak lagi menanggung pencelaan bangsa-bangsa dan tidak lagi memunahkan bangsamu, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 16, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 17, '"Hai anak manusia, waktu kaum Israel tinggal di tanah mereka, mereka menajiskannya dengan tingkah laku mereka; kelakuan mereka sama seperti cemar kain di hadapan-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 18, 'Maka Aku mencurahkan amarah-Ku ke atas mereka karena darah yang dicurahkan mereka di tanah itu, sedang tanah itu mereka najiskan dengan berhala-berhala mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 19, 'Aku menghamburkan mereka di antara bangsa-bangsa, sehingga mereka berserak-serak di semua negeri, Aku menghakimi mereka selaras dengan tingkah lakunya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 20, 'Di mana saja mereka datang di tengah bangsa-bangsa, mereka menajiskan nama-Ku yang kudus, dalam hal orang menyindir mereka: Katanya mereka umat TUHAN, tetapi mereka harus keluar dari tanah-Nya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 21, 'Aku merasa sakit hati karena nama-Ku yang kudus yang dinajiskan oleh kaum Israel di tengah bangsa-bangsa, di mana mereka datang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 22, 'Oleh karena itu katakanlah kepada kaum Israel: Beginilah firman Tuhan ALLAH: Bukan karena kamu Aku bertindak, hai kaum Israel, tetapi karena nama-Ku yang kudus yang kamu najiskan di tengah bangsa-bangsa di mana kamu datang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 23, 'Aku akan menguduskan nama-Ku yang besar yang sudah dinajiskan di tengah bangsa-bangsa, dan yang kamu najiskan di tengah-tengah mereka. Dan bangsa-bangsa akan mengetahui bahwa Akulah TUHAN, demikianlah firman Tuhan ALLAH, manakala Aku menunjukkan kekudusan-Ku kepadamu di hadapan bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 24, 'Aku akan menjemput kamu dari antara bangsa-bangsa dan mengumpulkan kamu dari semua negeri dan akan membawa kamu kembali ke tanahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 25, 'Aku akan mencurahkan kepadamu air jernih, yang akan mentahirkan kamu; dari segala kenajisanmu dan dari semua berhala-berhalamu Aku akan mentahirkan kamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 26, 'Kamu akan Kuberikan hati yang baru, dan roh yang baru di dalam batinmu dan Aku akan menjauhkan dari tubuhmu hati yang keras dan Kuberikan kepadamu hati yang taat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 27, 'Roh-Ku akan Kuberikan diam di dalam batinmu dan Aku akan membuat kamu hidup menurut segala ketetapan-Ku dan tetap berpegang pada peraturan-peraturan-Ku dan melakukannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 28, 'Dan kamu akan diam di dalam negeri yang telah Kuberikan kepada nenek moyangmu dan kamu akan menjadi umat-Ku dan Aku akan menjadi Allahmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 29, 'Aku akan melepaskan kamu dari segala dosa kenajisanmu dan Aku akan menumbuhkan gandum serta memperbanyaknya, dan Aku tidak lagi mendatangkan kelaparan atasmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 30, 'Aku juga memperbanyak buah pohon-pohonanmu dan hasil ladangmu, supaya kamu jangan lagi menanggung noda kelaparan di tengah bangsa-bangsa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 31, 'Dan kamu akan teringat-ingat kepada kelakuanmu yang jahat dan perbuatan-perbuatanmu yang tidak baik dan kamu akan merasa mual melihat dirimu sendiri karena kesalahan-kesalahanmu dan perbuatan-perbuata yang keji.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 32, 'Bukan karena kamu Aku bertindak, demikianlah firman Tuhan ALLAH, ketahuilah itu. Merasa malulah kamu dan biarlah kamu dipermalukan karena kelakuanmu, hai kaum Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 33, 'Beginilah firman Tuhan ALLAH: Pada hari Aku mentahirkan kamu dari segala kesalahanmu, Aku akan membuat kota-kota didiami lagi dan reruntuhan-reruntuhan akan dibangun kembali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 34, 'Tanah yang sudah lama tinggal tandus akan dikerjakan kembali, supaya jangan lagi tetap tandus di hadapan semua orang yang lintas dari padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 35, 'Sebaliknya mereka akan berkata: Tanah ini yang sudah lama tinggal tandus menjadi seperti taman Eden dan kota-kota yang sudah runtuh, sunyi sepi dan musnah, sekarang didiami dan menjadi kubu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 36, 'Dan bangsa-bangsa yang tertinggal, yang ada di sekitarmu akan mengetahui, bahwa Akulah TUHAN, yang membangun kembali yang sudah musnah dan menanami kembali yang sudah tandus. Aku, TUHAN, yang mengatakannya dan akan membuatnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 37, 'Beginilah firman Tuhan ALLAH: Dalam hal ini juga Aku menginginkan, supaya kaum Israel meminta dari pada-Ku apa yang hendak Kulakukan bagi mereka, yaitu membuat mereka banyak seperti lautan manusia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 36, 38, 'Seperti domba-domba persembahan kudus, dan seumpama domba-domba Yerusalem pada waktu-waktu perayaannya, begitulah kota-kota yang sudah runtuh penuh dengan lautan manusia. Dengan begitu mereka akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 1, 'Lalu kekuasaan TUHAN meliputi aku dan Ia membawa aku ke luar dengan perantaraan Roh-Nya dan menempatkan aku di tengah-tengah lembah, dan lembah ini penuh dengan tulang-tulang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 2, 'Ia membawa aku melihat tulang-tulang itu berkeliling-keliling dan sungguh, amat banyak bertaburan di lembah itu; lihat, tulang-tulang itu amat kering.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 3, 'Lalu Ia berfirman kepadaku: "Hai anak manusia, dapatkah tulang-tulang ini dihidupkan kembali?" Aku menjawab: "Ya Tuhan ALLAH, Engkaulah yang mengetahui!"', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 4, 'Lalu firman-Nya kepadaku: "Bernubuatlah mengenai tulang-tulang ini dan katakanlah kepadanya: Hai tulang-tulang yang kering, dengarlah firman TUHAN!', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 5, 'Beginilah firman Tuhan ALLAH kepada tulang-tulang ini: Aku memberi nafas hidup di dalammu, supaya kamu hidup kembali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 6, 'Aku akan memberi urat-urat padamu dan menumbuhkan daging padamu, Aku akan menutupi kamu dengan kulit dan memberikan kamu nafas hidup, supaya kamu hidup kembali. Dan kamu akan mengetahui bahwa Akulah TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 7, 'Lalu aku bernubuat seperti diperintahkan kepadaku; dan segera sesudah aku bernubuat, kedengaranlah suara, sungguh, suatu suara berderak-derak, dan tulang-tulang itu bertemu satu sama lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 8, 'Sedang aku mengamat-amatinya, lihat, urat-urat ada dan daging tumbuh padanya, kemudian kulit menutupinya, tetapi mereka belum bernafas.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 9, 'Maka firman-Nya kepadaku: "Bernubuatlah kepada nafas hidup itu, bernubuatlah, hai anak manusia, dan katakanlah kepada nafas hidup itu: Beginilah firman Tuhan ALLAH: Hai nafas hidup, datanglah dari keempat penjuru angin, dan berembuslah ke dalam orang-orang yang terbunuh ini, supaya mereka hidup kembali."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 10, 'Lalu aku bernubuat seperti diperintahkan-Nya kepadaku. Dan nafas hidup itu masuk di dalam mereka, sehingga mereka hidup kembali. Mereka menjejakkan kakinya, suatu tentara yang sangat besar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 11, 'Firman-Nya kepadaku: "Hai anak manusia, tulang-tulang ini adalah seluruh kaum Israel. Sungguh, mereka sendiri mengatakan: Tulang-tulang kami sudah menjadi kering, dan pengharapan kami sudah lenyap, kami sudah hilang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 12, 'Oleh sebab itu, bernubuatlah dan katakan kepada mereka: Beginilah firman Tuhan ALLAH: Sungguh, Aku membuka kubur-kuburmu dan membangkitkan kamu, hai umat-Ku, dari dalamnya, dan Aku akan membawa kamu ke tanah Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 13, 'Dan kamu akan mengetahui bahwa Akulah TUHAN, pada saat Aku membuka kubur-kuburmu dan membangkitkan kamu, hai umat-Ku, dari dalamnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 14, 'Aku akan memberikan Roh-Ku ke dalammu, sehingga kamu hidup kembali dan Aku akan membiarkan kamu tinggal di tanahmu. Dan kamu akan mengetahui bahwa Aku, TUHAN, yang mengatakannya dan membuatnya, demikianlah firman TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 15, 'Kemudian datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 16, '"Hai engkau anak manusia, ambillah sepotong papan dan tulis di atasnya: Untuk Yehuda dan orang-orang Israel yang bersekutu dengan dia. Kemudian ambillah papan yang lain dan tulis di atasnya: Untuk Yusuf?papan Efraim?dan seluruh kaum Israel yang bersekutu dengan dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 17, 'Gabungkanlah keduanya menjadi satu papan, sehingga keduanya menjadi satu dalam tanganmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 18, 'Maka kalau teman-teman sebangsamu bertanya kepadamu: Tidakkah engkau bersedia memberitahukan kepada kami, apa artinya ini?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 19, 'katakanlah kepada mereka: Beginilah firman Tuhan ALLAH: Aku mengambil papan Yusuf?yang dalam tangan Efraim?beserta suku-suku Israel yang bersekutu dengan dia dan menggabungkannya dengan papan Yehuda dan Aku akan menjadikan mereka satu papan, sehingga mereka menjadi satu dalam tangan-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 20, 'Dan sedang engkau memegang papan-papan yang kautulisi itu dalam tanganmu di hadapan mereka,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 21, 'katakanlah kepadanya: Beginilah firman Tuhan ALLAH: Sungguh, Aku menjemput orang Israel dari tengah bangsa-bangsa, ke mana mereka pergi; Aku akan mengumpulkan mereka dari segala penjuru dan akan membawa mereka ke tanah mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 22, 'Aku akan menjadikan mereka satu bangsa di tanah mereka, di atas gunung-gunung Israel, dan satu raja memerintah mereka seluruhnya; mereka tidak lagi menjadi dua bangsa dan tidak lagi terbagi menjadi dua kerajaan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 23, 'Mereka tidak lagi menajiskan dirinya dengan berhala-berhalanya atau dewa-dewa mereka yang menjijikkan atau dengan semua pelanggaran mereka. Tetapi Aku akan melepaskan mereka dari segala penyelewengan mereka, dengan mana mereka berbuat dosa, dan mentahirkan mereka, sehingga mereka akan menjadi umat-Ku dan Aku akan menjadi Allahnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 24, 'Maka hamba-Ku Daud akan menjadi rajanya, dan mereka semuanya akan mempunyai satu gembala. Mereka akan hidup menurut peraturan-peraturan-Ku dan melakukan ketetapan-ketetapan-Ku dengan setia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 25, 'Mereka akan tinggal di tanah yang Kuberikan kepada hamba-Ku Yakub, di mana nenek moyang mereka tinggal, ya, mereka, anak-anak mereka maupun cucu cicit mereka akan tinggal di sana untuk selama-lamanya dan hamba-Ku Daud menjadi raja mereka untuk selama-lamanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 26, 'Aku akan mengadakan perjanjian damai dengan mereka, dan itu akan menjadi perjanjian yang kekal dengan mereka. Aku akan memberkati mereka dan membuat mereka banyak dan memberikan tempat kudus-Ku di tengah-tengah mereka untuk selama-lamanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 27, 'Tempat kediaman-Kupun akan ada pada mereka dan Aku akan menjadi Allah mereka dan mereka akan menjadi umat-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 37, 28, 'Maka bangsa-bangsa akan mengetahui bahwa Aku, TUHAN, menguduskan Israel, pada waktu tempat kudus-Ku berada di tengah-tengah mereka untuk selama-lamanya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 1, 'Datanglah firman TUHAN kepadaku:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 2, '"Hai anak manusia, tujukanlah mukamu kepada Gog di tanah Magog, yaitu raja agung negeri Mesekh dan Tubal dan bernubuatlah melawan dia', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 3, 'dan katakanlah: Beginilah firman Tuhan ALLAH: Lihat, Aku akan menjadi lawanmu, hai Gog raja agung negeri Mesekh dan Tubal.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 4, 'Aku akan menarik engkau dengan mengenakan kelikir pada rahangmu dan membawa engkau ke luar beserta seluruh tentaramu, yaitu pasukan berkuda, semuanya berpakaian lengkap, suatu kumpulan orang banyak dengan perisai besar dan kecil dan semuanya berpedang di tangannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 5, 'Orang Persia, Etiopia, dan Put menyertai mereka dan semuanya dengan perisai dan ketopong;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 6, 'orang Gomer dengan seluruh bala tentaranya, Bet-Togarma dari utara sekali dengan seluruh bala tentaranya, banyak bangsa menyertai engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 7, 'Bersedialah dan bersiaplah engkau dengan semua kumpulan orang yang menggabungkan diri dengan engkau dan jadilah pelindung bagi mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 8, 'Sesudah waktu yang lama sekali engkau akan mendapat perintah; pada hari yang terkemudian engkau akan datang di sebuah negeri yang dibangun kembali sesudah musnah karena perang, dan engkau menuju suatu bangsa yang dikumpul dari tengah-tengah banyak bangsa di atas gunung-gunung Israel yang telah lama menjadi reruntuhan. Bangsa ini telah dibawa ke luar dari tengah bangsa-bangsa dan mereka semuanya diam dengan aman tenteram.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 9, 'Engkau muncul seperti angin badai dan datang seperti awan yang menutupi seluruh bumi, engkau beserta seluruh bala tentaramu dan banyak bangsa menyertai engkau.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 10, 'Beginilah firman Tuhan ALLAH: Pada hari itu timbullah niat dalam hatimu dan engkau membuat rancangan jahat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 11, 'Engkau berkata: Aku akan bangkit bergerak menyerang tanah yang kota-kotanya tanpa tembok dan akan mendatangi orang-orang yang hidup tenang-tenang dan diam dengan aman tenteram; mereka semuanya diam tanpa tembok atau palang atau pintu gerbang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 12, 'Engkau bermaksud untuk merampas dan menjarah dan mengacungkan tanganmu terhadap reruntuhan-reruntuhan yang sudah didiami kembali dan menyerang umat-Ku yang dikumpulkan dari tengah bangsa-bangsa. Mereka sudah mempunyai ternak dan harta benda dan mereka diam di pusat bumi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 13, 'Negeri Syeba dan Dedan beserta pembeli-pembeli barangnya, negeri Tarsis beserta pedagang-pedagangnya akan berkata kepadamu: Apakah engkau datang untuk merampas dan mengumpulkan sekutumu untuk menjarah, untuk mengangkut perak dan emas, untuk melarikan ternak dan harta benda dan untuk melakukan perampasan yang hebat sekali?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 14, 'Sebab itu, bernubuatlah, hai anak manusia dan katakanlah kepada Gog: Beginilah firman Tuhan ALLAH: Ketika umat-Ku Israel sedang diam dengan aman tenteram, pada waktu itulah engkau akan bergerak', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 15, 'dan datang dari tempatmu dari utara sekali, engkau dengan banyak bangsa yang menyertai engkau, mereka semuanya mengendarai kuda, suatu kumpulan yang besar dan suatu pasukan yang kuat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 16, 'Engkau bangkit melawan umat-Ku Israel seperti awan yang menutupi seluruh bumi. Pada hari yang terkemudian akan terjadi hal itu dan Aku akan membawa engkau untuk melawan tanah-Ku, supaya bangsa-bangsa mengenal Aku, pada saat Aku menunjukkan kekudusan-Ku kepadamu di hadapan mereka, hai Gog.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 17, 'Beginilah firman Tuhan ALLAH: Engkaulah itu tentang siapa Aku sudah berfirman pada hari-hari dahulu kala dengan perantaraan hamba-hamba-Ku, yaitu nabi-nabi Israel, yang bertahun-tahun bernubuat pada waktu itu, bahwa Aku akan membawa engkau melawan umat-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 18, 'Pada waktu itu, pada saat Gog datang melawan tanah Israel, demikianlah firman Tuhan ALLAH, amarah-Ku akan timbul. Dalam murka-Ku,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 19, 'dalam cemburu-Ku dan dalam api kemurkaan-Ku Aku akan berfirman: Pada hari itu pasti terjadi gempa bumi yang dahsyat di tanah Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 20, 'Ikan-ikan di laut, burung-burung di udara, binatang-binatang hutan, segala binatang melata yang merayap di bumi dan semua manusia yang ada di atas bumi akan gentar melihat wajah-Ku. Gunung-gunung akan runtuh, lereng-lereng gunung akan longsor dan tiap tembok akan roboh ke tanah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 21, 'Dan Aku akan memanggil segala macam kekejutan terhadap Gog, demikianlah firman Tuhan ALLAH, sehingga pedang seorang akan memakan yang lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 22, 'Aku akan menghukum dia dengan sampar dan tumpahan darah; Aku akan menurunkan hujan lebat, rambun, api dan hujan belerang ke atasnya dan ke atas tentaranya dan ke atas banyak bangsa yang menyertai dia.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 38, 23, 'Aku akan menunjukkan kebesaran-Ku dan kekudusan-Ku dan menyatakan diri-Ku di hadapan bangsa-bangsa yang banyak, dan mereka akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 1, 'Dan engkau, anak manusia, bernubuatlah melawan Gog dan katakanlah: Beginilah firman Tuhan ALLAH: Lihat, Aku akan menjadi lawanmu, hai Gog raja agung negeri Mesekh dan Tubal', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 2, 'dan Aku akan menarik dan menuntun engkau dan Aku akan mendatangkan engkau dari utara sekali dan membawa engkau ke gunung-gunung Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 3, 'Aku akan memukul tangan kirimu sehingga busurmu jatuh dan membuat panah-panahmu berjatuhan dari tangan kananmu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 4, 'Di atas gunung-gunung Israel engkau akan rebah dengan seluruh bala tentaramu beserta bangsa-bangsa yang menyertai engkau; dan engkau akan Kuberikan kepada burung-burung buas dari segala jenis dan kepada binatang-binatang buas menjadi makanannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 5, 'Engkau akan rebah di padang, sebab Aku yang mengatakannya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 6, 'Aku mendatangkan api ke atas Magog dan ke atas orang-orang yang diam di daerah pesisir dengan aman tenteram, dan mereka akan mengetahui bahwa Akulah TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 7, 'Dan Aku akan menyatakan nama-Ku yang kudus di tengah-tengah umat-Ku Israel dan Aku tidak lagi membiarkan nama-Ku yang kudus dinajiskan, sehingga bangsa-bangsa akan mengetahui bahwa Akulah TUHAN, Yang Mahakudus di Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 8, 'Sungguh, pasti datang dan terjadi, yaitu hari yang sudah Kufirmankan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 9, 'Dan yang diam di kota-kota Israel akan keluar dan menyalakan api serta membakar semua perlengkapan senjata Gog, yaitu perisai kecil dan besar, busur dan panah, tongkat pemukul dan tombak, dan mereka membakarnya selama tujuh tahun.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 10, 'Mereka tidak akan mengambil kayu dari hutan belukar atau membelah kayu api di hutan-hutan, sebab mereka akan menyalakan api itu dengan perlengkapan senjata itu. Mereka akan merampas orang-orang yang merampas mereka dan menjarah orang-orang yang menjarah mereka, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 11, 'Maka pada hari itu Aku akan memberikan kepada Gog suatu tempat, di mana ia akan dikubur di Israel, yaitu Lembah Penyeberangan di sebelah timur dari laut dan kuburan itu akan menghalangi orang-orang yang menyeberang. Di sana Gog akan dikubur dengan semua khalayak ramai yang mengikutinya dan tempat itu akan disebut Lembah Khalayak Ramai Gog.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 12, 'Kaum Israel akan mengubur mereka selama tujuh bulan dengan maksud mentahirkan tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 13, 'Dan seluruh penduduk negeri turut menguburnya dan hal itu menjadikan mereka kenamaan pada hari Aku menyatakan kemuliaan-Ku, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 14, 'Beberapa orang dikhususkan untuk terus-menerus menjelajahi seluruh tanah itu untuk mengubur orang-orang yang masih bergelimpangan di atas tanah dengan maksud mentahirkannya. Sesudah lewat yang tujuh bulan itu mereka akan memeriksa tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 15, 'Kalau mereka menjelajahinya dan seorang menjumpai sepotong tulang manusia, maka ia harus meletakkan batu di sampingnya sebagai tanda sampai tukang-tukang kubur menguburkannya di Lembah khalayak Ramai Gog.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 16, '?Dan ada juga nama kota Hamona?.Dengan demikian mereka mentahirkan tanah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 17, 'Dan engkau, anak manusia, beginilah firman Tuhan ALLAH: Katakanlah kepada segala jenis burung-burung dan segala binatang buas: Berkumpullah kamu dan datanglah, berhimpunlah kamu dari segala penjuru pada perjamuan korban yang Kuadakan bagimu, yaitu suatu perjamuan korban yang besar di atas gunung-gunung Israel; kamu akan makan daging dan minum darah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 18, 'Daging para pahlawan akan kamu makan dan darah para pemimpin dunia akan kamu minum, mereka semuanya ibarat domba jantan, anak domba, kambing jantan dan lembu jantan, ternak gemukan dari Basan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 19, 'Kamu akan makan lemak sampai kamu kenyang dan minum darah sampai kamu menjadi mabuk pada perjamuan korban yang Kuadakan bagimu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 20, 'Kamu akan menjadi kenyang pada perjamuan-Ku dengan makanan: kuda dan penunggangnya, pahlawan dan semua orang perang, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 21, 'Aku akan membuat kuasa kemuliaan-Ku berlaku atas bangsa-bangsa dan mereka semua melihat hukuman yang akan Kujatuhkan dan melihat tangan-Ku yang akan memukul mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 22, 'Dan kaum Israel akan mengetahui bahwa Akulah TUHAN, Allah mereka, mulai hari itu dan seterusnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 23, 'Dan bangsa-bangsa akan mengetahui bahwa karena kesalahannya kaum Israel harus pergi ke dalam pembuangan, dan sebab mereka berobah setia terhadap Aku, Aku menyembunyikan wajah-Ku terhadap mereka. Dan Aku menyerahkan mereka ke dalam tangan lawan-lawannya dan mereka semuanya mati rebah oleh pedang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 24, 'Selaras dengan kenajisan dan durhaka mereka Kuperlakukan mereka dan Kusembunyikan wajah-Ku terhadap mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 25, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Sekarang, Aku akan memulihkan keadaan Yakub dan akan menyayangi seluruh kaum Israel dan cemburu-Ku timbul untuk mempertahankan nama-Ku yang kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 26, 'Mereka akan melupakan noda mereka dan segala ketidaksetiaan mereka, yang dilakukannya terhadap Aku, kalau mereka sudah diam kembali di tanah mereka dengan aman tenteram dengan tidak dikejutkan oleh apapun,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 27, 'dan kalau Aku sudah membawa mereka kembali dari tengah bangsa-bangsa dan mengumpulkan mereka dari tanah musuh-musuh mereka dan pada saat Aku menunjukkan kekudusan-Ku kepada mereka di hadapan bangsa-bangsa yang banyak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 28, 'Dan mereka akan mengetahui bahwa Akulah TUHAN, Allah mereka, yang membawa mereka ke dalam pembuangan di tengah bangsa-bangsa dan mengumpulkan mereka kembali di tanahnya dan Aku tidak membiarkan seorangpun dari padanya tinggal di sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 39, 29, 'Aku tidak lagi menyembunyikan wajah-Ku terhadap mereka, kalau Aku mencurahkan Roh-Ku ke atas kaum Israel, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 1, 'Dalam tahun kedua puluh lima sesudah pembuangan kami, yaitu pada permulaan tahun, pada tanggal sepuluh bulan itu, dalam tahun keempat belas sesudah kota itu ditaklukkan, pada hari itu juga kekuasaan TUHAN meliputi aku dan dibawa-Nya aku', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 2, 'dalam penglihatan-penglihatan ilahi ke tanah Israel dan menempatkan aku di atas sebuah gunung yang tinggi sekali. Di atas itu di hadapanku ada yang menyerupai bentuk kota.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 3, 'Ke sanalah aku dibawa-Nya. Dan lihat, ada seorang yang kelihatan seperti tembaga dan di tangannya ada tali lenan beserta tongkat pengukur; dan ia berdiri di pintu gerbang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 4, 'Orang itu berbicara kepadaku: "Hai anak manusia, lihatlah dengan teliti dan dengarlah dengan sungguh-sungguh dan perhatikanlah baik-baik segala sesuatu yang akan kuperlihatkan kepadamu; sebab untuk itulah engkau dibawa ke mari, supaya aku memperlihatkan semuanya itu kepadamu. Beritahukanlah segala sesuatu yang kaulihat kepada kaum Israel."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 5, 'Lihat, di luar bangunan itu ada tembok, seluruh keliling bangunan itu. Dan di tangan orang itu ada tongkat pengukur, yang panjangnya enam hasta. ?Hasta ini setapak tangan lebih panjang dari hasta biasa?.Ia mengukur tembok itu, tebalnya satu tongkat dan tingginya satu tongkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 6, 'Lalu ia sampai di pintu gerbang yang menghadap ke timur dan menaiki tangganya, ia mengukur ambang dari pintu gerbang itu: satu tongkat lebarnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 7, 'Kemudian ia mengukur kamar jaga: panjangnya satu tongkat dan lebarnya satu tongkat, dan jarak antara dua kamar jaga adalah lima hasta. Dan ambang pintu gerbang sebelah dalam yang dekat balai gerbang itu adalah satu tongkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 8, 'Kemudian ia mengukur balai gerbang itu: delapan hasta', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 9, 'dan tiang temboknya dua hasta dan balai itu ada di sebelah dalam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 10, 'Mengenai kamar-kamar jaga yang di pintu gerbang sebelah timur itu ada tiga kamar pada tiap sisi; ketiga-tiganya sama ukurannya dan kedua tiang tembok pada kedua sisi sama juga ukurannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 11, 'Lalu ia mengukur lobang pintu gerbang itu: lebarnya sebelah dalam adalah sepuluh hasta, dan lebarnya sebelah luar tiga belas hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 12, 'Di bagian muka dari kamar-kamar jaga itu ada sekatan, yang berukuran satu hasta dan demikian juga ukuran sekatan di sebelah yang lain. Dan ukuran kamar jaga itu adalah enam hasta pada kedua belah pihak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 13, 'Lalu ia mengukur pintu gerbang itu dari dinding belakang kamar jaga yang satu sampai dinding belakang kamar jaga yang lain, melalui kedua pintu sekatan itu: lebarnya dua puluh lima hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 14, 'Ia mengukur juga balai gerbang itu: dua puluh hasta dan sekeliling balai gerbang itu adalah pelataran.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 15, 'Dari muka pintu gerbang luar sampai balai gerbang sebelah dalam: lima puluh hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 16, 'Pada sekeliling pintu gerbang itu di bagian dalam ada jendela-jendela dengan bidai, yaitu di kamar-kamar jaga dan pada tiang-tiang tembok dan begitu juga pada balai gerbang. Dan pada tiang-tiang tembok itu terukir gambar pohon-pohon korma.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 17, 'Lalu dibawanya aku ke pelataran luar, sungguh, sekeliling pelataran itu ada bilik-bilik, yang jumlahnya tiga puluh. Dan bilik-bilik itu dibangun di atas sebuah lantai batu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 18, 'Dan lantai batu itu ada di samping pintu-pintu gerbang mengikuti panjangnya. Itulah lantai batu bawah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 19, 'Kemudian ia mengukur lebar pelataran itu dari sebelah dalam pintu gerbang bawah sampai sebelah luar pintu gerbang dalam: seratus hasta. Lalu ia berjalan di depanku menuju ke utara', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 20, 'dan sungguh, ada pintu gerbang yang menghadap ke utara, yang termasuk pelataran luar. Ia mengukur panjang dan lebarnya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 21, 'Kamar jaganya, tiga sebelah-menyebelah, tiang-tiang tembok dan balai gerbangnya adalah seukuran dengan pintu gerbang pertama: lima puluh hasta panjangnya dan lebarnya dua puluh lima hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 22, 'Jendela-jendelanya, balai gerbangnya dan gambar-gambar pohon kormanya seukuran juga dengan pintu gerbang yang menghadap ke timur. Orang dapat naik ke situ melalui tangga yang tujuh tingkat dan balai gerbangnya ada sebelah dalam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 23, 'Di pelataran dalam ada sebuah pintu gerbang yang berhadapan dengan pintu gerbang utara sama seperti halnya dengan pintu gerbang timur; ia mengukur dari pintu gerbang sampai pintu gerbang: seratus hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 24, 'Kemudian ia membawa aku menuju selatan, sungguh, ada sebuah pintu gerbang yang menghadap ke selatan; ia mengukur kamar-kamar jaganya, tiang-tiang temboknya dan balai gerbangnya, ukurannya sama saja dengan yang lain-lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 25, 'Sekeliling pintu gerbang itu dan balai gerbangnya ada jendela-jendela, yang sama dengan yang lain-lain; panjang pintu gerbang itu lima puluh hasta dan lebarnya dua puluh lima hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 26, 'Tangga ke situ adalah tujuh tingkat, dan balai gerbangnya ada sebelah dalam. Pada pintu gerbang itu juga, di tiang-tiang temboknya, terukir gambar pohon-pohon korma, satu batang di sebelah sini dan satu batang di sebelah sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 27, 'Di bagian selatan pelataran dalam ada juga pintu gerbang; ia mengukur dari pintu gerbang sampai pintu gerbang di bagian selatan: seratus hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 28, 'Lalu dibawanya aku ke pelataran dalam melalui pintu gerbang selatan dan ia mengukur pintu gerbang itu, ukurannya sama saja dengan yang lain-lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 29, 'Kamar-kamar jaganya, tiang-tiang temboknya dan balai gerbangnya, ukurannya sama saja dengan yang lain-lain. Sekeliling pintu gerbang itu dan balai gerbangnya ada jendela-jendela; panjang pintu gerbang itu lima puluh hasta dan lebarnya dua puluh lima hasta. ?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 30, 'Sekelilingnya ada balai-balai gerbang, panjangnya dua puluh lima hasta dan lebarnya lima hasta. ?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 31, 'Balai gerbangnya adalah sebelah pelataran luar dan pada tiang-tiang temboknya terukir gambar pohon-pohon korma dan tangganya ke atas ada delapan tingkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 32, 'Lalu dibawanya aku ke sebelah timur pelataran dalam dan ia mengukur pintu gerbang yang di situ, dan ukurannya sama saja dengan yang lain-lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 33, 'Kamar-kamar jaganya, tiang-tiang temboknya dan balai gerbangnya, ukurannya sama saja dengan yang lain-lain. Sekeliling pintu gerbang itu dan balai gerbangnya ada jendela-jendela; panjang pintu gerbang itu lima puluh hasta dan lebarnya dua puluh lima hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 34, 'Balai gerbangnya adalah sebelah pelataran luar dan pada tiang-tiang temboknya terukir gambar pohon-pohon korma, sebelah sini dan sebelah sana, dan tangganya ke atas ada delapan tingkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 35, 'Kemudian dibawanya aku ke pintu gerbang utara dan ia mengukurnya, dan ukurannya sama saja dengan yang lain-lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 36, 'Kamar-kamar jaganya, tiang-tiang temboknya dan balai gerbangnya, ukurannya sama saja dengan yang lain-lain, dan sekelilingnya ada jendela-jendela; panjang pintu gerbang itu lima puluh hasta dan lebarnya dua puluh lima hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 37, 'Balai gerbangnya adalah sebelah pelataran luar, dan pada tiang-tiang temboknya terukir gambar pohon-pohon korma, sebelah sini dan sebelah sana, dan tangganya ke atas ada delapan tingkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 38, 'Ada juga sebuah bilik, yang pintunya di balai gerbang dan di sana orang membasuh korban bakaran.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 39, 'Dalam balai gerbang itu ada dua meja sebelah sini dan dua meja sebelah sana, tempat menyembelih korban bakaran, korban penghapus dosa dan korban penebus salah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 40, 'Di samping kiri balai gerbang, di sebelah luar, ada dua meja, dan di samping kanan balai gerbang itu juga dua meja.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 41, 'Jadi di pintu gerbang itu ada empat meja sebelah sini dan empat meja sebelah sana; semuanya delapan meja di situ untuk tempat menyembelih korban.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 42, 'Ada juga empat meja lagi untuk korban bakaran, yang diperbuat dari batu pahat. Panjangnya satu setengah hasta, lebarnya satu setengah hasta dan tingginya satu hasta. Di sana diletakkan perkakas-perkakas untuk menyembelih korban bakaran dan korban sembelihan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 43, 'Sekeliling ruangan itu dipakukan gantungan-gantungan yang panjangnya setapak tangan, dan di atas meja-meja itu diletakkan daging korban.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 44, 'Lalu dibawanya aku ke pelataran dalam, sungguh, di sana ada dua bilik, yaitu satu di samping pintu gerbang utara dan mukanya menghadap ke selatan, satu lagi di samping pintu gerbang selatan dan mukanya menghadap ke utara.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 45, 'Ia berkata kepadaku: "Bilik ini, yang mukanya menghadap ke selatan, adalah bagi imam-imam yang bertugas di Bait Suci,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 46, 'dan bilik yang mukanya menghadap ke utara, adalah bagi imam-imam yang bertugas di mezbah; mereka ini adalah bani Zadok dan hanya golongan inilah dari bani Lewi yang boleh mendekat kepada TUHAN untuk menyelenggarakan kebaktian."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 47, 'Lalu ia mengukur pelataran dalam: itu suatu empat persegi, yang panjangnya seratus hasta dan lebarnya seratus hasta; mezbah ada di hadapan Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 48, 'Lalu dibawanya aku ke balai Bait Suci dan ia mengukur tiang-tiang temboknya: tebalnya lima hasta yang sebelah sini dan lima hasta yang sebelah sana; lebar pintu itu empat belas hasta dan dinding sampingnya masing-masing tiga hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 40, 49, 'Panjang balai Bait Suci itu adalah dua puluh hasta dan lebarnya dua belas hasta. Orang dapat naik ke situ melalui tangga yang sepuluh tingkat dan dekat kedua tiang tembok itu ada dua tiang, satu sebelah sini dan satu sebelah sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 1, 'Kemudian dibawanya aku ke dalam ruang besar Bait Suci dan ia mengukur tiang temboknya: yang sebelah sini enam hasta tebalnya dan yang sebelah sana enam hasta juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 2, 'Lebar pintu itu adalah sepuluh hasta dan lebar dinding sampingnya adalah lima hasta sebelah sini dan lima hasta sebelah sana. Panjang ruang besar diukur juga: empat puluh hasta dan lebarnya dua puluh hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 3, 'Lalu ia sampai ke ruang dalam. Ia mengukur tiang temboknya: tebalnya dua hasta, dan lebar pintu sendiri: enam hasta dan lebar dinding sampingnya tujuh hasta sebelah sini dan tujuh hasta sebelah sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 4, 'Ia mengukur panjang ruang dalam itu: dua puluh hasta, dan lebarnya: dua puluh hasta sesuai dengan lebar ruang besar. Lalu ia berkata kepadaku: "Inilah tempat maha kudus."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 5, 'Kemudian ia mengukur dinding Bait Suci itu: enam hasta tebalnya dan lebar kamar tambahan yang terdapat di sekeliling Bait Suci itu, empat hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 6, 'Kamar-kamar tambahan itu ada tiga tingkat dan pada satu tingkat terdapat tiga puluh kamar. Pada sekeliling dinding Bait Suci ada ceruk-ceruk untuk mengokohkan kamar-kamar tambahan itu, sebab kamar-kamar ini tidak digabungkan pada dinding Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 7, 'Dan kamar-kamar tambahan semakin lebih besar dari tingkat pertama sampai tingkat ketiga selaras dengan bertambah besarnya ceruk-ceruk pada tiap tingkat sekeliling Bait Suci itu; ada tangga menuju ke atas dan dengan demikian orang dapat naik dari tingkat bawah ke tingkat atas melalui tingkat tengah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 8, 'Aku melihat bahwa alas Bait Suci itu lebih tinggi dari sekelilingnya. Dasar kamar-kamar tambahan itu berukuran satu tongkat penuh, yaitu tingginya enam hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 9, 'Tebal dinding yang sebelah luar kamar tambahan adalah lima hasta; lebar bagian alas Bait Suci yang dibiarkan kosong adalah lima hasta. Di antara alas bangunan itu dan', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 10, 'bilik-bilik ada jarak dua puluh hasta sekeliling bangunan itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 11, 'Dan pintu-pintu kamar tambahan ke luar ke bagian yang kosong itu, satu pintu di sebelah utara dan satu pintu di sebelah selatan; dan lebar tempat yang kosong itu adalah lima hasta sekeliling.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 12, 'Bangunan yang terdapat di lapangan tertutup yang di sebelah barat lebarnya tujuh puluh hasta, sedang dinding yang mengelilinginya tebalnya lima hasta dan panjangnya sembilan puluh hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 13, 'Lalu ia mengukur Bait Suci itu: seratus hasta panjangnya dan lapangan tertutup bersama bangunan dan dindingnya: seratus hasta juga;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 14, 'begitu juga lebarnya muka Bait Suci bersama lapangan tertutup sebelah timur: seratus hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 15, 'Kemudian ia mengukur panjang bangunan yang terdapat di lapangan tertutup sebelah barat bersama serambi-serambinya di kedua belah: seratus hasta. Ruang besar, ruang dalam dan balai luar', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 16, 'ditutupi dengan papan dan sekeliling ketiga ruang itu ada jendela-jendela yang berbidai dan serambi-serambi. Di hadapan ambang itu seluruh Bait Suci ditutupi dengan papan, mulai dari lantai sampai ke jendela-jendelanya?sedang jendela-jendela ini terlindung?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 17, 'sampai bagian atas pintu dan ruang dalam dan juga di luar. Dan di seluruh dinding bagian dalam dan bagian luar terukir', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 18, 'gambar-gambar kerub dan pohon-pohon korma, di antara dua kerub sebatang pohon korma, dan masing-masing kerub itu mempunyai dua muka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 19, 'Dari sebelah yang satu muka manusia dan dari sebelah yang lain muka singa yang menghadap ke pohon korma itu dan begitulah dibuat di seluruh Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 20, 'Dari lantai sampai ke atas pintu terukir kerub-kerub dan pohon-pohon korma pada dinding.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 21, 'Tiang-tiang pintu dari ruang besar adalah empat persegi. Dan di hadapan tempat maha kudus ada sesuatu yang kelihatan menyerupai', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 22, 'mezbah dari kayu, tingginya tiga hasta, panjangnya dua hasta dan lebarnya dua hasta; sudut-sudutnya serta alasnya dan dindingnya dari kayu. Ia berkata kepadaku: "Inilah meja yang ada di hadirat TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 23, 'Ruang besar mempunyai dua daun pintu dan tempat maha kudus', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 24, 'juga mempunyai dua daun pintu. Pada pintu-pintu itu ada dua daun pintu yang dapat berputar, dua daun pintu pada pintu yang satu dan dua daun pintu pada yang lain.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 25, 'Pada pintu-pintu ini juga, yaitu pintu-pintu ruang besar, terukir kerub-kerub dan pohon-pohon korma, seperti pada dinding-dinding. Di muka balai Bait Suci itu, yaitu di luar, ada tangga kayu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 41, 26, 'Pada kedua dinding samping dari balai itu ada jendela-jendela yang berbidai dan ukiran pohon-pohon korma.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 1, 'Lalu diiringnya aku ke pelataran luar bagian utara dan dibawanya aku ke bilik-bilik sebelah utara yang berhadapan dengan lapangan tertutup dan berhadapan dengan bangunan yang di ujung barat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 2, 'Panjang bangunan bilik-bilik itu di sebelah utara ialah seratus hasta dan lebarnya lima puluh hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 3, 'Berhadapan dengan yang dua puluh hasta dari pelataran dalam dan berhadapan dengan lantai batu yang terdapat di pelataran luar ada serambi yang berhadap-hadapan dan yang bertingkat tiga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 4, 'Di depan bilik-bilik itu ada gang menuju ke dalam yang lebarnya sepuluh hasta dan panjangnya seratus hasta dan pintu-pintu masuknya adalah di sebelah utara.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 5, 'Bilik-bilik di tingkat atas adalah lebih kecil dari bilik-bilik di tingkat bawah dan tingkat menengah dari bangunan itu oleh karena serambi-serambi itu memakan lebih banyak tempat dari bilik-bilik itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 6, 'Sebab bilik-bilik itu bertingkat tiga dan tidak mempunyai tiang-tiang seperti yang ada di pelataran luar. Itulah sebabnya bilik-bilik atas lebih kecil dari bilik-bilik bawah atau tengah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 7, 'Di luar ada tembok yang sejajar dengan barisan bilik-bilik, berdekatan dengan pelataran luar dan terdapat di hadapan bilik-bilik; panjangnya lima puluh hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 8, 'Sebab barisan bilik yang berbatasan dengan pelataran luar panjangnya adalah lima puluh hasta, tetapi barisan bilik yang berbatasan dengan Bait Suci panjangnya seratus hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 9, 'Di bagian bawah bilik-bilik ini terdapat pintu masuk dari jurusan timur, kalau orang dari pelataran luar ingin masuk ke dalamnya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 10, 'dan pintu itu terdapat pada pangkal tembok luar. Di sebelah selatan di hadapan lapangan tertutup itu dan di hadapan bangunan yang di ujung barat ada juga bilik-bilik', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 11, 'dan di depannya ada gang. Bilik-bilik ini serupa dengan bilik-bilik yang di sebelah utara, panjangnya dan lebarnya, pintu-pintu keluar dan rancangannya. Seperti pintu-pintu masuk di sebelah utara', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 12, 'begitulah pintu-pintu masuk bilik-bilik yang di sebelah selatan. Ada juga pintu pada pangkal jalan yang melintang di sisi tembok, yaitu pintu dari jurusan timur, kalau orang ingin masuk ke dalam bilik-bilik.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 13, 'Lalu ia berkata kepadaku: "Bilik-bilik yang di utara dan bilik-bilik yang di selatan yang menghadap ke lapangan tertutup, itulah bilik-bilik kudus, di mana imam-imam, yang mendekat kepada TUHAN, memakan persembahan-persembahan maha kudus. Di sana mereka akan menaruh persembahan-persembahan maha kudus, korban sajian, korban penghapus dosa dan korban penebus salah, sebab tempat itu kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 14, 'Kalau para imam masuk ke tempat kudus, mereka tidak akan keluar ke pelataran luar, sebelum mereka menanggalkan pakaian mereka di sana, yang dipakainya waktu menyelenggarakan kebaktian, sebab pakaian-pakaian itu adalah kudus. Mereka harus memakai pakaian yang lain, barulah mereka boleh datang ke tempat umat TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 15, 'Sesudah ia selesai dengan mengukur seluruh bangunan dalam itu, ia mengiring aku menuju pintu gerbang yang menghadap ke sebelah timur, lalu mengukur sekeliling lingkungan Bait Suci itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 16, 'Ia mengukur sisi timur dengan tongkat pengukur: lima ratus hasta menurut tongkat pengukur. Lalu ia berputar', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 17, 'dan mengukur sisi utara: lima ratus hasta menurut tongkat pengukur. Ia berputar lagi', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 18, 'ke sisi selatan dan mengukurnya: lima ratus hasta menurut tongkat pengukur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 19, 'Kemudian ia berputar ke sisi barat dan mengukurnya: lima ratus hasta menurut tongkat pengukur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 42, 20, 'Keempat sisinya diukur. Sekeliling lingkungan itu ada tembok: panjangnya lima ratus hasta dan lebarnya lima ratus hasta, untuk memisahkan yang kudus dari yang tidak kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 1, 'Lalu dibawanya aku ke pintu gerbang, yaitu pintu gerbang yang menghadap ke sebelah timur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 2, 'Sungguh, kemuliaan Allah Israel datang dari sebelah timur dan terdengarlah suara seperti suara air terjun yang menderu dan bumi bersinar karena kemuliaan-Nya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 3, 'Yang kelihatan kepadaku itu adalah seperti yang kelihatan kepadaku ketika Ia datang untuk memusnahkan kota itu dan seperti yang kelihatan kepadaku di tepi sungai Kebar, maka aku sembah sujud.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 4, 'Sedang kemuliaan TUHAN masuk di dalam Bait Suci melalui pintu gerbang yang menghadap ke sebelah timur,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 5, 'Roh itu mengangkat aku dan membawa aku ke pelataran dalam, sungguh, Bait Suci itu penuh kemuliaan TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 6, 'Lalu aku mendengar Dia berfirman kepadaku dari dalam Bait Suci itu?orang yang mengukur Bait Suci itu berdiri di sampingku?', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 7, 'dan Ia berfirman kepadaku: "Hai anak manusia, inilah tempat takhta-Ku dan inilah tempat tapak kaki-Ku; di sinilah Aku akan diam di tengah-tengah orang Israel untuk selama-lamanya dan kaum Israel tidak lagi akan menajiskan nama-Ku yang kudus, baik mereka maupun raja-raja mereka, dengan persundalan mereka atau dengan mayat raja-raja mereka yang sudah mati;', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 8, 'juga tidak dengan meletakkan ambang pintu mereka dekat ambang pintu-Ku atau mendirikan tiang-tiang pintu mereka dekat tiang-tiang pintu-Ku, sehingga hanya dinding yang memisahkan Aku dari mereka. Mereka menajiskan nama-Ku yang kudus dengan perbuatan-perbuatan mereka yang keji, maka dari itu Aku menghabiskan mereka dalam amarah-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 9, 'Sekarang, mereka akan menjauhkan ketidaksetiaan mereka dan mayat raja-raja mereka dari pada-Ku dan Aku akan diam di tengah-tengah mereka untuk selama-lamanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 10, 'Maka engkau, hai anak manusia, terangkanlah kepada kaum Israel tentang Bait Suci ini, agar mereka menjadi malu melihat kesalahan-kesalahan mereka, juga bagaimana Bait Suci itu kelihatan dan rancangannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 11, 'Dan kalau mereka merasa malu melihat segala sesuatu yang dilakukan mereka, gambarlah Bait Suci itu, bagian-bagiannya, pintu-pintu keluar dan pintu-pintu masuknya dan seluruh bagannya; beritahukanlah kepada mereka segala peraturannya dan hukumnya dan tuliskanlah itu di hadapan mereka, agar mereka melakukan dengan setia segala hukumnya dan peraturannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 12, 'Inilah ketentuan mengenai Bait Suci itu: seluruh daerah yang di puncak gunung itu adalah maha kudus. Sungguh, inilah ketentuan mengenai Bait Suci itu."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 13, 'Inilah ukuran-ukuran mezbah itu dalam hasta, yaitu hasta yang setapak tangan lebih panjang dari hasta biasa: paritnya adalah satu hasta dalamnya dan satu hasta lebarnya dan sekeliling parit itu ada tepi yang tingginya satu jengkal. Dan inilah tinggi mezbah itu:', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 14, 'dari parit yang di dalam tanah sampai jalur keliling yang terbawah adalah dua hasta dan lebar jalur keliling itu adalah satu hasta. Dari jalur keliling yang terbawah sampai jalur keliling yang di atas ada empat hasta dan lebar jalur keliling itu satu hasta juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 15, 'Tempat perapian itu adalah empat hasta tingginya dan dari tempat perapian itu muncul ke atas empat tanduk.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 16, 'Tempat perapian itu panjangnya dua belas hasta dan lebarnya dua belas hasta, jadi empat persegi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 17, 'Jalur yang mengelilingi perapian itu panjangnya empat belas hasta dan lebarnya empat belas hasta, jadi empat persegi juga. Sekeliling mezbah itu ada parit, yang satu hasta lebarnya dan sekeliling parit itu ada tepinya, yang setengah hasta lebarnya. Tangga mezbah itu adalah sebelah timur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 18, 'Lalu Ia berfirman kepadaku: "Hai anak manusia, beginilah firman Tuhan ALLAH: Beginilah peraturan mengenai mezbah itu: Ketika sudah selesai dibuat dan hendak mempersembahkan korban bakaran di atasnya dan menyiramkan darah padanya,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 19, 'berikanlah kepada imam-imam orang Lewi dari keturunan Zadok seekor lembu jantan muda untuk korban penghapus dosa, sebab merekalah yang boleh mendekat kepada-Ku untuk menyelenggarakan kebaktian, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 20, 'Dan ambillah sedikit dari darah itu dan bubuhlah itu pada keempat tanduk mezbah itu dan pada keempat sudut jalur keliling itu dan pada tepinya sekeliling; dengan demikian engkau menyucikan mezbah itu dan mengadakan pendamaian baginya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 21, 'Ambillah lembu jantan untuk korban penghapus dosa itu dan orang harus membakarnya di tempat yang sudah ditentukan sekitar Bait Suci, di luar tempat kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 22, 'Pada hari kedua engkau harus mempersembahkan seekor kambing jantan yang tidak bercela sebagai korban penghapus dosa dan orang harus menyucikan mezbah itu seperti sudah disucikan dengan lembu jantan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 23, 'Sesudah upacara penyucian itu engkau selesaikan, engkau harus mempersembahkan seekor lembu jantan muda yang tidak bercela dan seekor domba jantan dari antara domba-domba, yang tidak bercela.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 24, 'Engkau harus membawanya ke hadapan TUHAN dan imam-imam harus menaburkan garam ke atasnya dan mempersembahkannya sebagai korban bakaran bagi TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 25, 'Selama tujuh hari engkau harus mengolah setiap hari seekor kambing sebagai korban penghapus dosa; harus diolah juga seekor lembu jantan muda dan domba jantan dari antara domba-domba, yang tidak bercela.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 26, 'Tujuh hari lamanya mereka harus mengadakan pendamaian bagi mezbah itu serta mentahirkannya, dan dengan demikian mentahbiskan mezbah itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 43, 27, 'Sesudah hari-hari itu berakhir, maka pada hari kedelapan dan seterusnya imam-imam akan mengolah korban-korban bakaranmu dan korban-korban keselamatanmu di atas mezbah itu dan Aku akan berkenan kepada kamu, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 1, 'Kemudian ia membawa aku kembali ke pintu gerbang luar dari tempat kudus, yang menghadap ke timur; gerbang ini tertutup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 2, 'Lalu TUHAN berfirman kepadaku: "Pintu gerbang ini harus tetap tertutup, jangan dibuka dan jangan seorangpun masuk dari situ, sebab TUHAN, Allah Israel, sudah masuk melaluinya; karena itu gerbang itu harus tetap tertutup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 3, 'Hanya raja itu, oleh karena ia raja boleh duduk di sana makan santapan di hadapan TUHAN. Raja itu akan masuk melalui balai gerbang dan akan keluar dari situ."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 4, 'Lalu dibawanya aku melalui pintu gerbang utara ke depan Bait Suci; aku melihat, sungguh, rumah TUHAN penuh kemuliaan TUHAN, maka aku sujud menyembah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 5, 'TUHAN berfirman kepadaku: "Hai anak manusia, perhatikanlah baik-baik, lihatlah dengan teliti dan dengarlah dengan sungguh-sungguh segala sesuatu yang hendak Kufirmankan kepadamu mengenai peraturan-peraturan rumah TUHAN dan tentang segala hukumnya dan perhatikanlah baik-baik siapa yang diperbolehkan masuk ke dalamnya: dan siapa yang harus ditolak dari tempat kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 6, 'Katakanlah kepada kaum pemberontak, yaitu kaum Israel: Beginilah firman Tuhan ALLAH: Cukuplah perbuatan-perbuatanmu yang keji itu, hai kaum Israel,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 7, 'yang membiarkan orang-orang asing, yaitu orang-orang yang tidak bersunat hatinya maupun dagingnya masuk dalam tempat kudus-Ku dan dengan kehadirannya mereka menajiskannya waktu kamu mempersembahkan santapan-Ku, yaitu lemak dan darah. Dengan berbuat begitu kamu lebih mengingkari perjanjian-Ku dari pada dengan segala perbuatanmu yang keji yang sudah-sudah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 8, 'Kamu tidak memelihara barang-barang-Ku yang kudus dan kamu mengangkat mereka untuk memelihara kewajibanmu terhadap Aku di dalam tempat kudus-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 9, 'Oleh sebab itu beginilah firman Tuhan ALLAH: Tidak seorangpun dari orang-orang asing yang hatinya dan dagingnya tidak bersunat, boleh masuk dalam tempat kudus-Ku, ya setiap orang asing yang ada di tengah-tengah orang Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 10, 'Tetapi orang-orang Lewi yang menjauh dari pada-Ku waktu Israel sesat dari pada-Ku dengan mengikuti berhala-berhala mereka, akan menanggung hukumannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 11, 'Di dalam tempat kudus-Ku merekalah yang mendapat tugas penjagaan di pintu-pintu gerbang Bait Suci dan tugas pelayanan di dalam Bait Suci; merekalah yang menyembelih korban bakaran dan korban sembelihan bagi bangsa itu dan bertugas bagi bangsa itu untuk melayaninya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 12, 'Oleh karena mereka telah melayani bangsa itu di hadapan berhala-berhala mereka, dan mereka bagi kaum Israel telah menjadi batu sandungan, yang menjatuhkannya ke dalam kesalahan, oleh karena itu Aku bersumpah mengenai mereka, demikianlah firman Tuhan ALLAH, bahwa mereka akan menanggung hukumannya sendiri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 13, 'Mereka tidak akan mendekati Aku untuk melaksanakan tugas imam di hadapan-Ku ataupun mendekati segala barang-Ku yang kudus atau persembahan-persembahan maha kudus; mereka akan menanggung nodanya yang timbul karena perbuatan-perbuatan mereka yang keji.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 14, 'Aku menetapkan mereka untuk bertugas di Bait Suci dan melakukan segala pelayanan yang berhubungan dengan itu dan melakukan segala sesuatu yang perlu di situ.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 15, 'Tetapi mengenai imam-imam orang Lewi dari bani Zadok yang menjalankan tugas-tugas di tempat kudus-Ku waktu orang Israel sesat dari pada-Ku, merekalah yang akan mendekat kepada-Ku untuk menyelenggarakan kebaktian dan bertugas di hadapan-Ku untuk mempersembahkan kepada-Ku lemak dan darah, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 16, 'Merekalah yang akan masuk ke dalam tempat kudus-Ku dan yang akan mendekati meja-Ku untuk menyelenggarakan kebaktian dan mereka akan menjalankan tugasnya terhadap Aku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 17, 'Maka kalau mereka hendak masuk dari pintu-pintu gerbang pelataran dalam, mereka harus mengenakan pakaian lenan; mereka tidak boleh memakai pakaian bulu domba waktu mereka bertugas di pintu-pintu gerbang pelataran dalam atau waktu menyelenggarakan kebaktian dalam Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 18, 'Mereka harus memakai destar lenan dan memakai celana lenan, tetapi jangan memakai ikat pinggang yang menimbulkan keringat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 19, 'Dan waktu mereka keluar ke pelataran luar menjumpai umat TUHAN itu, mereka harus menanggalkan pakaian mereka yang mereka pakai dalam menyelenggarakan kebaktian dan menyimpannya dalam bilik-bilik kudus, kemudian mengenakan pakaian yang lain, supaya umat itu jangan menjadi kudus disebabkan kena kepada pakaian imam-imam itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 20, 'Rambut mereka tidak boleh dicukur atau dibiarkan tumbuh panjang, melainkan harus dipotong pendek.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 21, 'Imam-imam tidak boleh minum anggur, kalau mereka hendak masuk dalam pelataran dalam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 22, 'Janda atau seorang perempuan yang telah diceraikan oleh suaminya jangan mereka ambil menjadi isteri, tetapi hanya seorang perawan dari keturunan kaum Israel, atau seorang janda imam boleh mereka ambil.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 23, 'Mereka harus mengajar umat-Ku tentang perbedaan antara yang kudus dengan yang tidak kudus dan memberitahukan kepada mereka perbedaan antara yang najis dengan yang tahir.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 24, 'Di dalam sesuatu perkara mereka harus bertindak sebagai hakim dan mereka harus menghakiminya menurut peraturan-peraturan-Ku; mereka harus berpegang pada hukum-hukum-Ku dan ketetapan-ketetapan-Ku pada hari-hari raya-Ku dan menguduskan hari-hari Sabat-Ku.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 25, 'Mereka tidak boleh melihat orang mati oleh karena dengan demikian mereka menjadi najis. Hanya dengan mayat bapaknya atau ibunya, anaknya lelaki atau perempuan, kakak adiknya lelaki, kakak adiknya perempuan yang belum kawin, mereka boleh menajiskan dirinya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 26, 'Sesudah pentahirannya ia harus menghitung tujuh hari,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 27, 'dan pada hari ia masuk lagi ke tempat kudus, ke pelataran dalam, untuk menyelenggarakan kebaktian di tempat kudus, ia harus mempersembahkan korban penghapus dosanya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 28, 'Mereka tidak mendapat bagian milik pusaka, sebab Akulah milik pusakanya, dan janganlah berikan kepada mereka tanah milik di Israel, sebab Akulah milik mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 29, 'Persembahan, korban penghapus dosa dan korban penebus salah, merekalah yang harus memakannya dan segala yang dikhususkan di tanah Israel adalah bagian mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 30, 'Dan yang terbaik dari buah sulung apapun dan segala persembahan khusus dari apapun, dari segala persembahan khususmu adalah bagian imam-imam; juga yang terbaik dari tepung jelaimu harus kamu berikan kepada imam supaya rumah-rumahmu mendapat berkat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 44, 31, 'Segala burung atau binatang yang sudah mati atau yang menjadi sisa mangsa binatang buas janganlah dimakan oleh imam-imam."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 1, '"Pada waktu kamu membagi-bagi negeri itu menjadi milik pusakamu dengan jalan mengundi, kamu harus mengkhususkan sebidang dari tanah itu menjadi persembahan khusus yang kudus bagi TUHAN, panjangnya dua puluh lima ribu hasta dan lebarnya dua puluh ribu hasta. Seluruh tanah yang di dalam batas ini adalah kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 2, 'Dari tanah ini harus disediakan untuk tempat kudus suatu empat persegi yang panjang dan lebarnya lima ratus hasta dan sekelilingnya ada lapangan yang lebarnya lima puluh hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 3, 'Dari daerah yang sudah diukur ini ukurlah sebagian yang panjangnya dua puluh lima ribu hasta dan lebarnya sepuluh ribu hasta: di situlah letaknya tempat kudus, dan bagian ini adalah maha kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 4, 'Ini adalah bagian yang kudus dari tanah itu dan menjadi tempat bagi imam-imam yang menyelenggarakan kebaktian di tempat kudus, yang datang mendekat untuk melayani TUHAN. Itulah tempat perumahan mereka dan menjadi daerah kudus untuk tempat kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 5, 'Yang dua puluh lima ribu hasta panjangnya dan sepuluh ribu hasta lebarnya harus menjadi milik orang-orang Lewi yang mendapat tugas pelayanan dalam Bait Suci; itulah kota-kotanya, tempat tinggal mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 6, 'Sebagai milik kota harus engkau tentukan: lima ribu hasta lebarnya dan dua puluh lima ribu hasta panjangnya, berbatasan dengan persembahan khusus yang kudus itu. Itulah untuk seluruh kaum Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 7, 'Mengenai bagian raja itu haruslah terdapat di sebelah barat dan di sebelah timur dari persembahan khusus yang kudus dan milik kota itu dan harus berbatasan dengan kedua bagian itu. Yang di sebelah barat harus sampai ke perbatasan barat dan yang di sebelah timur harus sampai ke perbatasan timur. Jadi panjangnya harus sama dengan panjang dari bagian suatu suku Israel, yaitu dari perbatasan barat sampai perbatasan timur negeri itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 8, 'Itulah yang menjadi miliknya di tanah Israel. Dan raja-raja Israel tidak lagi akan menindas umat-Ku; mereka akan menyerahkan negeri itu kepada kaum Israel menurut suku-suku mereka."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 9, 'Beginilah firman Tuhan ALLAH: "Cukuplah itu, hai raja-raja Israel, jauhkanlah kekerasan dan aniaya, tetapi lakukanlah keadilan dan kebenaran; hentikanlah kekerasanmu yang mengusir umat-Ku dari tanah miliknya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 10, 'Neraca yang betul, efa yang betul dan bat yang betullah patut ada padamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 11, 'Sepatutnyalah efa dan bat mempunyai ukuran yang sama yang ditera, sehingga satu bat isinya sepersepuluh homer, dan satu efa ialah sepersepuluh homer juga; jadi menurut homerlah ukuran-ukuran itu ditera.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 12, 'Bagi kamu satu syikal sepatutnya sama dengan dua puluh gera, lima syikal, ya lima syikal dan sepuluh syikal, ya sepuluh syikal, dan lima puluh syikal adalah satu mina.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 13, 'Inilah persembahan khusus yang kamu harus persembahkan: seperenam efa dari sehomer gandum dan seperenam efa dari sehomer jelai.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 14, 'Tentang ketetapan mengenai minyak: sepersepuluh bat dari satu kor; satu kor adalah sama dengan sepuluh bat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 15, 'Seekor anak domba dari setiap dua ratus ekor milik sesuatu kaum keluarga Israel. Semuanya itu untuk korban sajian, korban bakaran dan korban keselamatan untuk mengadakan pendamaian bagi mereka, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 16, 'Seluruh penduduk negeri harus mempersembahkan persembahan khusus ini kepada raja di Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 17, 'Dan rajalah yang bertanggung jawab mengenai korban bakaran, korban sajian, korban curahan pada hari-hari raya, bulan-bulan baru, hari-hari Sabat dan pada setiap perayaan kaum Israel. Ialah yang akan mengolah korban penghapus dosa, korban sajian, korban bakaran dan korban keselamatan untuk mengadakan pendamaian bagi kaum Israel."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 18, 'Beginilah firman Tuhan ALLAH: "Pada bulan yang pertama, pada tanggal satu bulan itu ambillah seekor lembu jantan muda yang tidak bercela dan sucikanlah tempat kudus itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 19, 'Imam harus mengambil sedikit dari darah korban penghapus dosa dan membubuhnya pada tiang-tiang Bait Suci dan pada keempat sudut jalur keliling yang ada pada mezbah dan pada tiang-tiang pintu gerbang pelataran dalam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 20, 'Demikianlah engkau harus perbuat pada hari pertama bulan yang ketujuh demi orang-orang yang berbuat dosa dengan tidak sengaja dan tanpa diketahui. Dengan demikian engkau mengadakan pendamaian bagi Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 21, 'Pada bulan pertama, pada tanggal empat belas bulan itu haruslah kamu merayakan hari raya Paskah, dan selama tujuh hari kamu harus makan roti yang tidak beragi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 22, 'Pada hari itu raja harus mengolah lembu jantan sebagai korban penghapus dosa karena dirinya dan karena seluruh penduduk negeri.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 23, 'Selama tujuh hari hari raya itu ia harus mengolah korban bakaran bagi TUHAN: tiap hari tujuh ekor lembu jantan dan tujuh ekor domba jantan yang tidak bercela dan untuk korban penghapus dosa tiap hari seekor kambing jantan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 24, 'Sebagai korban sajian ia harus mengolah satu efa tepung dengan seekor lembu dan satu efa tepung dengan seekor domba jantan dan minyak satu hin untuk satu efa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 45, 25, 'Pada bulan ketujuh, pada tanggal lima belas bulan itu, yaitu pada hari raya, ia harus mengolah seperti ini selama tujuh hari: korban penghapus dosa, korban bakaran, korban sajian dan minyak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 1, 'Beginilah firman Tuhan ALLAH: Pintu gerbang pelataran dalam yang menghadap ke sebelah timur haruslah tertutup selama enam hari kerja, tetapi pada hari Sabat supaya dibuka; pada hari bulan baru juga supaya dibuka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 2, 'Raja itu akan masuk dari luar melalui balai gerbang dan akan berdiri dekat tiang pintu gerbang itu. Sementara itu imam-imam akan mengolah korban bakaran dan korban keselamatan raja itu dan ia akan sujud menyembah di ambang pintu gerbang itu, lalu keluar lagi. Dan pintu gerbang itu tidak boleh ditutup sampai petang hari.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 3, 'Penduduk negeri juga harus turut sujud menyembah di hadapan TUHAN di pintu gerbang itu pada hari Sabat dan hari bulan baru.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 4, 'Korban bakaran yang harus dipersembahkan raja itu kepada TUHAN pada hari Sabat ialah enam ekor domba yang tidak bercela dan seekor domba jantan yang tidak bercela.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 5, 'Korban sajian dari domba jantan harus diolah dengan satu efa tepung, tetapi korban sajian dari domba-domba yang lain bergantung pada kemampuannya, serta minyak satu hin untuk satu efa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 6, 'Pada bulan baru harus dipersembahkan seekor lembu jantan muda yang tiada bercela, serta enam ekor domba dan seekor domba jantan yang tiada bercela.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 7, 'Sebagai korban sajian ia harus mengolah satu efa tepung dengan seekor lembu dan satu efa tepung dengan seekor domba jantan, tetapi korban sajian dari domba-domba lain bergantung pada kemampuannya, serta minyak satu hin untuk satu efa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 8, 'Kalau raja hendak masuk ke dalam, ia harus masuk melalui balai gerbang dan keluar dari situ juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 9, 'Tetapi kalau penduduk negeri pada perayaan-perayaan yang tetap berkumpul di hadapan TUHAN, dan yang masuk melalui pintu gerbang utara untuk turut sujud menyembah biarlah mereka keluar melalui pintu gerbang selatan, dan yang masuk melalui pintu gerbang selatan, biarlah keluar melalui pintu gerbang utara. Janganlah seorang kembali melalui pintu gerbang kemasukannya, tetapi masing-masing harus keluar dari pintu gerbang yang di depannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 10, 'Mengenai raja itu, ia akan masuk bersama-sama mereka dan keluar bersama-sama mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 11, 'Pada hari-hari raya dan perayaan-perayaan yang tetap harus ada korban sajian, yaitu satu efa tepung diolah dengan seekor lembu jantan dan satu efa tepung diolah dengan seekor domba jantan, tetapi korban sajian dari domba-domba yang lain bergantung pada kemampuannya, serta minyak satu hin untuk satu efa.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 12, 'Kalau raja mengolah korban bakaran sukarela atau korban keselamatan sukarela bagi TUHAN, maka orang harus membukakan pintu gerbang sebelah timur untuk dia dan ia akan mempersembahkan korban bakarannya dan korban keselamatannya itu seperti ia perbuat pada hari Sabat. Kemudian ia keluar, dan sesudah ia keluar pintu gerbang harus ditutup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 13, 'Tiap hari ia harus mengolah domba yang berumur satu tahun dan yang tiada bercela sebagai korban bakaran bagi TUHAN; setiap pagi ia harus melakukan itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 14, 'Di samping itu setiap pagi ia harus mempersembahkan korban sajian seperenam efa tepung dengan minyak sepertiga hin untuk mencampur tepung yang terbaik itu; itulah korban sajian bagi TUHAN, dan ketetapan itu tetap selama-lamanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 15, 'Demikianlah mereka harus mempersembahkan domba dan korban sajian dan minyak setiap pagi sebagai korban bakaran yang tetap.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 16, 'Beginilah firman Tuhan ALLAH: Kalau raja itu memberi sesuatu pemberian dari milik pusakanya kepada salah seorang anaknya, maka itu menjadi kepunyaan anaknya, dan milik ini menjadi pusaka mereka.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 17, 'Kalau ia memberikan pemberian dari milik pusakanya kepada salah seorang hambanya, maka itu menjadi kepunyaannya sampai tahun kebebasan, lalu harus kembali kepada raja itu; hanya anak-anak raja itu boleh mewarisi milik pusakanya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 18, 'Dan janganlah raja itu mengambil sesuatu dari milik pusaka rakyat, sehingga mereka terdesak dari miliknya; hanya dari miliknya boleh ia mewariskan kepada anak-anaknya supaya jangan seorangpun dari umat-Ku didesak dari miliknya."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 19, 'Lalu dibawanya aku melalui pintu masuk yang di samping pintu gerbang ke bilik-bilik untuk para imam yang di sebelah utara tempat kudus, dan sungguh, di sana di bahagian barat sekali ada suatu tempat.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 20, 'Ia berkata kepadaku: "Di sinilah tempatnya imam-imam memasak korban penebus salah dan korban penghapus dosa dan membakar korban sajian, dan mereka tidak boleh membawanya ke pelataran luar, supaya dengan demikian mereka jangan menguduskan umat TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 21, 'Kemudian diiringnya aku ke pelataran luar dan membiarkan aku pergi ke keempat sudut pelataran itu, sungguh, di tiap sudut pelataran itu ada lagi pelataran.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 22, 'Pada keempat sudut pelataran itu ada pelataran-pelataran kecil, empat puluh hasta panjangnya dan tiga puluh hasta lebarnya, keempatnya sama ukurannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 23, 'Mengelilingi keempat pelataran kecil itu ada tembok batu dan di bagian bawah tembok-tembok batu itu sekelilingnya diperbuat tempat-tempat memasak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 46, 24, 'Ia berkata kepadaku: "Inilah dapur tempat memasak, di mana petugas-petugas Bait Suci memasak korban sembelihan umat TUHAN."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 1, 'Kemudian ia membawa aku kembali ke pintu Bait Suci, dan sungguh, ada air keluar dari bawah ambang pintu Bait Suci itu dan mengalir menuju ke timur; sebab Bait Suci juga menghadap ke timur; dan air itu mengalir dari bawah bagian samping kanan dari Bait Suci itu, sebelah selatan mezbah.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 2, 'Lalu diiringnya aku ke luar melalui pintu gerbang utara dan dibawanya aku berkeliling dari luar menuju pintu gerbang luar yang menghadap ke timur, sungguh, air itu membual dari sebelah selatan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 3, 'Sedang orang itu pergi ke arah timur dan memegang tali pengukur di tangannya, ia mengukur seribu hasta dan menyuruh aku masuk dalam air itu, maka dalamnya sampai di pergelangan kaki.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 4, 'Ia mengukur seribu hasta lagi dan menyuruh aku masuk sekali lagi dalam air itu, sekarang sudah sampai di lutut; kemudian ia mengukur seribu hasta lagi dan menyuruh aku ketiga kalinya masuk ke dalam air itu, sekarang sudah sampai di pinggang.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 5, 'Sekali lagi ia mengukur seribu hasta lagi, sekarang air itu sudah menjadi sungai, di mana aku tidak dapat berjalan lagi, sebab air itu sudah meninggi sehingga orang dapat berenang, suatu sungai yang tidak dapat diseberangi lagi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 6, 'Lalu ia berkata kepadaku: "Sudahkah engkau lihat, hai anak manusia?" Kemudian ia membawa aku kembali menyusur tepi sungai.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 7, 'Dalam perjalanan pulang, sungguh, sepanjang tepi sungai itu ada amat banyak pohon, di sebelah sini dan di sebelah sana.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 8, 'Ia berkata kepadaku: "Sungai ini mengalir menuju wilayah timur, dan menurun ke Araba-Yordan, dan bermuara di Laut Asin, air yang mengandung banyak garam dan air itu menjadi tawar,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 9, 'sehingga ke mana saja sungai itu mengalir, segala makhluk hidup yang berkeriapan di sana akan hidup. Ikan-ikan akan menjadi sangat banyak, sebab ke mana saja air itu sampai, air laut di situ menjadi tawar dan ke mana saja sungai itu mengalir, semuanya di sana hidup.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 10, 'Maka penangkap-penangkap ikan penuh sepanjang tepinya mulai dari En-Gedi sampai En-Eglaim; daerah itu menjadi penjemuran pukat dan di sungai itu ada berjenis-jenis ikan, seperti ikan-ikan di laut besar, sangat banyak.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 11, 'Tetapi rawa-rawanya dan paya-payanya tidak menjadi tawar, itu menjadi tempat mengambil garam.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 12, 'Pada kedua tepi sungai itu tumbuh bermacam-macam pohon buah-buahan, yang daunnya tidak layu dan buahnya tidak habis-habis; tiap bulan ada lagi buahnya yang baru, sebab pohon-pohon itu mendapat air dari tempat kudus itu. Buahnya menjadi makanan dan daunnya menjadi obat."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 13, 'Beginilah firman Tuhan ALLAH: "Inilah batas-batas tanah yang kamu harus bagi-bagi menjadi milik pusakamu di antara kedua belas suku Israel. Yusuf mendapat dua bagian.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 14, 'Tanah itu harus kamu bagi rata, yaitu tanah yang dengan sumpah Kujanjikan memberikannya kepada nenek moyangmu dan dengan demikian tanah ini menjadi milik pusakamu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 15, 'Inilah perbatasan tanah itu: di sebelah utara: dari laut besar terus ke Hetlon sampai jalan masuk ke Hamat dan terus ke Zedad,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 16, 'Berota, Sibraim, yang terletak di antara daerah kota Damsyik dan daerah kota Hamat, terus ke Hazar-Enon yang di daerah kota Hauran.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 17, 'Demikianlah perbatasannya itu mulai dari laut sampai di Hazar-Enon, sehingga daerah kota Damsyik dan juga daerah kota Hamat terletak di sebelah utaranya. Itulah sebelah utara.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 18, 'Di sebelah timur: mulai dari Hazar-Enon yang terletak di antara Hauran dan Damsyik, sungai Yordan menjadi perbatasan di antara Gilead dan tanah Israel, terus ke Laut Timur sampai ke Tamar. Itulah sebelah timur.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 19, 'Di sebelah selatan: perbatasan mulai dari Tamar sampai mata air Meriba dekat Kadesh, terus ke sungai Mesir, terus ke laut besar. Itulah di sebelah selatan perbatasan dengan Tanah Negeb.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 20, 'Di sebelah barat laut besar merupakan perbatasan sampai tempat jalan masuk ke Hamat. Itulah sebelah barat."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 21, '"Tanah inilah kamu harus bagi-bagi di antara kamu menurut suku-suku Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 22, 'Dan kamu harus membagi-baginya menjadi milik pusaka di antara kamu dan di antara orang-orang asing yang tinggal di antara kamu, yang melahirkan anak di tengah-tengahmu dan mereka harus kamu anggap sama seperti orang Israel asli; bersama-sama kamu mereka harus mendapat bagian milik pusaka di tengah-tengah suku-suku Israel.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 47, 23, 'Jadi kalau di tengah-tengah sesuatu suku ada tinggal orang asing, di situlah kamu berikan milik pusakanya, demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 1, 'Inilah nama suku-suku itu: Yang paling utara: dari laut terus ke Hetlon, ke jalan masuk ke Hamat, Hazar-Enon, sehingga daerah kota Damsyik, yang berdekatan dengan Hamat, terletak di sebelah utaranya, dari perbatasan sebelah timur sampai perbatasan sebelah barat terdapat bagian Dan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 2, 'Berbatasan dengan wilayah Dan, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Asyer.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 3, 'Berbatasan dengan wilayah Asyer, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Naftali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 4, 'Berbatasan dengan wilayah Naftali, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Manasye.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 5, 'Berbatasan dengan wilayah Manasye, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Efraim.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 6, 'Berbatasan dengan wilayah Efraim, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Ruben.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 7, 'Berbatasan dengan wilayah Ruben, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Yehuda.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 8, 'Berbatasan dengan wilayah Yehuda, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat persembahan khusus yang harus kamu khususkan, yaitu dua puluh lima ribu hasta lebarnya, dan panjangnya sama dengan panjang satu bagian, yaitu dari perbatasan sebelah timur sampai perbatasan sebelah barat, dan di tengah-tengahnya terdapat tempat kudus.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 9, 'Bagian persembahan khusus yang harus kamu khususkan bagi TUHAN, panjangnya dua puluh lima ribu hasta dan lebarnya dua puluh ribu hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 10, 'Dan bagi orang-orang inilah persembahan khusus yang kudus itu: Bagian imam-imam ialah panjangnya di utara dan selatan dua puluh lima ribu hasta, dan lebarnya di timur dan di barat sepuluh ribu hasta. Dan di tengah-tengahnyalah terletak tempat kudus TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 11, 'Inilah bagian imam-imam, yang sudah dikuduskan, yaitu bani Zadok, yang memelihara kewajibannya terhadap Aku dan yang tidak turut sesat dalam kesesatan orang Israel, seperti orang-orang Lewi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 12, 'Ini adalah bagian khusus bagi mereka dari tanah yang sudah dikhususkan, suatu hal yang maha kudus, berbatasan dengan bagian orang-orang Lewi.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 13, 'Bagian orang-orang Lewi ialah sejajar dengan wilayah imam-imam, panjangnya dua puluh lima ribu hasta dan lebarnya sepuluh ribu hasta. Jadi seluruhnya ialah: panjang dua puluh lima ribu hasta dan lebar dua puluh ribu hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 14, 'Mereka tidak boleh menjual sedikitpun dari situ atau menukarnya, dan mereka tidak boleh mewariskan yang terbaik dari negeri itu kepada orang lain, sebab itu kudus bagi TUHAN.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 15, 'Yang tertinggal dari lebarnya, yaitu lima ribu hasta lagi, yang berbatasan dengan yang dua puluh lima ribu hasta itu adalah tidak kudus, tetapi itu untuk keperluan kota sebagai tempat tinggal dan tanah perladangan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 16, 'Dan ukurannya adalah begini: sebelah utara dan selatan: empat ribu lima ratus hasta, sebelah timur dan barat: juga empat ribu lima ratus hasta.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 17, 'Sekeliling kota itu ada tanah lapang, di sebelah utara dan selatan dua ratus lima puluh hasta, serta di sebelah timur dan barat dua ratus lima puluh hasta juga.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 18, 'Yang tertinggal dari panjangnya, yang sejajar dengan persembahan khusus yang kudus itu, adalah sepuluh ribu hasta di sebelah timur dan sepuluh ribu hasta di sebelah barat dan hasilnya ialah menjadi makanan untuk pekerja-pekerja di kota itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 19, 'Pekerja-pekerja ini, yang datang dari semua suku Israel, akan mengerjakannya.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 20, 'Seluruh persembahan khusus itu adalah dua puluh lima ribu hasta kali dua puluh lima ribu hasta. Dalam bentuk empat persegi kamu harus mengkhususkan persembahan khusus yang kudus itu bersama milik kota itu.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 21, 'Selebihnya adalah milik raja, yaitu di sebelah timur dan barat dari persembahan khusus yang kudus dan milik kota itu, dan berbatasan dengan yang dua puluh lima ribu hasta itu, ke timur sampai di perbatasan timur dan ke barat sampai di perbatasan barat dan sejajar dengan bagian suku-suku lain, adalah untuk raja. Di tengah-tengah bagian itu adalah persembahan khusus yang kudus dan Bait Suci.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 22, 'Terkecuali milik orang-orang Lewi dan milik kota itu?yang terletak di tengah-tengah kepunyaan raja itu?maka yang diapit oleh wilayah Yehuda dan Benyamin adalah bagi raja.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 23, 'Mengenai suku-suku yang lain: dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Benyamin.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 24, 'Berbatasan dengan wilayah Benyamin, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Simeon.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 25, 'Berbatasan dengan wilayah Simeon, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Isakhar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 26, 'Berbatasan dengan wilayah Isakhar, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Zebulon.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 27, 'Berbatasan dengan wilayah Zebulon, dari perbatasan sebelah timur sampai perbatasan sebelah barat, terdapat bagian Gad.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 28, 'Perbatasan wilayah Gad di sebelah selatan ialah dari Tamar sampai mata air Meriba dekat Kadesh, terus ke sungai Mesir, terus ke laut besar.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 29, 'Inilah negeri yang harus kamu bagi-bagi menjadi milik pusakamu di antara suku-suku Israel, dan itulah bagian-bagian mereka, demikianlah firman Tuhan ALLAH."', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 30, '"Inilah pintu-pintu keluar kota itu: di sisi sebelah utara, yang ukurannya adalah empat ribu lima ratus hasta,', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 31, 'terdapat tiga pintu gerbang, yaitu pintu gerbang Ruben, pintu gerbang Yehuda dan pintu gerbang Lewi?sebab pintu-pintu gerbang kota itu disebut menurut nama suku-suku Israel?.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 32, 'Di sisi sebelah timur, yang ukurannya empat ribu lima ratus hasta, terdapat tiga pintu gerbang juga, yaitu pintu gerbang Yusuf, pintu gerbang Benyamin dan pintu gerbang Dan.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 33, 'Di sisi sebelah selatan, yang ukurannya empat ribu lima ratus hasta, terdapat tiga pintu gerbang juga, yaitu pintu gerbang Simeon, pintu gerbang Isakhar dan pintu gerbang Zebulon.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 34, 'Di sisi sebelah barat, yang ukurannya empat ribu lima ratus hasta, terdapat tiga pintu gerbang juga, yaitu pintu gerbang Gad, pintu gerbang Asyer dan pintu gerbang Naftali.', 'id', 'TB'),
  ('26', 'yeh', 'Yehezkiel', 48, 35, 'Jadi keliling kota itu adalah delapan belas ribu hasta. Sejak hari itu nama kota itu ialah: TUHAN HADIR DI SITU."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 1, 'Pada tahun yang ketiga pemerintahan Yoyakim, raja Yehuda, datanglah Nebukadnezar, raja Babel, ke Yerusalem, lalu mengepung kota itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 2, 'Tuhan menyerahkan Yoyakim, raja Yehuda, dan sebagian dari perkakas-perkakas di rumah Allah ke dalam tangannya. Semuanya itu dibawanya ke tanah Sinear, ke dalam rumah dewanya; perkakas-perkakas itu dibawanya ke dalam perbendaharaan dewanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 3, 'Lalu raja bertitah kepada Aspenas, kepala istananya, untuk membawa beberapa orang Israel, yang berasal dari keturunan raja dan dari kaum bangsawan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 4, 'yakni orang-orang muda yang tidak ada sesuatu cela, yang berperawakan baik, yang memahami berbagai-bagai hikmat, berpengetahuan banyak dan yang mempunyai pengertian tentang ilmu, yakni orang-orang yang cakap untuk bekerja dalam istana raja, supaya mereka diajarkan tulisan dan bahasa orang Kasdim.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 5, 'Dan raja menetapkan bagi mereka pelabur setiap hari dari santapan raja dan dari anggur yang biasa diminumnya. Mereka harus dididik selama tiga tahun, dan sesudah itu mereka harus bekerja pada raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 6, 'Di antara mereka itu ada juga beberapa orang Yehuda, yakni Daniel, Hananya, Misael dan Azarya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 7, 'Pemimpin pegawai istana itu memberi nama lain kepada mereka: Daniel dinamainya Beltsazar, Hananya dinamainya Sadrakh, Misael dinamainya Mesakh dan Azarya dinamainya Abednego.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 8, 'Daniel berketetapan untuk tidak menajiskan dirinya dengan santapan raja dan dengan anggur yang biasa diminum raja; dimintanyalah kepada pemimpin pegawai istana itu, supaya ia tak usah menajiskan dirinya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 9, 'Maka Allah mengaruniakan kepada Daniel kasih dan sayang dari pemimpin pegawai istana itu;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 10, 'tetapi berkatalah pemimpin pegawai istana itu kepada Daniel: "Aku takut, kalau-kalau tuanku raja, yang telah menetapkan makanan dan minumanmu, berpendapat bahwa kamu kelihatan kurang sehat dari pada orang-orang muda lain yang sebaya dengan kamu, sehingga karena kamu aku dianggap bersalah oleh raja."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 11, 'Kemudian berkatalah Daniel kepada penjenang yang telah diangkat oleh pemimpin pegawai istana untuk mengawasi Daniel, Hananya, Misael dan Azarya:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 12, '"Adakanlah percobaan dengan hamba-hambamu ini selama sepuluh hari dan biarlah kami diberikan sayur untuk dimakan dan air untuk diminum;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 13, 'sesudah itu bandingkanlah perawakan kami dengan perawakan orang-orang muda yang makan dari santapan raja, kemudian perlakukanlah hamba-hambamu ini sesuai dengan pendapatmu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 14, 'Didengarkannyalah permintaan mereka itu, lalu diadakanlah percobaan dengan mereka selama sepuluh hari.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 15, 'Setelah lewat sepuluh hari, ternyata perawakan mereka lebih baik dan mereka kelihatan lebih gemuk dari pada semua orang muda yang telah makan dari santapan raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 16, 'Kemudian penjenang itu selalu mengambil makanan mereka dan anggur yang harus mereka minum, lalu memberikan sayur kepada mereka.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 17, 'Kepada keempat orang muda itu Allah memberikan pengetahuan dan kepandaian tentang berbagai-bagai tulisan dan hikmat, sedang Daniel juga mempunyai pengertian tentang berbagai-bagai penglihatan dan mimpi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 18, 'Setelah lewat waktu yang ditetapkan raja, bahwa mereka sekalian harus dibawa menghadap, maka dibawalah mereka oleh pemimpin pegawai istana itu ke hadapan Nebukadnezar.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 19, 'Raja bercakap-cakap dengan mereka; dan di antara mereka sekalian itu tidak didapati yang setara dengan Daniel, Hananya, Misael dan Azarya; maka bekerjalah mereka itu pada raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 20, 'Dalam tiap-tiap hal yang memerlukan kebijaksanaan dan pengertian, yang ditanyakan raja kepada mereka, didapatinya bahwa mereka sepuluh kali lebih cerdas dari pada semua orang berilmu dan semua ahli jampi di seluruh kerajaannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 1, 21, 'Daniel ada di sana sampai tahun pertama pemerintahan Koresh.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 1, 'Pada tahun yang kedua pemerintahan Nebukadnezar bermimpilah Nebukadnezar; karena itu hatinya gelisah dan ia tidak dapat tidur.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 2, 'Lalu raja menyuruh memanggil orang-orang berilmu, ahli jampi, ahli sihir dan para Kasdim, untuk menerangkan kepadanya tentang mimpinya itu; maka datanglah mereka dan berdiri di hadapan raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 3, 'Kata raja kepada mereka: "Aku bermimpi, dan hatiku gelisah, karena ingin mengetahui mimpi itu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 4, 'Lalu berkatalah para Kasdim itu kepada raja (dalam bahasa Aram): "Ya raja, kekallah hidupmu! Ceriterakanlah kepada hamba-hambamu mimpi itu, maka kami akan memberitahukan maknanya."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 5, 'Tetapi raja menjawab para Kasdim itu: "Aku telah mengambil keputusan, yakni jika kamu tidak memberitahukan kepadaku mimpi itu dengan maknanya, maka kamu akan dipenggal-penggal dan rumah-rumahmu akan dirobohkan menjadi timbunan puing;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 6, 'tetapi jika kamu dapat memberitahukan mimpi itu dengan maknanya, maka kamu akan menerima hadiah, pemberian-pemberian dan kehormatan yang besar dari padaku. Oleh sebab itu beritahukanlah kepadaku mimpi itu dengan maknanya!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 7, 'Mereka menjawab pula: "Silakan tuanku raja menceriterakan mimpi itu kepada hamba-hambanya ini, maka kami akan memberitahukan maknanya."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 8, 'Jawab raja: "Aku tahu benar-benar, bahwa kamu mencoba mengulur-ulur waktu, karena kamu melihat, bahwa aku telah mengambil keputusan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 9, 'yakni jika kamu tidak dapat memberitahukan kepadaku mimpi itu, maka kamu akan kena hukuman yang sama; dan aku tahu bahwa kamu telah bermufakat untuk mengatakan kepadaku hal-hal yang bohong dan busuk, sampai keadaan berubah. Oleh sebab itu ceriterakanlah kepadaku mimpi itu, supaya aku tahu, bahwa kamu dapat memberitahukan maknanya juga kepadaku."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 10, 'Para Kasdim itu menjawab raja: "Tidak ada seorangpun di muka bumi yang dapat memberitahukan apa yang diminta tuanku raja! Dan tidak pernah seorang raja, bagaimanapun agungnya dan besar kuasanya, telah meminta hal sedemikian dari seorang berilmu atau seorang ahli jampi atau seorang Kasdim.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 11, 'Apa yang diminta tuanku raja adalah terlalu berat, dan tidak ada seorangpun yang dapat memberitahukannya kepada tuanku raja, selain dari dewa-dewa yang tidak berdiam di antara manusia."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 12, 'Maka raja menjadi sangat geram dan murka karena hal itu, lalu dititahkannyalah untuk melenyapkan semua orang bijaksana di Babel.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 13, 'Ketika titah dikeluarkan supaya orang-orang bijaksana dibunuh, maka Daniel dan teman-temannyapun terancam akan dibunuh.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 14, 'Lalu berkatalah Daniel dengan cerdik dan bijaksana kepada Ariokh, pemimpin pengawal raja yang telah pergi untuk membunuh orang-orang bijaksana di Babel itu,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 15, 'katanya kepada Ariokh, pembesar raja itu: "Mengapa titah yang begitu keras ini dikeluarkan oleh raja?" Lalu Ariokh memberitahukan hal itu kepada Daniel.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 16, 'Maka Daniel menghadap raja dan meminta kepadanya, supaya ia diberi waktu untuk memberitahukan makna itu kepada raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 17, 'Kemudian pulanglah Daniel dan memberitahukan hal itu kepada Hananya, Misael dan Azarya, teman-temannya,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 18, 'dengan maksud supaya mereka memohon kasih sayang kepada Allah semesta langit mengenai rahasia itu, supaya Daniel dan teman-temannya jangan dilenyapkan bersama-sama orang-orang bijaksana yang lain di Babel.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 19, 'Maka rahasia itu disingkapkan kepada Daniel dalam suatu penglihatan malam. Lalu Daniel memuji Allah semesta langit.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 20, 'Berkatalah Daniel: "Terpujilah nama Allah dari selama-lamanya sampai selama-lamanya, sebab dari pada Dialah hikmat dan kekuatan!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 21, 'Dia mengubah saat dan waktu, Dia memecat raja dan mengangkat raja, Dia memberi hikmat kepada orang bijaksana dan pengetahuan kepada orang yang berpengertian;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 22, 'Dialah yang menyingkapkan hal-hal yang tidak terduga dan yang tersembunyi, Dia tahu apa yang ada di dalam gelap, dan terang ada pada-Nya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 23, 'Ya Allah nenek moyangku, kupuji dan kumuliakan Engkau, sebab Engkau mengaruniakan kepadaku hikmat dan kekuatan, dan telah memberitahukan kepadaku sekarang apa yang kami mohon kepada-Mu: Engkau telah memberitahukan kepada kami hal yang dipersoalkan raja."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 24, 'Sebab itu pergilah Daniel kepada Ariokh yang telah ditugaskan raja untuk melenyapkan orang-orang bijaksana di Babel; maka pergilah ia serta berkata kepadanya, demikian: "Orang-orang bijaksana di Babel itu jangan kaulenyapkan! Bawalah aku menghadap raja, maka aku akan memberitahukan kepada raja makna itu!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 25, 'Ariokh segera membawa Daniel menghadap raja serta berkata kepada raja demikian: "Aku telah mendapat seorang dari antara orang-orang buangan dari Yehuda, yang dapat memberitahukan makna itu kepada raja."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 26, 'Bertanyalah raja kepada Daniel yang namanya Beltsazar: "Sanggupkah engkau memberitahukan kepadaku mimpi yang telah kulihat itu dengan maknanya juga?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 27, 'Daniel menjawab, katanya kepada raja: "Rahasia, yang ditanyakan tuanku raja, tidaklah dapat diberitahukan kepada raja oleh orang bijaksana, ahli jampi, orang berilmu atau ahli nujum.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 28, 'Tetapi di sorga ada Allah yang menyingkapkan rahasia-rahasia; Ia telah memberitahukan kepada tuanku raja Nebukadnezar apa yang akan terjadi pada hari-hari yang akan datang. Mimpi dan penglihatan-penglihatan yang tuanku lihat di tempat tidur ialah ini:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 29, 'Sedang tuanku ada di tempat tidur, ya tuanku raja, timbul pada tuanku pikiran-pikiran tentang apa yang akan terjadi di kemudian hari, dan Dia yang menyingkapkan rahasia-rahasia telah memberitahukan kepada tuanku apa yang akan terjadi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 30, 'Adapun aku, kepadaku telah disingkapkan rahasia itu, bukan karena hikmat yang mungkin ada padaku melebihi hikmat semua orang yang hidup, tetapi supaya maknanya diberitahukan kepada tuanku raja, dan supaya tuanku mengenal pikiran-pikiran tuanku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 31, 'Ya raja, tuanku melihat suatu penglihatan, yakni sebuah patung yang amat besar! Patung ini tinggi, berkilau-kilauan luar biasa, tegak di hadapan tuanku, dan tampak mendahsyatkan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 32, 'Adapun patung itu, kepalanya dari emas tua, dada dan lengannya dari perak, perut dan pinggangnya dari tembaga,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 33, 'sedang pahanya dari besi dengan kakinya sebagian dari besi dan sebagian lagi dari tanah liat.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 34, 'Sementara tuanku melihatnya, terungkit lepas sebuah batu tanpa perbuatan tangan manusia, lalu menimpa patung itu, tepat pada kakinya yang dari besi dan tanah liat itu, sehingga remuk.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 35, 'Maka dengan sekaligus diremukkannyalah juga besi, tanah liat, tembaga, perak dan emas itu, dan semuanya menjadi seperti sekam di tempat pengirikan pada musim panas, lalu angin menghembuskannya, sehingga tidak ada bekas-bekasnya yang ditemukan. Tetapi batu yang menimpa patung itu menjadi gunung besar yang memenuhi seluruh bumi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 36, 'Itulah mimpi tuanku, dan sekarang maknanya akan kami katakan kepada tuanku raja:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 37, 'Ya tuanku raja, raja segala raja, yang kepadanya oleh Allah semesta langit telah diberikan kerajaan, kekuasaan, kekuatan dan kemuliaan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 38, 'dan yang ke dalam tangannya telah diserahkan-Nya anak-anak manusia, di manapun mereka berada, binatang-binatang di padang dan burung-burung di udara, dan yang dibuat-Nya menjadi kuasa atas semuanya itu?tuankulah kepala yang dari emas itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 39, 'Tetapi sesudah tuanku akan muncul suatu kerajaan lain, yang kurang besar dari kerajaan tuanku; kemudian suatu kerajaan lagi, yakni yang ketiga, dari tembaga, yang akan berkuasa atas seluruh bumi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 40, 'Sesudah itu akan ada suatu kerajaan yang keempat, yang keras seperti besi, tepat seperti besi yang meremukkan dan menghancurkan segala sesuatu; dan seperti besi yang menghancurluluhkan, maka kerajaan ini akan meremukkan dan menghancurluluhkan semuanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 41, 'Dan seperti tuanku lihat kaki dan jari-jarinya sebagian dari tanah liat tukang periuk dan sebagian lagi dari besi, itu berarti, bahwa kerajaan itu terbagi; memang kerajaan itu juga keras seperti besi, sesuai dengan yang tuanku lihat besi itu bercampur dengan tanah liat.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 42, 'Tetapi sebagaimana jari-jari kaki itu sebagian dari besi dan sebagian lagi dari tanah liat, demikianlah kerajaan itu akan menjadi keras sebagian dan rapuh sebagian.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 43, 'Seperti tuanku lihat besi bercampur dengan tanah liat, itu berarti: mereka akan bercampur oleh perkawinan, tetapi tidak akan merupakan satu kesatuan, seperti besi tidak dapat bercampur dengan tanah liat.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 44, 'Tetapi pada zaman raja-raja, Allah semesta langit akan mendirikan suatu kerajaan yang tidak akan binasa sampai selama-lamanya, dan kekuasaan tidak akan beralih lagi kepada bangsa lain: kerajaan itu akan meremukkan segala kerajaan dan menghabisinya, tetapi kerajaan itu sendiri akan tetap untuk selama-lamanya,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 45, 'tepat seperti yang tuanku lihat, bahwa tanpa perbuatan tangan manusia sebuah batu terungkit lepas dari gunung dan meremukkan besi, tembaga, tanah liat, perak dan emas itu. Allah yang maha besar telah memberitahukan kepada tuanku raja apa yang akan terjadi di kemudian hari; mimpi itu adalah benar dan maknanya dapat dipercayai."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 46, 'Lalu sujudlah raja Nebukadnezar serta menyembah Daniel; juga dititahkannya mempersembahkan korban dan bau-bauan kepadanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 47, 'Berkatalah raja kepada Daniel: "Sesungguhnyalah, Allahmu itu Allah yang mengatasi segala allah dan Yang berkuasa atas segala raja, dan Yang menyingkapkan rahasia-rahasia, sebab engkau telah dapat menyingkapkan rahasia itu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 48, 'Lalu raja memuliakan Daniel: dianugerahinyalah dengan banyak pemberian yang besar, dan dibuatnya dia menjadi penguasa atas seluruh wilayah Babel dan menjadi kepala semua orang bijaksana di Babel.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 2, 49, 'Atas permintaan Daniel, raja menyerahkan pemerintahan wilayah Babel itu kepada Sadrakh, Mesakh dan Abednego, sedang Daniel sendiri tinggal di istana raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 1, 'Raja Nebukadnezar membuat sebuah patung emas yang tingginya enam puluh hasta dan lebarnya enam hasta yang didirikannya di dataran Dura di wilayah Babel.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 2, 'Lalu raja Nebukadnezar menyuruh orang mengumpulkan para wakil raja, para penguasa, para bupati, para penasihat negara, para bendahara, para hakim, para ahli hukum dan semua kepala daerah, untuk menghadiri pentahbisan patung yang telah didirikannya itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 3, 'Lalu berkumpullah para wakil raja, para penguasa, para bupati, para penasihat negara, para bendahara, para hakim, para ahli hukum dan semua kepala daerah, untuk menghadiri pentahbisan patung yang telah didirikan raja Nebukadnezar itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 4, 'Dan berserulah seorang bentara dengan suara nyaring: "Beginilah dititahkan kepadamu, hai orang-orang dari segala bangsa, suku bangsa dan bahasa:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 5, 'demi kamu mendengar bunyi sangkakala, seruling, kecapi, rebab, gambus, serdam dan berbagai-bagai jenis bunyi-bunyian, maka haruslah kamu sujud menyembah patung yang telah didirikan raja Nebukadnezar itu;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 6, 'siapa yang tidak sujud menyembah, akan dicampakkan seketika itu juga ke dalam perapian yang menyala-nyala!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 7, 'Sebab itu demi segala bangsa mendengar bunyi sangkakala, seruling, kecapi, rebab, gambus dan berbagai-bagai jenis bunyi-bunyian, maka sujudlah orang-orang dari segala bangsa, suku bangsa dan bahasa, dan menyembah patung emas yang telah didirikan raja Nebukadnezar itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 8, 'Pada waktu itu juga tampillah beberapa orang Kasdim menuduh orang Yahudi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 9, 'Berkatalah mereka kepada raja Nebukadnezar: "Ya raja, kekallah hidup tuanku!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 10, 'Tuanku raja telah mengeluarkan titah, bahwa setiap orang yang mendengar bunyi sangkakala, seruling, kecapi, rebab, gambus, serdam dan berbagai-bagai jenis bunyi-bunyian, harus sujud menyembah patung emas itu,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 11, 'dan bahwa siapa yang tidak sujud menyembah, akan dicampakkan ke dalam perapian yang menyala-nyala.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 12, 'Ada beberapa orang Yahudi, yang kepada mereka telah tuanku berikan pemerintahan atas wilayah Babel, yakni Sadrakh, Mesakh dan Abednego, orang-orang ini tidak mengindahkan titah tuanku, ya raja: mereka tidak memuja dewa tuanku dan tidak menyembah patung emas yang telah tuanku dirikan."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 13, 'Sesudah itu Nebukadnezar memerintahkan dalam marahnya dan geramnya untuk membawa Sadrakh, Mesakh dan Abednego menghadap. Setelah orang-orang itu dibawa menghadap raja,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 14, 'berkatalah Nebukadnezar kepada mereka: "Apakah benar, hai Sadrakh, Mesakh dan Abednego, bahwa kamu tidak memuja dewaku dan tidak menyembah patung emas yang kudirikan itu?', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 15, 'Sekarang, jika kamu bersedia, demi kamu mendengar bunyi sangkakala, seruling, kecapi, rebab, gambus, serdam dan berbagai-bagai jenis bunyi-bunyian, sujudlah menyembah patung yang kubuat itu! Tetapi jika kamu tidak menyembah, kamu akan dicampakkan seketika itu juga ke dalam perapian yang menyala-nyala. Dan dewa manakah yang dapat melepaskan kamu dari dalam tanganku?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 16, 'Lalu Sadrakh, Mesakh dan Abednego menjawab raja Nebukadnezar: "Tidak ada gunanya kami memberi jawab kepada tuanku dalam hal ini.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 17, 'Jika Allah kami yang kami puja sanggup melepaskan kami, maka Ia akan melepaskan kami dari perapian yang menyala-nyala itu, dan dari dalam tanganmu, ya raja;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 18, 'tetapi seandainya tidak, hendaklah tuanku mengetahui, ya raja, bahwa kami tidak akan memuja dewa tuanku, dan tidak akan menyembah patung emas yang tuanku dirikan itu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 19, 'Maka meluaplah kegeraman Nebukadnezar, air mukanya berubah terhadap Sadrakh, Mesakh dan Abednego; lalu diperintahkannya supaya perapian itu dibuat tujuh kali lebih panas dari yang biasa.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 20, 'Kepada beberapa orang yang sangat kuat dari tentaranya dititahkannya untuk mengikat Sadrakh, Mesakh dan Abednego dan mencampakkan mereka ke dalam perapian yang menyala-nyala itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 21, 'Lalu diikatlah ketiga orang itu, dengan jubah, celana, topi dan pakaian-pakaian mereka yang lain, dan dicampakkan ke dalam perapian yang menyala-nyala.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 22, 'Karena titah raja itu keras, dipanaskanlah perapian itu dengan luar biasa, sehingga nyala api itu membakar mati orang-orang yang mengangkat Sadrakh, Mesakh dan Abednego itu ke atas.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 23, 'Tetapi ketiga orang itu, yakni Sadrakh, Mesakh dan Abednego, jatuh ke dalam perapian yang menyala-nyala itu dengan terikat.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 24, 'Ketiga orang itu berjalan-jalan di tengah nyala api seraya bernyanyi kepada Allah serta memuji Tuhan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 25, 'Maka Azarya berdiri dan berdoa sebagai berikut. Ia membuka mulutnya di tengah-tengah api itu, katanya:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 26, '"Terpujilah Engkau, Tuhan, Allah nenek moyang kami, yang patut dihormat, dan dimuliakanlah namaMu selama-lamanya!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 27, 'Oleh karena Engkau adil dalam segala-galanya yang telah Kauperbuat kepada kami; benarlah segala pekerjaanMu! Segala jalanMu adalah lurus, dan benar pulalah segenap keputusanMu!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 28, 'Keputusan-keputusan benar telah Kaujalankan dalam segala sesuatunya yang Kaudatangkan atas diri kami dan atas kota suci nenek moyang kami, yaitu Yerusalem. Sungguh, sesuai dengan keadilan dan kebenaran telah Kaudatangkan semuanya itu oleh sebab segala dosa kami!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 29, 'Memang kami telah berdosa dan berbuat jahat dengan murtad dari padaMu; memang kami telah banyak berbuat dosa, dan perintahMu tidaklah kami dengarkan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 30, 'Tidaklah kami tepati dan tidak kami perbuat, sebagaimana yang telah Kauperintahkan kepada kami demi kebaikan kami sendiri.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 31, 'Sungguh, segala apa yang telah Kaudatangkan atas diri kami, dan segala apa yang telah Kauperbuat kepada kami, telah Kauperbuat menurut yang benar.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 32, 'Kami telah Kauserahkan ke dalam tangan musuh yang fasik, kepada orang murtad yang paling sengit, kepada seorang raja yang lalim, yang lebih jahat dari siapapun di bumi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 33, 'Bahkan membuka mulutpun sekarang kami tak boleh, malu dan nista menjadi bagian para hambaMu dan bagian mereka yang takut kepadaMu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 34, 'Janganlah kami Kautolak selamanya demi namaMu, dan janganlah Kaubatalkan perjanjianMu;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 35, 'janganlah Kautarik kembali dari pada kami belas kasihanMu demi Abraham, kekasihMu, demi Ishak, hambaMu dan demi Israel, orang suciMu,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 36, 'yang kepadanya telah Kaujanjikan untuk memperbanyak keturunan mereka laksana bintang-bintang di langit dan seperti pasir di tepi taut.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 37, 'Ya Tuhan, jumlah kami telah menjadi lebih kecil dari jumlah sekalian bangsa, dan sekarang kamipun dianggap rendah di seluruh bumi oleh karena segala dosa kami.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 38, 'Dewasa inipun tidak ada pemuka, nabi atau penguasa, tiada korban bakaran atau korban sembelihan, korban sajian atau ukupan; tidak pula ada tempat untuk mempersembahkan buah bungaran kepadaMu dan mendapat belas kasihan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 39, 'Tetapi semoga kami diterima baik, karena jiwa yang remuk redam dan roh yang rendah, seolah-olah kami datang membawa korban-korban bakaran domba dan lembu serta ribuan anak domba tambun.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 40, 'Demikianlah hendaknya korban kami di hadapanMu pada hari ini berkenan seluruhnya kepadaMu. Sebab tidak dikecewakanlah mereka yang percaya padaMu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 41, 'Kini kami mengikuti Engkau dengan segenap jiwa dan dengan takut kepadaMu, dan wajahMu kami cari. Janganlah kami Kaupermalukan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 42, 'melainkan perlakukankanlah kami sesuai dengan kemurahanMu dan menurut besarnya belas kasihanMu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 43, 'Lepaskanlah kami sesuai dengan perbuatanMu yang ajaib, dan nyatakanlah kemuliaan namaMu, ya Tuhan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 44, 'Tetapi semoga kesipuanlah semua yang melakukan yang jahat kepada para hambaMu, dan semoga segenap kekuasaan serta keperkasaannya dipermalukan, dan semoga kekuatan mereka dihancurkan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 45, 'supaya diketahuilah oleh mereka bahwa Engkaulah Tuhan, Allah yang tunggal, dan mulia di dunia semesta."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 46, 'Para pelayan raja yang telah mencampakkan mereka ke dalam perapian itu menghangatkannya dengan nafta, gala-gala, pakal dan ranting-ranting', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 47, 'begitu rupa, sehingga nyalanya membubung lebih kurang empat puluh sembilan hasta ke atas perapian itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 48, 'Nyala itu menjulur ke mana-mana dan membakar habis orang-orang Kasdim yang terdapat di keliling perapian itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 49, 'Tetapi bersama dengan Azarya dan kawan-kawannya turunlah malaikat Tuhan ke dalam perapian dan dihalaukannya nyala api ke luar dari perapian itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 50, 'Di dalam perapian itu dibuatnya seolah-olah bertiuplah angin berembun. Maka api sekali-kali tidak menyentuh ketiga orang itu, bahkan tidak sampai menyakiti atau menghanguskan mereka.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 51, 'Maka ketiga orang di dalam perapian itu semulut melambungkan suatu lagu untuk memuliakan dan memuji Allah, katanya:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 52, '"Terpujilah Engkau, Tuhan, Allah nenek moyang kami, yang patut dihormati dan ditinggikan selama-lamanya. Terpujilah namaMu yang mulia dan kudus, yang patut dihormat dan ditinggikan selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 53, 'Terpujilah Engkau dalam BaitMu yang mulia dan kudus, Engkau patut dinyanyikan dan dimuliakan selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 54, 'Terpujilah Engkau di atas takhta kerajaanMu, Engkau patut dinyanyikan dan ditinggikan selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 55, 'Terpujilah Engkau yang mendugai samudera raya dan bersemayam di atas kerub-kerub, Engkau patut dihormat dan ditinggikan selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 56, 'Terpujilah Engkau di bentangan langit, Engkau patut dinyanyikan dan dimuliakan selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 57, 'Pujilah Tuhan, hai segala buatan Tuhan, nyanyikanlah dan tinggikanlah Dia selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 58, 'Pujilah Tuhan, hai segala malaikat Tuhan, nyanyikanlah dan tinggikanlah Dia selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 59, 'Pujilah Tuhan, hai segenap langit, nyanyikanlah dan tinggikanlah Dia selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 3, 60, 'Pujilah Tuhan, hai segala air di atas langit, nyanyikanlah dan tinggikanlah Dia selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 1, 'Dari raja Nebukadnezar kepada orang-orang dari segala bangsa, suku bangsa dan bahasa, yang diam di seluruh bumi: "Bertambah-tambahlah kiranya kesejahteraanmu!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 2, 'Aku berkenan memaklumkan tanda-tanda dan mujizat-mujizat yang telah dilakukan Allah yang maha tinggi kepadaku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 3, 'Betapa besarnya tanda-tanda-Nya dan betapa hebatnya mujizat-mujizat-Nya! Kerajaan-Nya adalah kerajaan yang kekal dan pemerintahan-Nya turun-temurun!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 4, 'Aku, Nebukadnezar, diam dalam rumahku dengan tenang dan hidup dengan senang dalam istanaku;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 5, 'lalu aku mendapat mimpi yang mengejutkan aku, dan khayalanku di tempat tidurku serta penglihatan-penglihatan yang kulihat menggelisahkan aku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 6, 'Maka aku mengeluarkan titah, bahwa semua orang bijaksana di Babel harus dibawa menghadap aku, supaya mereka memberitahukan kepadaku makna mimpi itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 7, 'Kemudian orang-orang berilmu, ahli jampi, para Kasdim dan ahli nujum datang menghadap dan aku menceritakan kepada mereka mimpi itu, tetapi mereka tidak dapat memberitahukan maknanya kepadaku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 8, 'Pada akhirnya Daniel datang menghadap aku, yakni Daniel yang dinamai Beltsazar menurut nama dewaku, dan yang penuh dengan roh para dewa yang kudus. Lalu kuceritakan kepadanya mimpi itu:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 9, 'Hai Beltsazar, kepala orang-orang berilmu! Aku tahu, bahwa engkau penuh dengan roh para dewa yang kudus, dan bahwa tidak ada rahasia yang sukar bagimu! Sebab itu inilah riwayat penglihatan mimpi yang kudapat, maka ceritakanlah kepadaku maknanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 10, 'Adapun penglihatan yang kudapat di tempat tidurku itu, demikian: di tengah-tengah bumi ada sebatang pohon yang sangat tinggi;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 11, 'pohon itu bertambah besar dan kuat, tingginya sampai ke langit, dan dapat dilihat sampai ke ujung seluruh bumi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 12, 'Daun-daunnya indah, buahnya berlimpah-limpah, padanya ada makanan bagi semua yang hidup; di bawahnya binatang-binatang di padang mencari tempat bernaung dan di dahan-dahannya bersarang burung-burung di udara, dan segala makhluk mendapat makanan dari padanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 13, 'Kemudian dalam penglihatan yang kudapat di tempat tidurku itu tampak seorang penjaga, seorang kudus, turun dari langit;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 14, 'ia berseru dengan nyaring, demikian katanya: Tebanglah pohon itu dan potonglah dahan-dahannya, gugurkanlah daun-daunnya dan hamburkanlah buah-buahnya! Biarlah binatang-binatang lari dari bawahnya dan burung-burung dari dahan-dahannya!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 15, 'Tetapi biarkanlah tunggulnya tinggal di dalam tanah, terikat dengan rantai dari besi dan tembaga, di rumput muda di padang; biarlah ia dibasahi dengan embun dari langit dan bersama-sama dengan binatang-binatang mendapat bagiannya dari rumput di bumi!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 16, 'Biarlah hati manusianya berubah dan diberikan kepadanya hati binatang. Demikianlah berlaku atasnya sampai tujuh masa berlalu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 17, 'Titah ini adalah menurut putusan para penjaga dan hal ini menurut perkataan orang-orang kudus, supaya orang-orang yang hidup tahu, bahwa Yang Mahatinggi berkuasa atas kerajaan manusia dan memberikannya kepada siapa yang dikehendaki-Nya, bahkan orang yang paling kecil sekalipun dapat diangkat-Nya untuk kedudukan itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 18, 'Itulah mimpi yang telah kudapat, aku, raja Nebukadnezar; sekarang engkau, Beltsazar, katakanlah kepadaku maknanya, sebab semua orang bijaksana dari kerajaanku tidak dapat memberitahukan maknanya kepadaku; tetapi engkaulah yang sanggup, karena engkau penuh dengan roh para dewa yang kudus!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 19, 'Lalu berdirilah Daniel yang namanya Beltsazar, tercengang beberapa saat, pikiran-pikirannya menggelisahkan dia. Berkatalah raja: "Beltsazar, janganlah mimpi dan maknanya itu menggelisahkan engkau!" Beltsazar menjawab: "Tuanku, biarlah mimpi itu tertimpa atas musuh tuanku dan maknanya atas seteru tuanku!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 20, 'Pohon yang tuanku lihat itu, yang bertambah besar dan kuat, yang tingginya sampai ke langit dan yang terlihat sampai ke seluruh bumi,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 21, 'yang daun-daunnya indah dan buahnya berlimpah-limpah dan padanya ada makanan bagi semua yang hidup, yang di bawahnya ada binatang-binatang di padang dan di dahan-dahannya bersarang burung-burung di udara?', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 22, 'tuankulah itu, ya raja, tuanku yang telah bertambah besar dan kuat, yang kebesarannya bertambah sampai ke langit, dan yang kekuasaannya sampai ke ujung bumi!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 23, 'Tentang yang tuanku raja lihat, yakni seorang penjaga, seorang kudus, yang turun dari langit, sambil berkata: Tebanglah pohon ini dan binasakanlah dia, tetapi biarkanlah tunggulnya ada di dalam tanah, terikat dengan rantai dari besi dan tembaga, di rumput muda di padang, dan biarlah ia dibasahi dengan embun dari langit dan mendapat bagiannya bersama-sama dengan binatang-binatang di padang, hingga sudah berlaku yang demikian atasnya sampai tujuh masa berlalu?', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 24, 'inilah maknanya, ya raja, dan inilah putusan Yang Mahatinggi mengenai tuanku raja:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 25, 'tuanku akan dihalau dari antara manusia dan tempat tinggal tuanku akan ada di antara binatang-binatang di padang; kepada tuanku akan diberikan makanan rumput, seperti kepada lembu, dan tuanku akan dibasahi dengan embun dari langit; dan demikianlah akan berlaku atas tuanku sampai tujuh masa berlalu, hingga tuanku mengakui, bahwa Yang Mahatinggi berkuasa atas kerajaan manusia dan memberikannya kepada siapa yang dikehendaki-Nya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 26, 'Yang dikatakan tentang membiarkan tunggul pohon itu, berarti: kerajaan tuanku akan kembali tuanku pegang segera sesudah tuanku mengakui, bahwa Sorgalah yang mempunyai kekuasaan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 27, 'Jadi, ya raja, biarlah nasihatku berkenan pada hati tuanku: lepaskanlah diri tuanku dari pada dosa dengan melakukan keadilan, dan dari pada kesalahan dengan menunjukkan belas kasihan terhadap orang yang tertindas; dengan demikian kebahagiaan tuanku akan dilanjutkan!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 28, 'Semuanya itu terjadi atas raja Nebukadnezar;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 29, 'sebab setelah lewat dua belas bulan, ketika ia sedang berjalan-jalan di atas istana raja di Babel,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 30, 'berkatalah raja: "Bukankah itu Babel yang besar itu, yang dengan kekuatan kuasaku dan untuk kemuliaan kebesaranku telah kubangun menjadi kota kerajaan?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 31, 'Raja belum habis bicara, ketika suatu suara terdengar dari langit: "Kepadamu dinyatakan, ya raja Nebukadnezar, bahwa kerajaan telah beralih dari padamu;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 32, 'engkau akan dihalau dari antara manusia dan tempat tinggalmu akan ada di antara binatang-binatang di padang; kepadamu akan diberikan makanan rumput seperti kepada lembu; dan demikianlah akan berlaku atasmu sampai tujuh masa berlalu, hingga engkau mengakui, bahwa Yang Mahatinggi berkuasa atas kerajaan manusia dan memberikannya kepada siapa yang dikehendaki-Nya!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 33, 'Pada saat itu juga terlaksanalah perkataan itu atas Nebukadnezar, dan ia dihalau dari antara manusia dan makan rumput seperti lembu, dan tubuhnya basah oleh embun dari langit, sampai rambutnya menjadi panjang seperti bulu burung rajawali dan kukunya seperti kuku burung.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 34, 'Tetapi setelah lewat waktu yang ditentukan, aku, Nebukadnezar, menengadah ke langit, dan akal budiku kembali lagi kepadaku. Lalu aku memuji Yang Mahatinggi dan membesarkan dan memuliakan Yang Hidup kekal itu, karena kekuasaan-Nya ialah kekuasaan yang kekal dan kerajaan-Nya turun-temurun.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 35, 'Semua penduduk bumi dianggap remeh; Ia berbuat menurut kehendak-Nya terhadap bala tentara langit dan penduduk bumi; dan tidak ada seorangpun yang dapat menolak tangan-Nya dengan berkata kepada-Nya: "Apa yang Kaubuat?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 36, 'Pada waktu akal budiku kembali kepadaku, kembalilah juga kepadaku kebesaran dan kemuliaanku untuk kemasyhuran kerajaanku. Para menteriku dan para pembesarku menjemput aku lagi; aku dikembalikan kepada kerajaanku, bahkan kemuliaan yang lebih besar dari dahulu diberikan kepadaku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 4, 37, 'Jadi sekarang aku, Nebukadnezar, memuji, meninggikan dan memuliakan Raja Sorga, yang segala perbuatan-Nya adalah benar dan jalan-jalan-Nya adalah adil, dan yang sanggup merendahkan mereka yang berlaku congkak.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 1, 'Raja Belsyazar mengadakan perjamuan yang besar untuk para pembesarnya, seribu orang jumlahnya; dan di hadapan seribu orang itu ia minum-minum anggur.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 2, 'Dalam kemabukan anggur, Belsyazar menitahkan orang membawa perkakas dari emas dan perak yang telah diambil oleh Nebukadnezar, ayahnya, dari dalam Bait Suci di Yerusalem, supaya raja dan para pembesarnya, para isteri dan para gundik mereka minum dari perkakas itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 3, 'Kemudian dibawalah perkakas dari emas dan perak itu, yang diambil dari dalam Bait Suci, Rumah Allah di Yerusalem, lalu raja dan para pembesarnya, para isteri dan para gundik mereka minum dari perkakas itu;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 4, 'mereka minum anggur dan memuji-muji dewa-dewa dari emas dan perak, tembaga, besi, kayu dan batu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 5, 'Pada waktu itu juga tampaklah jari-jari tangan manusia menulis pada kapur dinding istana raja, di depan kaki dian, dan raja melihat punggung tangan yang sedang menulis itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 6, 'Lalu raja menjadi pucat, dan pikiran-pikirannya menggelisahkan dia; sendi-sendi pangkal pahanya menjadi lemas dan lututnya berantukan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 7, 'Kemudian berserulah raja dengan keras, supaya para ahli jampi, para Kasdim dan para ahli nujum dibawa menghadap. Berkatalah raja kepada para orang bijaksana di Babel itu: "Setiap orang yang dapat membaca tulisan ini dan dapat memberitahukan maknanya kepadaku, kepadanya akan dikenakan pakaian dari kain ungu, dan lehernya akan dikalungkan rantai emas, dan di dalam kerajaanku ia akan mempunyai kekuasaan sebagai orang ketiga."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 8, 'Tetapi semua orang bijaksana dari raja, yang telah datang menghadap, tidak sanggup membaca tulisan itu dan tidak sanggup memberitahukan maknanya kepada raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 9, 'Sesudah itu sangatlah cemas hati raja Belsyazar dan ia menjadi pucat; juga para pembesarnya terperanjat.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 10, 'Karena perkataan raja dan para pembesarnya itu masuklah permaisuri ke dalam ruang perjamuan; berkatalah ia: "Ya raja, kekallah hidup tuanku! Janganlah pikiran-pikiran tuanku menggelisahkan tuanku dan janganlah menjadi pucat;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 11, 'sebab dalam kerajaan tuanku ada seorang yang penuh dengan roh para dewa yang kudus! Dalam zaman ayah tuanku ada terdapat pada orang itu kecerahan, akal budi dan hikmat yang seperti hikmat para dewa. Ia telah diangkat oleh raja Nebukadnezar, ayah tuanku menjadi kepala orang-orang berilmu, para ahli jampi, para Kasdim dan para ahli nujum,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 12, 'karena pada orang itu terdapat roh yang luar biasa dan pengetahuan dan akal budi, sehingga dapat menerangkan mimpi, menyingkapkan hal-hal yang tersembunyi dan menguraikan kekusutan, yakni pada Daniel yang dinamai Beltsazar oleh raja. Baiklah sekarang Daniel dipanggil dan ia akan memberitahukan maknanya!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 13, 'Lalu dibawalah Daniel menghadap raja. Bertanyalah raja kepada Daniel: "Engkaukah Daniel itu, salah seorang buangan yang telah diangkut oleh raja, ayahku, dari tanah Yehuda?', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 14, 'Telah kudengar tentang engkau, bahwa engkau penuh dengan roh para dewa, dan bahwa padamu terdapat kecerahan, akal budi dan hikmat yang luar biasa.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 15, 'Kepadaku telah dibawa orang-orang bijaksana, para ahli jampi, supaya mereka membaca tulisan ini dan memberitahukan maknanya kepadaku, tetapi mereka tidak sanggup mengatakan makna perkataan itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 16, 'Tetapi telah kudengar tentang engkau, bahwa engkau dapat memberikan makna dan dapat menguraikan kekusutan. Oleh sebab itu, jika engkau dapat membaca tulisan itu dan dapat memberitahukan maknanya kepadaku, maka kepadamu akan dikenakan pakaian dari kain ungu dan pada lehermu akan dikalungkan rantai emas, dan dalam kerajaan ini engkau akan mempunyai kekuasaan sebagai orang ketiga."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 17, 'Kemudian Daniel menjawab raja: "Tahanlah hadiah tuanku, berikanlah pemberian tuanku kepada orang lain! Namun demikian, aku akan membaca tulisan itu bagi raja dan memberitahukan maknanya kepada tuanku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 18, 'Ya tuanku raja! Allah, Yang Mahatinggi, telah memberikan kekuasaan sebagai raja, kebesaran, kemuliaan dan keluhuran kepada Nebukadnezar, ayah tuanku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 19, 'Dan oleh karena kebesaran yang telah diberikan-Nya kepadanya itu, maka takut dan gentarlah terhadap dia orang-orang dari segala bangsa, suku bangsa dan bahasa; dibunuhnya siapa yang dikehendakinya dan dibiarkannya hidup siapa yang dikehendakinya, ditinggikannya siapa yang dikehendakinya dan direndahkannya siapa yang dikehendakinya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 20, 'Tetapi ketika ia menjadi tinggi hati dan keras kepala, sehingga berlaku terlalu angkuh, maka ia dijatuhkan dari takhta kerajaannya dan kemuliaannya diambil dari padanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 21, 'Ia dihalau dari antara manusia dan hatinya menjadi sama seperti hati binatang, dan tempat tinggalnya ada di antara keledai hutan; kepadanya diberikan makanan rumput seperti kepada lembu, dan tubuhnya basah oleh embun dari langit, sampai ia mengakui, bahwa Allah, Yang Mahatinggi, berkuasa atas kerajaan manusia dan mengangkat siapa yang dikehendaki-Nya untuk kedudukan itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 22, 'Tetapi tuanku, Belsyazar, anaknya, tidak merendahkan diri, walaupun tuanku mengetahui semuanya ini.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 23, 'Tuanku meninggikan diri terhadap Yang Berkuasa di sorga: perkakas dari Bait-Nya dibawa orang kepada tuanku, lalu tuanku serta para pembesar tuanku, para isteri dan para gundik tuanku telah minum anggur dari perkakas itu; tuanku telah memuji-muji dewa-dewa dari perak dan emas, dari tembaga, besi, kayu dan batu, yang tidak dapat melihat atau mendengar atau mengetahui, dan tidak tuanku muliakan Allah, yang menggenggam nafas tuanku dan menentukan segala jalan tuanku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 24, 'Sebab itu Ia menyuruh punggung tangan itu dan dituliskanlah tulisan ini.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 25, 'Maka inilah tulisan yang tertulis itu: Mene, mene, tekel ufarsin.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 26, 'Dan inilah makna perkataan itu: Mene: masa pemerintahan tuanku dihitung oleh Allah dan telah diakhiri;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 27, 'Tekel: tuanku ditimbang dengan neraca dan didapati terlalu ringan;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 28, 'Peres: kerajaan tuanku dipecah dan diberikan kepada orang Media dan Persia."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 29, 'Lalu atas titah Belsyazar dikenakanlah kepada Daniel pakaian dari kain ungu dan pada lehernya dikalungkan rantai emas, dan dimaklumkanlah tentang dia, bahwa di dalam kerajaan ia akan mempunyai kekuasaan sebagai orang ketiga.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 30, 'Pada malam itu juga terbunuhlah Belsyazar, raja orang Kasdim itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 5, 31, '(6-1) Darius, orang Media, menerima pemerintahan ketika ia berumur enam puluh dua tahun.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 1, '(6-2) Lalu berkenanlah Darius mengangkat seratus dua puluh wakil-wakil raja atas kerajaannya; mereka akan ditempatkan di seluruh kerajaan;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 2, '(6-3) membawahi mereka diangkat pula tiga pejabat tinggi, dan Daniel adalah salah satu dari ketiga orang itu; kepada merekalah para wakil-wakil raja harus memberi pertanggungan jawab, supaya raja jangan dirugikan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 3, '(6-4) Maka Daniel ini melebihi para pejabat tinggi dan para wakil raja itu, karena ia mempunyai roh yang luar biasa; dan raja bermaksud untuk menempatkannya atas seluruh kerajaannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 4, '(6-5) Kemudian para pejabat tinggi dan wakil raja itu mencari alasan dakwaan terhadap Daniel dalam hal pemerintahan, tetapi mereka tidak mendapat alasan apapun atau sesuatu kesalahan, sebab ia setia dan tidak ada didapati sesuatu kelalaian atau sesuatu kesalahan padanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 5, '(6-6) Maka berkatalah orang-orang itu: "Kita tidak akan mendapat suatu alasan dakwaan terhadap Daniel ini, kecuali dalam hal ibadahnya kepada Allahnya!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 6, '(6-7) Kemudian bergegas-gegaslah para pejabat tinggi dan wakil raja itu menghadap raja serta berkata kepadanya: "Ya raja Darius, kekallah hidup tuanku!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 7, '(6-8) Semua pejabat tinggi kerajaan ini, semua penguasa dan wakil raja, para menteri dan bupati telah mufakat, supaya dikeluarkan kiranya suatu penetapan raja dan ditetapkan suatu larangan, agar barangsiapa yang dalam tiga puluh hari menyampaikan permohonan kepada salah satu dewa atau manusia kecuali kepada tuanku, ya raja, maka ia akan dilemparkan ke dalam gua singa.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 8, '(6-9) Oleh sebab itu, ya raja, keluarkanlah larangan itu dan buatlah suatu surat perintah yang tidak dapat diubah, menurut undang-undang orang Media dan Persia, yang tidak dapat dicabut kembali."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 9, '(6-10) Sebab itu raja Darius membuat surat perintah dengan larangan itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 10, '(6-11) Demi didengar Daniel, bahwa surat perintah itu telah dibuat, pergilah ia ke rumahnya. Dalam kamar atasnya ada tingkap-tingkap yang terbuka ke arah Yerusalem; tiga kali sehari ia berlutut, berdoa serta memuji Allahnya, seperti yang biasa dilakukannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 11, '(6-12) Lalu orang-orang itu bergegas-gegas masuk dan mendapati Daniel sedang berdoa dan bermohon kepada Allahnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 12, '(6-13) Kemudian mereka menghadap raja dan menanyakan kepadanya tentang larangan raja: "Bukankah tuanku mengeluarkan suatu larangan, supaya setiap orang yang dalam tiga puluh hari menyampaikan permohonan kepada salah satu dewa atau manusia kecuali kepada tuanku, ya raja, akan dilemparkan ke dalam gua singa?" Jawab raja: "Perkara ini telah pasti menurut undang-undang orang Media dan Persia, yang tidak dapat dicabut kembali."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 13, '(6-14) Lalu kata mereka kepada raja: "Daniel, salah seorang buangan dari Yehuda, tidak mengindahkan tuanku, ya raja, dan tidak mengindahkan larangan yang tuanku keluarkan, tetapi tiga kali sehari ia mengucapkan doanya."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 14, '(6-15) Setelah raja mendengar hal itu, maka sangat sedihlah ia, dan ia mencari jalan untuk melepaskan Daniel, bahkan sampai matahari masuk, ia masih berusaha untuk menolongnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 15, '(6-16) Lalu bergegas-gegaslah orang-orang itu menghadap raja serta berkata kepadanya: "Ketahuilah, ya raja, bahwa menurut undang-undang orang Media dan Persia tidak ada larangan atau penetapan yang dikeluarkan raja yang dapat diubah!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 16, '(6-17) Sesudah itu raja memberi perintah, lalu diambillah Daniel dan dilemparkan ke dalam gua singa. Berbicaralah raja kepada Daniel: "Allahmu yang kausembah dengan tekun, Dialah kiranya yang melepaskan engkau!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 17, '(6-18) Maka dibawalah sebuah batu dan diletakkan pada mulut gua itu, lalu raja mencap itu dengan cincin meterainya dan dengan cincin meterai para pembesarnya, supaya dalam hal Daniel tidak dibuat perubahan apa-apa.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 18, '(6-19) Lalu pergilah raja ke istananya dan berpuasalah ia semalam-malaman itu; ia tidak menyuruh datang penghibur-penghibur, dan ia tidak dapat tidur.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 19, '(6-20) Pagi-pagi sekali ketika fajar menyingsing, bangunlah raja dan pergi dengan buru-buru ke gua singa;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 20, '(6-21) dan ketika ia sampai dekat gua itu, berserulah ia kepada Daniel dengan suara yang sayu. Berkatalah ia kepada Daniel: "Daniel, hamba Allah yang hidup, Allahmu yang kausembah dengan tekun, telah sanggupkah Ia melepaskan engkau dari singa-singa itu?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 21, '(6-22) Lalu kata Daniel kepada raja: "Ya raja, kekallah hidupmu!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 22, '(6-23) Allahku telah mengutus malaikat-Nya untuk mengatupkan mulut singa-singa itu, sehingga mereka tidak mengapa-apakan aku, karena ternyata aku tak bersalah di hadapan-Nya; tetapi juga terhadap tuanku, ya raja, aku tidak melakukan kejahatan."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 23, '(6-24) Lalu sangat sukacitalah raja dan ia memberi perintah, supaya Daniel ditarik dari dalam gua itu. Maka ditariklah Daniel dari dalam gua itu, dan tidak terdapat luka apa-apa padanya, karena ia percaya kepada Allahnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 24, '(6-25) Raja memberi perintah, lalu diambillah orang-orang yang telah menuduh Daniel dan mereka dilemparkan ke dalam gua singa, baik mereka maupun anak-anak dan isteri-isteri mereka. Belum lagi mereka sampai ke dasar gua itu, singa-singa itu telah menerkam mereka, bahkan meremukkan tulang-tulang mereka.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 25, '(6-26) Kemudian raja Darius mengirim surat kepada orang-orang dari segala bangsa, suku bangsa dan bahasa, yang mendiami seluruh bumi, bunyinya: "Bertambah-tambahlah kiranya kesejahteraanmu!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 26, '(6-27) Bersama ini kuberikan perintah, bahwa di seluruh kerajaan yang kukuasai orang harus takut dan gentar kepada Allahnya Daniel, sebab Dialah Allah yang hidup, yang kekal untuk selama-lamanya; pemerintahan-Nya tidak akan binasa dan kekuasaan-Nya tidak akan berakhir.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 27, '(6-28) Dia melepaskan dan menolong, dan mengadakan tanda dan mujizat di langit dan di bumi, Dia yang telah melepaskan Daniel dari cengkaman singa-singa."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 6, 28, '(6-29) Dan Daniel ini mempunyai kedudukan tinggi pada zaman pemerintahan Darius dan pada zaman pemerintahan Koresh, orang Persia itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 1, 'Pada tahun pertama pemerintahan Belsyazar, raja Babel, bermimpilah Daniel dan mendapat penglihatan-penglihatan di tempat tidurnya. Lalu dituliskannya mimpi itu, dan inilah garis besarnya:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 2, 'Berkatalah Daniel, demikian: "Pada malam hari aku mendapat penglihatan, tampak keempat angin dari langit mengguncangkan laut besar,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 3, 'dan empat binatang besar naik dari dalam laut, yang satu berbeda dengan yang lain.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 4, 'Yang pertama rupanya seperti seekor singa, dan mempunyai sayap burung rajawali; aku terus melihatnya sampai sayapnya tercabut dan ia terangkat dari tanah dan ditegakkan pada dua kaki seperti manusia, dan kepadanya diberikan hati manusia.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 5, 'Dan tampak ada seekor binatang yang lain, yang kedua, rupanya seperti beruang; ia berdiri pada sisinya yang sebelah, dan tiga tulang rusuk masih ada di dalam mulutnya di antara giginya. Dan demikianlah dikatakan kepadanya: Ayo, makanlah daging banyak-banyak.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 6, 'Kemudian aku melihat, tampak seekor binatang yang lain, rupanya seperti macan tutul; ada empat sayap burung pada punggungnya, lagipula binatang itu berkepala empat, dan kepadanya diberikan kekuasaan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 7, 'Kemudian aku melihat dalam penglihatan malam itu, tampak seekor binatang yang keempat, yang menakutkan dan mendahsyatkan, dan ia sangat kuat. Ia bergigi besar dari besi; ia melahap dan meremukkan, dan sisanya diinjak-injaknya dengan kakinya; ia berbeda dengan segala binatang yang terdahulu; lagipula ia bertanduk sepuluh.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 8, 'Sementara aku memperhatikan tanduk-tanduk itu, tampak tumbuh di antaranya suatu tanduk lain yang kecil, sehingga tiga dari tanduk-tanduk yang dahulu itu tercabut; dan pada tanduk itu tampak ada mata seperti mata manusia dan mulut yang menyombong.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 9, 'Sementara aku terus melihat, takhta-takhta diletakkan, lalu duduklah Yang Lanjut Usianya; pakaian-Nya putih seperti salju dan rambut-Nya bersih seperti bulu domba; kursi-Nya dari nyala api dengan roda-rodanya dari api yang berkobar-kobar;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 10, 'suatu sungai api timbul dan mengalir dari hadapan-Nya; seribu kali beribu-ribu melayani Dia, dan selaksa kali berlaksa-laksa berdiri di hadapan-Nya. Lalu duduklah Majelis Pengadilan dan dibukalah Kitab-kitab.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 11, 'Aku terus melihatnya, karena perkataan sombong yang diucapkan tanduk itu; aku terus melihatnya, sampai binatang itu dibunuh, tubuhnya dibinasakan dan diserahkan ke dalam api yang membakar.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 12, 'Juga kekuasaan binatang-binatang yang lain dicabut, dan jangka hidup mereka ditentukan sampai pada waktu dan saatnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 13, 'Aku terus melihat dalam penglihatan malam itu, tampak datang dengan awan-awan dari langit seorang seperti anak manusia; datanglah ia kepada Yang Lanjut Usianya itu, dan ia dibawa ke hadapan-Nya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 14, 'Lalu diberikan kepadanya kekuasaan dan kemuliaan dan kekuasaan sebagai raja, maka orang-orang dari segala bangsa, suku bangsa dan bahasa mengabdi kepadanya. Kekuasaannya ialah kekuasaan yang kekal, yang tidak akan lenyap, dan kerajaannya ialah kerajaan yang tidak akan musnah.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 15, 'Maka aku, Daniel, terharu karena hal itu, dan penglihatan-penglihatan yang kulihat itu menggelisahkan aku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 16, 'Lalu kudekati salah seorang dari mereka yang berdiri di sana dan kuminta penjelasan tentang semuanya itu. Maka berkatalah ia kepadaku dan diberitahukannyalah kepadaku maknanya:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 17, 'Binatang-binatang besar yang empat ekor itu ialah empat raja yang akan muncul dari dalam bumi;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 18, 'sesudah itu orang-orang kudus milik Yang Mahatinggi akan menerima pemerintahan, dan mereka akan memegang pemerintahan itu sampai selama-lamanya, bahkan kekal selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 19, 'Lalu aku ingin mendapat penjelasan tentang binatang yang keempat itu, yang berbeda dengan segala binatang yang lain, yang sangat menakutkan, dengan gigi besinya dan kuku tembaganya, yang melahap dan meremukkan dan menginjak-injak sisanya dengan kakinya;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 20, 'dan tentang kesepuluh tanduk yang ada pada kepalanya, dan tentang tanduk yang lain, yakni tanduk yang mempunyai mata dan yang mempunyai mulut yang menyombong, yang tumbuh sehingga patahlah tiga tanduk, dan yang lebih besar rupanya dari tanduk-tanduk yang lain.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 21, 'Dan aku melihat tanduk itu berperang melawan orang-orang kudus dan mengalahkan mereka,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 22, 'sampai Yang Lanjut Usianya itu datang dan keadilan diberikan kepada orang-orang kudus milik Yang Mahatinggi dan waktunya datang orang-orang kudus itu memegang pemerintahan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 23, 'Maka demikianlah katanya: Binatang yang keempat itu ialah kerajaan yang keempat yang akan ada di bumi, yang akan berbeda dengan segala kerajaan dan akan menelan seluruh bumi, menginjak-injaknya dan meremukkannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 24, 'Kesepuluh tanduk itu ialah kesepuluh raja yang muncul dari kerajaan itu. Sesudah mereka, akan muncul seorang raja; dia berbeda dengan raja-raja yang dahulu dan akan merendahkan tiga raja.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 25, 'Ia akan mengucapkan perkataan yang menentang Yang Mahatinggi, dan akan menganiaya orang-orang kudus milik Yang Mahatinggi; ia berusaha untuk mengubah waktu dan hukum, dan mereka akan diserahkan ke dalam tangannya selama satu masa dan dua masa dan setengah masa.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 26, 'Lalu Majelis Pengadilan akan duduk, dan kekuasaan akan dicabut dari padanya untuk dimusnahkan dan dihancurkan sampai lenyap.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 27, 'Maka pemerintahan, kekuasaan dan kebesaran dari kerajaan-kerajaan di bawah semesta langit akan diberikan kepada orang-orang kudus, umat Yang Mahatinggi: pemerintahan mereka adalah pemerintahan yang kekal, dan segala kekuasaan akan mengabdi dan patuh kepada mereka.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 7, 28, 'Sekianlah berita itu. Adapun aku, Daniel, pikiran-pikiranku sangat menggelisahkan aku, sehingga aku menjadi pucat; dan aku menyimpan hal itu dalam ingatanku."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 1, 'Pada tahun yang ketiga pemerintahan raja Belsyazar, nampaklah kepadaku, Daniel, suatu penglihatan sesudah yang tampak kepadaku dahulu itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 2, 'Aku melihat dalam penglihatan itu, dan sementara aku melihat, aku berada di puri Susan, yang ada di wilayah Elam, dan aku melihat dalam penglihatan itu, bahwa aku sedang di tepi sungai Ulai.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 3, 'Aku mengangkat mukaku dan melihat, tampak seekor domba jantan berdiri di depan sungai itu; tanduknya dua dan kedua tanduk itu tinggi, tetapi yang satu lebih tinggi dari yang lain, dan yang tinggi itu tumbuh terakhir.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 4, 'Aku melihat domba jantan itu menanduk ke barat, ke utara dan ke selatan, dan tidak ada seekor binatangpun yang tahan menghadapi dia, dan tidak ada yang dapat membebaskan dari kuasanya; ia berbuat sekehendak hatinya dan membesarkan diri.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 5, 'Tetapi sementara aku memperhatikannya, tampak seekor kambing jantan datang dari sebelah barat, yang melintasi seluruh bumi tanpa menginjak tanah; dan kambing jantan itu mempunyai satu tanduk yang aneh di antara kedua matanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 6, 'Ia datang pada domba jantan yang dua tanduknya dan yang kulihat berdiri di depan sungai itu, lalu menyerangnya dengan keganasan yang hebat.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 7, 'Aku melihatnya mendekati domba jantan itu; ia menggeram, lalu ditanduknya domba jantan itu, dipatahkannya kedua tanduknya, dan domba jantan itu tidak berdaya untuk tahan menghadapi dia; dihempaskannya dia ke bumi, diinjak-injaknya, dan tidak ada yang melepaskan domba jantan itu dari kuasanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 8, 'Kambing jantan itu sangat membesarkan dirinya, tetapi ketika ia sampai pada puncak kuasanya, patahlah tanduk yang besar itu, lalu pada tempatnya tumbuh empat tanduk yang aneh, sejajar dengan keempat mata angin yang dari langit.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 9, 'Maka dari salah satu tanduk itu muncul suatu tanduk kecil, yang menjadi sangat besar ke arah selatan, ke arah timur dan ke arah Tanah Permai.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 10, 'Ia menjadi besar, bahkan sampai kepada bala tentara langit, dan dari bala tentara itu, dari bintang-bintang, dijatuhkannya beberapa ke bumi, dan diinjak-injaknya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 11, 'Bahkan terhadap Panglima bala tentara itupun ia membesarkan dirinya, dan dari pada-Nya diambilnya korban persembahan sehari-hari, dan tempat-Nya yang kudus dirobohkannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 12, 'Suatu kebaktian diadakan secara fasik menggantikan korban sehari-hari, kebenaran dihempaskannya ke bumi, dan apapun yang dibuatnya, semuanya berhasil.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 13, 'Kemudian kudengar seorang kudus berbicara, dan seorang kudus lain berkata kepada yang berbicara itu: "Sampai berapa lama berlaku penglihatan ini, yakni korban sehari-hari dan kefasikan yang membinasakan, tempat kudus yang diserahkan dan bala tentara yang diinjak-injak?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 14, 'Maka ia menjawab: "Sampai lewat dua ribu tiga ratus petang dan pagi, lalu tempat kudus itu akan dipulihkan dalam keadaan yang wajar."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 15, 'Sedang aku, Daniel, melihat penglihatan itu dan berusaha memahaminya, maka tampaklah seorang berdiri di depanku, yang rupanya seperti seorang laki-laki;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 16, 'dan aku mendengar dari tengah sungai Ulai itu suara manusia yang berseru: "Gabriel, buatlah orang ini memahami penglihatan itu!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 17, 'Lalu datanglah ia ke tempat aku berdiri, dan ketika ia datang, terkejutlah aku dan jatuh tertelungkup, lalu ia berkata kepadaku: "Pahamilah, anak manusia, bahwa penglihatan itu mengenai akhir masa!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 18, 'Sementara ia berbicara dengan aku, jatuh pingsanlah aku tertelungkup ke tanah; tetapi ia menyentuh aku dan membuat aku berdiri kembali.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 19, 'Lalu berkatalah ia: "Kuberitahukan kepadamu apa yang akan terjadi pada akhir murka ini, sebab hal itu mengenai akhir zaman.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 20, 'Domba jantan yang kaulihat itu, dengan kedua tanduknya, ialah raja-raja orang Media dan Persia.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 21, 'Dan kambing jantan yang berbulu kesat itu ialah raja negeri Yunani, dan tanduk besar yang di antara kedua matanya itu ialah raja yang pertama.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 22, 'Dan bahwa tanduk itu patah dan pada tempatnya itu muncul empat buah, berarti: empat kerajaan akan muncul dari bangsa itu, tetapi tidak sekuat yang terdahulu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 23, 'Dan pada akhir kerajaan mereka, apabila orang-orang fasik telah penuh kejahatannya, maka akan muncul seorang raja dengan muka yang garang dan yang pandai menipu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 24, 'Kekuatannya akan menjadi hebat, tetapi tidak sekuat yang terdahulu, dan ia akan mendatangkan kebinasaan yang mengerikan, dan apa yang dilakukannya akan berhasil; orang-orang berkuasa akan dibinasakannya, juga umat orang kudus.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 25, 'Dan oleh karena akalnya, penipuan yang dilakukannya akan berhasil; ia akan membesarkan dirinya dalam hatinya, dan dengan tak disangka-sangka banyak orang akan dibinasakannya; juga ia akan bangkit melawan Raja segala raja. Tetapi tanpa perbuatan tangan manusia, ia akan dihancurkan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 26, 'Adapun penglihatan tentang petang dan pagi itu, apa yang dikatakan tentang itu adalah benar. Tetapi engkau, sembunyikanlah penglihatan itu, sebab hal itu mengenai masa depan yang masih jauh."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 8, 27, 'Maka aku, Daniel, lelah dan jatuh sakit beberapa hari lamanya; kemudian bangunlah aku dan melakukan pula urusan raja. Dan aku tercengang-cengang tentang penglihatan itu, tetapi tidak memahaminya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 1, 'Pada tahun pertama pemerintahan Darius, anak Ahasyweros, dari keturunan orang Media, yang telah menjadi raja atas kerajaan orang Kasdim,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 2, 'pada tahun pertama kerajaannya itu aku, Daniel, memperhatikan dalam kumpulan Kitab jumlah tahun yang menurut firman TUHAN kepada nabi Yeremia akan berlaku atas timbunan puing Yerusalem, yakni tujuh puluh tahun.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 3, 'Lalu aku mengarahkan mukaku kepada Tuhan Allah untuk berdoa dan bermohon, sambil berpuasa dan mengenakan kain kabung serta abu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 4, 'Maka aku memohon kepada TUHAN, Allahku, dan mengaku dosaku, demikian: "Ah Tuhan, Allah yang maha besar dan dahsyat, yang memegang Perjanjian dan kasih setia terhadap mereka yang mengasihi Engkau serta berpegang pada perintah-Mu!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 5, 'Kami telah berbuat dosa dan salah, kami telah berlaku fasik dan telah memberontak, kami telah menyimpang dari perintah dan peraturan-Mu,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 6, 'dan kami tidak taat kepada hamba-hamba-Mu, para nabi, yang telah berbicara atas nama-Mu kepada raja-raja kami, kepada pemimpin-pemimpin kami, kepada bapa-bapa kami dan kepada segenap rakyat negeri.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 7, 'Ya Tuhan, Engkaulah yang benar, tetapi patutlah kami malu seperti pada hari ini, kami orang-orang Yehuda, penduduk kota Yerusalem dan segenap orang Israel, mereka yang dekat dan mereka yang jauh, di segala negeri kemana Engkau telah membuang mereka oleh karena mereka berlaku murtad terhadap Engkau.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 8, 'Ya TUHAN, kami, raja-raja kami, pemimpin-pemimpin kami dan bapa-bapa kami patutlah malu, sebab kami telah berbuat dosa terhadap Engkau.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 9, 'Pada Tuhan, Allah kami, ada kesayangan dan keampunan, walaupun kami telah memberontak terhadap Dia,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 10, 'dan tidak mendengarkan suara TUHAN, Allah kami, yang menyuruh kami hidup menurut hukum yang telah diberikan-Nya kepada kami dengan perantaraan para nabi, hamba-hamba-Nya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 11, 'Segenap orang Israel telah melanggar hukum-Mu dan menyimpang karena tidak mendengarkan suara-Mu. Sebab itu telah dicurahkan ke atas kami kutuk dan sumpah, yang tertulis dalam kitab Taurat Musa, hamba Allah itu, sebab kami telah berbuat dosa terhadap Dia.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 12, 'Dan telah ditetapkan-Nya firman-Nya, yang diucapkan-Nya terhadap kami dan terhadap orang-orang yang telah memerintah kami, yakni bahwa akan didatangkan-Nya kepada kami malapetaka yang besar, yang belum pernah terjadi di bawah semesta langit, seperti di Yerusalem.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 13, 'Seperti yang tertulis dalam kitab Taurat Musa, segala malapetaka ini telah menimpa kami, dan kami tidak memohon belas kasihan TUHAN, Allah kami, dengan berbalik dari segala kesalahan kami dan memperhatikan kebenaran yang dari pada-Mu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 14, 'Sebab itu TUHAN bersiap dengan malapetaka itu dan mendatangkannya kepada kami; karena TUHAN, Allah kami, adalah adil dalam segala perbuatan yang dilakukan-Nya, tetapi kami tidak mendengarkan suara-Nya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 15, 'Oleh sebab itu, ya Tuhan, Allah kami, yang telah membawa umat-Mu keluar dari tanah Mesir dengan tangan yang kuat dan memasyhurkan nama-Mu, seperti pada hari ini, kami telah berbuat dosa, kami telah berlaku fasik.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 16, 'Ya Tuhan, sesuai dengan belas kasihan-Mu, biarlah kiranya murka dan amarah-Mu berlalu dari Yerusalem, kota-Mu, gunung-Mu yang kudus; sebab oleh karena dosa kami dan oleh karena kesalahan nenek moyang kami maka Yerusalem dan umat-Mu telah menjadi cela bagi semua orang yang di sekeliling kami.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 17, 'Oleh sebab itu, dengarkanlah, ya Allah kami, doa hamba-Mu ini dan permohonannya, dan sinarilah tempat kudus-Mu yang telah musnah ini dengan wajah-Mu, demi Tuhan sendiri.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 18, 'Ya Allahku, arahkanlah telinga-Mu dan dengarlah, bukalah mata-Mu dan lihatlah kebinasaan kami dan kota yang disebut dengan nama-Mu, sebab kami menyampaikan doa permohonan kami ke hadapan-Mu bukan berdasarkan jasa-jasa kami, tetapi berdasarkan kasih sayang-Mu yang berlimpah-limpah.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 19, 'Ya Tuhan, dengarlah! Ya, Tuhan, ampunilah! Ya Tuhan, perhatikanlah dan bertindaklah dengan tidak bertangguh, oleh karena Engkau sendiri, Allahku, sebab kota-Mu dan umat-Mu disebut dengan nama-Mu!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 20, 'Sementara aku berbicara dan berdoa dan mengaku dosaku dan dosa bangsaku, bangsa Israel, dan menyampaikan ke hadapan TUHAN, Allahku, permohonanku bagi gunung kudus Allahku,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 21, 'sementara aku berbicara dalam doa, terbanglah dengan cepat ke arahku Gabriel, dia yang telah kulihat dalam penglihatan yang dahulu itu pada waktu persembahan korban petang hari.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 22, 'Lalu ia mengajari aku dan berbicara dengan aku: "Daniel, sekarang aku datang untuk memberi akal budi kepadamu untuk mengerti.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 23, 'Ketika engkau mulai menyampaikan permohonan keluarlah suatu firman, maka aku datang untuk memberitahukannya kepadamu, sebab engkau sangat dikasihi. Jadi camkanlah firman itu dan perhatikanlah penglihatan itu!', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 24, 'Tujuh puluh kali tujuh masa telah ditetapkan atas bangsamu dan atas kotamu yang kudus, untuk melenyapkan kefasikan, untuk mengakhiri dosa, untuk menghapuskan kesalahan, untuk mendatangkan keadilan yang kekal, untuk menggenapkan penglihatan dan nabi, dan untuk mengurapi yang maha kudus.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 25, 'Maka ketahuilah dan pahamilah: dari saat firman itu keluar, yakni bahwa Yerusalem akan dipulihkan dan dibangun kembali, sampai pada kedatangan seorang yang diurapi, seorang raja, ada tujuh kali tujuh masa; dan enam puluh dua kali tujuh masa lamanya kota itu akan dibangun kembali dengan tanah lapang dan paritnya, tetapi di tengah-tengah kesulitan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 26, 'Sesudah keenam puluh dua kali tujuh masa itu akan disingkirkan seorang yang telah diurapi, padahal tidak ada salahnya apa-apa. Maka datanglah rakyat seorang raja memusnahkan kota dan tempat kudus itu, tetapi raja itu akan menemui ajalnya dalam air bah; dan sampai pada akhir zaman akan ada peperangan dan pemusnahan, seperti yang telah ditetapkan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 9, 27, 'Raja itu akan membuat perjanjian itu menjadi berat bagi banyak orang selama satu kali tujuh masa. Pada pertengahan tujuh masa itu ia akan menghentikan korban sembelihan dan korban santapan; dan di atas sayap kekejian akan datang yang membinasakan, sampai pemusnahan yang telah ditetapkan menimpa yang membinasakan itu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 1, 'Pada tahun ketiga pemerintahan Koresh, raja orang Persia, suatu firman dinyatakan kepada Daniel yang diberi nama Beltsazar; firman itu benar dan mengenai kesusahan yang besar. Maka dicamkannyalah firman itu dan diperhatikannyalah penglihatan itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 2, 'Pada waktu itu aku, Daniel, berkabung tiga minggu penuh:', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 3, 'makanan yang sedap tidak kumakan, daging dan anggur tidak masuk ke dalam mulutku dan aku tidak berurap sampai berlalu tiga minggu penuh.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 4, 'Pada hari kedua puluh empat bulan pertama, ketika aku ada di tepi sungai besar, yakni sungai Tigris,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 5, 'kuangkat mukaku, lalu kulihat, tampak seorang yang berpakaian kain lenan dan berikat pinggang emas dari ufas.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 6, 'Tubuhnya seperti permata Tarsis dan wajahnya seperti cahaya kilat; matanya seperti suluh yang menyala-nyala, lengan dan kakinya seperti kilau tembaga yang digilap, dan suara ucapannya seperti gaduh orang banyak.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 7, 'Hanya aku, Daniel, melihat penglihatan itu, tetapi orang-orang yang bersama-sama dengan aku, tidak melihatnya; tetapi mereka ditimpa oleh ketakutan yang besar, sehingga mereka lari bersembunyi;', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 8, 'demikianlah aku tinggal seorang diri. Ketika aku melihat penglihatan yang besar itu, hilanglah kekuatanku; aku menjadi pucat sama sekali, dan tidak ada lagi kekuatan padaku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 9, 'Lalu kudengar suara ucapannya, dan ketika aku mendengar suara ucapannya itu, jatuh pingsanlah aku tertelungkup dengan mukaku ke tanah.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 10, 'Tetapi ada suatu tangan menyentuh aku dan membuat aku bangun sambil bertumpu pada lutut dan tanganku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 11, 'Katanya kepadaku: "Daniel, engkau orang yang dikasihi, camkanlah firman yang kukatakan kepadamu, dan berdirilah pada kakimu, sebab sekarang aku diutus kepadamu." Ketika hal ini dikatakannya kepadaku, berdirilah aku dengan gemetar.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 12, 'Lalu katanya kepadaku: "Janganlah takut, Daniel, sebab telah didengarkan perkataanmu sejak hari pertama engkau berniat untuk mendapat pengertian dan untuk merendahkan dirimu di hadapan Allahmu, dan aku datang oleh karena perkataanmu itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 13, 'Pemimpin kerajaan orang Persia berdiri dua puluh satu hari lamanya menentang aku; tetapi kemudian Mikhael, salah seorang dari pemimpin-pemimpin terkemuka, datang menolong aku, dan aku meninggalkan dia di sana berhadapan dengan raja-raja orang Persia.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 14, 'Lalu aku datang untuk membuat engkau mengerti apa yang akan terjadi pada bangsamu pada hari-hari yang terakhir; sebab penglihatan ini juga mengenai hari-hari itu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 15, 'Ketika dikatakannya hal ini kepadaku, kutundukkan mukaku ke tanah dan aku terkelu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 16, 'Tetapi sesuatu yang menyerupai manusia menyentuh bibirku; lalu kubuka mulutku dan mulai berbicara, kataku kepada yang berdiri di depanku itu: "Tuanku, oleh sebab penglihatan itu aku ditimpa kesakitan, dan tidak ada lagi kekuatan padaku.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 17, 'Masakan aku, hamba tuanku ini dapat berbicara dengan tuanku! Bukankah tidak ada lagi kekuatan padaku dan tidak ada lagi nafas padaku?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 18, 'Lalu dia yang rupanya seperti manusia itu menyentuh aku pula dan memberikan aku kekuatan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 19, 'dan berkata: "Hai engkau yang dikasihi, janganlah takut, sejahteralah engkau, jadilah kuat, ya, jadilah kuat!" Sementara ia berbicara dengan aku, aku merasa kuat lagi dan berkata: "Berbicaralah kiranya tuanku, sebab engkau telah memberikan aku kekuatan."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 20, 'Lalu katanya: "Tahukah engkau, mengapa aku datang kepadamu? Sebentar lagi aku kembali untuk berperang dengan pemimpin orang Persia, dan sesudah aku selesai dengan dia, maka pemimpin orang Yunani akan datang.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 10, 21, 'Namun demikian, aku akan memberitahukan kepadamu apa yang tercantum dalam Kitab Kebenaran. Tidak ada satupun yang berdiri di pihakku dengan tetap hati melawan mereka, kecuali Mikhael, pemimpinmu itu,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 1, 'seperti dahulu aku juga mendampinginya untuk menguatkan dan menyokongnya, yakni pada tahun pertama pemerintahan Darius, orang Media itu."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 2, '"Oleh sebab itu, aku akan memberitahukan kepadamu hal yang benar. Sesungguhnya, tiga raja lagi akan muncul di negeri Persia, dan yang keempat akan mendapat kekayaan yang lebih besar dari mereka semua, dan apabila ia telah menjadi kuat karena kekayaannya, ia akan berusaha sekuat-kuatnya untuk melawan kerajaan Yunani.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 3, 'Kemudian akan muncul seorang raja yang gagah perkasa, yang akan memerintah dengan kekuasaan yang besar dan akan berbuat sekehendaknya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 4, 'Tetapi baru saja ia muncul, maka kerajaannya akan pecah dan terbagi-bagi menurut keempat mata angin dari langit, jatuh bukan kepada keturunannya, dan tanpa kekuasaan seperti yang dipunyainya; sebab kerajaannya akan runtuh dan menjadi milik orang-orang yang lain dari pada orang-orang ini.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 5, 'Maka raja negeri Selatan akan menjadi kuat; tetapi salah seorang dari panglima-panglimanya akan menjadi lebih kuat dari padanya dan orang ini memerintah, lalu kekuasaannya akan menjadi kekuasaan yang besar.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 6, 'Beberapa tahun kemudian keduanya akan bersekutu: puteri raja negeri Selatan akan datang kepada raja negeri Utara untuk mengadakan persetujuan. Tetapi puteri itu tidak berhasil, juga keturunannya tidak dapat bertahan: puteri itu akan diserahkan, demikian pula orang-orang yang mengantarnya, anak yang dilahirkannya dan orang yang mengawininya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 7, 'Dan pada waktu itu akan tumbuh suatu tunas yang seakar dengan puteri itu menggantikan orang itu, dan orang ini akan bergerak maju melawan tentara raja negeri Utara dan memasuki kota bentengnya, dan ia akan bertindak terhadap mereka dan ia akan berkuasa.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 8, 'Bahkan dewa-dewa mereka dan patung-patung tuangan mereka dan barang-barang mereka yang berharga dari perak dan emas akan diangkutnya sebagai jarahan ke Mesir, lalu beberapa tahun lamanya ia akan berhenti berperang melawan raja negeri Utara.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 9, 'Kemudian raja ini akan memasuki kerajaan raja negeri Selatan, tetapi kemudian pulang ke negerinya sendiri.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 10, 'Kemudian anak-anaknya akan bersiap untuk berperang, dan akan mengerahkan sejumlah tentara yang besar, lalu salah seorang dari mereka itu akan bergerak maju melawan dia, menggenangi dan meliputi semuanya seperti air bah; dan pada serbuan yang kedua kalinya ia akan sampai ke benteng musuhnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 11, 'Maka menggeramlah raja negeri Selatan itu, lalu maju berperang melawan raja negeri Utara, yang telah mengerahkan sejumlah tentara besar, dan tentara besar itu akan jatuh ke tangan musuhnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 12, 'Setelah tentara besar itu dihancurkannya, maka hatinya akan bermegah; walaupun ia telah menewaskan berlaksa-laksa orang, ia tidak akan mempunyai kekuatan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 13, 'Lalu untuk kedua kalinya raja negeri Utara itu akan mengerahkan sejumlah tentara besar, lebih besar dari yang pertama, dan beberapa tahun kemudian, ia akan bergerak maju melawan dia dengan tentara yang besar dan dengan banyak perlengkapan perang.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 14, 'Pada waktu itu banyak orang akan bangkit melawan raja negeri Selatan; juga orang-orang yang lalim dari bangsamu akan membesarkan diri, sehingga penglihatan itu menjadi kenyataan, tetapi mereka akan tergelincir.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 15, 'Maka raja negeri Utara itu akan datang, mendirikan kubu pengepungan dan merebut kota yang berbenteng; dan tentara negeri Selatan tidak akan dapat bertahan, juga pasukan-pasukan pilihannya sekalipun, ya, tidak ada kekuatan apapun yang dapat bertahan,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 16, 'sehingga raja yang menyerangnya akan berbuat sekehendak hati, dan tidak ada seorangpun yang dapat bertahan menghadapinya; ia akan menduduki Tanah Permai dan seluruhnya akan ada dalam kekuasaannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 17, 'Kemudian ia akan berusaha untuk menguasai seluruh kerajaan orang yang lain itu: ia akan mengadakan persetujuan dengan dia, dan seorang puterinya diberikannya kepadanya untuk menghancurkan kerajaan itu, tetapi maksudnya itu tidak akan berhasil dan tidak akan menguntungkannya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 18, 'Lalu ia akan memalingkan mukanya ke tanah-tanah pesisir dan banyak yang direbutnya; tetapi seorang panglima akan menghentikan penghinaannya itu, bahkan akan mengembalikan penghinaan itu kepadanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 19, 'Sesudah itu ia akan memalingkan mukanya ke kota-kota benteng di negerinya sendiri; tetapi ia akan tergelincir dan jatuh dan tidak akan ditemukan lagi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 20, 'Menggantikan dia akan muncul seorang yang menyuruh seorang pemungut pajak menjalani bagian yang terindah dari kerajaan itu, tetapi beberapa hari kemudian ia akan dibinasakan, bukan oleh kemarahan atau oleh peperangan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 21, 'Menggantikan dia akan muncul seorang yang hina, yang tidak memperoleh martabat raja; tetapi dengan tak disangka-sangka ia akan datang merebut kedudukan raja dengan perbuatan-perbuatan licin.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 22, 'Seluruh tentara yang datang melanda akan dihanyutkan di hadapannya dan dihancurkan, bahkan juga seorang raja Perjanjian.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 23, 'Dan dari saat diadakan persekutuan dengan dia, ia akan berlaku curang, dan ia akan maju serta menjadi berkuasa, meskipun sedikit orang-orangnya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 24, 'Dengan tak disangka-sangka ia akan memasuki daerah-daerah yang paling subur dari negeri itu, dan melakukan apa yang belum pernah dilakukan oleh para bapa dan nenek moyangnya, yakni menghamburkan rampasan dan jarahan dan harta di antara orang-orangnya; juga terhadap tempat-tempat yang berbenteng ia membuat siasat, tetapi hanya untuk sementara waktu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 25, 'Kekuatan dan keberaniannya akan ditujukannya melawan raja negeri Selatan dengan memakai tentara yang besar; dan walaupun raja negeri Selatan itu akan bersiap untuk berperang dengan tentara yang amat besar dan kuat, ia tidak akan dapat bertahan, sebab akan diadakan siasat terhadap dia,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 26, 'dan orang-orang yang makan dari santapannya akan meruntuhkannya: tentaranya akan hanyut dan banyak orangnya yang tewas dibunuh.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 27, 'Dan kedua raja itu bermaksud jahat, dan sedang mereka duduk bersama-sama pada satu meja, mereka akan saling membohongi; tetapi hal itu tidak akan berhasil, sebab akhir zaman itu belum mencapai waktu yang ditetapkan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 28, 'Kemudian ia akan pulang ke negerinya dengan banyak harta, dan hatinya bermaksud menentang Perjanjian Kudus; dan itu dilakukannya, lalu pulang ke negerinya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 29, 'Pada waktu yang ditetapkan ia akan memasuki pula negeri Selatan, tetapi kali yang kedua ini tidak akan sama dengan yang pertama,', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 30, 'karena akan datang kapal-kapal orang Kitim melawan dia, sehingga hilanglah keberaniannya. Lalu pulanglah ia dengan hati mendendam terhadap Perjanjian Kudus dan ia akan bertindak: setelah pulang kembali, ia akan menujukan perhatiannya kepada mereka yang meninggalkan Perjanjian Kudus.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 31, 'Tentaranya akan muncul, mereka akan menajiskan tempat kudus, benteng itu, menghapuskan korban sehari-hari dan menegakkan kekejian yang membinasakan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 32, 'Dan orang-orang yang berlaku fasik terhadap Perjanjian akan dibujuknya sampai murtad dengan kata-kata licin; tetapi umat yang mengenal Allahnya akan tetap kuat dan akan bertindak.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 33, 'Dan orang-orang bijaksana di antara umat itu akan membuat banyak orang mengerti, tetapi untuk beberapa waktu lamanya mereka akan jatuh oleh karena pedang dan api, oleh karena ditawan dan dirampas.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 34, 'Sementara jatuh, mereka akan mendapat pertolongan sedikit, dan banyak orang akan menggabungkan diri kepada mereka secara berpura-pura.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 35, 'Sebagian dari orang-orang bijaksana itu akan jatuh, supaya dengan demikian diadakan pengujian, penyaringan dan pemurnian di antara mereka, sampai pada akhir zaman; sebab akhir zaman itu belum mencapai waktu yang telah ditetapkan.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 36, 'Raja itu akan berbuat sekehendak hati; ia akan meninggikan dan membesarkan dirinya terhadap setiap allah. Juga terhadap Allah yang mengatasi segala allah ia akan mengucapkan kata-kata yang tak senonoh sama sekali, dan ia akan beruntung sampai akhir murka itu; sebab apa yang telah ditetapkan akan terjadi.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 37, 'Juga para allah nenek moyangnya tidak akan diindahkannya; baik pujaan orang-orang perempuan maupun allah manapun juga tidak akan diindahkannya, sebab terhadap semuanya itu ia akan membesarkan diri.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 38, 'Tetapi sebagai ganti semuanya itu ia akan menghormati dewa benteng-benteng: dewa yang tidak dikenal oleh nenek moyangnya akan dihormatinya dengan membawa emas dan perak dan permata dan barang-barang yang berharga.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 39, 'Dan ia akan bertindak terhadap benteng-benteng yang diperkuat dengan pertolongan dewa asing itu. Siapa yang mengakui dewa ini akan dilimpahi kehormatan; ia akan membuat mereka menjadi berkuasa atas banyak orang dan kepada mereka akan dibagikannya tanah sebagai upah.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 40, 'Tetapi pada akhir zaman raja negeri Selatan akan berperang dengan dia, dan raja negeri Utara itu akan menyerbunya dengan kereta dan orang-orang berkuda dan dengan banyak kapal; dan ia akan memasuki negeri-negeri, dan menggenangi dan meliputi semuanya seperti air bah.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 41, 'Juga Tanah Permai akan dimasukinya, dan banyak orang akan jatuh; tetapi dari tangannya akan terluput tanah Edom, tanah Moab dan bagian yang penting dari bani Amon.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 42, 'Ia akan menjangkau negeri-negeri, dan negeri Mesir tidak akan terluput.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 43, 'Ia akan menguasai harta benda emas dan perak dan segala barang berharga negeri Mesir, dan orang Libia serta orang Etiopia akan mengikuti dia.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 44, 'Tetapi kabar-kabar dari sebelah timur dan dari sebelah utara akan mengejutkan hatinya, sehingga ia akan keluar dengan kegeraman yang besar untuk memusnahkan dan membinasakan banyak orang.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 11, 45, 'Ia akan mendirikan kemah kebesarannya di antara laut dan gunung Permai yang kudus itu, tetapi kemudian ia akan menemui ajalnya dan tidak ada seorangpun yang menolongnya."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 1, '"Pada waktu itu juga akan muncul Mikhael, pemimpin besar itu, yang akan mendampingi anak-anak bangsamu; dan akan ada suatu waktu kesesakan yang besar, seperti yang belum pernah terjadi sejak ada bangsa-bangsa sampai pada waktu itu. Tetapi pada waktu itu bangsamu akan terluput, yakni barangsiapa yang didapati namanya tertulis dalam Kitab itu.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 2, 'Dan banyak dari antara orang-orang yang telah tidur di dalam debu tanah, akan bangun, sebagian untuk mendapat hidup yang kekal, sebagian untuk mengalami kehinaan dan kengerian yang kekal.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 3, 'Dan orang-orang bijaksana akan bercahaya seperti cahaya cakrawala, dan yang telah menuntun banyak orang kepada kebenaran seperti bintang-bintang, tetap untuk selama-lamanya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 4, 'Tetapi engkau, Daniel, sembunyikanlah segala firman itu, dan meteraikanlah Kitab itu sampai pada akhir zaman; banyak orang akan menyelidikinya, dan pengetahuan akan bertambah."', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 5, 'Kemudian aku, Daniel, melihat, maka tampaklah berdiri dua orang lain, seorang di tepi sungai sebelah sini dan yang lain di tepi sungai yang sebelah sana.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 6, 'Dan yang seorang bertanya kepada yang berpakaian kain lenan, yang ada di sebelah atas air sungai itu: "Bilakah hal-hal yang ajaib ini akan berakhir?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 7, 'Lalu kudengar orang yang berpakaian kain lenan, yang ada di sebelah atas air sungai itu bersumpah demi Dia yang hidup kekal, sambil mengangkat tangan kanan dan tangan kirinya ke langit: "Satu masa dan dua masa dan setengah masa; dan setelah berakhir kuasa perusak bangsa yang kudus itu, maka segala hal ini akan digenapi!"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 8, 'Adapun aku, memang kudengar hal itu, tetapi tidak memahaminya, lalu kutanya: "Tuanku, apakah akhir segala hal ini?"', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 9, 'Tetapi ia menjawab: "Pergilah, Daniel, sebab firman ini akan tinggal tersembunyi dan termeterai sampai akhir zaman.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 10, 'Banyak orang akan disucikan dan dimurnikan dan diuji, tetapi orang-orang fasik akan berlaku fasik; tidak seorangpun dari orang fasik itu akan memahaminya, tetapi orang-orang bijaksana akan memahaminya.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 11, 'Sejak dihentikan korban sehari-hari dan ditegakkan dewa-dewa kekejian yang membinasakan itu ada seribu dua ratus dan sembilan puluh hari.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 12, 'Berbahagialah orang yang tetap menanti-nanti dan mencapai seribu tiga ratus tiga puluh lima hari.', 'id', 'TB'),
  ('27', 'dan', 'Daniel', 12, 13, 'Tetapi engkau, pergilah sampai tiba akhir zaman, dan engkau akan beristirahat, dan akan bangkit untuk mendapat bagianmu pada kesudahan zaman."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 1, 'Firman TUHAN yang datang kepada Hosea bin Beeri pada zaman Uzia, Yotam, Ahas dan Hizkia, raja-raja Yehuda, dan pada zaman Yerobeam bin Yoas, raja Israel.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 2, 'Ketika TUHAN mulai berbicara dengan perantaraan Hosea, berfirmanlah Ia kepada Hosea: "Pergilah, kawinilah seorang perempuan sundal dan peranakkanlah anak-anak sundal, karena negeri ini bersundal hebat dengan membelakangi TUHAN."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 3, 'Maka pergilah ia dan mengawini Gomer binti Diblaim, lalu mengandunglah perempuan itu dan melahirkan baginya seorang anak laki-laki.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 4, 'Kemudian berfirmanlah TUHAN kepada Hosea: "Berilah nama Yizreel kepada anak itu, sebab sedikit waktu lagi maka Aku akan menghukum keluarga Yehu karena hutang darah Yizreel dan Aku akan mengakhiri pemerintahan kaum Israel.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 5, 'Maka pada waktu itu Aku akan mematahkan busur panah Israel di lembah Yizreel."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 6, 'Lalu perempuan itu mengandung lagi dan melahirkan seorang anak perempuan. Berfirmanlah TUHAN kepada Hosea: "Berilah nama Lo-Ruhama kepada anak itu, sebab Aku tidak akan menyayangi lagi kaum Israel, dan sama sekali tidak akan mengampuni mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 7, 'Tetapi Aku akan menyayangi kaum Yehuda dan menyelamatkan mereka demi TUHAN, Allah mereka. Aku akan menyelamatkan mereka bukan dengan panah atau pedang, dengan alat perang atau dengan kuda dan orang-orang berkuda."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 8, 'Sesudah menyapih Lo-Ruhama, mengandunglah perempuan itu lagi dan melahirkan seorang anak laki-laki.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 9, 'Lalu berfirmanlah Ia: "Berilah nama Lo-Ami kepada anak itu, sebab kamu ini bukanlah umat-Ku dan Aku ini bukanlah Allahmu."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 10, 'Tetapi kelak, jumlah orang Israel akan seperti pasir laut, yang tidak dapat ditakar dan tidak dapat dihitung. Dan di tempat di mana dikatakan kepada mereka: "Kamu ini bukanlah umat-Ku," akan dikatakan kepada mereka: "Anak-anak Allah yang hidup."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 1, 11, 'Orang Yehuda dan orang Israel akan berkumpul bersama-sama dan akan mengangkat bagi mereka satu pemimpin, lalu mereka akan menduduki negeri ini, sebab besar hari Yizreel itu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 1, '(1-12) Katakanlah kepada saudara-saudaramu laki-laki: "Ami!" dan kepada saudara-saudaramu perempuan: "Ruhama!"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 2, '(2-1) "Adukanlah ibumu, adukanlah, sebab dia bukan isteri-Ku, dan Aku ini bukan suaminya; biarlah dijauhkannya sundalnya dari mukanya, dan zinahnya dari antara buah dadanya,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 3, '(2-2) supaya jangan Aku menanggalkan pakaiannya sampai dia telanjang, dan membiarkan dia seperti pada hari dia dilahirkan, membuat dia seperti padang gurun, dan membuat dia seperti tanah kering, lalu membiarkan dia mati kehausan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 4, '(2-3) Tentang anak-anaknya, Aku tidak menyayangi mereka, sebab mereka adalah anak-anak sundal.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 5, '(2-4) Sebab ibu mereka telah menjadi sundal; dia yang mengandung mereka telah berlaku tidak senonoh. Sebab dia berkata: Aku mau mengikuti para kekasihku, yang memberi roti dan air minumku, bulu domba dan kain lenanku, minyak dan minumanku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 6, '(2-5) Sebab itu, sesungguhnya, Aku akan menyekat jalannya dengan duri-duri, dan mendirikan pagar tembok mengurung dia, sehingga dia tidak dapat menemui jalannya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 7, '(2-6) Dia akan mengejar para kekasihnya, tetapi tidak akan mencapai mereka; dia akan mencari mereka, tetapi tidak bertemu dengan mereka. Maka dia akan berkata: Aku akan pulang kembali kepada suamiku yang pertama, sebab waktu itu aku lebih berbahagia dari pada sekarang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 8, '(2-7) Tetapi dia tidak insaf bahwa Akulah yang memberi kepadanya gandum, anggur dan minyak, dan yang memperbanyak bagi dia perak dan emas yang dibuat mereka menjadi patung Baal.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 9, '(2-8) Sebab itu Aku akan mengambil kembali gandum-Ku pada masanya dan anggur-Ku pada musimnya, dan akan merampas kain bulu domba dan kain lenan-Ku yang harus menutupi auratnya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 10, '(2-9) Dan sekarang, Aku akan menyingkapkan kemaluannya, di depan mata para kekasihnya, dan seorangpun tidak akan melepaskan dia dari tangan-Ku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 11, '(2-10) Aku akan menghentikan segala kegirangannya, hari rayanya, bulan barunya dan hari Sabatnya dan segala perayaannya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 12, '(2-11) Aku akan memusnahkan pohon anggurnya dan pohon aranya, yang tentangnya dikatakannya: Ini semuanya pemberian kepadaku, yang dihadiahkan kepadaku oleh para kekasihku! Aku akan membuatnya menjadi hutan, dan binatang-binatang di padang akan memakannya habis.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 13, '(2-12) Dan Aku akan menghukum dia karena hari-hari ketika dia membakar korban untuk para Baal, berhias dengan anting-antingnya dan kalungnya, dan mengikuti para kekasihnya dan melupakan Aku," demikianlah firman TUHAN.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 14, '(2-13) "Sebab itu, sesungguhnya, Aku ini akan membujuk dia, dan membawa dia ke padang gurun, dan berbicara menenangkan hatinya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 15, '(2-14) Aku akan memberikan kepadanya kebun anggurnya dari sana, dan membuat lembah Akhor menjadi pintu pengharapan. Maka dia akan merelakan diri di sana seperti pada masa mudanya, seperti pada waktu dia berangkat keluar dari tanah Mesir.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 16, '(2-15) Maka pada waktu itu, demikianlah firman TUHAN, engkau akan memanggil Aku: Suamiku, dan tidak lagi memanggil Aku: Baalku!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 17, '(2-16) Lalu Aku menjauhkan nama para Baal dari mulutmu, maka nama mereka tidak lagi disebut.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 18, '(2-17) Aku akan mengikat perjanjian bagimu pada waktu itu dengan binatang-binatang di padang dan dengan burung-burung di udara, dan binatang-binatang melata di muka bumi; Aku akan meniadakan busur panah, pedang dan alat perang dari negeri, dan akan membuat engkau berbaring dengan tenteram.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 19, '(2-18) Aku akan menjadikan engkau isteri-Ku untuk selama-lamanya dan Aku akan menjadikan engkau isteri-Ku dalam keadilan dan kebenaran, dalam kasih setia dan kasih sayang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 20, '(2-19) Aku akan menjadikan engkau isteri-Ku dalam kesetiaan, sehingga engkau akan mengenal TUHAN.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 21, '(2-20) Maka pada waktu itu, demikianlah firman TUHAN, Aku akan mendengarkan langit, dan langit akan mendengarkan bumi.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 22, '(2-21) Bumi akan mendengarkan gandum, anggur dan minyak, dan mereka ini akan mendengarkan Yizreel.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 2, 23, '(2-22) Aku akan menaburkan dia bagi-Ku di bumi, dan akan menyayangi Lo-Ruhama, dan Aku berkata kepada Lo-Ami: Umat-Ku engkau! dan ia akan berkata: Allahku!"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 3, 1, 'Berfirmanlah TUHAN kepadaku: "Pergilah lagi, cintailah perempuan yang suka bersundal dan berzinah, seperti TUHAN juga mencintai orang Israel, sekalipun mereka berpaling kepada allah-allah lain dan menyukai kue kismis."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 3, 2, 'Lalu aku membeli dia bagiku dengan bayaran lima belas syikal perak dan satu setengah homer jelai.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 3, 3, 'Aku berkata kepadanya: "Lama engkau harus diam padaku dengan tidak bersundal dan dengan tidak menjadi kepunyaan seorang laki-laki; juga aku ini tidak akan bersetubuh dengan engkau."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 3, 4, 'Sebab lama orang Israel akan diam dengan tidak ada raja, tiada pemimpin, tiada korban, tiada tugu berhala dan tiada efod dan terafim.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 3, 5, 'Sesudah itu orang Israel akan berbalik dan akan mencari TUHAN, Allah mereka, dan Daud, raja mereka. Mereka akan datang dengan gementar kepada TUHAN dan kepada kebaikan-Nya pada hari-hari yang terakhir.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 1, 'Dengarlah firman TUHAN, hai orang Israel, sebab TUHAN mempunyai perkara dengan penduduk negeri ini, sebab tidak ada kesetiaan dan tidak ada kasih, dan tidak ada pengenalan akan Allah di negeri ini.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 2, 'Hanya mengutuk, berbohong, membunuh, mencuri, berzinah, melakukan kekerasan dan penumpahan darah menyusul penumpahan darah.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 3, 'Sebab itu negeri ini akan berkabung, dan seluruh penduduknya akan merana; juga binatang-binatang di padang dan burung-burung di udara, bahkan ikan-ikan di laut akan mati lenyap.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 4, 'Hanya janganlah ada orang mengadu, dan janganlah ada orang menegor, sebab terhadap engkaulah pengaduan-Ku itu, hai imam!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 5, 'Engkau akan tergelincir jatuh pada siang hari, juga nabi akan tergelincir jatuh bersama-sama engkau pada malam hari; dan Aku akan membinasakan ibumu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 6, 'Umat-Ku binasa karena tidak mengenal Allah; karena engkaulah yang menolak pengenalan itu maka Aku menolak engkau menjadi imam-Ku; dan karena engkau melupakan pengajaran Allahmu, maka Aku juga akan melupakan anak-anakmu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 7, 'Makin bertambah banyak mereka, makin berdosa mereka kepada-Ku, kemuliaan mereka akan Kutukar dengan kehinaan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 8, 'Mereka mendapat rezeki dari dosa umat-Ku dan mengharapkan umat-Ku itu berbuat salah.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 9, 'Maka seperti nasib rakyat demikianlah nasib imam: Aku akan menghukum dia karena tindakan-tindakannya dan Aku akan membalaskan perbuatan-perbuatannya kepadanya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 10, 'Mereka akan makan, tetapi tidak menjadi kenyang, mereka akan bersundal, tetapi tidak menjadi banyak, sebab mereka telah meninggalkan TUHAN untuk berpegang kepada sundal.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 11, 'Anggur dan air anggur menghilangkan daya pikir.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 12, 'Umat-Ku bertanya kepada pohonnya, dan tongkatnya akan memberitahu kepadanya, sebab roh perzinahan menyesatkan mereka, dan mereka berzinah meninggalkan Allah mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 13, 'Mereka mempersembahkan korban di puncak gunung-gunung dan membakar korban di atas bukit-bukit, di bawah pohon besar dan pohon hawar dan pohon rimbun, sebab naungannya baik. Itulah sebabnya anak-anakmu perempuan berzinah dan menantu-menantumu perempuan bersundal.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 14, 'Aku tidak akan menghukum anak-anak perempuanmu sekalipun mereka berzinah, atau menantu-menantumu perempuan, sekalipun mereka bersundal; sebab mereka sendiri mengasingkan diri bersama-sama dengan perempuan-perempuan sundal dan mempersembahkan korban bersama-sama dengan sundal-sundal bakti, dan umat yang tidak berpengertian akan runtuh.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 15, 'Jika engkau ini berzinah, hai Israel, janganlah Yehuda turut bersalah! Janganlah pergi ke Gilgal, dan janganlah naik ke Bet-Awen, dan janganlah bersumpah: "Demi TUHAN yang hidup!"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 16, 'Sebab Israel degil seperti lembu yang degil, masakan sekarang TUHAN menggembalakan mereka, seperti domba di tanah lapang?', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 17, 'Efraim bersekutu dengan berhala-berhala, biarkanlah dia!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 18, 'Persepakatan para pemabuk! mereka menyerahkan diri habis-habisan kepada persundalan; mereka lebih mencintai kehinaan dari pada kemasyhuran mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 4, 19, 'Angin melingkupi mereka dalam sayap-sayapnya, dan mereka akan mendapat malu karena korban-korban mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 1, 'Dengarlah ini, hai para imam, perhatikanlah, hai kaum Israel, dan pasanglah telinga, hai keluarga raja! Sebab mengenai kamulah penghukuman itu, karena kamu telah menjadi perangkap bagi Mizpa, dan jaring yang dikembangkan di atas gunung Tabor,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 2, 'dan lobang yang dikeruk di lembah Sitim, maka Aku ini akan menghajar mereka sekalian.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 3, 'Aku ini mengenal Efraim, dan Israel tidaklah tersembunyi bagi-Ku, sebab engkau telah berzinah, hai Efraim; dan Israel telah menajiskan diri.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 4, 'Perbuatan-perbuatan mereka tidak mengizinkan mereka berbalik kepada Allah mereka, sebab roh perzinahan ada di antara mereka, dan mereka tidak mengenal TUHAN.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 5, 'Kecongkakan Israel menjadi saksi terhadap dirinya sendiri; Efraim akan tergelincir jatuh oleh kesalahannya sendiri, dan bersama-sama mereka juga Yehuda.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 6, 'Dengan korban kambing domba dan lembu sapinya mereka akan pergi untuk mencari TUHAN, tetapi tidak akan menjumpai Dia; Ia telah menarik diri dari mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 7, 'Mereka telah berkhianat terhadap TUHAN, sebab mereka telah memperanakkan anak-anak yang tidak sah; sekarang pembinasa akan memakan habis mereka dan ladang mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 8, 'Tiuplah sangkakala di Gibea, dan nafiri di Rama. Berteriaklah di Bet-Awen, gemetarlah, hai Benyamin!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 9, 'Efraim akan menjadi tandus, pada hari penghukuman; mengenai suku-suku Israel Aku memberitahu apa yang pasti.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 10, 'Para pemuka Yehuda adalah seperti orang-orang yang menggeser batas; ke atas mereka akan Kucurahkan gemas-Ku seperti air.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 11, 'Efraim tertindas, diremukkan oleh hukuman, sebab ia berkeras untuk berjalan mengikuti kesia-siaan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 12, 'Sebab itu Aku ini akan seperti ngengat bagi Efraim dan seperti belatung bagi kaum Yehuda.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 13, 'Ketika Efraim melihat penyakitnya, dan Yehuda melihat bisulnya, maka pergilah Efraim ke Asyur dan mengutus orang kepada Raja ?Agung?. Tetapi iapun tidak dapat menyembuhkan kamu dan tidak dapat melenyapkan bisul itu dari padamu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 14, 'Sebab Aku ini seperti singa bagi Efraim, dan seperti singa muda bagi kaum Yehuda. Aku, Aku ini akan menerkam, lalu pergi, Aku akan membawa lari dan tidak ada yang melepaskan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 5, 15, 'Aku akan pergi pulang ke tempat-Ku, sampai mereka mengaku bersalah dan mencari wajah-Ku. Dalam kesesakannya mereka akan merindukan Aku:', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 1, '"Mari, kita akan berbalik kepada TUHAN, sebab Dialah yang telah menerkam dan yang akan menyembuhkan kita, yang telah memukul dan yang akan membalut kita.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 2, 'Ia akan menghidupkan kita sesudah dua hari, pada hari yang ketiga Ia akan membangkitkan kita, dan kita akan hidup di hadapan-Nya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 3, 'Marilah kita mengenal dan berusaha sungguh-sungguh mengenal TUHAN; Ia pasti muncul seperti fajar, Ia akan datang kepada kita seperti hujan, seperti hujan pada akhir musim yang mengairi bumi."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 4, 'Apakah yang akan Kulakukan kepadamu, hai Efraim? Apakah yang akan Kulakukan kepadamu, hai Yehuda? Kasih setiamu seperti kabut pagi, dan seperti embun yang hilang pagi-pagi benar.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 5, 'Sebab itu Aku telah meremukkan mereka dengan perantaraan nabi-nabi, Aku telah membunuh mereka dengan perkataan mulut-Ku, dan hukum-Ku keluar seperti terang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 6, 'Sebab Aku menyukai kasih setia, dan bukan korban sembelihan, dan menyukai pengenalan akan Allah, lebih dari pada korban-korban bakaran.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 7, 'Tetapi mereka itu telah melangkahi perjanjian di Adam, di sana mereka telah berkhianat terhadap Aku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 8, 'Gilead adalah kota para penjahat, penuh dengan jejak darah.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 9, 'Seperti gerombolan menghadang demikianlah persekutuan para imam; mereka membunuh di jalan ke Sikhem, sungguh, mereka melakukan perbuatan mesum.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 10, 'Di antara kaum Israel telah Kulihat hal-hal yang mengerikan; di sana ada Efraim bersundal dan Israel telah menajiskan diri.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 6, 11, 'Juga bagimu, hai Yehuda, telah ditentukan penuaian: Apabila Aku memulihkan keadaan umat-Ku,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 1, 'apabila Aku menyembuhkan Israel, maka tersingkaplah kesalahan Efraim dan kejahatan-kejahatan Samaria: sebab mereka melakukan penipuan: pencuri mendobrak masuk, gerombolan merampas di luar.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 2, 'Dan tidak terpikir mereka bahwa Aku mengingat segala kejahatan mereka. Sekarangpun perbuatan-perbuatan mereka mengepung mereka, semuanya ada di hadapan wajah-Ku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 3, 'Mereka menyukakan raja dengan kejahatan mereka, dan para pemuka dengan kebohongan mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 4, 'Sekaliannya mereka orang-orang berzinah, bagaikan dapur perapian yang menyala terus, ketika tukang bakar roti berhenti membesarkan apinya, sementara ia meremas adonan sampai menjadi muai oleh ragi.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 5, 'Pada pesta raja kita mereka membuat sakit para pemuka dengan anggur yang menghangatkan; ia bersekutu dengan para pencemooh.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 6, 'Batin mereka seperti dapur perapian; hati mereka menyala-nyala; semalam-malaman murka mereka surut, pada waktu pagi menyala kembali seperti api yang menjilat.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 7, 'Mereka semua sudah panas seperti dapur perapian, dan memakan habis para hakim mereka. Semua raja mereka sudah tewas, tidak ada seorang di antara mereka yang berseru kepada-Ku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 8, 'Efraim mencampurkan dirinya di antara bangsa-bangsa, Efraim telah menjadi roti bundar yang tidak dibalik.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 9, 'Orang-orang luar memakan habis kekuatannya, tetapi ia sendiri tidak mengetahuinya; juga ia sudah banyak beruban, tetapi ia sendiri tidak mengetahuinya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 10, 'Kecongkakan Israel menjadi saksi terhadap dirinya, namun mereka tidak berbalik kepada TUHAN, Allah mereka, dan tidak mencari Dia kendati semuanya ini.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 11, 'Efraim telah menjadi merpati tolol, tidak berakal, dengan memanggil kepada Mesir, dengan pergi kepada Asyur.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 12, 'Apabila mereka pergi, Aku akan membentangkan jaring-Ku ke atas mereka; Aku akan menurunkan mereka seperti burung-burung di udara, Aku akan menghajar mereka karena kejahatan-kejahatan mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 13, 'Celakalah mereka, sebab mereka melarikan diri dari pada-Ku! Binasalah mereka, sebab mereka memberontak terhadap Aku! Aku ini mau menebus mereka, tetapi mereka berdusta terhadap Aku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 14, 'Seruan mereka kepada-Ku tidak keluar dari hatinya, tetapi mereka meratap di pembaringan mereka. Mereka menoreh-noreh diri karena gandum dan anggur, dan mereka berontak terhadap Aku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 15, 'Sekalipun Aku telah melatih dan menguatkan lengan-lengan mereka, namun mereka merancang kejahatan terhadap Aku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 7, 16, 'Mereka berbalik kepada Baal, mereka adalah seperti busur tipu; pemuka-pemuka mereka akan tewas oleh pedang karena ucapan mereka yang kasar. Inilah yang akan menjadi olok-olok kepada mereka di tanah Mesir.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 1, 'Tiuplah sangkakala! Serangan laksana rajawali atas rumah TUHAN! Oleh karena mereka telah melangkahi perjanjian-Ku dan telah mendurhaka terhadap pengajaran-Ku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 2, 'Kepada-Ku mereka berseru-seru: "Ya Allahku, kami, Israel mengenal Engkau!"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 3, 'Israel telah menolak yang baik?biarlah musuh mengejar dia!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 4, 'Mereka telah mengangkat raja, tetapi tanpa persetujuan-Ku; mereka mengangkat pemuka, tetapi dengan tidak setahu-Ku. Dari emas dan peraknya mereka membuat berhala-berhala bagi dirinya sendiri, sehingga mereka dilenyapkan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 5, 'Aku menolak anak lembumu, hai Samaria; murka-Ku menyala terhadap mereka! Sampai berapa lama tidak dapat disucikan,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 6, 'orang-orang Israel itu? Itu dibuat oleh tukang, dan itu bukan Allah! Sungguh, akan menjadi serpih anak lembu Samaria itu!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 7, 'Sebab mereka menabur angin, maka mereka akan menuai puting beliung; gandum yang belum menguning tidak ada pada mereka; tumbuh-tumbuhan itu tidak menghasilkan tepung; dan jika memberi hasil, maka orang-orang lain menelannya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 8, 'Israel sudah ditelan; sekarang mereka itu ada di antara bangsa-bangsa seperti barang yang tidak disukai orang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 9, 'Sebab mereka telah pergi ke Asyur, bagaikan keledai hutan yang memencilkan diri; Efraim telah membagi-bagi hadiah cinta.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 10, 'Sekalipun mereka membagi-bagi hadiah itu di antara bangsa-bangsa, sekarang ini Aku akan mengumpulkan mereka, dan sebentar lagi mereka akan berhenti mengurapi raja dan para pemuka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 11, 'Sungguh, Efraim telah memperbanyak mezbah; mezbah-mezbah itu menjadikan mereka berdosa.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 12, 'Sekalipun Kutuliskan baginya banyak pengajaran-Ku, itu akan dianggap mereka sebagai sesuatu yang asing.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 13, 'Mereka mencintai korban sembelihan; mereka mempersembahkan daging dan memakannya; tetapi TUHAN tidak berkenan kepada mereka. Sekarang Ia akan mengingat kesalahan mereka dan akan menghukum dosa mereka; mereka harus kembali ke Mesir!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 8, 14, 'Israel telah melupakan Pembuatnya dan telah mendirikan istana-istana; Yehuda telah memperbanyak kota-kota yang berkubu; tetapi Aku akan melepas api ke dalam kota-kota mereka, sehingga puri mereka dimakan habis.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 1, 'Janganlah bersukacita, hai Israel! Janganlah bersorak-sorak seperti bangsa-bangsa! Sebab engkau telah berzinah dengan meninggalkan Allahmu, engkau telah mencintai upah sundal di segala tempat pengirikan gandum.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 2, 'Tempat pengirikan gandum dan tempat pemerasan anggur tidak akan memberi mereka makan, dan anggur akan mengecewakan mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 3, 'Mereka tidak akan tetap diam di tanah TUHAN, tetapi Efraim harus kembali ke Mesir, dan di Asyur mereka akan memakan makanan najis.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 4, 'Mereka tidak akan mempersembahkan korban curahan anggur kepada TUHAN dan korban-korban sembelihan mereka tidak akan menyenangkan hati-Nya. Roti mereka adalah seperti roti perkabungan, semua orang yang memakannya akan menjadi najis, sebab roti mereka adalah untuk dirinya sendiri, tidak boleh dibawa ke dalam rumah TUHAN.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 5, 'Apakah yang hendak kamu perbuat pada waktu pertemuan raya dan pada waktu hari raya TUHAN?', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 6, 'Sebab walaupun mereka mengelakkan diri dari pemusnahan, Mesir akan mengumpulkan mereka, Memfis akan menguburkan mereka. Rumput akan menutupi barang-barang perak mereka yang berharga; onak akan tumbuh dalam kemah-kemah mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 7, 'Sudah datang hari-hari penghukuman, sudah datang hari-hari pembalasan, Israel akan mengalaminya, "Nabi adalah seorang pandir, orang yang penuh roh adalah orang gila!", oleh karena besarnya kesalahanmu dan besarnya permusuhan:', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 8, 'Efraim, umat Allahku, sedang mengintai nabi, jerat penangkap burung ada di sepanjang jalannya, permusuhan ada di rumah Allahnya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 9, 'Busuk sangat perbuatan mereka seperti pada hari-hari Gibea; Ia akan mengingat kesalahan mereka dan akan menghukum dosa mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 10, 'Seperti buah-buah anggur di padang gurun Aku mendapati Israel dahulu; seperti buah sulung sebagai hasil pertama pohon ara Aku melihat nenek moyangmu. Tetapi mereka itu telah pergi kepada Baal-Peor dan telah membaktikan diri kepada dewa keaiban, sehingga mereka menjadi kejijikan sama seperti apa yang mereka cintai itu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 11, 'Kemuliaan Efraim terbang seperti burung: tiada yang melahirkan, yang hamil dan yang mengandung!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 12, 'Sekalipun mereka membesarkan anak-anaknya, Aku akan membuat mereka bulus, sehingga tidak ada manusia lagi. Sungguh, celakalah juga mereka pada waktu Aku menjauh dari pada mereka!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 13, 'Efraim, seperti yang Aku lihat, telah membuat anak-anaknya menjadi binatang perburuan; Efraim terpaksa menyerahkan anak-anaknya kepada si pembunuh.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 14, 'Berilah kepada mereka, ya TUHAN?apakah yang hendak Kauberi? Berilah kepada mereka kandungan yang mandul dan buah dada yang kering.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 15, 'Segala kejahatan mereka terjadi di Gilgal, sungguh, di sana Aku mulai membenci mereka. Oleh karena jahatnya perbuatan-perbuatan mereka Aku akan menghalau mereka dari rumah-Ku. Aku tidak akan mengasihi mereka lagi, semua pemuka mereka adalah pemberontak.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 16, 'Efraim telah dipukul, akarnya telah menjadi kering, mereka tidak akan menghasilkan buah. Bahkan sekalipun mereka melahirkan anak, Aku akan mematikan buah kandungannya yang berharga.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 9, 17, 'Allahku akan membuang mereka, sebab mereka tidak mendengarkan Dia, maka mereka akan mengembara di antara bangsa-bangsa.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 1, 'Israel adalah pohon anggur yang riap tumbuhnya, yang menghasilkan buah. Makin banyak buahnya, makin banyak dibuatnya mezbah-mezbah. Makin baik tanahnya, makin baik dibuatnya tugu-tugu berhala.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 2, 'Hati mereka licik, sekarang mereka harus menanggung akibat kesalahannya: Dia akan menghancurkan mezbah-mezbah mereka, akan meruntuhkan tugu-tugu berhala mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 3, 'Sungguh, sekarang mereka berkata: "Kita tidak mempunyai raja lagi, sebab kita tidak takut kepada TUHAN. Apakah yang dapat dilakukan raja bagi kita?"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 4, 'Mereka membual, mengangkat sumpah dusta, mengikat perjanjian, sehingga tumbuh hukum seperti pohon upas di alur-alur ladang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 5, 'Penduduk Samaria gentar mengenai anak lembu Bet-Awen. Sungguh, rakyatnya akan berkabung oleh karenanya, dan imam-imamnya akan meratap oleh karenanya, oleh sebab kemuliaannya telah beralih dari padanya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 6, 'Anak lembu itu sendiri akan dibawa ke Asyur sebagai persembahan kepada Raja ?Agung?. Efraim akan menanggung malu, Israel akan mendapat malu karena rancangannya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 7, 'Samaria akan dihancurkan; rajanya seperti sepotong ranting yang terapung di air.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 8, 'Bukit-bukit pengorbanan Awen, yakni dosa Israel, akan dimusnahkan. Semak duri dan rumput duri akan tumbuh di atas mezbah-mezbahnya. Dan mereka akan berkata kepada gunung-gunung: "Timbunilah kami!" dan kepada bukit-bukit: "Runtuhlah menimpa kami!"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 9, 'Sejak hari Gibea engkau telah berdosa, hai Israel; di sana mereka bangkit melawan. Tidakkah perang melawan orang-orang curang akan mencapai mereka di Gibea?', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 10, 'Aku telah datang untuk menghajar mereka; bangsa-bangsa akan berkumpul melawan mereka, apabila mereka dihajar karena salahnya yang berganda.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 11, 'Efraim dahulu seekor anak lembu yang terlatih, yang suka mengirik, dan Aku ini menyayangi tengkuknya yang elok, Aku memasang Efraim; Yehuda harus membajak, Yakub harus menyisir tanah baginya sendiri.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 12, 'Menaburlah bagimu sesuai dengan keadilan, menuailah menurut kasih setia! Bukalah bagimu tanah baru, sebab sudah waktunya untuk mencari TUHAN, sampai Ia datang dan menghujani kamu dengan keadilan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 13, 'Kamu telah membajak kefasikan, telah menuai kecurangan, telah memakan buah kebohongan. Oleh karena engkau telah mengandalkan diri pada keretamu, pada banyaknya pahlawan-pahlawanmu,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 14, 'maka keriuhan perang akan timbul di antara bangsamu, dan segala kubumu akan dihancurkan seperti Salman menghancurkan Bet-Arbel pada hari pertempuran: ibu beserta anak-anak diremukkan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 10, 15, 'Demikianlah akan Kulakukan kepadamu, hai kaum Israel, oleh karena dahsyatnya kejahatanmu. Pada waktu fajar akan dilenyapkan sama sekali raja Israel.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 1, 'Ketika Israel masih muda, Kukasihi dia, dan dari Mesir Kupanggil anak-Ku itu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 2, 'Makin Kupanggil mereka, makin pergi mereka itu dari hadapan-Ku; mereka mempersembahkan korban kepada para Baal, dan membakar korban kepada patung-patung.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 3, 'Padahal Akulah yang mengajar Efraim berjalan dan mengangkat mereka di tangan-Ku, tetapi mereka tidak mau insaf, bahwa Aku menyembuhkan mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 4, 'Aku menarik mereka dengan tali kesetiaan, dengan ikatan kasih. Bagi mereka Aku seperti orang yang mengangkat kuk dari tulang rahang mereka; Aku membungkuk kepada mereka untuk memberi mereka makan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 5, 'Mereka harus kembali ke tanah Mesir, dan Asyur akan menjadi raja mereka, sebab mereka menolak untuk bertobat.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 6, 'Pedang akan mengamuk di kota-kota mereka, akan memusnahkan palang-palang pintu mereka, dan akan memakan mereka di benteng-benteng mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 7, 'Umat-Ku betah dalam membelakangi Aku; mereka memanggil kepada Baal dan berhenti meninggikan nama-Ku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 8, 'Masakan Aku membiarkan engkau, hai Efraim, menyerahkan engkau, hai Israel? Masakan Aku membiarkan engkau seperti Adma, membuat engkau seperti Zeboim? Hati-Ku berbalik dalam diri-Ku, belas kasihan-Ku bangkit serentak.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 9, 'Aku tidak akan melaksanakan murka-Ku yang bernyala-nyala itu, tidak akan membinasakan Efraim kembali. Sebab Aku ini Allah dan bukan manusia, Yang Kudus di tengah-tengahmu, dan Aku tidak datang untuk menghanguskan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 10, 'Mereka akan mengikuti TUHAN, Ia akan mengaum seperti singa. Sungguh, Ia akan mengaum, maka anak-anak akan datang dengan gemetar dari barat,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 11, 'seperti burung dengan gemetar datang dari Mesir, dan seperti merpati dari tanah Asyur, lalu Aku akan menempatkan mereka lagi di rumah-rumah mereka, demikianlah firman TUHAN.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 11, 12, '(12-1) Dengan kebohongan Aku telah dikepung oleh Efraim, dengan tipu oleh kaum Israel; sedang Yehuda menghilang dari dekat Allah, dari dekat Yang Mahakudus yang setia.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 1, '(12-2) Efraim menjaga angin, dan mengejar angin timur sehari suntuk, memperbanyak dusta dan pemusnahan; mereka mengadakan perjanjian dengan Asyur, dan membawa minyak kepada Mesir.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 2, '(12-3) TUHAN mempunyai perbantahan dengan Yehuda, Ia akan menghukum Yakub sesuai dengan tingkah lakunya, dan akan memberi balasan kepadanya sesuai dengan perbuatan-perbuatannya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 3, '(12-4) Di dalam kandungan ia menipu saudaranya, dan dalam kegagahannya ia bergumul dengan Allah.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 4, '(12-5) Ia bergumul dengan Malaikat dan menang; ia menangis dan memohon belas kasihan kepada-Nya. Di Betel ia bertemu dengan Dia, dan di sanalah Dia berfirman kepadanya:', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 5, '(12-6) ?yakni TUHAN, Allah semesta alam, TUHAN nama-Nya?', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 6, '(12-7) "Engkau ini harus berbalik kepada Allahmu, peliharalah kasih setia dan hukum, dan nantikanlah Allahmu senantiasa."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 7, '(12-8) Sama seperti Kanaan, dengan neraca palsu di tangannya, dan suka memeras,', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 8, '(12-9) berkatalah Efraim: "Bukankah aku telah menjadi kaya, telah mendapat harta benda bagiku! Tetapi segala hasil jerih payahku tidak mendatangkan kesalahan yang merupakan dosa bagiku."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 9, '(12-10) Tetapi Aku adalah TUHAN, Allahmu sejak di tanah Mesir; Aku masih mau membuat engkau diam kembali di kemah-kemah seperti di hari-hari pertemuan raya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 10, '(12-11) Aku berbicara kepada para nabi dan banyak kali memberi penglihatan dan memberi perumpamaan dengan perantaraan para nabi.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 11, '(12-12) Bila di Gilead ada kejahatan, maka mereka menjadi kesia-siaan belaka; di Gilgal mereka mempersembahkan lembu-lembu jantan, maka mezbah-mezbah mereka juga menjadi seperti timbunan batu di alur-alur ladang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 12, '(12-13) Yakub melarikan diri ke tanah Aram, dan Israel memperhambakan diri untuk mendapat isteri, ya, untuk mendapat isteri ia menjadi gembala.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 13, '(12-14) Israel dituntun oleh TUHAN keluar dari Mesir dengan perantaraan seorang nabi, ya, ia dijaga oleh seorang nabi.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 12, 14, '(12-15) Efraim telah menimbulkan sakit hati-Nya secara pahit, maka Tuhannya akan membiarkan hutang darahnya menimpa dia, dan akan membalas celanya kepadanya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 1, 'Apabila Efraim berbicara, gemetarlah orang; ia diangkat-angkat di Israel, tetapi ia bersalah dengan menyembah Baal, sehingga matilah ia.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 2, 'Sekarangpun mereka terus berdosa, dan membuat baginya patung tuangan dari perak dan berhala-berhala sesuai dengan kecakapan mereka; semuanya itu buatan tukang-tukang. Persembahkanlah korban kepadanya!, kata mereka. Baiklah manusia mencium anak-anak lembu!', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 3, 'Sebab itu mereka akan seperti kabut pagi atau seperti embun yang hilang pagi-pagi benar, seperti debu jerami yang diterbangkan badai dari tempat pengirikan atau seperti asap dari tingkap.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 4, 'Tetapi Aku adalah TUHAN, Allahmu sejak di tanah Mesir; engkau tidak mengenal allah kecuali Aku, dan tidak ada juruselamat selain dari Aku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 5, 'Akulah yang mengenal engkau di padang gurun, di tanah yang gersang.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 6, 'Ketika mereka makan rumput, maka mereka kenyang; setelah mereka kenyang, maka hati mereka meninggi; itulah sebabnya mereka melupakan Aku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 7, 'Maka Aku menjadi seperti singa bagi mereka, seperti macan tutul Aku mengintip-intip di pinggir jalan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 8, 'Aku mau mendatangi mereka seperti beruang yang kehilangan anak, Aku mau mengoyakkan dada mereka. Di sana Aku memakan mereka seperti singa; binatang liar di padang akan merobek mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 9, 'Aku membinasakan engkau, hai Israel, siapakah yang dapat menolong engkau?', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 10, 'Di mana gerangan rajamu, supaya diselamatkannya engkau, dan semua pemukamu, supaya diberinya engkau keadilan, hai, engkau yang berkata: "Berilah kepadaku seorang raja dan pemuka-pemuka!"', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 11, 'Aku memberikan engkau seorang raja dalam murka-Ku dan mengambilnya dalam gemas-Ku.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 12, 'Kesalahan Efraim dibungkus, dosanya disimpan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 13, 'Sakit beranak mendahului kelahirannya, tetapi ia adalah seorang anak yang tidak bijaksana; sebab tidak pada waktunya ia bergerak, bila waktunya tiba, ia tidak mau keluar dari kandungan ibu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 14, 'Akan Kubebaskankah mereka dari kuasa dunia orang mati, akan Kutebuskah mereka dari pada maut? Di manakah penyakit samparmu, hai maut, di manakah tenaga pembinasamu, hai dunia orang mati? Mata-Ku tertutup bagi belas kasihan.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 15, 'Sekalipun ia tumbuh subur di antara rumput-rumput, maka angin timur, angin TUHAN, akan datang, bertiup dari padang gurun, mengeringkan sumber-sumbernya dan merusakkan mata-mata airnya; dirampasnya harta benda, segala barang yang indah-indah.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 13, 16, '(14-1) Samaria harus mendapat hukuman, sebab ia memberontak terhadap Allahnya. Mereka akan tewas oleh pedang, bayi-bayinya akan diremukkan, dan perempuan-perempuannya yang mengandung akan dibelah perutnya.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 1, '(14-2) Bertobatlah, hai Israel, kepada TUHAN, Allahmu, sebab engkau telah tergelincir karena kesalahanmu.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 2, '(14-3) Bawalah sertamu kata-kata penyesalan, dan bertobatlah kepada TUHAN! katakanlah kepada-Nya: "Ampunilah segala kesalahan, sehingga kami mendapat yang baik, maka kami akan mempersembahkan pengakuan kami.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 3, '(14-4) Asyur tidak dapat menyelamatkan kami; kami tidak mau mengendarai kuda, dan kami tidak akan berkata lagi: Ya, Allah kami! kepada buatan tangan kami. Karena Engkau menyayangi anak yatim."', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 4, '(14-5) Aku akan memulihkan mereka dari penyelewengan, Aku akan mengasihi mereka dengan sukarela, sebab murka-Ku telah surut dari pada mereka.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 5, '(14-6) Aku akan seperti embun bagi Israel, maka ia akan berbunga seperti bunga bakung dan akan menjulurkan akar-akarnya seperti pohon hawar.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 6, '(14-7) Ranting-rantingnya akan merambak, semaraknya akan seperti pohon zaitun dan berbau harum seperti yang di Libanon.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 7, '(14-8) Mereka akan kembali dan diam dalam naungan-Ku dan tumbuh seperti gandum; mereka akan berkembang seperti pohon anggur, yang termasyhur seperti anggur Libanon.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 8, '(14-9) Efraim, apakah lagi sangkut paut-Ku dengan berhala-berhala? Akulah yang menjawab dan memperhatikan engkau! Aku ini seperti pohon sanobar yang menghijau, dari pada-Ku engkau mendapat buah.', 'id', 'TB'),
  ('28', 'hos', 'Hosea', 14, 9, '(14-10) Siapa yang bijaksana, biarlah ia memahami semuanya ini; siapa yang paham, biarlah ia mengetahuinya; sebab jalan-jalan TUHAN adalah lurus, dan orang benar menempuhnya, tetapi pemberontak tergelincir di situ.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 1, 'Firman TUHAN yang datang kepada Yoel bin Petuel.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 2, 'Dengarlah ini, hai para tua-tua, pasanglah telinga, hai seluruh penduduk negeri! Pernahkah terjadi seperti ini dalam zamanmu, atau dalam zaman nenek moyangmu?', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 3, 'Ceritakanlah tentang itu kepada anak-anakmu, dan biarlah anak-anakmu menceritakannya kepada anak-anak mereka, dan anak-anak mereka kepada angkatan yang kemudian.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 4, 'Apa yang ditinggalkan belalang pengerip telah dimakan belalang pindahan, apa yang ditinggalkan belalang pindahan telah dimakan belalang pelompat, dan apa yang ditinggalkan belalang pelompat telah dimakan belalang pelahap.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 5, 'Bangunlah, hai pemabuk, dan menangislah! Merataplah, hai semua peminum anggur karena anggur baru, sebab sudah dirampas dari mulutmu anggur itu!', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 6, 'Sebab maju menyerang negeriku suatu bangsa yang kuat dan tidak terbilang banyaknya; giginya bagaikan gigi singa, dan taringnya bagaikan taring singa betina.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 7, 'Telah dibuatnya pohon anggurku menjadi musnah, dan pohon araku menjadi buntung; dikelupasnya kulitnya sama sekali dan dilemparkannya, sehingga carang-carangnya menjadi putih.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 8, 'Merataplah seperti anak dara yang berlilitkan kain kabung karena mempelai, kekasih masa mudanya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 9, 'Korban sajian dan korban curahan sudah lenyap dari rumah TUHAN; dan berkabunglah para imam, yakni pelayan-pelayan TUHAN.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 10, 'Ladang sudah musnah, tanah berkabung, sebab gandum sudah musnah, buah anggur sudah kering, minyak sudah menipis.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 11, 'Para petani menjadi malu, tukang-tukang kebun anggur meratap karena gandum dan karena jelai, sebab sudah musnah panen ladang.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 12, 'Pohon anggur sudah kering dan pohon ara sudah merana; pohon delima, juga pohon korma dan pohon apel, segala pohon di padang sudah mengering. Sungguh, kegirangan melayu dari antara anak-anak manusia.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 13, 'Lilitkanlah kain kabung dan mengeluhlah, hai para imam; merataplah, hai para pelayan mezbah; masuklah, bermalamlah dengan memakai kain kabung, hai para pelayan Allahku, sebab sudah ditahan dari rumah Allahmu, korban sajian dan korban curahan.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 14, 'Adakanlah puasa yang kudus, maklumkanlah perkumpulan raya; kumpulkanlah para tua-tua dan seluruh penduduk negeri ke rumah TUHAN, Allahmu, dan berteriaklah kepada TUHAN.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 15, 'Wahai, hari itu! Sungguh, hari TUHAN sudah dekat, datangnya sebagai pemusnahan dari Yang Mahakuasa.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 16, 'Bukankah di depan mata kita sudah lenyap makanan, sukaria dan sorak-sorai dari rumah Allah kita?', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 17, 'Biji-bijian menjadi kering di dalam tanah, lumbung-lumbung sudah licin tandas, rengkiang-rengkiang sudah runtuh, sebab gandum sudah habis.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 18, 'Betapa mengeluhnya hewan dan gempar kawanan-kawanan lembu, sebab tidak ada lagi padang rumput baginya; juga kawanan kambing domba terkejut.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 19, 'Kepada-Mu, ya TUHAN, aku berseru, sebab api telah memakan habis tanah gembalaan di padang gurun, dan nyala api telah menghanguskan segala pohon di padang.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 1, 20, 'Juga binatang-binatang di padang menjerit karena rindu kepada-Mu, sebab wadi telah kering, dan apipun telah memakan habis tanah gembalaan di padang gurun.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 1, 'Tiuplah sangkakala di Sion dan berteriaklah di gunung-Ku yang kudus! Biarlah gemetar seluruh penduduk negeri, sebab hari TUHAN datang, sebab hari itu sudah dekat;', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 2, 'suatu hari gelap gulita dan kelam kabut, suatu hari berawan dan kelam pekat; seperti fajar di atas gunung-gunung terbentang suatu bangsa yang banyak dan kuat, yang serupa itu tidak pernah ada sejak purbakala, dan tidak akan ada lagi sesudah itu turun-temurun, pada masa yang akan datang.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 3, 'Di depannya api memakan habis, di belakangnya nyala api berkobar. Tanah di depannya seperti Taman Eden, tetapi di belakangnya padang gurun tandus, dan sama sekali tidak ada yang dapat luput.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 4, 'Rupanya seperti kuda, dan seperti kuda balapan mereka berlari.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 5, 'Seperti gemertaknya kereta-kereta, mereka melompat-lompat di atas puncak gunung-gunung; seperti geletiknya nyala api yang memakan habis jerami; seperti suatu bangsa yang kuat, teratur barisannya untuk berperang.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 6, 'Terhadapnya bangsa-bangsa gemetar, segala muka bertambah menjadi pucat pasi.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 7, 'Seperti pahlawan mereka berlari, seperti prajurit mereka naik tembok; dan mereka masing-masing berjalan terus dengan tidak membelok dari jalannya;', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 8, 'mereka tidak berdesak-desakan, mereka berjalan terus masing-masing di jalannya; mereka menerobos pertahanan dengan tombak, mereka tidak membiarkan barisannya terputus.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 9, 'Mereka menyerbu ke dalam kota, mereka berlari ke atas tembok, mereka memanjat ke dalam rumah-rumah, mereka masuk melalui jendela-jendela seperti pencuri.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 10, 'Di depannya bumi gemetar, langit bergoncang; matahari dan bulan menjadi gelap, dan bintang-bintang menghilangkan cahayanya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 11, 'Dan TUHAN memperdengarkan suara-Nya di depan tentara-Nya. Pasukan-Nya sangat banyak dan pelaksana firman-Nya kuat. Betapa hebat dan sangat dahsyat hari TUHAN! Siapakah yang dapat menahannya?', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 12, '"Tetapi sekarang juga," demikianlah firman TUHAN, "berbaliklah kepada-Ku dengan segenap hatimu, dengan berpuasa, dengan menangis dan dengan mengaduh."', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 13, 'Koyakkanlah hatimu dan jangan pakaianmu, berbaliklah kepada TUHAN, Allahmu, sebab Ia pengasih dan penyayang, panjang sabar dan berlimpah kasih setia, dan Ia menyesal karena hukuman-Nya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 14, 'Siapa tahu, mungkin Ia mau berbalik dan menyesal, dan ditinggalkan-Nya berkat, menjadi korban sajian dan korban curahan bagi TUHAN, Allahmu.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 15, 'Tiuplah sangkakala di Sion, adakanlah puasa yang kudus, maklumkanlah perkumpulan raya;', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 16, 'kumpulkanlah bangsa ini, kuduskanlah jemaah, himpunkanlah orang-orang yang tua, kumpulkanlah anak-anak, bahkan anak-anak yang menyusu; baiklah penganten laki-laki keluar dari kamarnya, dan penganten perempuan dari kamar tidurnya;', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 17, 'baiklah para imam, pelayan-pelayan TUHAN, menangis di antara balai depan dan mezbah, dan berkata: "Sayangilah, ya TUHAN, umat-Mu, dan janganlah biarkan milik-Mu sendiri menjadi cela, sehingga bangsa-bangsa menyindir kepada mereka. Mengapa orang berkata di antara bangsa: Di mana Allah mereka?"', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 18, 'TUHAN menjadi cemburu karena tanah-Nya, dan Ia belas kasihan kepada umat-Nya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 19, 'TUHAN menjawab, kata-Nya kepada umat-Nya: "Sesungguhnya, Aku akan mengirim kepadamu gandum, anggur dan minyak, dan kamu akan kenyang memakannya; Aku tidak akan menyerahkan kamu lagi menjadi cela di antara bangsa-bangsa.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 20, 'Yang datang dari utara itu akan Kujauhkan dari padamu, dan akan Kuusir ke suatu negeri kering dan tandus, barisan mukanya ke laut timur, dan barisan belakangnya ke laut barat, maka bau busuknya dan bau anyirnya akan naik, sebab ia telah melakukan perkara yang besar.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 21, 'Jangan takut, hai tanah, bersorak-soraklah dan bersukacitalah, sebab juga TUHAN telah melakukan perkara yang besar!', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 22, 'Jangan takut, hai binatang-binatang di padang, sebab tanah gembalaan di padang gurun menghijau, pohon menghasilkan buahnya, pohon ara dan pohon anggur memberi kekayaannya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 23, 'Hai bani Sion, bersorak-soraklah dan bersukacitalah karena TUHAN, Allahmu! Sebab telah diberikan-Nya kepadamu hujan pada awal musim dengan adilnya, dan diturunkan-Nya kepadamu hujan, hujan pada awal dan hujan pada akhir musim seperti dahulu.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 24, 'Tempat-tempat pengirikan menjadi penuh dengan gandum, dan tempat pemerasan kelimpahan anggur dan minyak.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 25, 'Aku akan memulihkan kepadamu tahun-tahun yang hasilnya dimakan habis oleh belalang pindahan, belalang pelompat, belalang pelahap dan belalang pengerip, tentara-Ku yang besar yang Kukirim ke antara kamu.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 26, 'Maka kamu akan makan banyak-banyak dan menjadi kenyang, dan kamu akan memuji-muji nama TUHAN, Allahmu, yang telah memperlakukan kamu dengan ajaib; dan umat-Ku tidak akan menjadi malu lagi untuk selama-lamanya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 27, 'Kamu akan mengetahui bahwa Aku ini ada di antara orang Israel, dan bahwa Aku ini, TUHAN, adalah Allahmu dan tidak ada yang lain; dan umat-Ku tidak akan menjadi malu lagi untuk selama-lamanya."', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 28, '"Kemudian dari pada itu akan terjadi, bahwa Aku akan mencurahkan Roh-Ku ke atas semua manusia, maka anak-anakmu laki-laki dan perempuan akan bernubuat; orang-orangmu yang tua akan mendapat mimpi, teruna-terunamu akan mendapat penglihatan-penglihatan.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 29, 'Juga ke atas hamba-hambamu laki-laki dan perempuan akan Kucurahkan Roh-Ku pada hari-hari itu.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 30, 'Aku akan mengadakan mujizat-mujizat di langit dan di bumi: darah dan api dan gumpalan-gumpalan asap.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 31, 'Matahari akan berubah menjadi gelap gulita dan bulan menjadi darah sebelum datangnya hari TUHAN yang hebat dan dahsyat itu.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 2, 32, 'Dan barangsiapa yang berseru kepada nama TUHAN akan diselamatkan, sebab di gunung Sion dan di Yerusalem akan ada keselamatan, seperti yang telah difirmankan TUHAN; dan setiap orang yang dipanggil TUHAN akan termasuk orang-orang yang terlepas."', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 1, '"Sebab sesungguhnya pada hari-hari itu dan pada waktu itu, apabila Aku memulihkan keadaan Yehuda dan Yerusalem,', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 2, 'Aku akan mengumpulkan segala bangsa dan akan membawa mereka turun ke lembah Yosafat; Aku akan berperkara dengan mereka di sana mengenai umat-Ku dan milik-Ku sendiri, Israel, oleh karena mereka mencerai-beraikannya ke antara bangsa-bangsa dan membagi-bagi tanah-Ku,', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 3, 'oleh karena mereka membuang undi mengenai umat-Ku, menyerahkan seorang anak laki-laki karena seorang sundal, dan menjual seorang anak perempuan karena anggur untuk diminum.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 4, 'Lagi apakah sangkut pautmu dengan Aku, hai Tirus dan Sidon dan seluruh wilayah Filistin? Apakah kamu ini hendak membalas perbuatan-Ku? Apabila kamu melakukan sesuatu terhadap Aku, maka dengan cepat, dengan segera Aku akan membalikkan perbuatanmu itu kepadamu sendiri.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 5, 'Oleh karena kamu telah mengambil perak-Ku dan emas-Ku dan telah membawa barang-barang-Ku yang berharga yang indah-indah ke tempat-tempat ibadahmu,', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 6, 'dan telah menjual orang-orang Yehuda dan orang-orang Yerusalem kepada orang Yunani dengan maksud menjauhkan mereka dari daerah mereka.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 7, 'Sesungguhnya Aku akan menggerakkan mereka dari tempat ke mana kamu menjual mereka, dan Aku akan membalikkan perbuatanmu itu ke atas kepalamu sendiri.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 8, 'Aku akan menjual anak-anakmu laki-laki dan perempuan kepada orang-orang Yehuda dan mereka akan menjual anak-anakmu itu kepada orang-orang Syeba, kepada suatu bangsa yang jauh, sebab TUHAN telah mengatakannya."', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 9, 'Maklumkanlah hal ini di antara bangsa-bangsa: bersiaplah untuk peperangan, gerakkanlah para pahlawan; suruhlah semua prajurit tampil dan maju!', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 10, 'Tempalah mata bajakmu menjadi pedang dan pisau-pisau pemangkasmu menjadi tombak; baiklah orang yang tidak berdaya berkata: "Aku ini pahlawan!"', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 11, 'Bergeraklah dan datanglah, hai segala bangsa dari segenap penjuru, dan berkumpullah ke sana! Bawalah turun, ya TUHAN, pahlawan-pahlawan-M', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 12, 'Baiklah bangsa-bangsa bergerak dan maju ke lembah Yosafat, sebab di sana Aku akan duduk untuk menghakimi segala bangsa dari segenap penjuru.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 13, 'Ayunkanlah sabit, sebab sudah masak tuaian; marilah, iriklah, sebab sudah penuh tempat anggur; tempat-tempat pemerasan kelimpahan, sebab banyak kejahatan mereka.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 14, 'Banyak orang, banyak orang di lembah penentuan! Ya, sudah dekat hari TUHAN di lembah penentuan!', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 15, 'Matahari dan bulan menjadi gelap, dan bintang-bintang menghilangkan cahayanya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 16, 'TUHAN mengaum dari Sion, dari Yerusalem Ia memperdengarkan suara-Nya, dan langit dan bumi bergoncang. Tetapi TUHAN adalah tempat perlindungan bagi umat-Nya, dan benteng bagi orang Israel.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 17, '"Maka kamu akan mengetahui bahwa Aku, TUHAN, adalah Allahmu, yang diam di Sion, gunung-Ku yang kudus. Dan Yerusalem akan menjadi kudus, dan orang-orang luar tidak akan melintasinya lagi.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 18, 'Pada waktu itu akan terjadi, bahwa gunung-gunung akan meniriskan anggur baru, bukit-bukit akan mengalirkan susu, dan segala sungai Yehuda akan mengalirkan air; mata air akan terbit dari rumah TUHAN dan akan membasahi lembah Sitim.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 19, 'Mesir akan menjadi sunyi sepi, dan Edom akan menjadi padang gurun tandus, oleh sebab kekerasan terhadap keturunan Yehuda, oleh karena mereka telah menumpahkan darah orang yang tak bersalah di tanahnya.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 20, 'Tetapi Yehuda tetap didiami untuk selama-lamanya dan Yerusalem turun-temurun.', 'id', 'TB'),
  ('29', 'yl', 'Yoel', 3, 21, 'Aku akan membalas darah mereka yang belum Kubalas; TUHAN tetap diam di Sion."', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 1, 'Perkataan yang dinyatakan kepada Amos, salah seorang peternak domba dari Tekoa, tentang Israel pada zaman Uzia, raja Yehuda, dan dalam zaman Yerobeam, anak Yoas, raja Israel, dua tahun sebelum gempa bumi.', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 2, 'Berkatalah ia: "TUHAN mengaum dari Sion dan dari Yerusalem Ia memperdengarkan suara-Nya; keringlah padang-padang penggembalaan dan layulah puncak gunung Karmel."', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 3, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Damsyik, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena mereka telah mengirik Gilead dengan eretan pengirik dari besi,', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 4, 'Aku akan melepas api ke dalam istana Hazael, sehingga puri Benhadad dimakan habis;', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 5, 'Aku akan mematahkan palang pintu Damsyik dan melenyapkan penduduk dari Bikeat-Awen serta pemegang tongkat kerajaan dari Bet-Eden; dan rakyat Aram harus pergi sebagai orang buangan ke Kir," firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 6, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Gaza, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena mereka telah mengangkut ke dalam pembuangan suatu bangsa seluruhnya, untuk diserahkan kepada Edom,', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 7, 'Aku akan melepas api ke dalam tembok Gaza, sehingga purinya dimakan habis;', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 8, 'Aku akan melenyapkan penduduk dari Asdod dan pemegang tongkat kerajaan dari Askelon; Aku akan mengacungkan tangan-Ku melawan Ekron, sehingga binasalah sisa-sisa orang Filistin," firman Tuhan ALLAH.', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 9, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Tirus, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena mereka telah menyerahkan tertawan suatu bangsa seluruhnya kepada Edom dan tidak mengingat perjanjian persaudaraan,', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 10, 'Aku akan melepas api ke dalam tembok Tirus, sehingga purinya dimakan habis."', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 11, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Edom, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena ia mengejar saudaranya dengan pedang dan mengekang belas kasihannya, memendamkan amarahnya untuk selamanya dan menyimpan gemasnya untuk seterusnya,', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 12, 'Aku akan melepas api ke dalam Teman, sehingga puri Bozra dimakan habis."', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 13, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat bani Amon, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena mereka membelah perut perempuan-perempuan hamil di Gilead dengan maksud meluaskan daerah mereka sendiri,', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 14, 'Aku akan menyalakan api di dalam tembok Raba, sehingga purinya dimakan habis, diiringi sorak-sorai pada waktu pertempuran, diiringi angin badai pada waktu puting beliung;', 'id', 'TB'),
  ('30', 'am', 'Amos', 1, 15, 'dan raja mereka harus pergi sebagai orang buangan, ia bersama-sama dengan pembesar-pembesarnya," firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 1, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Moab, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena ia telah membakar tulang-tulang raja Edom menjadi kapur,', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 2, 'Aku akan melepas api ke dalam Moab, sehingga puri Keriot dimakan habis; Moab akan mati di dalam kegaduhan, diiringi sorak-sorai pada saat sangkakala berbunyi;', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 3, 'Aku akan melenyapkan penguasa dari antaranya dan membunuh segala pembesarnya bersama-sama dengan dia," firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 4, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Yehuda, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena mereka telah menolak hukum TUHAN, dan tidak berpegang pada ketetapan-ketetapan-Nya, tetapi disesatkan oleh dewa-dewa kebohongannya, yang diikuti oleh nenek moyangnya,', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 5, 'Aku akan melepas api ke dalam Yehuda, sehingga puri Yerusalem dimakan habis."', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 6, 'Beginilah firman TUHAN: "Karena tiga perbuatan jahat Israel, bahkan empat, Aku tidak akan menarik kembali keputusan-Ku: Oleh karena mereka menjual orang benar karena uang dan orang miskin karena sepasang kasut;', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 7, 'mereka menginjak-injak kepala orang lemah ke dalam debu dan membelokkan jalan orang sengsara; anak dan ayah pergi menjamah seorang perempuan muda, sehingga melanggar kekudusan nama-Ku;', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 8, 'mereka merebahkan diri di samping setiap mezbah di atas pakaian gadaian orang, dan minum anggur orang-orang yang kena denda di rumah Allah mereka.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 9, 'Padahal Akulah yang memunahkan dari depan mereka, orang Amori, yang tingginya seperti tinggi pohon aras dan yang kuat seperti pohon tarbantin; Aku telah memunahkan buahnya dari atas dan akarnya dari bawah.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 10, 'Padahal Akulah yang menuntun kamu keluar dari tanah Mesir dan memimpin kamu empat puluh tahun lamanya di padang gurun, supaya kamu menduduki negeri orang Amori;', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 11, 'Aku telah membangkitkan sebagian dari anak-anakmu menjadi nabi dan sebagian dari teruna-terunamu menjadi nazir. Bukankah betul-betul begitu, hai orang Israel?" demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 12, '"Tetapi kamu memberi orang nazir minum anggur dan memerintahkan kepada para nabi: Jangan kamu bernubuat!', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 13, 'Sesungguhnya, Aku akan mengguncangkan tempat kamu berpijak seperti goncangan kereta yang sarat dengan berkas gandum.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 14, 'Orang cepat tidak mungkin lagi melarikan diri, orang kuat tidak dapat menggunakan kekuatannya, dan pahlawan tidak dapat melarikan diri.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 15, 'Pemegang panah tidak dapat bertahan, orang yang cepat kaki tidak akan terluput dan penunggang kuda tidak dapat meluputkan diri.', 'id', 'TB'),
  ('30', 'am', 'Amos', 2, 16, 'Juga orang yang berhati berani di antara para pahlawan akan melarikan diri dengan telanjang pada hari itu," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 1, 'Dengarlah firman ini, yang diucapkan TUHAN tentang kamu, hai orang Israel, tentang segenap kaum yang telah Kutuntun keluar dari tanah Mesir, bunyinya:', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 2, '"Hanya kamu yang Kukenal dari segala kaum di muka bumi, sebab itu Aku akan menghukum kamu karena segala kesalahanmu.', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 3, 'Berjalankah dua orang bersama-sama, jika mereka belum berjanji?', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 4, 'Mengaumkah seekor singa di hutan, apabila tidak mendapat mangsa? Bersuarakah singa muda dari sarangnya, jika belum menangkap apa-apa?', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 5, 'Jatuhkah seekor burung ke dalam perangkap di tanah, apabila tidak ada jerat terhadapnya? Membingkaskah perangkap dari tanah, jika tidak ditangkapnya sesuatu?', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 6, 'Adakah sangkakala ditiup di suatu kota, dan orang-orang tidak gemetar? Adakah terjadi malapetaka di suatu kota, dan TUHAN tidak melakukannya?', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 7, 'Sungguh, Tuhan ALLAH tidak berbuat sesuatu tanpa menyatakan keputusan-Nya kepada hamba-hamba-Nya, para nabi.', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 8, 'Singa telah mengaum, siapakah yang tidak takut? Tuhan ALLAH telah berfirman, siapakah yang tidak bernubuat?"', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 9, 'Siarkanlah di dalam puri di Asyur dan di dalam puri di tanah Mesir serta katakan: "Berkumpullah di gunung-gunung dekat Samaria dan pandanglah kekacauan besar yang ada di tengah-tengahnya dan pemerasan yang ada di kota itu."', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 10, '"Mereka tidak tahu berbuat jujur," demikianlah firman TUHAN, "mereka itu yang menimbun kekerasan dan aniaya di dalam purinya."', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 11, 'Sebab itu beginilah firman Tuhan ALLAH: "Musuh akan ada di sekeliling negeri, kekuatanmu akan ditanggalkannya dari padamu, dan purimu akan dijarahi!"', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 12, 'Beginilah firman TUHAN: "Seperti seorang gembala melepaskan dari mulut singa dua tulang betis atau potongan telinga, demikianlah orang Israel yang diam di Samaria akan dilepaskan seperti sebagian dari katil dan seperti sepenggal dari kaki balai-balai."', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 13, '"Dengarlah, dan peringatkanlah kaum keturunan Yakub," demikianlah firman Tuhan ALLAH, Allah semesta alam,', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 14, '"bahwa pada waktu Aku menghukum Israel karena perbuatan-perbuatannya yang jahat, Aku akan melakukan hukuman kepada mezbah-mezbah Betel, sehingga tanduk-tanduk mezbah itu dipatahkan dan jatuh ke tanah.', 'id', 'TB'),
  ('30', 'am', 'Amos', 3, 15, 'Aku akan merobohkan balai musim dingin beserta balai musim panas; hancurlah rumah-rumah gading, dan habislah rumah-rumah gedang," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 1, '"Dengarlah firman ini, hai lembu-lembu Basan, yang ada di gunung Samaria, yang memeras orang lemah, yang menginjak orang miskin, yang mengatakan kepada tuan-tuanmu: bawalah ke mari, supaya kita minum-minum!', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 2, 'Tuhan ALLAH telah bersumpah demi kekudusan-Nya: sesungguhnya, akan datang masanya bagimu, bahwa kamu diangkat dengan kait dan yang tertinggal di antara kamu dengan kail ikan.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 3, 'Kamu akan keluar melalui belahan tembok, masing-masing lurus ke depan, dan kamu akan diseret ke arah Hermon," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 4, '"Datanglah ke Betel dan lakukanlah perbuatan jahat, ke Gilgal dan perhebatlah perbuatan jahat! Bawalah korban sembelihanmu pada waktu pagi, dan persembahan persepuluhanmu pada hari yang ketiga!', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 5, 'Bakarlah korban syukur dari roti yang beragi dan maklumkanlah persembahan-persembahan sukarela; siarkanlah itu! Sebab bukankah yang demikian kamu sukai, hai orang Israel?" demikianlah firman Tuhan ALLAH.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 6, '"Sekalipun Aku ini telah memberi kepadamu gigi yang tidak disentuh makanan di segala kotamu dan kekurangan roti di segala tempat kediamanmu, namun kamu tidak berbalik kepada-Ku," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 7, '"Akupun telah menahan hujan dari padamu, ketika tiga bulan lagi sebelum panen; Aku menurunkan hujan ke atas kota yang satu dan tidak menurunkan hujan ke atas kota yang lain; ladang yang satu kehujanan, dan ladang, yang tidak kena hujan, menjadi kering;', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 8, 'penduduk dua tiga kota pergi terhuyung-huyung ke satu kota untuk minum air, tetapi mereka tidak menjadi puas; namun kamu tidak berbalik kepada-Ku," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 9, '"Aku telah memukul kamu dengan hama dan penyakit gandum, telah melayukan taman-tamanmu dan kebun-kebun anggurmu, pohon-pohon ara dan pohon-pohon zaitunmu dimakan habis oleh belalang, namun kamu tidak berbalik kepada-Ku," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 10, '"Aku telah melepas penyakit sampar ke antaramu seperti kepada orang Mesir; Aku telah membunuh terunamu dengan pedang pada waktu kudamu dijarah; Aku telah membuat bau busuk perkemahanmu tercium oleh hidungmu; namun kamu tidak berbalik kepada-Ku," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 11, '"Aku telah menjungkirbalikkan kota-kota di antara kamu, seperti Allah menjungkirbalikkan Sodom dan Gomora, sehingga kamu menjadi seperti puntung yang ditarik dari kebakaran, namun kamu tidak berbalik kepada-Ku," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 12, '"Sebab itu demikianlah akan Kulakukan kepadamu, hai Israel. ?Oleh karena Aku akan melakukan yang demikian kepadamu, maka bersiaplah untuk bertemu dengan Allahmu, hai Israel!"', 'id', 'TB'),
  ('30', 'am', 'Amos', 4, 13, 'Sebab sesungguhnya, Dia yang membentuk gunung-gunung dan menciptakan angin, yang memberitahukan kepada manusia apa yang dipikirkan-Nya, yang membuat fajar dan kegelapan dan yang berjejak di atas bukit-bukit bumi?TUHAN, Allah semesta alam, itulah nama-Nya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 1, 'Dengarlah perkataan ini yang kuucapkan tentang kamu sebagai ratapan, hai kaum Israel:', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 2, '"Telah rebah, tidak akan bangkit-bangkit lagi anak dara Israel, terkapar di atas tanahnya, tidak ada yang membangkitkannya."', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 3, 'Sebab beginilah firman Tuhan ALLAH kepada kaum Israel: "Kota yang maju berperang dengan seribu orang, dari padanya akan tersisa seratus orang, dan yang maju berperang dengan seratus orang, dari padanya akan tersisa sepuluh orang."', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 4, 'Sebab beginilah firman TUHAN kepada kaum Israel: "Carilah Aku, maka kamu akan hidup!', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 5, 'Janganlah kamu mencari Betel, janganlah pergi ke Gilgal dan janganlah menyeberang ke Bersyeba, sebab Gilgal pasti masuk ke dalam pembuangan dan Betel akan lenyap."', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 6, 'Carilah TUHAN, maka kamu akan hidup, supaya jangan Ia memasuki keturunan Yusuf bagaikan api, yang memakannya habis dengan tidak ada yang memadamkan bagi Betel.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 7, 'Hai kamu yang mengubah keadilan menjadi ipuh dan yang mengempaskan kebenaran ke tanah!', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 8, 'Dia yang telah membuat bintang kartika dan bintang belantik, yang mengubah kekelaman menjadi pagi dan yang membuat siang gelap seperti malam; Dia yang memanggil air laut dan mencurahkannya ke atas permukaan bumi?TUHAN itulah nama-Nya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 9, 'Dia yang menimpakan kebinasaan atas yang kuat, sehingga kebinasaan datang atas tempat yang berkubu.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 10, 'Mereka benci kepada yang memberi teguran di pintu gerbang, dan mereka keji kepada yang berkata dengan tulus ikhlas.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 11, 'Sebab itu, karena kamu menginjak-injak orang yang lemah dan mengambil pajak gandum dari padanya, ?sekalipun kamu telah mendirikan rumah-rumah dari batu pahat, kamu tidak akan mendiaminya; sekalipun kamu telah membuat kebun anggur yang indah, kamu tidak akan minum anggurnya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 12, 'Sebab Aku tahu, bahwa perbuatanmu yang jahat banyak dan dosamu berjumlah besar, hai kamu yang menjadikan orang benar terjepit, yang menerima uang suap dan yang mengesampingkan orang miskin di pintu gerbang.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 13, 'Sebab itu orang yang berakal budi akan berdiam diri pada waktu itu, karena waktu itu adalah waktu yang jahat.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 14, 'Carilah yang baik dan jangan yang jahat, supaya kamu hidup; dengan demikian TUHAN, Allah semesta alam, akan menyertai kamu, seperti yang kamu katakan.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 15, 'Bencilah yang jahat dan cintailah yang baik; dan tegakkanlah keadilan di pintu gerbang; mungkin TUHAN, Allah semesta alam, akan mengasihani sisa-sisa keturunan Yusuf.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 16, 'Sesungguhnya, beginilah firman TUHAN, Allah semesta alam, Tuhanku: "Di segala tanah lapang akan ada ratapan dan di segala lorong orang akan berkata: Wahai! Wahai! Petani dipanggil untuk berkabung dan orang-orang yang pandai meratap untuk mengadakan ratapan.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 17, 'Dan di segala kebun anggur akan ada ratapan, apabila Aku berjalan dari tengah-tengahmu," firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 18, 'Celakalah mereka yang menginginkan hari TUHAN! Apakah gunanya hari TUHAN itu bagimu? Hari itu kegelapan, bukan terang!', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 19, 'Seperti seseorang yang lari terhadap singa, seekor beruang mendatangi dia, dan ketika ia sampai ke rumah, bertopang dengan tangannya ke dinding, seekor ular memagut dia!', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 20, 'Bukankah hari TUHAN itu kegelapan dan bukan terang, kelam kabut dan tidak bercahaya?', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 21, '"Aku membenci, Aku menghinakan perayaanmu dan Aku tidak senang kepada perkumpulan rayamu.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 22, 'Sungguh, apabila kamu mempersembahkan kepada-Ku korban-korban bakaran dan korban-korban sajianmu, Aku tidak suka, dan korban keselamatanmu berupa ternak yang tambun, Aku tidak mau pandang.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 23, 'Jauhkanlah dari pada-Ku keramaian nyanyian-nyanyianmu, lagu gambusmu tidak mau Aku dengar.', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 24, 'Tetapi biarlah keadilan bergulung-gulung seperti air dan kebenaran seperti sungai yang selalu mengalir."', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 25, '"Apakah kamu mempersembahkan kepada-Ku korban sembelihan dan korban sajian, selama empat puluh tahun di padang gurun itu, hai kaum Israel?', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 26, 'Kamu akan mengangkut Sakut, rajamu, dan Kewan, dewa bintangmu, patung-patungmu yang telah kamu buat bagimu itu,', 'id', 'TB'),
  ('30', 'am', 'Amos', 5, 27, 'dan Aku akan membawa kamu ke dalam pembuangan jauh ke seberang Damsyik," firman TUHAN, yang nama-Nya Allah semesta alam.', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 1, '"Celaka atas orang-orang yang merasa aman di Sion, atas orang-orang yang merasa tenteram di gunung Samaria, atas orang-orang terkemuka dari bangsa yang utama, orang-orang yang kepada mereka kaum Israel biasa datang!', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 2, 'Menyeberanglah ke Kalne, dan lihat-lihatlah; berjalanlah dari sana ke Hamat yang besar itu, dan pergilah ke Gat orang Filistin! Adakah mereka lebih baik dari kerajaan-kerajaan ini, atau lebih besarkah daerah mereka dari daerahmu?', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 3, 'Hai kamu, yang menganggap jauh hari malapetaka, tetapi mendekatkan pemerintahan kekerasan;', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 4, 'yang berbaring di tempat tidur dari gading dan duduk berjuntai di ranjang; yang memakan anak-anak domba dari kumpulan kambing domba dan anak-anak lembu dari tengah-tengah kawanan binatang yang tambun;', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 5, 'yang bernyanyi-nyanyi mendengar bunyi gambus, dan seperti Daud menciptakan bunyi-bunyian bagi dirinya;', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 6, 'yang minum anggur dari bokor, dan berurap dengan minyak yang paling baik, tetapi tidak berduka karena hancurnya keturunan Yusuf!', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 7, 'Sebab itu sekarang, mereka akan pergi sebagai orang buangan di kepala barisan, dan berlalulah keriuhan pesta orang-orang yang duduk berjuntai itu."', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 8, 'Tuhan ALLAH telah bersumpah demi diri-Nya, ?demikianlah firman TUHAN, Allah semesta alam?:"Aku ini keji kepada kecongkakan Yakub, dan benci kepada purinya; Aku akan menyerahkan kota serta isinya."', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 9, 'Dan jika masih tinggal sepuluh orang dalam satu rumah, mereka akan mati.', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 10, 'Dan jika pamannya, pembakar mayat itu, yang datang mengangkat dan mengeluarkan mayat itu dari rumah itu, bertanya kepada orang yang ada di bagian belakang rumah: "Adakah lagi orang bersama-sama engkau?" dan dijawab: "Tidak ada," ia akan berkata: "Diam!" Sebab tidaklah patut menyebut-nyebut nama TUHAN!', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 11, 'Sebab sesungguhnya, TUHAN memberi perintah, maka rumah besar dirobohkan menjadi reruntuhan dan rumah kecil menjadi rosokan.', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 12, 'Berlarikah kuda-kuda di atas bukit batu, atau dibajak orangkah laut dengan lembu? Sungguh, kamu telah mengubah keadilan menjadi racun dan hasil kebenaran menjadi ipuh!', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 13, 'Hai kamu, yang bersukacita karena Lodabar, dan yang berkata: "Bukankah kita dengan kekuatan kita merebut Karnaim bagi kita?"', 'id', 'TB'),
  ('30', 'am', 'Amos', 6, 14, '"Sebab sesungguhnya, Aku akan membangkitkan suatu bangsa melawan kamu, hai kaum Israel," demikianlah firman TUHAN, Allah semesta alam, "dan mereka akan menindas kamu dari jalan yang menuju ke Hamat sampai ke sungai yang di Araba."', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 1, 'Inilah yang diperlihatkan Tuhan ALLAH kepadaku: Tampak Ia membentuk kawanan belalang, pada waktu rumput akhir mulai tumbuh, yaitu rumput akhir sesudah yang dipotong bagi raja.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 2, 'Ketika belalang mulai menghabisi tumbuh-tumbuhan di tanah, berkatalah aku: "Tuhan ALLAH, berikanlah kiranya pengampunan! Bagaimanakah Yakub dapat bertahan? Bukankah ia kecil?"', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 3, 'Maka menyesallah TUHAN karena hal itu. "Itu tidak akan terjadi," firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 4, 'Inilah yang diperlihatkan Tuhan ALLAH kepadaku: Tampak Tuhan ALLAH memanggil api untuk melakukan hukuman. Api itu memakan habis samudera raya dan akan memakan habis tanah ladang.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 5, 'Lalu aku berkata: "Tuhan ALLAH, hentikanlah kiranya! Bagaimanakah Yakub dapat bertahan? Bukankah ia kecil?"', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 6, 'Maka menyesallah TUHAN karena hal itu. "Inipun tidak akan terjadi," firman Tuhan ALLAH.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 7, 'Inilah yang diperlihatkan-Nya kepadaku: Tampak Tuhan berdiri dekat sebuah tembok yang tegak lurus, dan di tangan-Nya ada tali sipat.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 8, 'Lalu berfirmanlah TUHAN kepadaku: "Apakah yang kaulihat, Amos?" Jawabku: "Tali sipat!" Berfirmanlah Tuhan: "Sesungguhnya, Aku akan menaruh tali sipat di tengah-tengah umat-Ku Israel; Aku tidak akan memaafkannya lagi.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 9, 'Bukit-bukit pengorbanan dari pada Ishak akan dilicintandaskan dan tempat-tempat kudus Israel akan diruntuhkan, dan Aku akan bangkit melawan keluarga Yerobeam dengan pedang."', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 10, 'Lalu Amazia, imam di Betel, menyuruh orang menghadap Yerobeam, raja Israel, dengan pesan: "Amos telah mengadakan persepakatan melawan tuanku di tengah-tengah kaum Israel; negeri ini tidak dapat lagi menahan segala perkataannya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 11, 'Sebab beginilah dikatakan Amos: Yerobeam akan mati terbunuh oleh pedang dan Israel pasti pergi dari tanahnya sebagai orang buangan."', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 12, 'Lalu berkatalah Amazia kepada Amos: "Pelihat, pergilah, enyahlah ke tanah Yehuda! Carilah makananmu di sana dan bernubuatlah di sana!', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 13, 'Tetapi jangan lagi bernubuat di Betel, sebab inilah tempat kudus raja, inilah bait suci kerajaan."', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 14, 'Jawab Amos kepada Amazia: "Aku ini bukan nabi dan aku ini tidak termasuk golongan nabi, melainkan aku ini seorang peternak dan pemungut buah ara hutan.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 15, 'Tetapi TUHAN mengambil aku dari pekerjaan menggiring kambing domba, dan TUHAN berfirman kepadaku: Pergilah, bernubuatlah terhadap umat-Ku Israel.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 16, 'Maka sekarang, dengarlah firman TUHAN! Engkau berkata: Janganlah bernubuat menentang Israel, dan janganlah ucapkan perkataan menentang keturunan Ishak.', 'id', 'TB'),
  ('30', 'am', 'Amos', 7, 17, 'Sebab itu beginilah firman TUHAN: Isterimu akan bersundal di kota, dan anak-anakmu laki-laki dan perempuan akan tewas oleh pedang; tanahmu akan dibagi-bagikan dengan memakai tali pengukur, engkau sendiri akan mati di tanah yang najis, dan Israel pasti pergi dari tanahnya sebagai orang buangan."', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 1, 'Inilah yang diperlihatkan Tuhan ALLAH kepadaku: Tampak sebuah bakul berisi buah-buahan musim kemarau.', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 2, 'Lalu berfirmanlah Ia: "Apakah yang kaulihat, Amos?" Jawabku: "Sebuah bakul berisi buah-buahan musim kemarau." Berfirmanlah TUHAN kepadaku: "Kesudahan telah datang bagi umat-Ku Israel. Aku tidak akan memaafkannya lagi.', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 3, 'Nyanyian-nyanyian di tempat suci akan menjadi ratapan pada hari itu," demikianlah firman Tuhan ALLAH. "Ada banyak bangkai: ke mana-mana orang melemparkannya dengan diam-diam."', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 4, 'Dengarlah ini, kamu yang menginjak-injak orang miskin, dan yang membinasakan orang sengsara di negeri ini', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 5, 'dan berpikir: "Bilakah bulan baru berlalu, supaya kita boleh menjual gandum dan bilakah hari Sabat berlalu, supaya kita boleh menawarkan terigu dengan mengecilkan efa, membesarkan syikal, berbuat curang dengan neraca palsu,', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 6, 'supaya kita membeli orang lemah karena uang dan orang yang miskin karena sepasang kasut; dan menjual terigu rosokan?"', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 7, 'TUHAN telah bersumpah demi kebanggaan Yakub: "Bahwasanya Aku tidak akan melupakan untuk seterusnya segala perbuatan mereka!', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 8, 'Tidakkah akan gemetar bumi karena hal itu, sehingga setiap penduduknya berkabung? Tidakkah itu seluruhnya akan naik seperti sungai Nil, diombang-ambingkan dan surut seperti sungai Mesir?"', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 9, '"Pada hari itu akan terjadi," demikianlah firman Tuhan ALLAH, "Aku akan membuat matahari terbenam di siang hari dan membuat bumi gelap pada hari cerah.', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 10, 'Aku akan mengubah perayaan-perayaanmu menjadi perkabungan, dan segala nyanyianmu menjadi ratapan. Aku akan mengenakan kain kabung pada setiap pinggang dan menjadikan gundul setiap kepala. Aku akan membuatnya sebagai perkabungan karena kematian anak tunggal, sehingga akhirnya menjadi seperti hari yang pahit pedih."', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 11, '"Sesungguhnya, waktu akan datang," demikianlah firman Tuhan ALLAH, "Aku akan mengirimkan kelaparan ke negeri ini, bukan kelaparan akan makanan dan bukan kehausan akan air, melainkan akan mendengarkan firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 12, 'Mereka akan mengembara dari laut ke laut dan menjelajah dari utara ke timur untuk mencari firman TUHAN, tetapi tidak mendapatnya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 13, 'Pada hari itu akan rebah lesu anak-anak dara yang cantik dan anak-anak teruna karena haus;', 'id', 'TB'),
  ('30', 'am', 'Amos', 8, 14, 'mereka yang bersumpah demi Asima, dewi Samaria dan yang berkata: Demi allahmu yang hidup, hai Dan! serta: Demi dewa kekasihmu yang hidup, hai Bersyeba! mereka itu akan rebah dan tidak akan bangkit-bangkit lagi."', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 1, 'Kulihat Tuhan berdiri dekat mezbah, dan Ia berfirman: "Pukullah hulu tiang dengan keras, sehingga ambang-ambang bergoncang, dan runtuhkanlah itu ke atas kepala semua orang, dan sisa-sisa mereka akan Kubunuh dengan pedang; tidak seorangpun dari mereka akan dapat melarikan diri, dan tidak seorangpun dari mereka akan dapat meluputkan diri.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 2, 'Sekalipun mereka menembus sampai ke dunia orang mati, tangan-Ku akan mengambil mereka dari sana; sekalipun mereka naik ke langit, Aku akan menurunkan mereka dari sana.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 3, 'Sekalipun mereka bersembunyi di puncak gunung Karmel, Aku akan mengusut dan mengambil mereka dari sana; sekalipun mereka menyembunyikan diri terhadap mata-Ku di dasar laut, Aku akan memerintahkan ular untuk memagut mereka di sana.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 4, 'Sekalipun mereka berjalan di depan musuhnya sebagai orang tawanan, Aku akan memerintahkan pedang untuk membunuh mereka di sana. Aku akan mengarahkan mata-Ku kepada mereka untuk kecelakaan dan bukan untuk keberuntungan mereka."', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 5, 'Tuhan ALLAH semesta alamlah yang menyentuh bumi, sehingga bergoyang, dan semua penduduknya berkabung, dan seluruhnya naik seperti sungai Nil, dan surut seperti sungai Mesir;', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 6, 'yang mendirikan anjung-Nya di langit dan mendasarkan kubah-Nya di atas bumi; yang memanggil air laut dan mencurahkannya ke atas permukaan bumi?TUHAN itulah nama-Nya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 7, '"Bukankah kamu sama seperti orang Etiopia bagi-Ku, hai orang Israel?" demikianlah firman TUHAN. "Bukankah Aku telah menuntun orang Israel keluar dari tanah Mesir, orang Filistin dari Kaftor, dan orang Aram dari Kir?', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 8, 'Sesungguhnya, TUHAN Allah sudah mengamat-amati kerajaan yang berdosa ini: Aku akan memunahkannya dari muka bumi! Tetapi Aku tidak akan memunahkan keturunan Yakub sama sekali," demikianlah firman TUHAN.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 9, '"Sebab sesungguhnya, Aku memberi perintah, dan Aku mengiraikan kaum Israel di antara segala bangsa, seperti orang mengiraikan ayak, dan sebiji batu kecilpun tidak akan jatuh ke tanah.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 10, 'Oleh pedang akan mati terbunuh semua orang berdosa di antara umat-Ku yang mengatakan: Malapetaka itu tidak akan menyusul dan tidak akan mencapai kami."', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 11, '"Pada hari itu Aku akan mendirikan kembali pondok Daud yang telah roboh; Aku akan menutup pecahan dindingnya, dan akan mendirikan kembali reruntuhannya; Aku akan membangunnya kembali seperti di zaman dahulu kala,', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 12, 'supaya mereka menguasai sisa-sisa bangsa Edom dan segala bangsa yang Kusebut milik-Ku," demikianlah firman TUHAN yang melakukan hal ini.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 13, '"Sesungguhnya, waktu akan datang," demikianlah firman TUHAN, "bahwa pembajak akan tepat menyusul penuai dan pengirik buah anggur penabur benih; gunung-gunung akan meniriskan anggur baru dan segala bukit akan kebanjiran.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 14, 'Aku akan memulihkan kembali umat-Ku Israel: mereka akan membangun kota-kota yang licin tandas dan mendiaminya; mereka akan menanami kebun-kebun anggur dan minum anggurnya; mereka akan membuat kebun-kebun buah-buahan dan makan buahnya.', 'id', 'TB'),
  ('30', 'am', 'Amos', 9, 15, 'Maka Aku akan menanam mereka di tanah mereka, dan mereka tidak akan dicabut lagi dari tanah yang telah Kuberikan kepada mereka," firman TUHAN, Allahmu.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 1, 'Penglihatan Obaja. Beginilah firman Tuhan ALLAH tentang Edom?suatu kabar telah kami dengar dari TUHAN, seorang utusan telah disuruh ke tengah bangsa-bangsa: "Bangunlah, marilah kita bangkit memeranginya!" ?', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 2, 'Sesungguhnya, Aku membuat engkau kecil di antara bangsa-bangsa, engkau dihinakan sangat.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 3, 'Keangkuhan hatimu telah memperdayakan engkau, ya engkau yang tinggal di liang-liang batu, di tempat kediamanmu yang tinggi; engkau yang berkata dalam hatimu: "Siapakah yang sanggup menurunkan aku ke bumi?"', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 4, 'Sekalipun engkau terbang tinggi seperti burung rajawali, bahkan, sekalipun sarangmu ditempatkan di antara bintang-bintang, dari sanapun Aku akan menurunkan engkau, ?demikianlah firman TUHAN.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 5, 'Jika malam-malam pencuri atau perampok datang kepadamu?betapa engkau dibinasakannya?bukankah mereka akan mencuri seberapa yang diperlukannya? Jika pemetik buah anggur datang kepadamu, bukankah mereka akan meninggalkan sisa-sisa pemetikannya?', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 6, 'Betapa kaum Esau digeledah, betapa harta bendanya yang tersembunyi dicari-cari!', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 7, 'Sampai ke tapal batas engkau diusir oleh semua teman sekutumu; engkau diperdayakan, dikalahkan oleh sahabat-sahabatmu. Siapa yang makan sehidangan dengan engkau memasang jerat terhadap engkau. ?Tidak ada pengertian padanya.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 8, 'Bukankah pada waktu itu, demikianlah firman TUHAN, Aku akan melenyapkan orang-orang bijaksana dari Edom, dan pengertian dari pegunungan Esau?', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 9, 'Juga para pahlawanmu, hai Teman, akan tertegun, supaya semua orang di pegunungan Esau lenyap terbunuh.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 10, 'Karena kekerasan terhadap saudaramu Yakub, maka cela akan meliputi engkau, dan engkau akan dilenyapkan untuk selama-lamanya.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 11, 'Pada waktu engkau berdiri di kejauhan, sedang orang-orang luar mengangkut kekayaan Yerusalem dan orang-orang asing memasuki pintu gerbangnya dan membuang undi atasnya, engkaupun seperti salah seorang dari mereka itu.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 12, 'Janganlah memandang rendah saudaramu, pada hari kemalangannya, dan janganlah bersukacita atas keturunan Yehuda pada hari kebinasaannya; dan janganlah membual pada hari kesusahannya.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 13, 'Janganlah masuk ke pintu gerbang umat-Ku pada hari sialnya, bahkan janganlah memandang ringan malapetaka yang menimpanya pada hari sialnya; dan janganlah merenggut kekayaannya pada hari sialnya.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 14, 'Janganlah berdiri di persimpangan untuk melenyapkan orang-orangnya yang luput, dan janganlah serahkan orang-orangnya yang terlepas pada hari kesusahan.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 15, 'Sebab telah dekat hari TUHAN menimpa segala bangsa. Seperti yang engkau lakukan, demikianlah akan dilakukan kepadamu, perbuatanmu akan kembali menimpa kepalamu sendiri.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 16, 'Sesungguhnya, seperti kamu telah minum di atas gunung-Ku yang kudus, segala bangsapun akan minum dengan tidak henti-hentinya; bahkan, mereka akan minum dengan lahap, dan mereka akan menjadi seakan-akan mereka tidak pernah ada.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 17, 'Tetapi di gunung Sion akan ada orang-orang yang terluput, dan gunung itu akan menjadi tempat kudus; dan kaum keturunan Yakub akan memiliki pula tanah miliknya.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 18, 'Kaum keturunan Yakub akan menjadi api dan kaum keturunan Yusuf menjadi nyala api, dan kaum keturunan Esau menjadi tunggul gandum: mereka akan membakar dan memakan habis sekaliannya, dan dari kaum keturunan Esau tidak ada seorangpun yang terlepas, sebab Tuhanlah yang berfirman demikian.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 19, 'Maka orang-orang Tanah Negeb akan memiliki pegunungan Esau, dan orang-orang Daerah Bukit akan memiliki tanah orang Filistin. Mereka akan memiliki daerah Efraim dan daerah Samaria, dan suku Benyamin akan memiliki daerah Gilead.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 20, 'Orang-orang Israel yang diangkut ke dalam pembuangan akan memiliki tanah orang Kanaan sampai ke Zarfat; dan orang-orang Yerusalem yang diangkut ke dalam pembuangan, yang ada di Sefarad, akan memiliki kota-kota di Tanah Negeb.', 'id', 'TB'),
  ('31', 'ob', 'Obaja', 1, 21, 'Penyelamat-penyelamat akan naik ke atas gunung Sion untuk menghukumkan pegunungan Esau; maka Tuhanlah yang akan empunya kerajaan itu.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 1, 'Datanglah firman TUHAN kepada Yunus bin Amitai, demikian:', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 2, '"Bangunlah, pergilah ke Niniwe, kota yang besar itu, berserulah terhadap mereka, karena kejahatannya telah sampai kepada-Ku."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 3, 'Tetapi Yunus bersiap untuk melarikan diri ke Tarsis, jauh dari hadapan TUHAN; ia pergi ke Yafo dan mendapat di sana sebuah kapal, yang akan berangkat ke Tarsis. Ia membayar biaya perjalanannya, lalu naik kapal itu untuk berlayar bersama-sama dengan mereka ke Tarsis, jauh dari hadapan TUHAN.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 4, 'Tetapi TUHAN menurunkan angin ribut ke laut, lalu terjadilah badai besar, sehingga kapal itu hampir-hampir terpukul hancur.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 5, 'Awak kapal menjadi takut, masing-masing berteriak-teriak kepada allahnya, dan mereka membuang ke dalam laut segala muatan kapal itu untuk meringankannya. Tetapi Yunus telah turun ke dalam ruang kapal yang paling bawah dan berbaring di situ, lalu tertidur dengan nyenyak.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 6, 'Datanglah nakhoda mendapatkannya sambil berkata: "Bagaimana mungkin engkau tidur begitu nyenyak? Bangunlah, berserulah kepada Allahmu, barangkali Allah itu akan mengindahkan kita, sehingga kita tidak binasa."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 7, 'Lalu berkatalah mereka satu sama lain: "Marilah kita buang undi, supaya kita mengetahui, karena siapa kita ditimpa oleh malapetaka ini." Mereka membuang undi dan Yunuslah yang kena undi.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 8, 'Berkatalah mereka kepadanya: "Beritahukan kepada kami, karena siapa kita ditimpa oleh malapetaka ini. Apa pekerjaanmu dan dari mana engkau datang, apa negerimu dan dari bangsa manakah engkau?"', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 9, 'Sahutnya kepada mereka: "Aku seorang Ibrani; aku takut akan TUHAN, Allah yang empunya langit, yang telah menjadikan lautan dan daratan."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 10, 'Orang-orang itu menjadi sangat takut, lalu berkata kepadanya: "Apa yang telah kauperbuat?" ?sebab orang-orang itu mengetahui, bahwa ia melarikan diri, jauh dari hadapan TUHAN. Hal itu telah diberitahukannya kepada mereka.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 11, 'Bertanyalah mereka: "Akan kami apakan engkau, supaya laut menjadi reda dan tidak menyerang kami lagi, sebab laut semakin bergelora."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 12, 'Sahutnya kepada mereka: "Angkatlah aku, campakkanlah aku ke dalam laut, maka laut akan menjadi reda dan tidak menyerang kamu lagi. Sebab aku tahu, bahwa karena akulah badai besar ini menyerang kamu."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 13, 'Lalu berdayunglah orang-orang itu dengan sekuat tenaga untuk membawa kapal itu kembali ke darat, tetapi mereka tidak sanggup, sebab laut semakin bergelora menyerang mereka.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 14, 'Lalu berserulah mereka kepada TUHAN, katanya: "Ya TUHAN, janganlah kiranya Engkau biarkan kami binasa karena nyawa orang ini dan janganlah Engkau tanggungkan kepada kami darah orang yang tidak bersalah, sebab Engkau, TUHAN, telah berbuat seperti yang Kaukehendaki."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 15, 'Kemudian mereka mengangkat Yunus, lalu mencampakkannya ke dalam laut, dan laut berhenti mengamuk.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 16, 'Orang-orang itu menjadi sangat takut kepada TUHAN, lalu mempersembahkan korban sembelihan bagi TUHAN serta mengikrarkan nazar.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 1, 17, 'Maka atas penentuan TUHAN datanglah seekor ikan besar yang menelan Yunus; dan Yunus tinggal di dalam perut ikan itu tiga hari tiga malam lamanya.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 1, 'Berdoalah Yunus kepada TUHAN, Allahnya, dari dalam perut ikan itu,', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 2, 'katanya: "Dalam kesusahanku aku berseru kepada TUHAN, dan Ia menjawab aku, dari tengah-tengah dunia orang mati aku berteriak, dan Kaudengarkan suaraku.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 3, 'Telah Kaulemparkan aku ke tempat yang dalam, ke pusat lautan, lalu aku terangkum oleh arus air; segala gelora dan gelombang-Mu melingkupi aku.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 4, 'Dan aku berkata: telah terusir aku dari hadapan mata-Mu. Mungkinkah aku memandang lagi bait-Mu yang kudus?', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 5, 'Segala air telah mengepung aku, mengancam nyawaku; samudera raya merangkum aku; lumut lautan membelit kepalaku', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 6, 'di dasar gunung-gunung. Aku tenggelam ke dasar bumi; pintunya terpalang di belakangku untuk selama-lamanya. Ketika itulah Engkau naikkan nyawaku dari dalam liang kubur, ya TUHAN, Allahku.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 7, 'Ketika jiwaku letih lesu di dalam aku, teringatlah aku kepada TUHAN, dan sampailah doaku kepada-Mu, ke dalam bait-Mu yang kudus.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 8, 'Mereka yang berpegang teguh pada berhala kesia-siaan, merekalah yang meninggalkan Dia, yang mengasihi mereka dengan setia.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 9, 'Tetapi aku, dengan ucapan syukur akan kupersembahkan korban kepada-Mu; apa yang kunazarkan akan kubayar. Keselamatan adalah dari TUHAN!"', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 2, 10, 'Lalu berfirmanlah TUHAN kepada ikan itu, dan ikan itupun memuntahkan Yunus ke darat.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 1, 'Datanglah firman TUHAN kepada Yunus untuk kedua kalinya, demikian:', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 2, '"Bangunlah, pergilah ke Niniwe, kota yang besar itu, dan sampaikanlah kepadanya seruan yang Kufirmankan kepadamu."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 3, 'Bersiaplah Yunus, lalu pergi ke Niniwe, sesuai dengan firman Allah. Niniwe adalah sebuah kota yang mengagumkan besarnya, tiga hari perjalanan luasnya.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 4, 'Mulailah Yunus masuk ke dalam kota itu sehari perjalanan jauhnya, lalu berseru: "Empat puluh hari lagi, maka Niniwe akan ditunggangbalikkan."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 5, 'Orang Niniwe percaya kepada Allah, lalu mereka mengumumkan puasa dan mereka, baik orang dewasa maupun anak-anak, mengenakan kain kabung.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 6, 'Setelah sampai kabar itu kepada raja kota Niniwe, turunlah ia dari singgasananya, ditanggalkannya jubahnya, diselubungkannya kain kabung, lalu duduklah ia di abu.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 7, 'Lalu atas perintah raja dan para pembesarnya orang memaklumkan dan mengatakan di Niniwe demikian: "Manusia dan ternak, lembu sapi dan kambing domba tidak boleh makan apa-apa, tidak boleh makan rumput dan tidak boleh minum air.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 8, 'Haruslah semuanya, manusia dan ternak, berselubung kain kabung dan berseru dengan keras kepada Allah serta haruslah masing-masing berbalik dari tingkah lakunya yang jahat dan dari kekerasan yang dilakukannya.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 9, 'Siapa tahu, mungkin Allah akan berbalik dan menyesal serta berpaling dari murka-Nya yang bernyala-nyala itu, sehingga kita tidak binasa."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 3, 10, 'Ketika Allah melihat perbuatan mereka itu, yakni bagaimana mereka berbalik dari tingkah lakunya yang jahat, maka menyesallah Allah karena malapetaka yang telah dirancangkan-Nya terhadap mereka, dan Iapun tidak jadi melakukannya.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 1, 'Tetapi hal itu sangat mengesalkan hati Yunus, lalu marahlah ia.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 2, 'Dan berdoalah ia kepada TUHAN, katanya: "Ya TUHAN, bukankah telah kukatakan itu, ketika aku masih di negeriku? Itulah sebabnya, maka aku dahulu melarikan diri ke Tarsis, sebab aku tahu, bahwa Engkaulah Allah yang pengasih dan penyayang, yang panjang sabar dan berlimpah kasih setia serta yang menyesal karena malapetaka yang hendak didatangkan-Nya.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 3, 'Jadi sekarang, ya TUHAN, cabutlah kiranya nyawaku, karena lebih baik aku mati dari pada hidup."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 4, 'Tetapi firman TUHAN: "Layakkah engkau marah?"', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 5, 'Yunus telah keluar meninggalkan kota itu dan tinggal di sebelah timurnya. Ia mendirikan di situ sebuah pondok dan ia duduk di bawah naungannya menantikan apa yang akan terjadi atas kota itu.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 6, 'Lalu atas penentuan TUHAN Allah tumbuhlah sebatang pohon jarak melampaui kepala Yunus untuk menaunginya, agar ia terhibur dari pada kekesalan hatinya. Yunus sangat bersukacita karena pohon jarak itu.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 7, 'Tetapi keesokan harinya, ketika fajar menyingsing, atas penentuan Allah datanglah seekor ulat, yang menggerek pohon jarak itu, sehingga layu.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 8, 'Segera sesudah matahari terbit, maka atas penentuan Allah bertiuplah angin timur yang panas terik, sehingga sinar matahari menyakiti kepala Yunus, lalu rebahlah ia lesu dan berharap supaya mati, katanya: "Lebih baiklah aku mati dari pada hidup."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 9, 'Tetapi berfirmanlah Allah kepada Yunus: "Layakkah engkau marah karena pohon jarak itu?" Jawabnya: "Selayaknyalah aku marah sampai mati."', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 10, 'Lalu Allah berfirman: "Engkau sayang kepada pohon jarak itu, yang untuknya sedikitpun engkau tidak berjerih payah dan yang tidak engkau tumbuhkan, yang tumbuh dalam satu malam dan binasa dalam satu malam pula.', 'id', 'TB'),
  ('32', 'yun', 'Yunus', 4, 11, 'Bagaimana tidak Aku akan sayang kepada Niniwe, kota yang besar itu, yang berpenduduk lebih dari seratus dua puluh ribu orang, yang semuanya tak tahu membedakan tangan kanan dari tangan kiri, dengan ternaknya yang banyak?"', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 1, 'Firman TUHAN yang datang kepada Mikha, orang Moresyet, pada zaman Yotam, Ahas dan Hizkia, raja-raja Yehuda, yakni berkenaan dengan yang dilihatnya tentang Samaria dan Yerusalem.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 2, 'Dengarlah, hai bangsa-bangsa sekalian! Perhatikanlah, hai bumi serta isinya! Biarlah Tuhan ALLAH menjadi saksi terhadap kamu, yakni Tuhan dari bait-Nya yang kudus.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 3, 'Sebab sesungguhnya, TUHAN keluar dari tempat-Nya dan turun berjejak di atas bukit-bukit bumi.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 4, 'Luluhlah gunung-gunung di bawah kaki-Nya, dan lembah-lembah terbelah seperti lilin di depan api, seperti air tercurah di penurunan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 5, 'Semuanya ini terjadi karena pelanggaran Yakub, dan karena dosa kaum Israel. Pelanggaran Yakub itu apa? Bukankah itu Samaria? Dosa kaum Yehuda itu apa? Bukankah itu Yerusalem?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 6, 'Sebab itu Aku akan membuat Samaria menjadi timbunan puing di padang, menjadi tempat penanaman pohon anggur. Aku akan menggulingkan batu-batunya ke dalam lembah dan akan menyingkapkan dasar-dasarnya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 7, 'Segala patungnya akan diremukkan, segala upah sundalnya akan dibakar, dan segala berhalanya akan Kuhancurkan; sebab dari upah sundal dikumpulkan semuanya itu, dan akan kembali menjadi upah sundal.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 8, 'Karena inilah aku hendak berkeluh kesah dan meratap, hendak berjalan dengan tidak berkasut dan telanjang, hendak melolong seperti serigala dan meraung seperti burung unta:', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 9, 'sebab lukanya tidak dapat sembuh, sudah menjalar ke Yehuda, sudah sampai ke pintu gerbang bangsaku, ke Yerusalem!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 10, 'Di Gat janganlah sampaikan berita, janganlah sekali-kali menangis! Baiklah gulingkan dirimu dalam debu di Bet-Le-Afra!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 11, 'Berkemaslah, hai penduduk Safir, dengan telanjang dan malu. Tidak berani keluar penduduk Zaanan. Ratapan Bet-Haezel menghalangi engkau untuk tetap berdiri.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 12, 'Dengan bimbang penduduk Marot berharap akan kebaikan. Sebab malapetaka turun dari pada TUHAN sampai ke pintu gerbang Yerusalem.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 13, 'Pasanglah kuda teji pada kereta, hai penduduk Lakhis! Inilah permulaan dosa bagi puteri Sion, sebab padamulah terdapat pelanggaran Israel.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 14, 'Sebab itu baiklah diberi hadiah perpisahan kepada Moresyet-Gat. Rumah-rumah Akhzib akan menjadi tipu daya bagi raja-raja Israel.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 15, 'Penakluk masih akan Kudatangkan kepadamu, hai penduduk Maresya! Kemuliaan Israel akan sampai di Adulam.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 1, 16, 'Cukurlah dan gundulkanlah kepalamu, karena anak-anak kesayanganmu! Jadikanlah kepalamu gundul seperti gundulnya burung bangkai, sebab dari padamu mereka akan masuk pembuangan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 1, 'Celakalah orang-orang yang merancang kedurjanaan dan yang merencanakan kejahatan di tempat tidurnya; yang melakukannya di waktu fajar, sebab hal itu ada dalam kekuasaannya;', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 2, 'yang apabila menginginkan ladang-ladang, mereka merampasnya, dan rumah-rumah, mereka menyerobotnya; yang menindas orang dengan rumahnya, manusia dengan milik pusakanya!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 3, 'Sebab itu beginilah firman TUHAN: Sesungguhnya, Aku merancang malapetaka terhadap kaum ini, dan kamu tidak dapat menghindarkan lehermu dari padanya; kamu tidak dapat lagi berjalan angkuh, sebab waktu itu adalah waktu yang mencelakakan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 4, 'Pada hari itu orang akan melontarkan sindiran tentang kamu dan akan memperdengarkan suatu ratapan dan akan berkata: "Kita telah dihancurluluhkan! Bagian warisan bangsaku telah diukur dengan tali, dan tidak ada orang yang mengembalikannya, ladang-ladang kita dibagikan kepada orang-orang yang menawan kita."', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 5, 'Sebab itu tidak akan ada bagimu orang yang melontarkan tali dengan undian di dalam jemaah TUHAN.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 6, '"Janganlah ucapkan nubuat," kata mereka itu, "orang tidak mengucapkan nubuat seperti itu! Noda tidak akan menimpa kita."', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 7, 'Bolehkah hal itu dikatakan, keturunan Yakub? Apakah TUHAN kurang sabar? Atau seperti inikah tindakan-Nya? Bukankah firman-Ku baik terhadap orang yang benar kelakuannya?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 8, 'Tetapi kamulah yang bangkit sebagai musuh terhadap umat-Ku. Kamu merebut jubah dari orang-orang yang suka damai, dari orang-orang yang berjalan lewat dengan tenteram, yang tidak cenderung kepada perang.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 9, 'Para isteri di antara umat-Ku kamu halau dari rumah kesayangannya, dari bayi-bayinya kamu mengambil untuk selama-lamanya, semarak yang telah Kuberikan kepada mereka.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 10, 'Bangkitlah dan pergilah, sebab ini bukan tempat perhentian bagimu! Oleh karena kenajisan maka kamu akan dibinasakan dengan kebinasaan yang tidak terpulihkan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 11, 'Seandainya seseorang datang mereka-reka yang hampa dan dusta: "Aku bernubuat kepadamu tentang anggur dan arak," maka dialah yang patut menjadi orang yang bernubuat terhadap bangsa ini!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 12, 'Dengan sungguh-sungguh Aku akan mengumpulkan engkau seluruhnya, hai Yakub, dengan sungguh-sungguh Aku akan menghimpunkan sisa orang Israel; Aku akan menyatukannya seperti kambing domba dalam kandang, seperti kawanan binatang di tengah-tengah padangnya, sehingga ramai dengan manusia!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 2, 13, 'Penerobos akan maju di depan mereka; mereka akan menerobos dan berjalan melewati pintu gerbang dan akan keluar dari situ. Raja mereka akan berjalan terus di depan mereka, TUHAN sendiri di kepala barisan mereka!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 1, 'Kataku: Baiklah dengar, hai para kepala di Yakub, dan hai para pemimpin kaum Israel! Bukankah selayaknya kamu mengetahui keadilan,', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 2, 'hai kamu yang membenci kebaikan dan yang mencintai kejahatan? Mereka merobek kulit dari tubuh bangsaku dan daging dari tulang-tulangnya;', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 3, 'mereka memakan daging bangsaku, dan mengupas kulit dari tubuhnya; mereka meremukkan tulang-tulangnya, dan mencincangnya seperti daging dalam kuali, seperti potongan-potongan daging di dalam belanga.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 4, 'Mereka sendirilah nanti akan berseru-seru kepada TUHAN, tetapi Ia tidak akan menjawab mereka; Ia akan menyembunyikan wajah-Nya terhadap mereka pada waktu itu, sebab jahat perbuatan-perbuatan mereka.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 5, 'Beginilah firman TUHAN terhadap para nabi, yang menyesatkan bangsaku, yang apabila mereka mendapat sesuatu untuk dikunyah, maka mereka menyerukan damai, tetapi terhadap orang yang tidak memberi sesuatu ke dalam mulut mereka, maka mereka menyatakan perang.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 6, 'Sebab itu hari akan menjadi malam bagimu tanpa penglihatan, dan menjadi gelap bagimu tanpa tenungan. Matahari akan terbenam bagi para nabi itu, dan hari menjadi hitam suram bagi mereka.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 7, 'Para pelihat akan mendapat malu dan tukang-tukang tenung akan tersipu-sipu; mereka sekalian akan menutupi mukanya, sebab tidak ada jawab dari pada Allah.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 8, 'Tetapi aku ini penuh dengan kekuatan, dengan Roh TUHAN, dengan keadilan dan keperkasaan, untuk memberitakan kepada Yakub pelanggarannya dan kepada Israel dosanya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 9, 'Baiklah dengarkan ini, hai para kepala kaum Yakub, dan para pemimpin kaum Israel! Hai kamu yang muak terhadap keadilan dan yang membengkokkan segala yang lurus,', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 10, 'hai kamu yang mendirikan Sion dengan darah dan Yerusalem dengan kelaliman!', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 11, 'Para kepalanya memutuskan hukum karena suap, dan para imamnya memberi pengajaran karena bayaran, para nabinya menenung karena uang, padahal mereka bersandar kepada TUHAN dengan berkata: "Bukankah TUHAN ada di tengah-tengah kita! Tidak akan datang malapetaka menimpa kita!"', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 3, 12, 'Sebab itu oleh karena kamu maka Sion akan dibajak seperti ladang, dan Yerusalem akan menjadi timbunan puing, dan gunung Bait Suci akan menjadi bukit yang berhutan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 1, 'Akan terjadi pada hari-hari yang terakhir: gunung rumah TUHAN akan berdiri tegak mengatasi gunung-gunung dan menjulang tinggi di atas bukit-bukit; bangsa-bangsa akan berduyun-duyun ke sana,', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 2, 'dan banyak suku bangsa akan pergi serta berkata: "Mari, kita naik ke gunung TUHAN, ke rumah Allah Yakub, supaya Ia mengajar kita tentang jalan-jalan-Nya dan supaya kita berjalan menempuhnya; sebab dari Sion akan keluar pengajaran, dan firman TUHAN dari Yerusalem."', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 3, 'Ia akan menjadi hakim antara banyak bangsa, dan akan menjadi wasit bagi suku-suku bangsa yang besar sampai ke tempat yang jauh; mereka akan menempa pedang-pedangnya menjadi mata bajak, dan tombak-tombaknya menjadi pisau pemangkas; bangsa tidak akan lagi mengangkat pedang terhadap bangsa, dan mereka tidak akan lagi belajar perang.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 4, 'Tetapi mereka masing-masing akan duduk di bawah pohon anggurnya dan di bawah pohon aranya dengan tidak ada yang mengejutkan, sebab mulut TUHAN semesta alam yang mengatakannya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 5, 'Biarpun segala bangsa berjalan masing-masing demi nama allahnya, tetapi kita akan berjalan demi nama TUHAN Allah kita untuk selamanya dan seterusnya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 6, 'Pada hari itu, demikianlah firman TUHAN, Aku akan mengumpulkan mereka yang pincang, dan akan menghimpunkan mereka yang terpencar-pencar dan mereka yang telah Kucelakakan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 7, 'Mereka yang pincang akan Kujadikan pangkal suatu keturunan, dan yang diusir suatu bangsa yang kuat, dan TUHAN akan menjadi raja atas mereka di gunung Sion, dari sekarang sampai selama-lamanya.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 8, 'Dan engkau, hai Menara Kawanan Domba, hai Bukit puteri Sion, kepadamu akan datang dan akan kembali pemerintahan yang dahulu, kerajaan atas puteri Yerusalem.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 9, 'Maka sekarang, mengapa engkau berteriak dengan keras? Tiadakah raja di tengah-tengahmu? Atau sudah binasakah penasihatmu, sehingga engkau disergap kesakitan seperti perempuan yang melahirkan?', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 10, 'Menggeliatlah dan mengaduhlah, hai puteri Sion, seperti perempuan yang melahirkan! Sebab sekarang terpaksa engkau keluar dari kota dan tinggal di padang, terpaksa engkau berjalan sampai Babel; di sanalah engkau akan dilepaskan, di sanalah engkau akan ditebus oleh TUHAN dari tangan musuhmu.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 11, 'Sekarang banyak bangsa berkumpul melawan engkau, dengan berkata: "Biarlah dia dicemarkan, biarlah mata kita puas memandangi Sion!"', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 12, 'Tetapi mereka itu tidak mengetahui rancangan TUHAN; mereka tidak mengerti keputusan-Nya, bahwa Ia akan menghimpunkan mereka seperti berkas gandum ke tempat pengirikan.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 4, 13, 'Bangkitlah dan iriklah, hai puteri Sion, sebab tandukmu akan Kubuat seperti besi, dan kukumu akan Kubuat seperti tembaga, sehingga engkau menumbuk hancur banyak bangsa; engkau akan mengkhususkan rampasan mereka bagi TUHAN dan kekayaan mereka bagi Tuhan seluruh bumi.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 1, '(4-14) Sekarang, engkau harus mendirikan tembok bagimu; pagar pengepungan telah mereka dirikan melawan kita; dengan tongkat mereka memukul pipi orang yang memerintah Israel.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 2, '(5-1) Tetapi engkau, hai Betlehem Efrata, hai yang terkecil di antara kaum-kaum Yehuda, dari padamu akan bangkit bagi-Ku seorang yang akan memerintah Israel, yang permulaannya sudah sejak purbakala, sejak dahulu kala.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 3, '(5-2) Sebab itu ia akan membiarkan mereka sampai waktu perempuan yang akan melahirkan telah melahirkan; lalu selebihnya dari saudara-saudaranya akan kembali kepada orang Israel.', 'id', 'TB'),
  ('33', 'mi', 'Mikha', 5, 4, '(5-3) Maka ia akan bertindak dan akan menggembalakan mereka dalam kekuatan TUHAN, dalam kemegahan nama TUHAN Allahnya; mereka akan tinggal tetap, sebab sekarang ia menjadi besar sampai ke ujung bumi,', 'id', 'TB')
